SELECT 'moj-all-verified-judgments-review-002-chunk-136' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"08d7328d-a609-5ebf-8f44-0eafdc1b0cac","document_type":"judgment","category":"judicial","subcategory":"general","title":"انتهاك حرمة منزل بغرض السرقة -تستر -إقرار -ظروف مخففة للعقوبة -تعزير بالسجن واجللد -تعهد ض ب ع د إ ص ل ح ها)) -1قوله تعالى (( :و ل ت ف س دوا ف","document_number":"34186538","case_number":"34157003","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية على املعاملة املقيدة لدى المحكمة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/14","year":"1434","subject":"انتهاك حرمة منزل بغرض السرقة -تستر -إقرار -ظروف مخففة للعقوبة -تعزير بالسجن واجللد -تعهد ض ب ع د إ ص ل ح ها)) -1قوله تعالى (( :و ل ت ف س دوا ف","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"                  ‫رقم الصك ‪ 34186538 :‬تاريخه‪:‬‬\n           ‫‪1434/04/14‬هـ رقم الدعوى‪34157003 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34204176‬تاريخه‪1434/5/4 :‬هـ‬\n\n\n     ‫انتهــاك حرمــة منــزل بغــرض الســرقة ‪ -‬تســتر ‪ -‬إقــرار ‪ -‬ظــروف مخففة‬\n                                 ‫للعقوبــة ‪ -‬تعزيــر بالســجن واجللــد ‪ -‬تعهد‬\n\n\n\n                               ‫ض َب ْع َد ِإ ْص َل ِح َها))‬               ‫‪ -1‬قوله تعالى ‪َ (( :‬و َل ُت ْف ِس ُدوا ِف ْ َ‬\n                                                                     ‫ال ْر ِ‬\n                                  ‫ين))‬‫الل ال ُي ِح ُّب ْالُ ْع َتدِ َ‬      ‫‪ -2‬قوله تعالى ‪َ (( :‬وال َت ْع َت ُدوا ِإ َّن َّ َ‬\n     ‫دمـ ُه‬‫(كل املســلم علــى املســلم حــرا ٌم ُ‬                     ‫ُّ‬        ‫‪ -3‬قولــه صلــى اهلل عليــه وســلم ‪:‬‬\n                                                                                                              ‫وعرضــه)‬\n                                                                                                                    ‫ُ‬             ‫وما ُلـ ُه‬\n     ‫اض ُكـ ْـم‬\n              ‫كـ ْـم َوأ َْم َوا َل ُكـ ْـم َوأَعْ َر َ‬‫‪ -4‬قولــه صلــى اهلل عليــه وســلم ‪( :‬فَ ـ ِإ َّن د َِم َاء ُ‬\n     ‫كـ ْـم‬  ‫ك ْم َهـ َـذا ‪ِ ،‬ف َب َلدِ ُ‬        ‫ك ُح ْر َم ـ ِة َي ْومِ ُكـ ْـم َهـ َـذا ‪ِ ،‬ف َشــهْ ِر ُ‬   ‫َحـ َـرا ٌم َع َل ْي ُكـ ْـم َ‬\n                                                                                                                                     ‫َهـ َـذا)‬\n     ‫ـس‬  ‫‪ -5‬قولــه صلــى اهلل عليــه وســلم ‪( :‬أَال ِإ َّن ْالُ ْس ـل َِم أ َُخــو ْالُ ْس ـل ِِم ‪ ،‬فَ َل ْيـ َ‬\n                                 ‫َي ِحـ ُّـل لِ ُ ْس ـل ٍِم مِ ـ ْـن أ َِخي ـ ِه َشـ ْـي ٌء ِإال َمــا َحـ َّـل َل ـ ُه مِ ـ ْـن َن ْف ِس ـهِ)‬\n\n\n\n\n     ‫توجيــه االتهــام للمدعــى عليــه بقيامــه بالقفز من على ســور منزل ودخوله‬\n     ‫عبــر فتحــة مكيــف أحــد الغــرف بعــد دفعــه إلــى داخــل الغرفــة بغــرض‬\n     ‫الســرقة وتســتره علــى الهاربــن‪ ،‬وذلــك بعــد القبــض علــى املدعــى عليــه‬\n     ‫إثــر ورود بــاغ للجهــات املختصــة مــن أحــد املواطنــن مفــاده تعــرض‬\n\n‫‪83‬‬\n\f‫الفيــا التــي يقطــن فيهــا للقفــز مــن علــى الســور اخلارجــي مــن قبــل ثالثــة‬\n‫أشــخاص بغــرض الســرقة وعنــد مشــاهدتهم لــه الذوا بالفــرار‪ -‬بالبحــث‬\n‫عــن ســوابقه لــم يعثــر لــه علــى ســوابق جنائيــة مســجلة‪ -‬طلــب املدعــي‬\n‫العــام احلكــم عليــه بعقوبــة تعزيريــة‪ -‬بعــرض دعــوى املدعــي العــام علــى‬\n‫ـواء مــن الشــيطان‬‫املدعــى عليــه صــادق عليهــا وقــرر أن ذلــك كان إغـ ٌ‬\n‫وأنــه تائــب ونــادم علــى مــا بــدر منــه‪ -‬ثبتــت إدانــة املدعــى عليــه مبــا أســند‬\n‫أن مــا صــدر مــن املدعــى عليــه مــن احملـ َّـرم شــرعاً؛ ولتوجــه‬    ‫إليــه ومبــا َّ‬\n‫ـوابق لــه‬\n     ‫تخفيــف العقوبــة عليــه لظهــور آثــار النــدم عليــه وعــدم وجــود سـ ٍ‬\n‫ولصغــر ســنه والنتهــاء احلــق اخلــاص بالتنــازل كمــا يتوجــه أن تكــون‬\n‫عقوبتــه باجللــد أشـ َّـد مــن الســجن للظــروف الســابقة لــذا مت احلكــم‬\n‫بتعزيــره بســجنه ســبعة أشــهر وبجلــده مائتــي جلــدة مفرقــة علــى أربــع‬\n‫دفعــات وأخــذ التعهــد عليــه بعــدم العــودة ملثــل مــا صــدر منــه‪ -‬بعــرض‬\n‫احلكــم علــى الطرفــن قــرر املدعــي القناعــة وطلــب املدعــي العــام رفــع‬\n‫كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم دون الئحـ ٍة‬\n‫اعتراضيــة مكتفي ـ ًا مبــا ورد يف الئحــة الدعــوى‪ -‬وبعــد رفــع احلكــم‬\n                                   ‫حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد‬\n‫ـاء علــى‬\n       ‫ـدي أنــا ‪ .....‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n                                                                   ‫فلـ َّ‬\n‫املعاملــة الــواردة إلينــا مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة‬\n‫األحســاء برقــم ‪.....‬وتاريخ‪1434/04/03‬ه ـ واملقيــدة بهــذه احملكمــة‬\n‫برقم‪34836374‬وتاريخ‪1434/04/06‬ه ـ واحملالــة إلينــا مــن فضيلــة‬\n\n                                                                                            ‫‪84‬‬\n\f     ‫الرئيــس برقــم ‪ 34157003‬وتاريــخ ‪1434/04/06‬ه ـ فتحــت اجللســة‬\n     ‫األولــى يــوم االربعــاء ‪1434/04/10‬ه ـ الســاعة العاشــرة والنصــف‬\n     ‫صباحـ ًا وفيهــا حضــر املدعــي العــام ‪ .....‬امل َُع ّمــد بالترافــع أمــام احملكمــة‬\n     ‫طرفنــا مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واالدعــاء العــام‬\n     ‫مبحافظــة األحســاء ذي الرقــم ‪.....‬والتاريــخ ‪1433/12/1‬ه ـ وقـ ّـرر دعــواه‬\n     ‫عامــا بدائــرة االدعــاء العــام مبحافظة األحســاء‬     ‫ا ‪ :‬فبصفتــي مدعيـ ًا ً‬     ‫قائـ ً‬\n     ‫أدعــي علــى ‪ 20 ،.....:‬عامـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫رقــم (‪ ).....‬طالــب ‪ ،‬أوقــف بتاريــخ ‪1434/3/9‬ه ـ وأحيــل لشــعبة ســجن‬\n     ‫ا لديهــم برقــم (‪ ).....‬اســتناد ًا للفقــرة رقم‬   ‫محافظــة األحســاء وســجل نزيـ ً‬\n     ‫(‪ )13‬مــن القــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ ‪.‬حيــث‬\n     ‫أنــه بتاريــخ ‪1433/3/9‬ه ـ ورد لرجــال الدوريــات األمنيــة بــاغ مــن‬\n     ‫املدعــو ‪.....‬مفــاده تعــرض الفيــا التــي يقطــن فيهــا للقفــز مــن علــى الســور‬\n     ‫اخلارجــي مــن قبــل ثالثــة أشــخاص بغــرض الســرقة وعنــد مشــاهدتهم لــه‬\n     ‫الذوا بالفــرار وقبــض علــى املدعــى عليــه ‪.‬وباالنتقــال واملعاينــة للمنــزل‬\n     ‫اتضــح أن اجلنــاة وضعــوا دافــور لونــه أزرق حتــت موقــع مكيــف املقلــط‬\n     ‫واســتخدموه يف االرتفــاع ملســتوى املكيــف ليتــم دفعــه وقــد شــوهد‬\n     ‫املكيــف ســاقط داخــل املقلــط واملجلــس مبعثــر وكذلــك غرفــة نــوم‬\n     ‫األطفــال والصالة‪.‬وبضبــط أقــوال املبلــغ ‪.....‬أفــاد بأنــه ورد إليــه اتصــال‬\n     ‫مــن زوجتــه أخبرتــه عــن ســماع دخــول أشــخاص بواســطة القفــز مــن علــى‬\n     ‫الســور ومــن ثــم عبــر فتحــة املكيــف مــن أحــد الغــرف وعنــد وصولــه‬\n     ‫متكــن مــن القبــض علــى املدعــى عليــه ‪.‬وبضبــط أقــوال زوجــة املبلــغ ‪.....‬‬\n     ‫أفــادت أنهــا ســمعت صوتـ ًا بالــدور األرضــي وعنــد محاولــة خروجهــا مــن‬\n     ‫غرفتهــا شــاهدت شــخصني فعــادت مســرعة لغرفتهــا وأقفلــت البــاب‬\n\n\n‫‪85‬‬\n\f‫عليهــا وعلــى الفــور اتصلــت بزوجهــا وبجارتهــا وقــد حــاول اجلنــاة فتــح‬\n‫غرفتهــا ممــا دعاهــا إلــى الصــراخ بصــوت مرتفــع ممــا نتــج عنــه هروبهمــا‬\n‫‪.‬وبضبــط أقــوال الشــهود ‪.....‬و‪.....‬و‪.....‬أفــادوا بأنهــم شــاهدوا املبلــغ ‪.....‬‬\n‫يخــرج مــن منزلــه مســرع ًا واللحــاق بشــخص قــام بالقفــز مــن علــى ســور‬\n‫منزلــه ‪ .‬وباســتجواب املدعــى عليــه أقــر بالقفــز علــى منــزل املبلــغ ودخــول‬\n‫منزلــه عبــر فتحــة مكيــف أحــد الغــرف بعــد أن قــام بإخراجــه عنــوه‬\n‫ممــا أدى إلــى ســقوط املكيــف علــى األرض وعنــد محاولــة فتــح بــاب‬\n‫أحــد الغــرف الداخليــة ســمع صــوت صــراخ امــرأة حينهــا الذ بالفــرار ومت‬\n‫القبــض عليــه مــن قبــل املبلــغ ‪ .‬وقــد أســفر التحقيــق عــن توجيــه االتهــام‬\n‫لــه بقيامــه بالقفــز مــن علــى ســور منــزل املبلــغ ودخــول منزلــه عبــر فتحــة‬\n‫مكيــف أحــد الغــرف بعــد دفعــه إلــى داخــل الغرفــة بغــرض الســرقة‬\n                   ‫وتســتره علــى الهاربــن؛ وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n     ‫‪ .1‬إقراره املدونة على الصفحات رقم (‪ )11/10‬املرفق لفه رقم (‪.)1‬‬\n‫‪ .2‬محضــر االنتقــال واملعاينــة املــدون علــى الصفحــات رقــم (‪)3_2‬‬\n                                                            ‫املرفــق لفــه رقــم (‪.)2‬‬\n‫‪ .3‬أقــوال املبلــغ املدونــة علــى الصفحــات رقــم (‪ )9_10‬املرفــق لفــه رقــم‬\n                                                                                ‫(‪.)2‬‬\n‫‪ .4‬أقــوال زوجــة املبلــغ املدونــة علــى الصفحــات رقــم (‪ )5_4‬املرفــق لفــه‬\n                                                                           ‫رقــم (‪)1‬‬\n‫‪ .5‬أقــوال الشــهود املدونــة علــى الصفحــات رقــم (‪ )4‬املرفــق لفــه رقــم (‪)2‬‬\n                                     ‫والصفحــات رقــم (‪ )6‬املرفــق لفــه رقم (‪.)1‬‬\n                                       ‫‪ .6‬محضر القبض املرفق لفه رقم (‪)12‬‬\n‫وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق جنائيــة‬\n\n\n                                                                                        ‫‪86‬‬\n\f     ‫مســجلة كمــا هــو مــدون بقــرار االتهــام وحيــث إن مــا أقــدم عليــه‬\n     ‫املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب‬\n     ‫عليــه شــرعاً؛ لــذا أطلــب إثبــات مــا أســند إليــه ‪ ،‬واحلكــم عليــه بعقوبــة‬\n     ‫تعزيريــة تزجــره وتــردع غيــره ‪(.‬علم ـ ًا أن احلــق اخلــاص ال يــزال قائم ـاً)‬\n     ‫هكــذا ا َّدعــى ؛ عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد مــن‬\n     ‫ا ‪ :‬مــا‬   ‫هويتــه جــرى عــرض دعــوى املدعــي العــام عليــه فأجــاب قائ ـ ً‬\n     ‫ذكــره املدعــي العــام مــن اتهامــي بالقيــام بالقفــز علــى مــن علــى ســور‬\n     ‫املنــزل أحــد املواطنــن ودخــول منزلــه عبــر فتحــة مكيــف أحــد الغــرف‬\n     ‫بعــد دفعــه إلــى داخــل الغرفــة بغــرض الســرقة وتســتري علــى الهاربــن‬\n     ‫ـواء مــن الشــيطان وأنــا تائــب‬           ‫كل ذلــك صحيــح وقــد كان ذلــك إغـ ٌ‬\n     ‫ونــادم علــى مــا بــدر منــي هكــذا أجــاب ثــم جــرى االطــاع علــى جميــع‬\n     ‫أوراق املعاملــة ومنهــا كــرت ســوابق املدعــى عليــه املتضمــن عــدم وجــود‬\n     ‫ســوابق عليــه كمــا جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه‬\n     ‫ـاء علــى مــا تقــدم مــن‬        ‫املتضمنــة أنــه أوقــف بتاريــخ ‪1434/03/09‬ه ـ فبنـ ً‬\n     ‫الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه والتأكــد مــن‬\n     ‫أن املدعــى عليــه أقـ َّـر‬     ‫أهليتــه وبعــد دراســة أوراق املعاملــة وتأملهــا ومبــا َّ‬\n     ‫بدعــوى املدعــي العــام باتهامــه بالقيــام بالقفــز علــى مــن علــى ســور املنــزل‬\n     ‫أحــد املواطنــن ودخــول منزلــه عبــر فتحــة مكيــف أحــد الغــرف بعــد‬\n     ‫دفعــه إلــى داخــل الغرفــة بغــرض الســرقة وتســتره علــى الهاربــن ومبــا‬\n     ‫((و َل‬‫أن مــا صــدر مــن املدعــى عليــه مــن احملـ َّـرم شــرع ًا قــال تعالــى ‪َ :‬‬                  ‫َّ‬\n     ‫((وال َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n     ‫الل‬                           ‫ض َب ْعـ َـد ِإ ْص َلحِ َهــا)) وقــال تعالــى ‪َ :‬‬    ‫ُت ْف ِسـ ُـدوا ِف ْ َ‬\n                                                                                    ‫ال ْر ِ‬\n     ‫ال ُي ِحـ ُّـب ْال ُْع َتدِ يـ َـن)) وقــال صلــى اهلل عليــه وســلم ‪( :‬كلُّ املســلم علــى‬\n     ‫(فـ ِإ َّن‬\n             ‫وعرضــه) وقــال عليــه الصــاة والســام‪َ :‬‬         ‫ُ‬        ‫دمـ ُه وما ُلـ ُه‬\n                                                                                        ‫ـرام ُ‬\n                                                                                            ‫املســلم حـ ٌ‬\n\n‫‪87‬‬\n\f‫كـ ْـم‬  ‫ك ُح ْر َم ـ ِة َي ْومِ ُ‬‫كـ ْـم َ‬    ‫كـ ْـم َحـ َـر ٌام َع َل ْي ُ‬   ‫َكـ ْـم َو َأ ْع َر َ‬\n                                                                          ‫اض ُ‬                        ‫كـ ْـم َو َأ ْم َوال ُ‬\n                                                                                                                           ‫د َِم َاء ُ‬\n‫كـ ْـم َهـ َـذا) وقــال عليــه الصــاة‬                           ‫ك ْم َهـ َـذا ‪ِ ،‬ف َبلَدِ ُ‬         ‫َهـ َـذا ‪ِ ،‬ف َشـ ْـه ِر ُ‬\n‫ـس َي ِحــلُّ لِ ُْس ـل ٍِم مِ ــنْ َأخِ ي ـ ِه‬‫والســام ‪َ ( :‬أال ِإ َّن ْال ُْسـ ِـل َم َأ ُخــو ْال ُْس ـل ِِم ‪َ ،‬ف َل ْيـ َ‬\n‫َشـ ْـي ٌء ِإال َمــا َحــلَّ َل ـ ُه مِ ــنْ ن َْف ِس ـهِ) ممــا يســتوجب تعزيــر املدعــى عليــه‬\n‫ويتوجــه تخفيــف العقوبــة عليــه لظهــور آثــار النــدم عليــه وعــدم وجــود‬\n‫ـوابق لــه ولصغــر ســنه والنتهــاء احلــق اخلــاص بالتنــازل كمــا يتوجــه أن‬                                              ‫سـ ٍ‬\n‫تكــون عقوبتــه باجللــد أشـ َّـد مــن الســجن للظــروف الســابقة لــذا كلــه‬\n‫وألجــل احلــق العــام حكمـ ُـت علــى املدعــى عليــه مبــا يلــي ‪ :‬أوالً‪ /‬ثبــت‬\n‫ـدي إدانــة املدعــى عليــه بالقيــام بالقفــز علــى مــن علــى ســور املنــزل‬                                                ‫لـ َّ‬\n‫ألحــد املواطنــن ودخــول منزلــه عبــر فتحــة مكيــف أحــد الغــرف بعــد‬\n‫دفعــه إلــى داخــل الغرفــة بغــرض الســرقة وتســتره علــى الهاربــن وعزرتــه‬\n‫لقــاء ذلــك بســجنه ســبعة أشــهر مــن تاريــخ إيقافــه علــى ذمــة القضيــة‬\n‫وبجلــده مائتــا جلــدة مفرقــة علــى أربــع دفعــات كل دفعــة خمســون جلــدة‬\n‫وبــن كل دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيــام ‪ .‬ثاني ـ ًا ‪ /‬يؤخــذ‬\n‫عليــه التعهــد بعــدم العــودة ملثــل مــا صــدر منــه ‪ .‬وبتــاوة احلكــم علــى‬\n‫الطرفــن وإفهــام املدعــى عليــه بحقــه يف متييــز احلكــم قــرر القناعــة بــه‬\n‫وطلــب املدعــي العــام رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف‬\n‫لتدقيــق احلكــم دون الئح ـ ٍة اعتراضيــة مكتفي ـ ًا مبــا ورد يف الئحــة‬\n‫الدعــوى وأقفلــت اجللســة الســاعة احلاديــة عشــرة وصلــى اهلل وسـلَّم علــى‬\n  ‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪ُ .‬حـ ِـر َر يف ‪1434/04/10‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/341021209‬ج‪ 2‬وتاريــخ ‪1434/4/27‬ه ـ‬\n\n\n                                                                                                                                         ‫‪88‬‬\n\f     ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n     ‫املكلــف برقــم ‪ 34845938‬وتاريــخ ‪1434/4/22‬ه ـ املرفــق بهــا القــرار‬\n     ‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ...../‬املســجل برقــم‬\n     ‫‪ 34186538‬وتاريــخ ‪1434/4/14‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام‬\n     ‫ضــد‪...../‬يف قضيــة دخــول منــزل وســرقته وقــد تضمــن القــرار حكــم‬\n     ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n     ‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل‬\n              ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/5/1‬ه ـ‬\n\n\n\n\n‫‪89‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":83,"source_page_end":89,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"54b6b86f2aa80ec1184ba4ed1f8245bfde5d37acfa23d527d78e3fe1238dd150","normalized_text_hash":"c4a1e53b7d7748e1a39cb16a5e958a74a42223698b8e09f5595463f659d17730","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p83-34186538"},{"id":"add4ddcc-00a5-55f0-974c-28de2f7bc4c1","document_type":"judgment","category":"judicial","subcategory":"general","title":"-انتهاك حرمة منزل -رجوع املقر عن إقراره يف غير احلدود ال يقبل -تكرر السوابق من نفس نوع اجلرم املتهم به -إثبات إدانة - التعزير بالسجن واجللد علنا.","document_number":"34234470","case_number":"34168877","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/7","year":"1434","subject":"-انتهاك حرمة منزل -رجوع املقر عن إقراره يف غير احلدود ال يقبل -تكرر السوابق من نفس نوع اجلرم املتهم به -إثبات إدانة - التعزير بالسجن واجللد علنا.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34234470 :‬تاريخه‪1434/6/7 :‬هـ‬\n                   ‫رقم الدعوى‪34168877 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34297413‬تاريخه‪1434/8/15:‬هـ‬\n\n\n‫دخــول منــزل دون إذن صاحبــه مــع توجــه شــبهة الغــرض الســيء‬\n‫‪ -‬انتهــاك حرمــة منــزل ‪ -‬رجــوع املقــر عــن إقــراره يف غيــر احلــدود ال‬\n‫يقبــل ‪ -‬تكــرر الســوابق مــن نفــس نــوع اجلــرم املتهــم بــه ‪ -‬إثبــات إدانــة ‪-‬‬\n                                              ‫التعزيــر بالســجن واجللــد علنــا‪.‬‬\n\n\n\n‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم ‪ « :‬مــن اطلــع يف بيــت قــوم بغيــر‬\n                     ‫إذنهــم ‪ ،‬فقــد حــل لهــم أن يفقــؤوا عينــه » رواه مســلم‪.‬‬\n‫‪ -2‬مــا قــرره أهــل العلــم أن رجــوع املقــر عــن إقــراره ال يقبــل يف غيــر‬\n‫احلــدود‪ ،‬جــاء يف كشــاف القنــاع ‪ « :‬وال يقبــل رجــوع املقــر عــن إقــراره‬\n‫لتعلــق حــق املقــر لــه باملقــر بــه إال فيمــا كان حــد ًا هلل تعالــى فيقبــل‬\n‫رجوعــه عنــه كمــا تقــدم يف مواضعــه ألن احلــد يــدرأ بالشــبهة ‪.»6/475‬‬\n\n\n\n\n‫توجيــه االتهــام للمدعــى عليــه بدخــول منــزلٍ لغــرض ســيء لالطــاع علــى‬\n‫أهلــه مــن خــال نوافــذ املنــزل‪ ،‬وذلــك بعــد تقــدم أحد املقيمني بشــكوى‬\n‫للجهــات املختصــة مفادهــا قيــام املدعــى عليــه بالدخــول لفنــاء منزلــه‬\n‫وقيامــه بالنظــر إلــى أســرته مــن خــال فتحــات النوافــذ‪ -‬طلــب املدعــي‬\n‫العــام احلكــم عليــه بعقوبــة تعزيريــة‪ ،‬والتشــديد عليــه يف العقوبــة‬\n\n\n                                                                                       ‫‪90‬‬\n\f     ‫لكثــرة ســوابقه وتكــرار اجلــرم املتهــم بــه‪ -‬بالبحــث عــن ســوابقه تبــن‬\n     ‫وجــود ســت ســوابق مســجلة عليــه أربــع ســوابق منهــا دخــول منــزل لغــرض‬\n     ‫ســيء وســابقة ســرقة وســابقة تلفــظ بألفــاظ غيــر الئقــة‪ -‬بعــرض دعــوى‬\n     ‫املدعــي العــام علــى املدعــى عليــه أنكرهــا ودفــع أنــه وقــف علــى البيــت‬\n     ‫خطــأ حينمــا كان يبحــث عــن بيـ ٍـت آخــر‪ -‬مت ســماع شــهادة الشــاهد‬\n     ‫وبعــرض الشــاهد وشــهادته علــى املدعــى عليــه كــذب الشــهادة ولــم‬\n     ‫يطعــن يف الشــاهد‪ ،‬ثــم جــرى تعديــل الشــهود‪ -‬جــرى االطــاع علــى‬\n     ‫إقــرار املدعــى عليــه حتقيق ـ ًا وبعرضــه عليــه أنكــره‪ -‬نظــر ًا إلنــكار‬\n     ‫املدعــى عليــه مــا نســبه إليــه املدعــي العــام‪ ،‬وإلقــراره املدعــى عليــه‬\n     ‫بدخــول حــوش املنــزل وألن رجــوع املقــر عــن إقــراره يف غيــر احلــدود‬\n     ‫ال يقبــل مــا جــاء يف شــهادة الشــاهد املدونــة ‪ ،‬ولســوابق املدعــى عليــه‬\n     ‫ومنهــا أربــع ســوابق بنفــس التهمــة ولضعــف مــا دفــع بــه املدعــى عليــه‬\n     ‫مــن أن ذهابــه كان للبحــث عــن منــزل صاحبــه‪ ،‬وألن مــا أقــدم عليــه‬\n     ‫املدعــى عليــه فعــل منكــر وتعــدٍ علــى احلرمــات التــي جــاءت الشــريعة‬\n     ‫اإلســامية بحفظهــا لــذا ثبتــت إدانــة املدعــى عليــه بدخــول منــزل بغيــر‬\n     ‫إذن أهلــه‪ ،‬وتوجــه التهمــة القويــة بــأن دخولــه كان لغــرض ســيء ومت‬\n     ‫احلكــم بتعزيــره بســجنه مــدة عشــرة أشــهر وجلــده مائتــي جلــدة علن ـ ًا‬\n     ‫مفرقــة علــى دفعــات ‪ ،‬علــى أن تكــون دفعتــن منهــا يف مــكان عــام يف‬\n     ‫نفــس احلــي الــذي وقعــت فيــه حادثــة املدعــى عليــه‪ -‬بعــرض احلكــم علــى‬\n     ‫املدعــي العــام قــرر اعتراضــه وطلــب رفعــه حملكمــة االســتئناف بــدون‬\n     ‫الئحــة اعتراضيــة وبعرضــه علــى املدعــى عليــه قــرر اعتراضــه وطلــب‬\n     ‫تســليمه نســخة مــن احلكــم لكتابــة اعتراضــه عليــه ‪ ،‬فأجيــب لطلبــه‪،‬‬\n                  ‫وبعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n‫‪91‬‬\n\f‫احلمــد هلل وحــده وبعــد‪ :‬فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n‫بينبــع ‪ ،‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بينبع‪/‬املســاعد برقــم ‪ 34168877‬وتاريــخ ‪1434/04/13‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 34852448‬وتاريــخ ‪1434/04/08‬ه ـ ففــي‬\n‫يــوم األربعــاء املوافق‪1434/05/01‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي العــام ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪).....‬‬\n‫واملكلــف مــن رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة ينبــع‬\n‫باخلطــاب رقــم ‪.....‬وتاريــخ ‪1432/4/11‬ه ـ وادعــى قائــا‪ :‬بصفتــي مدعيا‬\n‫عامــا بدائــرة التحقيــق واالدعــاء العــام أدعي على ‪ )40(.....‬عاما ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬عاطــل عــن العمــل ويســكن‬\n‫يف ‪.....‬قبــض عليــه بتاريــخ ‪1434/3/9‬ه ـ وأودع بســجن محافظــة ينبــع‬\n‫‪ ،‬وبالبحــث عــن ســوابقه تبــن وجــود ســت ســوابق مســجلة عليــه وهــي‬\n‫أربــع ســوابق دخــول منــزل لغــرض ســيء وســابقة ســرقة وســابقة التلفــظ‬\n‫بألفــاظ غيــر الئقــة ‪ ،‬حيــث أنــه بتاريــخ ‪1434/3/8‬ه ـ تقــدم الوافــد‪.....‬‬\n‫مصــري اجلنســية بشــكوى للجهــات األمنيــة تتضمــن قيــام املتهــم أعــاه‬\n‫بالدخــول لفنــاء منزلــه وقيامــه بالنظــر علــى أســرته مــن خــال فتحــات‬\n‫النوافــذ ‪ ،‬وباالنتقــال واملعاينــة ملنــزل املدعــي مت مشــاهدة ســيارة املتهــم‬\n‫متوقفــة مبســافة كيلــو ونصــف عــن منــزل املدعــي وهــي نــوع فــورد لونهــا‬\n‫أبيــض ‪ .‬وباســتجواب املتهــم ‪ :‬اعتــرف بأنــه دخــل ملنــزل املدعــي حيــث‬\n‫اشــتبه عليــه منــزل املدعــي أحــد أصدقائــه كان يــود زيارتــه وبســماع‬\n‫شــهادة ‪(..... :‬جــار املدعــي ) أفــاد بأنــه شــاهد املتهــم كثيــر ًا مــا يكــرر‬\n\n                                                                                       ‫‪92‬‬\n\f     ‫حضــوره لنفــس احلــي الــذي يســكن بــه ‪ ،‬وقــد ســبق أن ســأل املتهــم عــن‬\n     ‫تواجــده يف احلــي الــذي يســكن بــه فأفــاد بأنــه حضــر لزيــارة قريــب لــه ‪،‬‬\n     ‫ويف املرة األخيرة شــاهد املتهم أوقف ســيارته بعيد ًا عن ســكن املدعي‬\n     ‫وهــي نــوع ‪ ......‬تقريب ـ ًا وعندهــا صعــد الشــاهد لســطح منزلــه فشــاهد‬\n     ‫املتهــم يقــوم بالنظــر مــن خــال نوافــذ منــزل املدعــي وفتحــات مكيــف‬\n     ‫التبريــد فنــزل وقــام بالقبــض عليــه مبســاعدة جــاره املدعــي وقامــوا‬\n     ‫بتســليمه للدوريــات األمنيــة ‪ .‬وقــد انتهــى التحقيــق إلــى توجيــه االتهــام‬\n     ‫لــه بدخــول منــزل املدعــي لغــرض ســيء باالطــاع علــى أســرته مــن خــال‬\n     ‫نوافــذ املنــزل وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء يف شــهادة‬\n     ‫الشــاهد واملدونــة بصفحــة (‪ )5-4‬مبلــف التحقيــق املرفــق بالقضيــة ‪-2 .‬‬\n     ‫مــا جــاء يف أقــوال املتهــم واملدونــة بصفحــة (‪ )3-1‬مبلــف التحقيــق املرفــق‬\n     ‫بالقضيــة ‪ -3 .‬مــا جــاء يف محضــر االنتقــال واملعاينــة واملدونــة بصفحــة‬\n     ‫(‪ )3‬مبلــف االســتدالل املرفــق بالقضيــة ‪ .‬وحيــث إن مــا أقــدم عليــه املتهــم‬\n     ‫فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب مــا أســند إليــه واحلكــم عليــه‬\n     ‫بعقوبــة تعزيريــة رادعــه لــه ولغيــره‪ .‬والتشــديد عليــه يف العقوبــة لكثــرة‬\n     ‫ســوابقه وتكــرار اجلــرم املتهــم بــه (علم ـ ًا بــأن احلــق اخلــاص قــد انتهــى‬\n     ‫بالتنــازل ) هكــذا ادعــى‪ .‬وجــرى عــرض دعــوى املدعــي العــام علــى‬\n     ‫ا ‪ :‬مــا ذكــره املدعــي العــام يف دعــواه كلــه‬    ‫املدعــى عليــه فأجــاب قائـ ً‬\n     ‫غيــر صحيــح ‪ ،‬فقــد كنــت يف اليــوم املذكــور يف الدعــوى مدعــوا عنــد‬\n     ‫زميلــي ‪ .....‬وقــد ذهبــت للحــي الــذي يســكن فيــه للمــرة الثانيــة إال إنــي‬\n     ‫لــم أســتطيع الوصــول إلــى بيتــه ‪ ،‬وقــد ســبق أن ذهبــت معــه يف املــرة‬\n     ‫األولــى ‪ ،‬وقــد أوقفــت ســيارتي يف مــكان بعيــدٍ عــن البيــت وذهبــت‬\n     ‫للبحــث عــن البيــت علــى قدمـ ّـي إال إنــي وقفــت علــى بيـ ٍـت خطــأ وفــور أن‬\n\n\n‫‪93‬‬\n\f‫تبــن لــي ذلــك قمــت باالنصــراف فلحــق بــي صاحــب املنــزل وأمســكني‬\n‫يف الشــارع قريبـ ًا مــن بيتــه هكــذا أجــاب‪ .‬ثــم جــرى ســؤاله عــن ســوابقه‬\n‫؟ فقــال ‪ :‬إنهــا صحيحــة وقــد تبــت منهــا وأخــذت جزاءهــا هكــذا أجــاب‪.‬‬\n‫ولطلــب البينــة مــن املدعــي العــام رفعــت اجللســة‪ .‬ويف جلســة أخــرى حضــر‬\n‫املدعــي العــام واملدعــى عليــه وبســؤال املدعــي العــام عــن البينــة؟ قــال ‪:‬‬\n‫لــم حتضــر وأطلــب مهلــة ثانيــة إلحضارهــا فأجيــب إلــى طلبــه ورفعــت‬\n‫اجللســة لذلــك‪ .‬ويف جلســة أخــرى حضــر املدعــي العــام واملدعــى عليــه‬\n‫وبســؤال املدعــي العــام عــن البينــة؟ قــال‪ :‬لــم حتضــر وأطلــب مهلــة أخــرى‬\n‫إلحضارهــا فأجيــب إلــى طلبــه وعليــه جــرى رفــع اجللســة ‪ .‬ويف جلســة‬\n‫أخــرى حضــر املدعــي العــام واملدعــى عليــه وبســؤال املدعــي العــام عــن‬\n‫البينــة؟ أحضــر للشــهادة ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم (‪ ).....‬والــذي يعمــل عســكري يف الدفــاع املدنــي يف الهيئــة امللكيــة‬\n‫وبســؤاله عمــا لديــه مــن شــهادة؟ قــال‪ :‬أشــهد هلل تعالــى بــأن هــذا احلاضــر‬\n‫‪.....‬كان يكثــر مــن تكــرار احلضــور للحــي الــذي يســكن فيــه والــدي‬\n‫وقــد شــاهدته أكثــر مــن ثــاث مــرات ‪ ،‬وقــد مســكته قبــل هــذه‬\n‫املــرة يف نفــس احلــي أنــا وزمالئــي تقريب ـ ًا بعــد الســاعة الثانيــة عشــرة‬\n‫ا وكانــت يــداه عليهــا مــادة بيضــاء تشــبه مــادة البويــة التــي علــى‬    ‫لي ـ ً‬\n‫جــدران املنــازل وقلــت لــه‪ :‬أيــش عنــدك يف حارتنــا؟ فقــال إنــي يف زيــارة‬\n‫لشــخص ‪ ،‬وعندمــا ســألته عــن اســمه لــم يخبرنــي ‪ ،‬وبعــد فتــرة اتصــل‬\n‫بــي أصدقائــي وأخبرونــي أنهــم شــاهدوه يف احلــي وكان يوقــف ســيارته‬\n‫بعيــدا ‪ ،‬ثــم ذهــب ويف املــرة األخيــرة شــاهدت ســيارته مــن نــوع فورد أظن‬\n‫أن موديلهــا ‪1995‬م وصعــدت إلــى أعلــى منزلــي للبحــث عنــه فشــاهدته‬\n‫داخــل حــوش املدعــو‪ .....‬وهــو يســترق النظــر مــن الشــباك فنزلــت مــن‬\n\n\n                                                                                        ‫‪94‬‬\n\f     ‫أعلــى وكان قــد خــرج مــن احلــوش وأخــذ يجــري وكان صاحــب املنــزل‬\n     ‫قــد خــرج مــن النــادي فناديــت عليــه ثــم قبضنــا علــى املدعــو ‪.....‬واتصلنــا‬\n     ‫علــى الدوريــات ثــم هــرب منــا فركضنــا وراءه ومســكناه يف احلــارة‬\n     ‫وعنــد مســكي لــه أخــذ يتوســلني بــأن أســتر عليــه وأتركــه ثــم جــاءت‬\n     ‫الدوريــات وقبضــت عليــه ‪ ،‬هــذا مــا أشــهد به وبعرض الشــاهد وشــهادته‬\n     ‫علــى املدعــى عليــه قــال ‪ :‬أمــا الشــاهد فــا أعرفــه ‪ ،‬وأمــا شــهادته فغيــر‬\n     ‫صحيحــة ‪ ،‬فلــم أكــرر احلضــور للحــي ولــم أوقــف ســيارتي بعيـ ًـد ًا ‪ ،‬ولــم‬\n     ‫أدخــل حــوش املدعــو ‪.....‬أو أســترق النظــر إلــى داخل منزلــه هكذا قال‪،‬‬\n     ‫وعليــه ولطلــب معدلــن لشــاهد املدعــي العــام رفعــت اجللســة ‪ .‬ويف جلســة‬\n     ‫أخــرى حضــر املدعــي العــام واملدعــى عليــه وبســؤال املدعــي العــام عــن‬\n     ‫تعديــل الشــاهد ‪.....‬أحضــر معــه ‪ .....‬ســعودي اجلنســية مبوجــب الســجل‬\n     ‫املدنــي رقــم ‪.....‬و‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n     ‫وبســؤالهما عمــا لديهمــا حيــال الشــاهد املذكــور؟ أجــاب كل واحــد‬\n     ‫ا ‪ :‬أشــهد هلل تعالــى أن ‪.....‬ثقــة عــدل مرضــي الشــهادة وأقبــل‬   ‫منهمــا قائـ ً‬\n     ‫شــهادته لــي أو علــي ‪ ،‬وقــد عرفتــه بالصــدق واحملافظــة علــى الصــاة‪.‬‬\n     ‫هكــذا شــهدا ‪ .‬ثــم جــرى رفــع اجللســة لدراســة القضيــة ‪ .‬ويف جلســة‬\n     ‫أخــرى حضــر املدعــي العــام واملدعــى عليــه وجــرى الرجــوع للمعاملــة‬\n     ‫وفيهــا إقــرار املدعــى عليــه املــدون علــى ص (‪ )1‬لفــة (‪ )9‬وقــد تضمــن‬\n     ‫‪ « :‬أفيدكــم بأنــي كنــت ذاهــب إلــى منــزل زميلي‪.....‬وكنــت متواجــد‬\n     ‫معــه علــى زيارتــه وقمــت بالدخــول إلــى أحــد املنــازل حيــث اشــتبه لــي أنــه‬\n     ‫منــزل ‪.....‬حيــث فتــح بــاب احلــوش ودخلــت إلــى حــوش املنــزل ظنـ ًا منــي أنه‬\n     ‫منــزل ‪ « .......‬أ ‪ .‬ه ـ وبعــرض مــا جــاء يف اإلقــرار أعــاه علــى املدعــى عليــه‬\n     ‫قــال ‪ :‬ال أدري عــن ذلــك فقــد ذكــرت لهــم أنــي لــم أدخــل حــوش املنــزل‬\n\n\n‫‪95‬‬\n\f‫هكــذا قــال ‪ .‬وعليــه فبعــد االطــاع علــى دعــوى املدعــي العــام وإجابــة‬\n‫املدعــى عليــه ‪ ،‬ونظــر ًا إلنــكار املدعــى عليــه ملــا نســبه إليــه املدعــي‬\n‫العــام ‪ ،‬وإلقــرار املدعــى عليــه بدخــول حــوش املنــزل باإلقــرار املرصــود‬\n‫أعــاه وألن رجــوع املقــر عــن إقــراره يف غيــر احلــدود ال يقبــل كمــا قــرره‬\n‫أهــل العلــم ‪ ،‬جــاء يف كشــاف القنــاع ‪ « :‬وال يقبــل رجــوع املقــر عــن‬\n‫إقــراره لتعلــق حــق املقــر لــه باملقــر بــه إال فيمــا كان حــد ًا هلل تعالــى‬\n‫فيقبــل رجوعــه عنــه كمــا تقــدم يف مواضعــه ألن احلــد يــدرأ بالشــبهة‬\n‫‪ »6/475‬لذلــك فقــد ثبــت لــدي إدانــة املدعــى عليــه بدخــول منــزل بغيــر‬\n‫إذن أهلــه‪ ،‬وتوجــه التهمــة القويــة بــأن دخولــه كان لغــرض ســيء ملــا جــاء‬\n‫يف شــهادة الشــاهد املدونــة ‪ ،‬ولســوابق املدعــى عليــه ومنهــا أربــع ســوابق‬\n‫بنفــس التهمــة ولضعــف مــا دفــع بــه املدعــى عليــه مــن أن ذهابــه كان‬\n‫للبحــث عــن منــزل صاحبــه ‪ ،‬وألن مــا أقــدم عليــه املدعــى عليــه فعــل‬\n‫منكــر وتعــدٍ علــى احلرمــات التــي جــاءت الشــريعة اإلســامية بحفظهــا‬\n‫ولقــول النبــي صلــى اهلل عليــه وســلم ‪ « :‬مــن اطلــع يف بيــت قــوم بغيــر‬\n‫إذنهــم ‪ ،‬فقــد حــل لهــم أن يفقــؤوا عينــه « رواه مســلم ‪ ،‬لذلــك فقــد‬\n‫قــررت تعزيــر املدعــى عليــه للحــق العــام مبــا يلــي ‪ /1 :‬ســجنه ملــدة عشــرة‬\n‫أشــهر مــن تاريــخ إيداعــه الســجن بســبب هــذه القضيــة ‪ /2‬جلــده مئتــي‬\n‫جلــدة علنـ ًا مفرقــة علــى دفعــات ‪ ،‬كل دفعــة خمســون جلــدة وبــن كل‬\n‫دفعــة وأخــرى مــا ال يقــل عــن أســبوع علــى أن تكــون دفعتــن منهــا يف‬\n‫مــكان عــام يف نفــس احلــي الــذي وقعــت فيــه حادثــة املدعــى عليــه هــذا‬\n‫مــا ظهــر لــي وبــه حكمــت ‪ ،‬وبعــرض احلكــم علــى املدعــي العــام قــرر‬\n‫اعتراضــه وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة اعتراضيــة‬\n‫وبعرضــه علــى املدعــى عليــه قــرر اعتراضــه وطلــب تســليمه نســخة مــن‬\n\n\n                                                                                      ‫‪96‬‬\n\f     ‫احلكــم لكتابــة اعتراضــه عليــه ‪ ،‬فأجيــب لطلبــه وأفهــم أنــه ســيجري‬\n     ‫اســتدعاءه الســتالم نســخة مــن احلكــم وإفهامــه بتعليمــات االســتئناف‬\n     ‫وعليــه جــرى التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‪1434/6/6‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافق‪1434/08/06‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 10 : 15‬وفيهــا جــرى اإلطــاع على املعاملة بعد‬\n     ‫ورودهــا مــن محكمــة االســتئناف مبكــة املكرمــة برقــم ‪34852448‬‬\n     ‫يف ‪1434/7/18‬ه ـ مرفقــا بهــا قــرار الدائــرة اجلزائيــة السادســة برقــم‬\n     ‫‪ 34234470‬يف ‪1434/6/7‬هـ املتضمن بعد املقدمة ما نصه « وبدراسة‬\n     ‫القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا فضيلــة‬\n     ‫حاكمهــا ملالحظــة أن مــا حكــم بــه علــى املدعــى عليــه مــن ســجن وجلد‬\n     ‫كثيــر ال يتناســب مــع جرميتــه فعلــى فضيلتــه إعــادة النظــر يف حكمــه‬\n     ‫واهلل املوفــق « قاضــي اســتئناف ‪.....‬ختمــه وتوقيعــه وقاضــي اســتئناف‬\n     ‫‪.....‬ختمــه وتوقيعــه رئيــس الدائــرة ‪.....‬ختمــه وتوقيعــه ‪،‬عليــه أجيــب علــى‬\n     ‫مــا جــاء يف قــرار أصحــاب الفضيلــة وفقهــم اهلل بأنــه لــم يظهــر لــي بــأن‬\n     ‫احلكــم علــى املدعــى عليــه لقــاء مــا أقــدم عليــه كثيــر وال يتناســب مــع‬\n     ‫جرميتــه ذلــك أنــه ال يخفــى علــى شــريف علــم أصحــاب الفضيلــة أن مــا‬\n     ‫أقــدم عليــه املدعــى عليــه فيــه تعــدٍ علــى األعــراض التــي جــاءت الشــريعة‬\n     ‫اإلســامية بحفظهــا ‪ ،‬وهتــك للســتر الــذي جــاءت الشــريعة بصيانتــه‬\n     ‫وال بــد مــن احلــزم يف مثــل هــذا لكــي يأمــن النــاس علــى محارمهــم‬\n     ‫وأعراضهــم يف بيوتهــم ‪ ،‬وال ســيما أن للمدعــى عليــه خمــس ســوابق‬\n     ‫منهــا أربــع يف نفــس موضــوع الدعــوى ‪ ،‬مــا يوحــي بعــدم ارتــداع املدعــى‬\n     ‫عليــه وتأصــل اإلجــرام فيــه ‪ ،‬واحلاجــة ألخــذه باحلــزم والشــدة لذلــك فإنــه‬\n\n\n‫‪97‬‬\n\f‫لــم يظهــر لــي ســوى مــا أجريــت ‪ ،‬وال زلــت باقي ـ ًا علــى مــا حكمــت بــه‬\n‫‪ ،‬وقــررت إعــادة املعاملــة مــع القــرار بعــد هــذا اإلجــراء إلــى محكمــة‬\n‫االســتئناف لتقريــر مــا يلــزم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‪1434/8/6‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ -:‬نحــن‬\n‫قضاة الدائرة اجلزائية السادسة مبحكمة االستئناف مبكة املكرمة‬\n‫جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه احملكمــة بكتــاب‬\n‫فضيلــة رئيــس احملكمــة العامــة بينبــع املســاعد رقــم (‪)34852448‬‬\n‫وتاريــخ (‪1434/8/7‬هــ) املرفــق بهــا القــرار رقــم(‪ )34234470‬وتاريــخ‬\n‫(‪1434/6/7‬هــ) الصــادر مــن فضيلــة الشــيخ‪ ...../‬القاضــي باحملكمــة‬\n‫العامــة بينبــع‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪ ...../‬ســعودي‬\n‫اجلنســية ‪ ،‬املتهــم بدخــول منــزل شــخص لغــرض ســيء‪ ،‬احملكــوم‬\n‫فيــه مبــا دون باطنــه ‪ ،‬واملالحــظ عليــه بقــرار محكمــة االســتئناف‬\n‫رقم‪34267985‬وتاريخ‪1434/7/15‬ه ـ ‪ ،‬وبدراســة القــرار وصــورة‬\n‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم بعــد اجلــواب‬\n‫األخيــر‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آله وصحبه‬\n                                                                         ‫وســلم‬\n\n\n\n\n                                                                                   ‫‪98‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":90,"source_page_end":98,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bcf9daeef038826d8ffd2706e82a6d8ca13ba125e4b53cb0f6f52d67c6ddd3ba","normalized_text_hash":"1644e5ea7f652a3999f4738822324a288f1b8d09b71bd36cd1812f36d8db7622","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p90-34234470"},{"id":"190714d2-1227-5a7c-b4e3-646faa8e004a","document_type":"judgment","category":"judicial","subcategory":"general","title":"دخول منزل دون إذن صاحبه -خلوة غير شرعية -إسام املدعى عليه بعد ارتكاب اجلرمية -اعتناق اإلسام يسقط التعازير يف احلقوق العامة دون احلقوق اخلاصة -اإلسام يجب ما قبله.","document_number":"34246286","case_number":"34204648","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية مبوجب اخلطاب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/20","year":"1434","subject":"دخول منزل دون إذن صاحبه -خلوة غير شرعية -إسام املدعى عليه بعد ارتكاب اجلرمية -اعتناق اإلسام يسقط التعازير يف احلقوق العامة دون احلقوق اخلاصة -اإلسام يجب ما قبله.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34246286 :‬تاريخه‪1434/6/20 :‬هـ‬\n                        ‫رقم الدعوى‪34204648 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34303138‬تاريخه‪1434/8/23 :‬هـ‬\n\n\n     ‫دخــول منــزل دون إذن صاحبــه ‪ -‬خلــوة غيــر شــرعية ‪ -‬إســام املدعــى‬\n     ‫عليــه بعــد ارتــكاب اجلرميــة ‪ -‬اعتنــاق اإلســام يســقط التعازيــر يف‬\n      ‫احلقــوق العامــة دون احلقــوق اخلاصــة ‪ -‬اإلســام يجــب مــا قبلــه‪.‬‬\n\n\n\n\n     ‫ـاص قــال ‪:‬‬ ‫أن عمــرو بـ َـن العـ ِ‬    ‫‪ -1‬أن اإلســام يجــب مــا قبلــه ملــا ُروي مــن َّ‬\n     ‫هلل ع ـ َّز وجـ َّـل يف قلبــي اإلســا َم قــال أتيـ ُـت النبــي ص َّلــى ا ُ‬\n     ‫هلل‬                                                                            ‫( ملــا ألقــى ا ُ‬\n       ‫ُبايعــك يــا رســولَ ا ِ‬\n     ‫هلل‬                      ‫بايعنــي فبســط يـ َـده إلـ َّـي فقلـ ُـت ال أ ُ‬  ‫عليـ ِه وسـ َّل َم ل ُِي َ‬\n      ‫هلل ص َّلــى ا ُ‬\n     ‫هلل‬             ‫حتــى تغفـ َـر لــي مــا تقـ َّـدم مــن ذنبــي قــال فقــال لــي رســولُ ا ِ‬\n     ‫الذنوب‬\n        ‫ِ‬         ‫تـ ُّـب مــا قب َلها مــن‬              ‫عليـ ِه وسـ َّل َم يــا عمــرو أمــا علمـ َـت َّ‬\n                                          ‫أن الهجــر َة َ ُ‬\n          ‫ـوب )‪.‬‬\n             ‫أن اإلســا َم َي ُجـ ُّـب مــا كان قب َلــه مــن الذنـ ِ‬    ‫يــا عمــرو أمــا علمـ َـت َّ‬\n                               ‫‪ -2‬املادة رقم ( ‪ ) 195‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n\n     ‫اتهــام املدعــى عليــه بالدخــول إلــى منــزلٍ بغيــر إذن صاحبــه لغــرض ســيء‬\n     ‫وإقامــة عالقــة محرمــة مــع خادمتــه واخللــوة بهــا‪ ،‬وذلــك بعــد القبــض على‬\n     ‫املدعــى عليــه داخــل املنــزل‪ -‬طلــب املدعــي العــام احلكــم علــى املدعــى‬\n     ‫عليــه بعقوبــة تعزيريــة‪ -‬بعــرض دعــوى املدعــي العــام علــى املدعــى عليــه‬\n     ‫بواســطة املترجــم أقــر بعالقتــه غيــر الشــرعية مــع اخلادمــة وأنــه دخــل‬\n\n‫‪99‬‬\n\f‫معهــا يف غرفتهــا يف منــزل كفيلهــا‪ ،‬وقــرر أنــه محصــن وأنــه دخــل يف‬\n‫اإلســام بعــد هــذه القضيــة ‪ -‬ألن اإلســام يجــب مــا قبلــه‪ ،‬وألن اخللــوة‬\n‫غيــر الشــرعية باخلادمــة حـ ٌـق محــض هلل تعالــى بينمــا انتهــاك حرمــة‬\n‫املنــزل املذكــور يتعلــق بــه حـ ٌـق آلدمــي لذلــك كلــه فقــد ثبتــت إدانــة‬\n‫املدعــى عليــه بانتهــاك حرمــة املنــزل املذكــور يف الدعــوى بالدخــول‬\n‫فيــه ومت احلكــم بتعزيــره لقــاء ذلــك للحــق العــام بســجنه مــدة خمســة‬\n‫أشــهر وجلــده تســعني جلــدة مفرقــة علــى دفعتــن متســاويتني‪ .‬بعــرض‬\n‫احلكــم علــى الطرفــن قــرر املدعــى عليــه القناعــة وقــرر املدعــي العــام‬\n‫االعتــراض وطلــب رفــع احلكــم حملكمــة االســتئناف بالئحـ ٍة اعتراضية‬\n‫مقدمـ ًة منــه ف ُأجيــب لطلبــه ‪ -‬انتهــت مــدة االعتــراض ولــم يســتلم املدعــي‬\n‫العــام صــورة احلكــم ولــم يقــدم الئحتــه االعتراضيــة وعليــه فقــد ســقط‬\n‫حقــه يف تقدميهــا ومت رفــع احلكــم حملكمــة االســتئناف ومتــت املصادقــة‬\n                                                                  ‫علــى احلكــم‪.‬‬\n\n\n\n\n‫اجلزائيــة‬\n   ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة‬\n‫بالدمــام ويف يــوم االثنــن املوافــق‪ 1434/06/19‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 11 : 15‬وفيهــا قــدم املدعــي العــام ‪ ................‬دعــواه ضــد‬\n‫ا فيهــا ‪ :‬إنــه بتاريــخ ‪1434/4/17‬ه ـ تقــدم املواطــن‬   ‫املدعــى عليــه ‪.....‬قائـ ً‬\n‫‪..... /‬بشــكوى مفادهــا قيــام املدعــى عليــه بانتهــاك حرمــة منزلــه‬\n‫ودخولــه مــن غيــر إذنــه وقــد مت القبــض علــى املدعــى عليــه داخــل منــزل‬\n‫املدعــي يف نفــس يــوم البــاغ وبســماع أقــوال املدعــى عليــه أقــر بأنهــا‬\n‫املــرة األولــى التــي يقــوم فيهــا بالدخــول ملنــزل املدعــي وباســتجوابه أقــر‬\n\n                                                                                        ‫‪100‬‬\n\f      ‫بدخولــه منــزلَ املدعــي بغيــر إذن منــه وأفــاد أنــه قــام بالدخــول حملادثــة‬\n      ‫اخلادمــة املنزليــة وأنــه اختلــى بهــا وانتهــى التحقيــق إلــى اتهــام ‪.....‬بانتهــاك‬\n      ‫منــزل املدعــي بالدخــول فيــه بغيــر إذنــه لغــرض ســيء وإقامــة عالقــة‬\n      ‫محرمــة مــع خادمتــه املنزليــة واخللــوة بهــا وذلــك لألدلــة والقرائــن التاليــة‬\n      ‫‪ -1 :‬مــا جــاء يف محضــر اســتجوابه املرفــق لفــه ( ‪ -2. ) 6,5‬مــا جــاء يف‬\n      ‫محضــر ســماع أقوالــه املــدون علــى الصفحتــن رقــم ( ‪ ) 11,10‬مــن دفتــر‬\n      ‫االســتدالل املرفــق لفــه ( ‪ -3. ) 1‬مــا جــاء يف محضــر القبــض املرفــق لفــه‬\n      ‫( ‪ ) 2‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه‬\n      ‫شــرع ًا واطالــب بإثبــات مــا ُأســند إليــه شــرع ًا واحلكــم عليــه بعقوبــة‬\n      ‫تعزيريــة تزجــره وتــردع غيــره ( علم ـ ًا بــأن احلــق اخلــاص ال زال قائم ـ ًا )‬\n      ‫وبــاهلل التوفيــق ويف هــذه اجللســة حضــر املدعــى عليــه ‪.....‬فلبينــي اجلنســية‬\n      ‫مبوجــب رخصــة إقامــة صــادرة مــن اخلبــر املــدون بهــا الرقــم ‪.....‬وبعــرض‬\n      ‫ا‪:‬‬ ‫دعــوى املدعــي العــام عليــه بواســطة مترجــم احملكمــة ‪.....‬أجــاب قائـ ً‬\n      ‫الصحيح أن هذه اخلادمة ال متت لي بصل ٍة شرعية وقد تعرفت عليها عن‬\n      ‫طريــق ُأختهــا يف الفلبــن وحصــل بينــي وبني اخلادمة املذكــورة اتصاالت‬\n      ‫هاتفيــة وقــد طلبــت منــي احلضــور ملنــزل كفيلهــا لكــي آخــذ منهــا مبلــغ‬\n      ‫مالــي وأقــوم بتحويلــه إلــى أهلهــا يف الفلبــن وبالفعــل حضــرت للمنــزل‬\n      ‫املذكــور وفتحــت لــي اخلادمــة البــاب ودخلــت يف غرفــة اخلادمــة بالــدور‬\n      ‫األرضــي ولــم يحصــل بينــي وبينهــا شــيء ســوى أنني حتدثــت معها وكان‬\n      ‫ا وكان بعــض أهــل البيــت موجوديــن ولكــن‬              ‫بــاب الغرفــة مفتــوح قلي ـ ً‬\n      ‫لــم يرونــي وأثنــاء ذلــك رأتنــي صاحبــة املنــزل وقــام ابنهــا مبســكي ومت‬\n      ‫إبــاغ الشــرطة علمـ ًا أننــي محصــن متــزوج وقــد دخلــت يف اإلســام بعــد‬\n      ‫هــذه القضيــة وتســميت باســم ‪.....‬هــذه إجابتــي ‪ .‬وبســؤال املدعــي العــام‬\n\n\n‫‪101‬‬\n\f‫هــل لديــه مزيــد بينــة علــى الدعــوى قــال ليس لدي ســوى مــا ورد يف الئحة‬\n‫الدعــوى وأوراق املعاملــة فنظــر ًا ملــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬\n‫أقــر املدعــى عليــه بجــود عالقـ ٍة هاتفيــه مــع اخلادمــة املذكــورة ودخولــه‬\n‫ـاك حلرمــة هــذا‬  ‫لغرفــة اخلادمــة باملنــزل املذكــور وحيــث أن يف ذلــك انتهـ ٌ‬\n‫املنــزل وبعــد االطــاع علــى طيــات املعاملــة وحيــث قــرر املدعــى عليــه‬\n‫أن‬\n ‫دخولــه يف اإلســام وحيــث أن اإلســام يجــب مــا قبلــه وملــا ُروي مــن َّ‬\n‫ـام قــال‬                                    ‫ُ‬\n         ‫ـاص قــال ‪ ( :‬ملــا ألقــى اهلل عـ َّـز وجــلَّ يف قلبــي اإلسـ َ‬  ‫عمــرو بـ َـن العـ ِ‬\n                                                                     ‫أتيـ ُـت النبــي ص َّلــى ُ‬\n                                         ‫اهلل علي ـ ِه وس ـل ََّم ل ُِي َ‬\n‫بايعنــي فبســط يـ َـده إلـ َّـي فقلـ ُـت ال‬\n‫هلل حتــى تغفـ َـر لــي مــا تقـ َّـدم مــن ذنبــي قــال فقــال لــي‬                       ‫ُأ ُ‬\n                                                                      ‫بايعــك يــا رســولَ ا ِ‬\n‫تـ ُّـب‬\n      ‫أن الهجــر َة َ ُ‬                                                ‫هلل ص َّلــى ُ‬\n                      ‫اهلل عليـ ِه وسـل ََّم يــا عمــرو أمــا علمـ َـت َّ‬        ‫رســولُ ا ِ‬\n‫ـام َي ُجـ ُّـب مــا كان‬\n                     ‫أن اإلسـ َ‬   ‫ـوب يــا عمــرو أمــا علمـ َـت َّ‬\n                                                                ‫مــا قب َلهــا مــن الذنـ ِ‬\n‫ـوب ) وحيــث أن اخللــوة غيــر الشــرعية باخلادمــة املذكــورة‬      ‫قب َلــه مــن الذنـ ِ‬\n‫حـ ٌـق محــض هلل تعالــى بينمــا انتهــاك حرمــة املنــزل املذكــور يتعلــق بــه‬\n‫حـ ٌـق آلدمــي لذلــك كلــه فقــد قــررت مــا يلــي أوالً‪ -‬ثبــت لــدي إدانــة‬\n‫املدعــى عليــه بانتهــاك حرمــة املنــزل املذكــور يف الدعــوى بالدخــول فيــه‬\n‫ـداء‬\n‫وقــررت تعزيــره لقــاء ذلــك للحــق العــام بســجنه ملــدة خمســة أشــهر ابتـ ً‬\n‫مــن تاريــخ إيقافــه وجلــده تســعني جلــدة مفرقــة علــى دفعتــن متســاويتني‬\n‫بــن كل دفعــة وأخــرى مــا ال يقــل عــن خمســة عشــر يومــا ‪ .‬ثانيـاً‪ -‬ثبــت‬\n‫لــدي إدانــة املدعــى عليــه باالختــاء احملــرم مــع امــرأ ٍة ال متــت لــه بصلــة‬\n‫شــرعية وال أرى معاقبتــه علــى ذلــك ملــا ذكــره مــن دخولــه يف اإلســام‬\n‫ـات أعــاه وبذلــك أجمــع حكمــت وبعــرض‬                ‫ومــا مت ذكــره مــن حيثيـ ٍ‬\n‫احلكــم علــى الطرفــن قــرر املدعــى عليــه بواســطة املترجــم آنــف‬\n‫الذكــر القناعــة وقــرر املدعــي العــام االعتــراض وطلــب رفــع احلكــم‬\n\n\n                                                                                                   ‫‪102‬‬\n\f      ‫حملكمــة االســتئناف بالئح ـ ٍة اعتراضيــة مقدم ـ ًة منــه ف ُأجيــب لطلبــه‬\n      ‫وجــرى إفهامــه أن عليــه احلضــور يــوم الثالثــاء ‪1434/6/20‬ه ـ الســتالم‬\n      ‫صــورة مــن احلكــم وأنــه يف التاريــخ املذكــور ســوف يتــم إيــداع القــرار‬\n      ‫ملــف الدعــوى وســوف يكــون ذلــك اإليــداع مجريـ ًا مليعــاد الثالثــن يومـ ًا‬\n      ‫يقــدم خاللهــا الئحتــه االعتراضيــة وأنــه مبضيهــا دون تقــدمي الالئحــة‬\n      ‫ويرفــع احلكــم حملكمــة االســتئناف‬          ‫ســوف يســقط حقــه يف تقدميهــا ُ‬\n      ‫بدونهــا فامتثــل واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n      ‫وســلم احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء املوافق‪1434/07/25‬ه ـ‬\n      ‫أفتتحــت اجللســة وقــد انتهــت مــدة االعتــراض املنصــوص عليهــا يف املــادة‬\n      ‫رقــم ( ‪ ) 194‬مــن نظــام اإلجــراءات اجلزائيــة ولــم يســتلم املدعــي العــام‬\n      ‫صــورة احلكــم ولــم يقــدم الئحتــه االعتراضيــة وعليــه فقــد ســقط حقــه‬\n      ‫ـاء علــى املــادة‬\n                      ‫يف تقدميهــا وســوف ُيرفــع احلكــم حملكمــة االســتئناف بنـ ً‬\n      ‫رقــم ( ‪ ) 195‬مــن نظــام اإلجــراءات اجلزائيــة واهلل املوفــق وصلــى اهلل‬\n                                            ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم األربعــاء املوافق‪1434/10/14‬ه ـ فتحــت‬\n      ‫اجللســة وقــد وردت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n      ‫مبوجــب اخلطــاب رقــم ‪ 342010273‬يف ‪1434/09/15‬ه ـ وبرفقهــا‬\n      ‫قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة الثانيــة مبحكمــة‬\n      ‫االســتئناف باملنطقــة الشــرقية رقــم ‪ 34303138‬يف ‪1434/08/23‬ه ـ‬\n      ‫املتضمــن املصادقــة علــى احلكــم لــذا جــرى إحلاقــه واهلل املوفــق وصلــى‬\n                                                     ‫اهلل علــى نبينــا محمــد وآلــه وســلم‬\n\n\n\n\n‫‪103‬‬\n\f104\n\f105\n\f106\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":99,"source_page_end":106,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d8f37f0bb0040d713f0f53bc2af456059673a2f480dcfbf1a8f76e0b3042d7f6","normalized_text_hash":"931947143ee7b2665a2944fc2f01cf1e9bd710a6c55509f4b8452e2b49d8fc2f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p99-34246286"},{"id":"2636714e-f068-5983-bd0e-bd6f9dd7a8a6","document_type":"judgment","category":"judicial","subcategory":"general","title":"حرابة -لواط -ارتكاب فاحشة اللوط بحدث -اعتداء بالضرب -إنكار املدعى عليه -حتليل حمض نووي -عدم ثبوت -رد طلب إثبات احلرابة -عدم وجود سوابق قضائية -توجه الشبهة املوجبة للتعزير بالسجن واجللد.","document_number":"34261554","case_number":"341961","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بجازان كال من","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/8","year":"1434","subject":"حرابة -لواط -ارتكاب فاحشة اللوط بحدث -اعتداء بالضرب -إنكار املدعى عليه -حتليل حمض نووي -عدم ثبوت -رد طلب إثبات احلرابة -عدم وجود سوابق قضائية -توجه الشبهة املوجبة للتعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34261554 :‬تاريخه‪1434/7/8 :‬هـ‬\n                          ‫رقم الدعوى‪341961 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34370126‬تاريخه‪1434/11/25 :‬هـ‬\n\n\n      ‫حرابــة ‪ -‬لــواط ‪ -‬ارتــكاب فاحشــة اللــوط بحــدث ‪ -‬اعتــداء بالضــرب‬\n      ‫‪ -‬إنــكار املدعــى عليــه ‪ -‬حتليــل حمــض نــووي ‪ -‬عــدم ثبــوت ‪ -‬رد طلــب‬\n      ‫إثبــات احلرابــة ‪ -‬عــدم وجــود ســوابق قضائيــة ‪ -‬توجــه الشــبهة املوجبــة‬\n                                                    ‫للتعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n      ‫‪ -1‬اتفــاق العلمــاء علــى مشــروعية التعزيــر لإلمــام « مجمــوع الفتــاوي‬\n                                                                               ‫‪.»402/35‬‬\n      ‫‪ -2‬التعزيــر «واجــب يف كل معصيــة ال حــد فيهــا وال كفــارة» كشــاف‬\n                                                                      ‫القناع (‪.)3027/5‬‬\n      ‫‪« -3‬املعصيــة تفتقــر إلــى مــا مينــع مــن فعلهــا فــإذا لــم يجــب فيهــا حــد‬\n      ‫وال كفــارة وجــب أن يشــرع فيهــا التعزيــر ليتحقــق املانــع مــن فعلهــا»‬\n                                                        ‫كشــاف القنــاع (‪.)3027/5‬‬\n      ‫‪« -4‬التعزيــر يكــون بالضــرب واحلبــس والصفــع والتوبيــخ والعــزل عــن‬\n                                             ‫الواليــة» كشــاف القنــاع (‪.)3029/5‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه باعتدائــه علــى‬\n      ‫حــدث وفعــل الفاحشــة بــه بالقــوة وطلــب إثبــات مــا أســند إليــه واحلكــم‬\n\n‫‪107‬‬\n\f‫عليــه بحــد احلرابــة حيــث تقــدم أحــد املواطنــن ببــاغ للشــرطة بــأن ابنــه‬\n‫احلــدث (‪ )16‬عامــا تعــرض للضــرب وفعــل فاحشــة قــوم لــوط بــه مــن قبــل‬\n‫املدعــى عليــه فجــرى البحــث عنــه وتبــن بأنــه هــارب وقــد قــام بتســليم‬\n‫نفســه للشــرطة الحقــا ‪ ،‬شــوهدت آثــار الضــرب علــى جســم املجنــي‬\n‫عليــه وأفــاد بــأن املدعــى عليــه صــوره وهــو عــاري بجوالــه ثــم أصبــح‬\n‫يبتــزه بالصــور وأنــه علــى عالقــة قدميــة معــه وفعــل بــه الفاحشــة عــدة‬\n‫مــرات ‪ ،‬أنكــر املدعــى عليــه فعــل الفاحشــة بــه وتصويــره وهروبــه وقــرر‬\n‫بــأن الصحيــح بأنــه تضــارب معــه خلــاف مالــي واصطلــح معــه يف يومهــا‬\n‫‪ ،‬بعــرض مــا تضمنــه تقريــر األدلــة اجلنائيــة املتضمــن فحــص التلوثــات‬\n‫املنويــة املرفوعــة مــن ســراويل املجنــي عليــه عبــر تقنيــة احلمــض النــووي‬\n‫(‪ )DNA‬وثبــوت بــأن هــذه التلوثــات عائــدة لــه أجــاب بأنــه احتلــم ليلتهــا‬\n‫وبقــي آثــار االحتــام يف ســراويله وقــام بلبســها بعــد الســباحة ‪ ،‬جــرى‬\n‫ســؤال املدعــي العــام عــن البينــة فقــرر بأن بينتــه األوراق املرفقــة باملعاملة‬\n‫‪ ،‬عليــه وإلنــكار املدعــى عليــه ولعــدم قيــام البينــة املوصلــة وملــا احتــف‬\n‫الدعــوى مــن قرائــن كاختفائــه عــن األنظــار بعــد االعتــداء عليــه ومــا‬\n‫تضمنــه تقريــر األدلــة اجلنائيــة وفحــص احلمــض النــووي وآثــار االعتــداء‬\n‫اجلســمي علــى املجنــي عليــه وإقــراره بوجــود عالقــة حــب قدميــة والتواجــد‬\n‫يف املســبح ‪ ،‬عليــه وألن مــا اتهــم بــه عمــل محــرم وضــرب مــن ضــروب‬\n‫اإلفســاد يف األرض ‪ ،‬والتفــاق العلمــاء علــى مشــروعية التعزيــر ‪ ،‬ونظــرا‬\n‫لعــدم وجــود ســوابق عليــه وملجمــوع مــا تقــدم فقــد قــررت احملكمــة عــدم‬\n‫ثبــوت إدانــة املدعــى عليــه مبــا يوجــب إقامــة حــد احلرابــة علــى املدعــى‬\n‫عليــه مــع توجــه التهمــة املوجبــة للعقوبــة التعزيريــة بحقــه وحكمــت‬\n‫بصــرف النظــر عــن دعــوى املدعــي العــام وطلبــه إقامــة حــد احلرابــة علــى‬\n\n\n                                                                                       ‫‪108‬‬\n\f      ‫املدعــى عليــه‪ ،‬وتعزيــر املدعــى عليــه بالســجن ثــاث ســنوات ابتــداء مــن‬\n      ‫تاريــخ إيقافــه يف هــذه القضيــة وتعزيــر املدعــى عليــه بجلــده ثالثمئــة‬\n      ‫جلــدة مفرقــة علــى دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة‬\n      ‫والتــي تليهــا أســبوع وقــرر املدعــي العــام واملدعــى عليــه االعتــراض علــى‬\n                  ‫احلكــم بالئحــة‪ ،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلدينــا نحــن القضــاة باحملكمــة العامــة‬\n      ‫بجــازان كال مــن‪...........‬و‪ ...........‬و‪ ...........‬وبنــاء علــى املعاملــة احملالــة‬\n      ‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بجــازان برقــم ‪341961‬‬\n      ‫وتاريــخ ‪1434/01/03‬ه ـ واملقيــدة باحملكمــة برقــم ‪ 341213‬وتاريــخ‬\n      ‫‪1434/01/03‬ه ـ ففــي يــوم األحــد املوافــق ‪1434/02/ 08‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪09 : 30‬وفيهــا حضــر املدعــي العــام املكلــف باالدعــاء‬\n      ‫مــن فضيلــة رئيــس فــرع هيئــة التحقيــق واالدعــاء العــام بجــازان مبوجــب‬\n      ‫التعميــد رقــم ‪...........‬وتاريــخ ‪1433/2/2‬ه ـ ولــم يحضــر املدعــى‬\n      ‫عليــه‪ ...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)...........‬‬\n      ‫‪ ،‬فقــررت ســماع وتدويــن دعــوى املدعــي العــام اســتنادا للمــادة (‪)141‬‬\n      ‫مــن نظــام اإلجــراءات اجلزائيــة ‪ .‬وبســؤال املدعــي العــام عــن دعــواه ادعــى‬\n      ‫ا ‪( :‬بصفتــي مدعيـ ًا عامـ ًا بدائــرة االدعــاء العام لفــرع الهيئة مبنطقة‬       ‫قائـ ً‬\n      ‫جــازان أدعــي علــى املذكــور أعــاه بتاريــخ ‪1431/12/17‬ه ـ تقــدم‬\n      ‫املواطــن‪........... /‬ببــاغ لشــرطة محافظــة ‪ ..........‬يفيــد فيــه بتعــرض ابنــه‬\n      ‫احلــدث (‪ )...........‬البالــغ مــن العمــر (‪ 16‬ســنة) للضــرب وفعــل فاحشــة‬\n      ‫اللــواط بــه مــن قبــل املدعــي عليــه عندهــا جــرى البحــث عنــه وتبــن أنــه‬\n\n‫‪109‬‬\n\f‫غيــر موجــود وأنــه هــارب ولــم يتم القبض عليه إال بتاريخ ‪1433/4/11‬هـ‬\n‫حيــث ســلم نفســه للشــرطة‪ .‬مبعاينــة جســم املجنــي عليــه (‪ )...........‬مــن‬\n‫قبــل الشــرطة بتاريــخ ‪1431/12/17‬ه ـ شــوهدت آثــار ضــرب خلــف‬\n‫ظهــره ويف كلتــا يديــه واعــد محضــر ًا بذلــك ‪ .‬أوقــف املدعــي عليــه‬\n‫اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬كــون قضيتــه موجبــة للتوقيــف‬\n‫بســماع أقــوال احلــدث (‪ )...........‬ذكــر أنــه ذهــب مــع املدعــي عليــه يف‬\n‫ســيارته نــوع (‪ ) ...........‬وذلــك حلــوش يف قريــة (‪ )...........‬وذلــك قبــل شــهر‬\n‫مــن البــاغ ‪ ،‬واعتــدى عليــه املدعــي عليــه بالضــرب وخلــع مالبســه‬\n‫وصــوره وهــو عــاري بجــوال نــوع (‪ )........‬وقــد حــاول الصيــاح ولكــن دون‬\n‫جــدوى لعــدم وجــود أي شــخص‪ ،‬ثــم بعدهــا صــار يبتــزه بتلــك الصــور‬\n‫وقــد تقابــا يــوم األحــد املوافــق ‪1431/10/15‬ه ـ وتخاصمــا بخصــوص‬\n‫ذلــك‪ ،‬كمــا ذكــر أنــه يف متــام الســاعة العاشــرة مــن يــوم االثنــن املوافــق‬\n‫‪1431/12/16‬ه ـ وعنــد خروجــه مــن منــزل جدتــه قابــل املدعــي عليــه‬\n‫وحــاول أن يرضيــه فطلــع معــه يف الســيارة وذهبــا ملطعــم ‪...........‬ثــم بعدها‬\n‫جلســا يتجــوالن يف شــوارع محافظــة (‪ )...........‬ثــم توقــف بــه املدعــي عليــه‬\n‫خلــف مســبح وضربــه بسلســلة علــى أنحــاء جســمه وأقفــل أبــواب الســيارة‬\n‫ثــم خلــع مالبســه وفعــل بــه الفاحشــة بإيــاج وبعــد االنتهــاء هــدده بنشــر‬\n‫صــوره إن أخبــر أحــد ًا بذلــك ‪ ،‬كمــا أفــاد أن العالقــة بينــه وبــن املدعــي‬\n‫عليــه قدميـ ًا كانــت عالقــة حــب يف البدايــة وقــد عمــل بــه املدعــي عليــه‬\n‫الفاحشــة عــدة مــرات وصــادق علــى أقوالــه ‪ .‬وباســتجواب املدعــي عليــه‬\n‫(‪ )......‬اعتــرف بضربــه للمجنــي عليــه وأنكــر فعــل الفاحشــة بــه أو‬\n‫تصويــره ‪ ،‬وذكــر أن جوالــه نــوع (‪ ).....‬ويوجــد لديــه جــوال آخــر نــوع‬\n‫(‪ ).....‬وقــد باعــه ‪ ،‬ومبواجهتــه مبــا ورد يف تقريــر (‪ )DNA‬مــن عائديــه‬\n\n\n                                                                                         ‫‪110‬‬\n\f      ‫بعــض التلوثــات املنويــة لــه ذكــر أنــه كان يف ذلــك اليــوم نائــم وقــد‬\n      ‫احتلــم يف املنــزل ثــم ذهــب للمســبح دون أن يغتســل وســبح هــو واملجنــي‬\n      ‫عليــه يف املســبح ثــم قــام املجنــي عليــه بلبــس ســرواله القصيــر باخلطــأ‪،‬‬\n      ‫ومبواجهتــه حــول تهربــه ألكثــر مــن ســنة وثالثــة أشــهر ذكــر أنــه جلــس‬\n      ‫فتــرة ثالثــة أشــهر يف جــدة يبحــث عــن وظيفــة كمــا أن والــده جــرى عليه‬\n      ‫حــادث وبقــي بجــواره حلــن تعافيــه وال يعلــم عــن كونــه مطلــوب للشــرطة‬\n                                                                    ‫وصــادق علــى أقوالــه ‪.‬‬\n      ‫بالكشــف علــى احلــدث املجنــي عليــه (‪ )...........‬ورد التقريــر الطبــي‬\n      ‫الصادر من مستشفى …‪ .‬العام برقم (‪ )...........‬وتاريخ ‪1431/12/17‬هـ‬\n      ‫املتضمــن (وجــود آثــار لعــض أســنان علــى الفخــذ األميــن واأليســر وعلــى‬\n      ‫الظهــر والذراعــن ‪ ،‬وآثــار للكمــة باجلانــب األيســر مــن الوجــه ‪،‬‬\n      ‫وســحجة ســطحية بالشــرج ‪ ،‬وال يوجــد دم أو آثــار إلفــرازات أخــرى)‬\n      ‫‪.‬وببعــث املالبــس وعينــات املســحات لألدلــة اجلنائيــة ‪ .....‬باخلطــاب رقــم‬\n      ‫‪ ...........‬وتاريــخ ‪1431/12/17‬ه ـ لفحصهــا فــورد التقريــر رقــم (‪...........‬‬\n      ‫) املتضمــن ((تطابــق األمنــاط الوارثيــة للعينــات (تلوثــات منويــة و خاليــا‬\n      ‫طالئيــة) بالعينــات الــواردة للفحــص ممــا يثبــت أنهــا مــن مصــدر واحــد))‬\n      ‫وعلــى ضــوء ذلــك مت طلــب عينــات دم قياســية مــن املجنــي عليــه و املدعــي‬\n      ‫عليــه ملقارنتهــا بهــذه النتيجــة فجــرى بعــث تلــك العينــات ‪(( -‬يتبــع)) وورد‬\n      ‫التقريــر رقــم (‪ )...........‬املتضمــن (تطابــق األمنــاط الوراثيــة لعينــة الــدم‬\n      ‫القياســية للفحــص مــع عينــات التلوثــات املنويــة والتــي صــدر بحقهــا‬\n      ‫التقريــر الفنــي رقــم (‪ )...........‬ممــا يثبــت أن املدعــي عليــه (‪ )...........‬هــو‬\n      ‫مصــدر تلــك التلوثــات املنويــة ‪.‬وقــد أســفر التحقيــق مــع املدعــي عليــه عــن‬\n      ‫توجيــه االتهــام للمدعــى عليــه باعتدائــه بالضــرب وفعــل الفاحشــة بالقــوة‬\n\n\n‫‪111‬‬\n\f‫باحلــدث (‪...........‬وحيــث إن مــا أقــدم عليــه املدعــي عليــه وهــو بكامــل‬\n‫ويعـ ّـد ضرب ـ ًا‬\n               ‫أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ُ‬\n‫مــن ضــروب احلرابــة واإلفســاد يف األرض وانتهــاك ًا ألعــراض املســلمني‬\n‫علــى ســبيل الغلبــة والقهــر لــذا أطلب‪/‬إثبات ما أســند إليــه واحلكم عليه‬\n‫بحــد احلرابــة الــوارد يف اآليــة الكرميــة رقــم (‪ )33‬مــن ســورة املائــدة يف‬\n‫ضــوء قــرار هيئــة كبــار العلمــاء رقــم (‪ )85‬يف ‪1401/11/11‬هــ‪( ،‬علمـ ًا‬\n‫بــأن احلــق اخلــاص ال زال قائمــا)‪ .‬هكــذا ادعــى ‪ .‬فقــررت رفــع اجللســة‬\n‫لطلــب املدعــى عليــه وعــرض دعــوى املدعــي العــام عليــه وســماع اإلجابــة‬\n‫‪ .‬ويف يــوم االثنــن املوافــق ‪143/04/01‬ه ـ افتتحــت اجللســة الســاعة ‪00‬‬\n‫‪ 10 :‬وفيهــا حضــر املدعــي العــام وحضــر املدعــى عليــه وبعــرض دعــوى‬\n‫ا ‪ ( :‬ما ذكــره املدعي العام‬     ‫املدعــي العــام علــى املدعــى عليــه أجــاب قائـ ً‬\n‫يف دعــواه غيــر صحيــح جملــة وتفصيــا والصحيــح أننــي قمــت مبضاربــة‬\n‫املجنــي عليــه أثــر خــاف مــادي وقــد قمــت بالصلــح معــه يف يومهــا ومــا‬\n‫ذكــره مــن وجــود حيوانــات منويــة فذلــك كونــي احتلمــت ومازالــت آثــار‬\n‫االحتــام يف ســروالي وقــد قــام بلبــس ســروالي بعــد الســباحة ولــم أقــم‬\n‫بالهــرب وال التخفــي وإمنــا كنــت مــع والــدي ملرافقتــه أثنــاء مرضــه )‪.‬‬\n‫هكــذا أجــاب ‪ .‬وبســؤال املدعــي العــام عــن بينتــه ‪ .‬قــال بينتــي مــا يف‬\n‫أوراق املعاملــة ‪ .‬فجــرى االطــاع علــى ‪ -1 :‬التقريــر الطبــي ‪ -2 .‬التقريــر‬\n‫الفنــي‪ -3 .‬أقــوال املدعــى عليــه‪ -4 .‬محاضــر املعاينــة ‪ .‬وبعــرض ذلــك‬\n‫علــى املدعــى عليــه قــال ‪ :‬أمــا التقريــر الطبــي فمــا ورد فيــه هــو نتيجــة‬\n‫املضاربــة وال أذكــر أنــي قــد قمــت بعــض املجنــي عليــه‪ .‬وأمــا التقريــر‬\n‫الفنــي فذلــك نتيجــة لبــس املجنــي عليــه ملالبســي التــي بهــا آثــار احتــام‬\n‫‪ .‬وأمــا أقوالــي فصحيــح أنــي ذهبــت للمســبح مــع املجنــي عليــه لغــرض‬\n\n\n                                                                                        ‫‪112‬‬\n\f      ‫الســباحة لكونــه صاحــب لــي منــذ زمــن وقــد اختلفــت معــه لكونــه أخذ‬\n      ‫مــن فلوســي ودفــع لصاحــب املســبح ‪ .‬ثــم حصلــت املضاربــة بعــد ذلــك‬\n      ‫‪ .‬هكــذا أجــاب ‪ .‬فجــرى ســؤال املدعــي العــام هــل لديــه مزيــد بينــة ‪.‬‬\n      ‫فقــال ليــس لــدي ســوى مــا ذكــرت يف أوراق املعاملــة ‪ .‬فقــرر رفــع اجللســة‬\n      ‫لدراســة القضيــة والتأمــل ‪ .‬ويف يــوم االثنــن املوافــق‪ 1434/04/29‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة (‪ )10:15‬لدينــا نحــن القضــاة يف احملكمــة‬\n      ‫العامــة بجــازان ‪..........‬و‪ ...........‬ونظــر ًا النتقــال فضيلــة الشــيخ ‪...........‬‬\n      ‫لقضــاء احملكمــة اجلزائيــة بالدمــام وعــدم مباشــرة خلــف لــه فقــد قررنــا‬\n      ‫التوقــف عــن إكمــال نظــر هــذه القضيــة مؤقت ـ ًا حلــن إعــادة تشــكيل‬\n      ‫أعضــاء الدوائــر اجلنائيــة املشــتركة ولألهميــة جــرى تدويــن ذلــك ‪ .‬ويف‬\n      ‫يــوم األربعــاء املوافــق ‪1434/07/05‬ه ـ افتتحــت اجللســة عنــد الســاعة‬\n      ‫(‪ )11:00‬وفيهــا حضــر املدعــي العــام واملدعــى عليــه وقــد جــرى اطــاع‬\n      ‫فضيلــة الشــيخ املشــارك ‪...........‬علــى مــا مت ضبــط ســابقا ‪ ،‬وبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة ‪ ،‬وجلميــع مــا قــرره الطرفــان ونظــرا‬\n      ‫ألن املدعــى عليــه أنكــر مــا جــاء يف هــذه الدعــوى وأنــه غيــر صحيــح‬\n      ‫ا ولعــدم قيــام البينــة املثبتــة لصحــة الدعــوى وملــا احتــف‬      ‫جملــة وتفصي ـ ً‬\n      ‫بوقائــع هــذه الدعــوى مــن قرائــن متضافــرة منهــا اختفــاؤه عــن األنظــار‬\n      ‫بعــد االعتــداء ‪ ،‬و مــا ورد يف التقريــر الطبــي وتطابــق األمنــاط الوراثيــة ‪،‬‬\n      ‫وآثــار االعتــداء علــى املجنــي عليــه ‪ ،‬وإقــراره بوجــود عالقــة حــب حتقيقــا‬\n      ‫‪ ،‬والتواجــد معــه يف املســبح ‪ .‬ونظــر ًا ألن هــذا العمــل يعــد يف أصلــه‬\n      ‫ا محرمــا وهــو نــوع مــن اإلفســاد يف األرض ‪ .‬والتفــاق العلمــاء علــى‬         ‫عمـ ً‬\n      ‫مشــروعية التعزيــر لإلمــام ( مجمــوع الفتــاوى ‪ )402/35‬وألنــه واجــب‬\n      ‫يف كل معصيــة ال حــد فيهــا وال كفــارة ألن املعصيــة تفتقــر إلــى مــا‬\n\n\n‫‪113‬‬\n\f‫مينــع مــن فعلهــا فــإذا لــم يجــب فيهــا حــد وال كفــارة وجــب أن يشــرع‬\n‫فيهــا التعزيــر ليتحقــق املانــع مــن فعلهــا (كشــاف القنــاع ‪ )121/6‬وألن‬\n‫التعزيــر يكــون بالضــرب واحلبــس والصفــع والتوبيــخ والعــزل عــن الوالية‬\n‫(كشــاف القنــاع ‪ )134/6‬ونظــر ًا لعــدم وجــود ســوابق بحــق املدعــى‬\n                         ‫عليــه‪ .‬ولــكل مــا تقــدم فقــد تقــرر لدينــا مــا يلــي ‪:‬‬\n‫لــم يثبــت لدينــا إدانــة املدعــى عليــه مبــا يوجــب حــد احلرابــة مــع توجــه‬\n‫(التهمــة) املوجبــة للعقوبــة بحقــه ‪ .‬وحكمنــا يف هــذه القضية (باإلجماع)‬\n                                                                             ‫مبــا يلــي ‪:‬‬\n‫أوال‪ :‬صرفنــا النظــر عــن طلــب املدعــي العــام إقامــة حــد احلرابــة بحــق‬\n                                                                       ‫املدعــى عليــه‬\n‫ثانيــا‪ :‬حكمنــا بتعزيــر املدعــى عليــه بالســجن ملــدة(‪ )3‬ثــاث ســنوات‬\n                           ‫تبــدأ مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة‪.‬‬\n‫ثالثــا ‪ :‬حكمنــا بتعزيــر املدعــى عليــه بجلــده عــدد (‪ )300‬ثالثمائــة جلــده‬\n‫مفرقــة علــى دفعــات مقــدار كل دفعــة خمســون جلــده بــن كل دفعــة‬\n                                                         ‫والتــي تليهــا مــدة أســبوع ‪.‬‬\n‫وبجميــع ذلــك حكمنــا واهلل أحكــم احلاكمــن ‪ .‬وبعرضه على أطراف‬\n‫الدعــوى قــرر املدعــى عليــه االعتــراض علــى احلكــم وقــرر املدعــي العــام‬\n‫اعتراضــه علــى احلكــم ورغــب كل منهــم يف رفــع احلكــم وأوراق‬\n‫املعاملــة إلــى محكمــة االســتئناف بالئحــة اعتراضيــة فأجبنــاه لطلبــه‬\n‫وســلم اجلميــع نســخة مــن صــك احلكــم حــاال وأفهــم بــأن لــه مهلــة ‪30‬‬\n‫يومــا لتقــدمي الئحتــه االعتراضيــة علــى احلكــم فــإن انقضــت املــدة ولــم‬\n‫يتقــدم بهــا ســقط حقــه يف االعتــراض ويرفــع بعــد ذلــك صــك احلكــم‬\n‫برفقــة كافــة أوراق املعاملــة حملكمــة االســتئناف مبنطقــة عســير‬\n\n\n                                                                                             ‫‪114‬‬\n\f      ‫لتدقيــق احلكــم حســب املتبــع ‪ ،‬وكان ختــام هــذه اجللســة بعــد النطــق‬\n      ‫باحلكــم عنــد الســاعة ‪ 11 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل وســلم علــى‬\n               ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/5‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/12/29‬ه ـ ويف‬\n      ‫متــام الســاعة (‪ )8:00‬افتتحــت اجللســة وقــد عــادت املعاملــة رفــق خطــاب‬\n      ‫رئيــس محكمــة االســتئناف مبنطقــة عســير رقــم ‪ 342585493‬يف‬\n      ‫تاريــخ ‪1434/12/19‬ه ـ مرفقــا بهــا قــرار الدائــرة اخلماســية الثانيــة رقــم‬\n      ‫‪ 34370126‬يف ‪1434/11/25‬ه ـ واملتضمــن نــص احلاجــة منــه وبدراســة‬\n      ‫احلكــم وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم مذيــا عليــه‬\n      ‫بتوقيــع قضــاة االســتئناف‪ ...... :‬و ‪......‬و ‪......‬و ‪ ......‬و‪ ......‬وحتــى ال يخفــى‬\n      ‫جــرى احلاقــة وأمرنــا بالتهميــش وكان ختــام هــذه اجللســة الســاعة‬\n      ‫(‪ )8:15‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد ‪ .‬حــرر يف‬\n                                                                       ‫‪1434/12/29‬ه ـ ‪.‬‬\n\n\n\n\n‫‪115‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":107,"source_page_end":115,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"814fb31a262e312a11ce91e08234c1a528e8903f9cc7d374e9c91341f602531c","normalized_text_hash":"69da99dd8b189d30bd3cad4e841cc3568b99c5e8875e405bf8759b21b100c3f6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p107-34261554"},{"id":"1de22b7a-60c0-570b-a619-d421f4b98ae1","document_type":"judgment","category":"judicial","subcategory":"general","title":"حرابة -لواط -ارتكاب فاحشة اللواط بحدث -خطف حدث - درء حد احلرابة -رجوع عن إقرار -التعزير لقاء التهمة بالسجن واجللد واإلبعاد.","document_number":"34301602","case_number":"3470780","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/21","year":"1434","subject":"حرابة -لواط -ارتكاب فاحشة اللواط بحدث -خطف حدث - درء حد احلرابة -رجوع عن إقرار -التعزير لقاء التهمة بالسجن واجللد واإلبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34301602 :‬تاريخه ‪1434/8/21:‬هـ‬\n                    ‫رقم الدعوى‪3470780 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34354098‬تاريخه‪1434/11/9 :‬هـ‬\n\n\n‫حرابــة ‪ -‬لــواط ‪ -‬ارتــكاب فاحشــة اللــواط بحــدث ‪ -‬خطــف حــدث ‪-‬‬\n‫درء حــد احلرابــة ‪ -‬رجــوع عــن إقــرار ‪ -‬التعزيــر لقــاء التهمــة بالســجن‬\n                                                          ‫واجللــد واإلبعــاد‪.‬‬\n\n\n\n\n                  ‫قوله صلى اهلل عليه وسلم‪( :‬ادرؤوا احلدود بالشبهات)‪.‬‬\n\n\n\n\n‫توجيــه االتهــام للمدعــى عليــه املقيــم بخطــف طفــل عمــره خمــس ســنوات‬\n‫وفعــل فاحشــة اللــواط بــه ‪ ،‬تقدمــت والــدة الطفــل ببالغ ملركز الشــرطة‬\n‫عــن قيــام املدعــى عليــه بأخــذ الطفــل البالــغ مــن العمــر خمــس ســنوات‬\n‫مــن املجلــس والتوجــه بــه إلــى غرفتــه وفعــل الفاحشــة بــه بإيــاج ‪ ،‬طلــب‬\n‫املدعــي العــام إثبــات مــا أســند للمدعــى عليــه واحلكــم عليه بحــد احلرابة‬\n‫‪ ،‬أقــر املدعــى عليــه مبــا نســب إليــه بواســطة مترجــم احملكمــة ‪ ،‬يف‬\n‫جلســة أخــرى رجــع املدعــى عليــه عــن إقــراره وأنكــر مــا جــاء يف دعــوى‬\n‫املدعــي العــام ‪ ،‬قــرر املدعــي العــام أن بينتــه إقــرار املدعــى عليــه حتقيقـ ًا‬\n‫‪ ،‬جــرى الرجــوع إلــى هــذا اإلقــرار ورصــد مضمونــه وهــو مطابــق ملــا جــاء‬\n‫يف دعــوى املدعــي العــام ‪ ،‬جــرى عــرض اإلقــرار علــى املدعــى عليــه فقــرر‬\n‫أن هــذا اإلقــرار صــدر منــه بســبب مــا تعــرض لــه مــن ضــرب شــديد مــن‬\n\n                                                                                         ‫‪116‬‬\n\f      ‫قبــل احملقــق ومــا جــاء فيــه غيــر صحيــح ‪ ،‬طلبــت احملكمــة مــن املدعــى‬\n      ‫عليــه البينــة علــى دعــوى الضــرب فقــرر أن ال بينــه لديــه ‪ ،‬جــرى الرجــوع‬\n      ‫إلــى محضــر اســتنطاق الطفــل وهــو مطابــق ملــا جــاء يف دعــوى املدعــي‬\n      ‫العــام ‪ ،‬جــرى عرضــه علــى املدعــي عليــه فقــرر أنــه والــدة الطفــل هي من‬\n      ‫أمرتــه بقــول هــذا الــكالم ‪ ،‬جــرى الرجــوع إلــى تقريــر الطــب الشــرعي‬\n      ‫ورصــد مضمونــه ‪ ،‬بالرجــوع إلــى صحيفــة ســوابق املدعــى عليــه وتبــن‬\n      ‫عــدم وجــود ســوابق مســجله عليــه ‪ ،‬صــدر احلكــم بــرد دعــوى املدعــي‬\n      ‫العــام يف طلبــه إثبــات إدانــة املدعــى عليــه بخطــف الطفــل ورد دعــواه‬\n      ‫بطلــب إقامــة حــد احلرابــة عليــه لعــدم ثبــوت موجبهــا وتعزيــر املدعــى‬\n      ‫عليــه لقــاء التهمــة املوجهــة لــه وذلــك بســجنه ســنتني وجلــده ثالثمائــة‬\n      ‫جلــدة مفرقــة علــى ســت دفعــات والتوصيــة بإبعــاده عــن البــاد ‪ ،‬صــدق‬\n                                               ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلدينــا نحــن ‪..............‬و‪..............‬و‪............‬‬\n      ‫القضــاة يف احملكمــة العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة‬\n      ‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالرياض‪/‬املســاعد برقــم‬\n      ‫‪..............‬وتاريــخ ‪1434/02/12‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ‬\n      ‫‪1434/02/09‬ه ـ ففــي يــوم األحــد املوافق‪1434/02/17‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪08 : 45‬وفيهــا حضــر املدعــي العــام وقــد الئحــة الدعــوى‬\n      ‫العامــة التالــي نصهــا (بصفتــي مدعيـ ًا عامـ ًا بدائــرة االدعاء العــام مبدينة‬\n      ‫الريــاض أدعــي علــى‪ ............. :‬عام ـ ًا ‪ ،‬باكســتاني اجلنســية مبوجــب‬\n      ‫رخصــة اإلقامــة رقــم(‪ )................‬غيــر محصــن‪ ،‬مســلم الديانــة‪،‬‬\n\n‫‪117‬‬\n\f‫موقــوف بتاريــخ‪ 1433/9/20‬مبوجــب أمــر التوقيــف رقــم وتاريــخ‪/21‬‬\n‫‪1433/9‬ه ـ وأمــر التمديــد واإلحالــة رقــم وتاريــخ ‪1433/9/24‬هـ ـ ‪.‬‬\n‫بتاريــخ ‪1433/9/20‬ه ـ قبــض علــى املدعــى عليــه مــن قبــل مركــز‬\n‫شــرطة ‪.....‬إثــر بــاغ تقدمــت بــه املرأة‪......../‬إرتيريــة اجلنســية ‪ ،‬عــن قيــام‬\n‫املتهــم املذكــور بفعــل الفاحشــة بابنهــا البالــغ مــن العمــر ‪5‬ســنوات وذلــك‬\n‫بقيامــه بأخــذه مــن املجلــس والتوجــه بــه إلــى غرفتــه وفعــل الفاحشــة بــه‬\n‫بإيــاج ‪ .‬وباســتنطاق الطفــل ‪ /‬أفــاد بــأن املذكــور قــام بحملــه والتوجــه‬\n‫بــه إلــى غرفتــه وأنــه قــام بخلــع مالبســه وفعــل بــه الفاحشــة وبإحضــار‬\n‫املتهــم املذكــور أمامــه أشــار إليــه بأنــه مــن قــام بذلــك ‪ .‬وبســماع أقــوال‬\n‫املتهــم واســتجوابه‪ /‬أقــر بأنــه شــاهد الطفــل ‪ ،‬يلعــب يف فنــاء املنــزل وأنــه‬\n‫قــام بحملــه بيديــه والتوجــه بــه إلــى غرفتــه خــارج القصــر وأنــه قــام بخلــع‬\n‫مالبســه وفعــل الفاحشــة بــه بإيــاج ‪ .‬صــدر بحــق املجنــي عليــه تقريــر‬\n‫الطــب الشــرعي رقــم(‪ ).....‬لعام‪1433‬ه ـ واملتضمــن أنــه بفحصه موضعيا‬\n‫مــن دبــر تبــن وجــود احمــرار وتــورم حــول فتحــة الشــرج وتشــققات مدماه‬\n‫عديــدة عنــد الســاعة‪ 11‬والســاعة ‪ 7‬مــن مينــاء عقــارب الســاعة وهــي‬\n‫إصابيــة املنشــأ معاصــره للواقعــة مضــى عليهــا أقــل مــن ‪24‬ســاعة مــن‬\n‫تاريــخ الكشــف الطبــي الشــرعي قــد تشــير إلــى محاولــة إيــاج مــن دبــر‬\n‫بجســم صلــب أيــا كان نوعــه ويجــوز حدوثهــا مــن مثــل عضــو ذكــري‬\n‫منتصــب لرجــل بالــغ أو مــا شــبهه كمــا تضمــن تعــذر أخــذ مســحات‬\n‫مــن جســمه ومســحات شــرجية لقيــام والــدة الطفــل بغســل جســم الطفــل‬\n‫باملــاء والصابــون ومــاده مطهــره عــن االثــار واملــواد املنويــة العالقة باجلســم‪.‬‬\n‫صــدر تقريــر االدلــة اجلنائيــة رقــم (‪ )....-...‬لعام‪1433‬ه ـ بشــأن فحــص‬\n‫مالبــس املجنــي عليــه واملتضمــن ســلبيات العينــات الــواردة يف الفحــص‬\n\n\n                                                                                          ‫‪118‬‬\n\f      ‫للحمــض النــووي الوراثــي ممــا يتعــذر معــه إجــراء أي مقارنــة ‪ .‬صــدر‬\n      ‫تقريــر األدلــة اجلنائيــة رقــم (‪ )....-....‬لعام‪1433‬ه ـ بشــأن فحــص عينــة‬\n      ‫دم قياســية للمتهــم املذكــور واملتضمــن حتديــد األمنــاط الوراثيــة لعينــة‬\n      ‫الــدم القياســية رقــم (‪ )...‬ومت بحــث هــذه األمنــاط يف قاعــدة املعلومــات‬\n      ‫الوراثيــة ولــم يتبــن حتــى وقــت إعــداد التقريــر وجــود تطابــق جنائــي مــع‬\n      ‫أي قضايــا ســابقة ‪ .‬وقــد أســفر التحقيــق عــن اتهــام املذكــور بخطــف‬\n               ‫طفــل وفعــل فاحشــة اللــواط بــه وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n      ‫‪ .1‬مــا جــاء يف إقــرار املتهــم واملــدون علــى الصفحــة (‪ )6‬مــن محضــر‬\n      ‫االســتجواب املرفــق لفــة رقــم (‪ )9‬وتطابــق أقوالــه مــع أقــوال والــدة‬\n                                                                 ‫الطفــل املجنــي عليــه‪.‬‬\n      ‫‪ .2‬مــا جــاء يف محضــر االســتنطاق وتعــرف املجنــي عليــه علــى املتهــم‬\n      ‫واملــدون علــى الصفحــة رقــم (‪ )3‬مــن ملــف االســتجواب املرفــق لفــه رقــم‬\n                                                                                      ‫(‪.)9‬‬\n                     ‫‪ .3‬ما جاء يف تقرير الطب الشرعي املرفق لفه رقم(‪.)17/16‬‬\n          ‫وباالطالع على سوابقه لم يعثر له على سوابق مسجلة حتى تاريخه ‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املتهــم فعــل محرم ومعاقب عليه شــرعا وضربا‬\n      ‫مــن ضــروب اإلفســاد يف األرض علــى ســبيل الغلبــة والقهــر أطلــب إثبــات‬\n      ‫مــا أســند إليــه واحلكــم عليــه بحــد احلرابــة الــوارد يف اآليــة الكرميــة رقــم‬\n      ‫(‪ )33‬مــن ســورة املائــدة يف ضــوء قــرار هيئــة كبــار العلمــاء رقــم (‪)85‬‬\n      ‫وتاريــخ ‪1401/11/11‬هـ(علمــا بــأن احلــق اخلــاص مــازال قائمــا)‪ .‬فرفعــت‬\n      ‫اجللســة إلحضــار املدعــى عليــه ويف يــوم الســبت املوافق‪1434/06/17‬هـ‬\n      ‫حضــر املدعــي العــام واملدعــى عليــه باكســتاني اجلنســية مبوجــب‬\n      ‫اإلقامــة رقــم ‪ ........‬متــت تــاوة الدعــوى عليــه بواســطة املترجــم ‪........‬‬\n\n\n‫‪119‬‬\n\f‫باكســتاني اجلنســية حامــل اإلقامــة رقــم ‪ ......‬فأجــاب قائــا بواســطة‬\n‫املترجــم املذكــور مــا ذكــره املدعــي العــام يف دعــواه كلــه صحيــح‬\n‫فقــد خطفــت الطفــل البالــغ مــن العمــر خمــس ســنوات وتوجهــت بــه‬\n‫إلــى غرفتــي وفعلــت الفاحشــة بــه بإيــاج حيــث أوجلــت ذكــري يف دبــره‬\n‫هكــذا أجــاب فرفعــت اجللســة إلحضــار مترجــم آخــر ‪ .‬ويف يــوم الســبت‬\n‫املوافــق ‪1434/07/15‬ه ـ افتتحــت اجللســة الســاعة العاشــرة مبشــاركة‬\n‫فضيلــة الشــيخ ‪ .......‬القاضــي بهــذه احملكمــة خلفـ ًا لفضيلــة ‪ ....‬النتقالــه‬\n‫مــن هــذه احملكمــة ‪ ،‬وفيهــا حضــر املدعــي العــام ولــم يحضــر املدعــى‬\n‫عليــه مــن قبــل إدارة الســجون ‪ ،‬ثــم جــرى االطــاع علــى مــا ســبق ضبطــه‬\n‫وبعرضه على املدعي العام صادق عليه ‪ ،‬ثم جرى رفع اجللســة إلحضار‬\n‫املدعــى عليــه ‪ .‬ويف يــوم الســبت املوافــق ‪1434/07/29‬ه ـ افتتحــت‬\n‫اجللســة الســاعة العاشــرة وفيهــا حضــر املدعــي العــام واملدعــى عليــه ‪،‬‬\n‫وحضــر املترجــم املتعــاون مــع احملكمــة باكســتاني اجلنســية مبوجــب‬\n‫رخصــة اإلقامــة الصــادرة مــن جــوازات اخلــرج برقــم‪ ، ......‬ثــم جــرى‬\n‫عــرض مــا ســبق ضبطــه علــى املدعــى عليــه بواســطة املترجــم احلاضــر‬\n‫ا ‪ :‬مــا ذكرتــه يف جوابــي علــى الدعــوى باجللســة الســابقة‬       ‫فقــرر قائ ـ ً‬\n‫مختلــف عمــا مت تدوينــه ولعــل املترجــم لــم يفهــم كالمــي ‪ ،‬والصحيــح‬\n‫أن مــا جــاء يف دعــوى املدعــي العــام كلــه غيــر صحيــح فلــم أقــم بخطــف‬\n‫الطفــل وال فعــل الفاحشــة بــه بإيــاج وال بــدون إيــاج ولــم أتعــرض لــه ‪،‬‬\n‫وأنــا أعمــل يف قصــر األميــرة ‪ .....‬ووالــدة الطفــل املذكــور تعمــل خادمــة‬\n‫هنــاك وحتضــر معهــا ابنهــا وال أعلــم ســبب تقدمهــا بالشــكوى ضــدي‬\n‫ا‪:‬‬ ‫هكــذا قــرر ‪ ،‬وبســؤال املدعــي العــام هــل لديــك بينــة أجــاب قائ ـ ً‬\n‫لــدي إقــرار املدعــى عليــه ومــا يف أوراق املعاملــة أطلــب الرجــوع إليهــا‬\n\n\n                                                                                      ‫‪120‬‬\n\f      ‫هكــذا أجــاب ‪ ،‬فجــرى االطــاع علــى أوراق املعاملــة فوجدنــا بــن‬\n      ‫طياتهــا وعلــى الصحيفــة رقــم ‪ 6‬مــن ملــف االســتجواب املرفــق باملعاملــة‬\n      ‫لغــة رقــم ‪ 9‬إقــرارا للمدعــى عليــه تضمــن مــا نصــه ( أننــي شــاهدت‬\n      ‫الطفــل يلعــب يف ســور القصــر وقمــت بحملــه علــى يــدي وتوجهــت بــه إلــى‬\n      ‫الغرفــة وقمــت بفعــل الفاحشــة بــه مــرة واحــدة بإيــاج وقمــت بإرجاعــه‬\n      ‫مــرة أخــرى إلــى املجلــس اخلــاص بالنســاء ) انتهــى نصــه ‪ ،‬وبعرضــه علــى‬\n      ‫ا ‪ :‬صحيــح أننــي‬  ‫املدعــي عليــه بواســطة املترجــم وســؤاله عنــه أجــاب قائـ ً‬\n      ‫أقــررت بهــذا اإلقــرار ‪ ،‬ولكــن كان بســبب مــا تعرضــت لــه مــن ضــرب‬\n      ‫شــديد مــن قبــل العســكري ‪ ،‬ومــا جــاء يف هــذا اإلقــرار كلــه غيــر‬\n      ‫صحيــح هكــذا أجــاب ‪ ،‬فســألناه هــل لديــك بينــة علــى الضــرب فأجــاب‬\n      ‫ا ‪ :‬ليــس لــدي بينــة وال أعــرف مــن ضربنــي هكــذا أجــاب ‪ ،‬كمــا‬         ‫قائـ ً‬\n      ‫جــرى االطــاع علــى محضــر االســتنطاق املــدون علــى الصحيفــة رقــم ‪3‬‬\n      ‫مــن امللــف املرفــق رقــم ‪ 9‬فوجدنــاه تضمــن أنــه مت اســتنطاق الطفــل عمــا‬\n      ‫تعــرض لــه وأفــاد بــأن الباكســتاني ( املدعــى عليــه ) قــام بحملــه إلــى‬\n      ‫الغرفــة وخلــع مالبســه وأدخــل ذكــره فيــه مــن اخللــف مرتــن ‪ ،‬علم ـ ًا‬\n      ‫بأنــه جــرى إحضــار الباكســتاني لــه وأشــار بأنــه مــن قــام بهــذه الفعلــة‬\n      ‫انتهــى مضمونــه ‪ ،‬وبعرضــه علــى املدعــى عليــه بواســطة املترجــم أجــاب‬\n      ‫ا ‪ :‬أن والــدة الطفــل هــي مــن أمرتــه بقــول هــذا الــكالم هكــذا‬      ‫قائ ـ ً‬\n      ‫أجــاب ‪ ،‬فســألنا املدعــى عليــه هــل أنــت متــزوج أو ســبق لــك الــزواج‬\n      ‫ا ‪ :‬لــم يســبق لــي الــزواج هكــذا أجــاب ‪ ،‬كمــا جــرى‬        ‫فأجــاب قائ ـ ً‬\n      ‫االطــاع علــى تقريــر الفحــوص الوراثيــة رقــم (‪ )...-...‬فحــوص وراثيــة‬\n      ‫الصــادر مــن شــعبة املختبــرات اجلنائيــة واملرفــق باملعاملــة لفــة رقــم ‪22‬‬\n      ‫فوجدنــاه تضمــن أن مالبــس احلــدث جــرى فحصهــا باســتخدام تقنيــة‬\n\n\n‫‪121‬‬\n\f‫احلمــض النــووي وتبــن ســلبيتها للحمــض النــووي ممــا يتعــذر معــه إجــراء‬\n‫املقارنــة انتهــى مضمونهــا ‪ ،‬كمــا جــرى االطــاع علــى التقريــر الطبــي‬\n‫الشــرعي رقــم ‪ ....‬لعــام ‪1433‬ه ـ املرفــق باملعاملــة لفــة رقــم ‪20 -18‬‬\n‫فوجدنــاه تضمــن يف ( الــرأي ) مــا نصــه ( ممــا ســبق وتقــدم فإننــا نــرى‬\n‫اآلتــي ‪1 :‬ـ لــم يتبــن لنــا مــن الكشــف الطبــي الشــرعي علــى الطفــل ‪/‬‬\n‫‪ 4 ........‬أعــوام ‪ ......‬اجلنســية وجــود عالمــات العتــداء جســدي مثــل جــروح‬\n‫أو كدمــات أو ســحجات ظفريــة أو شــريطية أو عالمــات تربيــط علــى‬\n‫اليديــن أو الســاقني أو عالمــات ذات طبيعــة جنســية مثــل عالمــات مــص‬\n‫أو عــض عــدا وجــود تلــون بلــون أحمــر يف أعلــى الكتفــن قــد يشــير إلــى‬\n‫إمســاك ومحاولــة إعتــداء جنســي ‪2 .‬ـ تعــذر فحــص املالبــس باســتخدام‬\n‫تقنيــة الكشــافات والنظــارات اجلنائيــة للتحــري عــن التلوثــات أو البقــع‬\n‫املشــتبهة لقيــام والــدة الطفــل بتســليمها للشــرطة ‪ ،‬كمــا تعــذر أخــذ‬\n‫املســحات الالزمــة مــن أنحــاء اجلســم ومــن املنطقــة الشــرجية ـ للتحــري‬\n‫عــن املــواد واحليوانــات املنويــة إن وجــدت ليتــم فحصهــا يف مختــرات‬\n‫إدارة األدلــة اجلنائيــة ويف حــال إيجابيــة املســحات ميكــن مقارنتهــا‬\n‫باحلمــض النــووي للمتهــم ـ لقيــام والــدة الطفــل بغســل جســم الطفــل باملــاء‬\n‫والصابــون ومــادة مطهــرة عــن اآلثــار واملــواد املنويــة العالقــة باجلســم ‪.‬‬\n‫‪3‬ـ وبفحصــه موضعي ـ ًا مــن دبــر تبــن وجــود احمــرار وتــورم حــول فتحــة‬\n‫الشــرج وتشــققات مدمــاه عديــدة عنــد الســاعة ‪ 11‬والســاعة ‪ 7‬مــن‬\n‫مينــاء عقــارب الســاعة وهــي إصابيــة املنشــأ معاصــرة للواقعــة مضــى‬\n‫عليهــا أقــل مــن أربــع وعشــرين ســاعة مــن تاريــخ الكشــف الطبــي‬\n‫الشــرعي قــد تشــير إلــى محاولــة إيــاج مــن دبــر بجســم صلــب أيــا كان‬\n‫نوعــه ويجــوز حدوثهــا مــن مثــل عضــو ذكــري منتصــب لرجــل بالــغ أو‬\n\n\n                                                                                     ‫‪122‬‬\n\f      ‫مــا شــابهه ‪4 .‬ـ وجتــدر اإلشــارة إلــى أن املواقعــة اجلنســية بإيــاج كامــل‬\n      ‫مــن دبــر بجســم صلــب مثــل عضــو ذكــري منتصــب لرجــل بالــغ أو مــا‬\n      ‫شــابهه عنــد األطفــال غالبـ ًا مــا ينتــج عنــه جــرح رضــي يف فتحــة الشــرح‬\n      ‫يتفــاوت يف شــدته مــن جــرح رضــي ســطحي إلــى جــرح رضــي عميــق‬\n      ‫نــازف يســتدعي تدخــل طبــي جراحــي لعالجــه نظــر ًا لعــدم التناســب مــا‬\n      ‫بــن حجــم الشــرج الطفولــي والعضــو الذكــري املنتصــب لرجــل بالــغ ‪،‬‬\n      ‫كمــا أن اســتخدام مــواد مزجلــة أثنــاء محاولــة اإليــاج يقلــل مــن شــدة‬\n      ‫اإلصابــة وقــد ال يتــرك أثــر ًا إصابي ـ ًا ينــم عنــه ويف مثــل تلــك احلــاالت‬\n      ‫ميكــن الرجــوع إلــى نتائــج الفحوصــات املخبريــة للمالبــس ‪5 .‬ـ لــم يتبــن‬\n      ‫وجــود عالمــات لفعــل الفاحشــة املتكــرر بإتيانــه لواط ـ ًا بإيــاج مــن‬\n      ‫ُدبــر) انتهــى نصــه ‪ ،‬وباالطــاع علــى صحيفــة الســوابق املرفقــة باملعاملــة‬\n      ‫لفــة رقــم ‪ 46‬وجدناهــا تضمنــت عــدم تســجيل الســوابق بحقــه ‪ ،‬ثــم‬\n      ‫قررنــا رفــع اجللســة للتأمــل والنطــق باحلكــم إلــى يــوم الســبت املوافــق‬\n      ‫‪1434/8/13‬ه ـ ‪ .‬ويف املوعــد احملــدد افتتحــت اجللســة الســاعة احلاديــة‬\n      ‫عشــرة والربــع للتأخــر يف إحضــار الســجني مــن قبــل إدارة الســجون ‪،‬‬\n      ‫ويف هــذه اجللســة حضــر املدعــي العــام واملدعــى عليــه واملترجــم املتعــاون‬\n      ‫مــع احملكمــة ‪ ، .......‬املــدون هويتــه بضبطــه ‪ ،‬وبســؤال املدعــي العــام‬\n      ‫واملدعــى عليــه إن كان لديهمــا مــا يــودان إضافتــه علــى مــا ســبق قــرر‬\n      ‫كل منهمــا قائــا ليــس لــدي ســوى مــا ســبق هكــذا قــررا ‪ ،‬فقفلنــا‬\n      ‫بــاب املرافعــة ‪ ،‬وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ‪ ،‬ومبــا أن‬\n      ‫املدعــى عليــه أقــر يف املجلــس الشــرعي مبــا نســبه إليــه املدعــي العــام يف‬\n      ‫دعــواه ‪ ،‬ثــم رجــع وأنكــر صحــة إقــراره وادعــى وهــم املترجــم يف فهمــه‬\n      ‫ملــا أجــاب بــه ‪ ،‬وبنــاء علــى مــا جــاء يف إقــراره املــدون مضمونــه أعــاه‬\n\n\n‫‪123‬‬\n\f‫املتضمــن إقــراره بصحــة مــا نســب إليــه مــن فعــل فاحشــة اللــواط بإيــاج‬\n‫بالطفــل املذكــور ‪ ،‬وادعــى اإلكــراه وال بينــة لــه علــى ذلــك‪ ،‬ونظــرا‬\n‫لعــدم إمكانيــة اســتبيان حقيقــة مــا جــرى للطفــل ومــدى عالقــة املدعــى‬\n‫عليــه بــه ـ نفيــا أو إيجابــا ـ عــن طريــق التحاليــل والفحــوص الوراثيــة‬\n‫جلســد الطفــل ومالبســه نظــرا لســلبيتها للحمــض النــووي نتيجــة لغســلها‬\n‫مــن قبــل والــدة الطفــل ‪ ،‬وبنــاء علــى مــا جــاء يف التقريــر الطبــي الشــرعي‬\n‫املتضمــن يف نتيجتــه أن الطفــل يعانــي مــن آثــار يف دبــره قــد تشــير إلــى‬\n‫محاولــة إيــاج جلســم صلــب ‪ ،‬مــن املمكــن حدوثهــا مــن عضــو ذكــر‬\n‫بالــغ ‪ ،‬ولــم يذكــر بالطفــل عالمــات تــدل علــى اعتــداء جســدي مــن‬\n‫جــروح أو خــدوش ونحوهــا ‪ ،‬وألن مــا ســبق عرضــه مــن أدلــة املدعــي‬\n‫العــام قرائــن ال تثبــت اإلدانــة بهــا ‪ ،‬وإمنــا تتوجــه بهــا التهمــة للمدعــى‬\n‫عليــه ‪ ،‬ونظــرا إلــى إنــكار املدعــى عليــه أخيــرا ملــا أقــر بــه ســابقا يعتبــر‬\n‫شــبهة تقــدح يف صحــة إقــراره ‪ ،‬وبنــاء علــى أن احلــدود تــدرأ بالشــبهات‬\n‫لقولــه عليــه الصــاة والســام (ادرؤوا احلــدود بالشــبهات) ‪ ،‬ولــكل مــا‬\n‫تقــدم فقــد توجهــت التهمــة القويــة للمدعــى عليــه بفعــل فاحشــة اللــواط‬\n‫بطفــل ‪ ،‬وقررنــا مــا يلــي‪ :‬أوال‪ /‬رد دعــوى املدعــي العــام يف طلبــه إثبــات‬\n‫إدانــة املدعــى عليــه بخطــف الطفــل ورد دعــواه بطلــب إقامــة حــد احلرابــة‬\n‫عليــه لعــدم ثبــوت موجبهــا ‪ .‬ثانيــا ‪ /‬تعزيــر املدعــى عليــه لقــاء التهمــة‬\n‫املوجــه لــه وذلــك بســجنه ســنتان اعتبــارا مــن تاريــخ إيقافــه بســبب هــذه‬\n‫القضيــة وجلــده ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات بــن كل دفعــة‬\n‫وأخــرى عشــرة أيــام ‪ ،‬وقــدر كل دفعــة خمســون جلــدة ‪ ،‬ثالثــا‪ /‬نوصــي‬\n‫بإبعــاد املدعــى عليــه عــن اململكــة بعــد انتهــاء محكوميتــه اتقــاء لشــره‬\n‫‪ ،‬وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليــه قــرر املدعــى عليــه‬\n\n\n                                                                                          ‫‪124‬‬\n\f      ‫قناعتــه بــه ‪ ،‬وأمــا املدعــي العــام فقــرر رغبتــه يف اســتئناف احلكــم‬\n      ‫مســتعدا بتقــدمي الئحــة اعتراضيــة فأفهــم بأنــه ســيتم تســليمه نســخة‬\n      ‫مــن القــرار لتقــدمي الئحتــه االعتراضيــة عليــه خــال ثالثــن يومــا مــن‬\n      ‫تاريــخ هــذا اليــوم ‪ ،‬وأنــه إذا لــم يتقــدم باعتراضــه عليــه خــال املــدة‬\n      ‫فســيتم رفــع املعاملــة حملكمــة االســتئناف بــدون الئحتــه االعتراضيــة‬\n      ‫ففهــم ذلــك ‪ ،‬وختمــت اجللســة الســاعة احلاديــة عشــرة والنصــف ‪ ،‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                        ‫حــرر يف ‪ 1434/08/13‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/12/19‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة الواحــدة والنصــف وقــد وردتنــا املعاملــة مــن‬\n      ‫محكمــة االســتئناف بالريــاض وقــد همــش علــى ظهــر الصــك مبــا نصــه‬\n      ‫( تظهيــرات الدائــرة اجلزائيــة اخلماســية مبحكمــة االســتئناف بالريــاض‬\n      ‫‪ ،‬احلمــد هلل وحــده وبعــد ‪ :‬فقــد اطلعنــا علــى هــذا القــرار رقــم وتاريــخ‬\n      ‫‪1434/08/21‬ه ـ الصــادر مــن أصحــاب الفضيلــة قضــاة احملكمــة‬\n      ‫العامة بالرياض الشــيخ ‪ ....‬والشــيخ ‪ ....‬والشــيخ ‪ ....‬وأصدرنا القرار رقم‬\n      ‫وتاريــخ ‪1434/11/09‬ه ـ املتضمــن املصادقــة باألكثريــة علــى احلكــم‬\n      ‫‪ ،‬واهلل املوفــق ‪ .‬قاضــي اســتئناف ختمــه وتوقيعــه قاضــي اســتئناف‬\n      ‫ختمــه وتوقيعــه قاضــي اســتئناف ختمــه وتوقيعــه لــه وجهــة نظــر قاضــي‬\n      ‫اســتئناف ختمــه وتوقيعــه رئيــس الدائــرة ختمــه وتوقيعــه ) وكان ختــام‬\n      ‫هــذه اجللســة الســاعة الثانيــة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                   ‫محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/12/19‬ه ـ ‪.‬‬\n\n\n\n\n‫‪125‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":116,"source_page_end":125,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"735c3d30538eb0efdbc3815a34e829489d384c76319b1763312b5fedac47dd65","normalized_text_hash":"90217091df4bdf3452eed124b18856150d4ad4dca04da759cd97bae15b8cbf95","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p116-34301602"},{"id":"daef242e-dae0-57be-8cbc-b91ea9955cbd","document_type":"judgment","category":"judicial","subcategory":"general","title":"حرابة -لواط -خطف حدث -فعل فاحشة بالقوة مع حدث -شهادة شهود -تقرير طبيب شرعي -حمض نووي -سوابق - قتل تعزير ا -مالحظة تقرير عدم حاجة عرض املدعى عليه على مصحة نفسية لفهمه اخلطاب -رد حد احلرابة ومصادر السيارة .","document_number":"3455295","case_number":"3483544","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل كال من","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/3","year":"1434","subject":"حرابة -لواط -خطف حدث -فعل فاحشة بالقوة مع حدث -شهادة شهود -تقرير طبيب شرعي -حمض نووي -سوابق - قتل تعزير ا -مالحظة تقرير عدم حاجة عرض املدعى عليه على مصحة نفسية لفهمه اخلطاب -رد حد احلرابة ومصادر السيارة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3455295 :‬تاريخه‪1434/3/3 :‬هـ‬\n                   ‫رقم الدعوى‪3483544 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 341167635‬تاريخه‪1434/7/1:‬هـ‬\n\n\n‫حرابــة ‪ -‬لــواط ‪ -‬خطــف حــدث ‪ -‬فعــل فاحشــة بالقــوة مــع حــدث‬\n‫‪ -‬شــهادة شــهود ‪ -‬تقريــر طبيــب شــرعي ‪ -‬حمــض نــووي ‪ -‬ســوابق ‪-‬‬\n‫قتــل تعزيــر ًا ‪ -‬مالحظــة تقريــر عــدم حاجــة عــرض املدعــى عليــه علــى‬\n‫مصحــة نفســية لفهمــه اخلطــاب ‪ -‬رد حــد احلرابــة ومصــادر الســيارة ‪.‬‬\n\n\n\n\n‫‪ -1‬قــول اهلل تعالــى‪ « :‬إمنــا جــزاء الذيــن يحاربــون اهلل ورســوله ويســعون‬\n‫يف األرض فســادا أن يقتلــوا أو يصلبــوا أو تقطــع أيديهــم وأرجلهــم مــن‬\n                                     ‫خــاف أو ينفــوا مــن األرض‪« ..‬اآليــة‪.‬‬\n‫‪ -2‬قــول النبــي صلــى اهلل عليــه وعلــى آلــه وســلم « مــن وجدمتــوه يعمــل‬\n‫عمــل قــوم لــوط فاقتلــوا الفاعــل واملفعــول بــه « رواه الترمــذي (‪57/4‬‬\n‫ـ ـ ‪ )58‬وســن أبــي داوود (‪ 607/4‬ـ ـ ‪ )608‬وابــن ماج ــه (‪ )856/2‬والســن‬\n‫الكبــرى للبيهقــي (‪ )232/8‬ومسن ــد اإلمــام أحم ــد (‪ )300/1‬وســن الــدار‬\n‫قطنــي (‪ )124/3‬واحلاكــم يف مســتدركه (‪ )355/4‬والكامــل البــن‬\n‫عــدي (‪ )1768/5‬واألوســط البــن املنــذر (‪ )623/2‬واحمللــى البــن حــزم‬\n                                                                  ‫(‪.)383/11‬‬\n‫‪ -3‬قــول النبــي صلــى اهلل عليــه وســلم‪ »:‬ملعــون مــن عمــل عمــل قــوم‬\n                                                     ‫لــوط « رواه الترمــذي‪.‬‬\n‫‪ -4‬إجمــاع الصحابــة رضــوان اهلل عليهــم علــى قتــل اللوطــي وأن‬\n\n\n                                                                                  ‫‪126‬‬\n\f      ‫معصيتــه مــن أعظــم املعاصــي التــي يــرجت لهــا عــرش الرحمــن وأن اهلل‬\n      ‫تعالــى جمــع علــى أهلهــا مــن أنــواع العقوبــات مــا لــم ينــكل بــه أم ــة‬\n      ‫ســواهم وذلــك لعظــم مفســدة هــذه اجلرميــة أنظــر فتــاوى ابــن تيميــة‬\n      ‫(‪ 334/28‬ـ ـ ‪ )345‬والسياســة الشــرعية البــن تيميــة ص(‪ )52‬وزاد املعــاد‬\n                                                                 ‫البــن القي ــم (‪.)40/5‬‬\n      ‫‪ -5‬مــا هــو مقــرر لــدى احملققــن مــن أهــل العلــم أن مــن لــم يندفــع‬\n                                                    ‫فســاده إال بالق ــتل فإنــه يق ــتل‪.‬‬\n\n\n\n      ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بخطــف حــدث‬\n      ‫وفعــل فاحشــة قــوم لــوط بــه بالقــوة ومحاولــة خطــف حــدث آخــر والهــرب‬\n      ‫مــن رجــال األمــن وصــدم دوريــة أمنيــة وطلــب إثبــات مــا أســند إليــه‬\n      ‫واحلكــم عليــه بحــد احلرابــة حيــث تقــدم أحــد املواطنــن ببــاغ عــن‬\n      ‫محاولــة أحــد األشــخاص خطــف ابنــه ولكنــه فــر منــه ‪ ،‬ومبحاولــة‬\n      ‫العثــور علــى الســيارة مت العثــور عليهــا وبداخلهــا شــخص ميــارس اللــواط‬\n      ‫مــع حــدث ‪ ،‬حــاول األب اســتيقافه ولكنــه هــرب ‪ ،‬مت القبــض علــى‬\n      ‫املدعــى عليــه وتبــن وجــود عــدة ســوابق قضائيــة لــه ‪ ،‬أنكــر املدعــى‬\n      ‫عليــه الدعــوى ‪ ،‬أحضــر املدعــى العــام بينــة وهــم رجــال األمــن وأحــد‬\n      ‫املواطنــن والــد املجنــي عليــه األول ومت ســماع شــهادتهم ‪ ،‬مت االطــاع‬\n      ‫علــى التقريــر الطبــي وفحــص احلمــض النــووي ولوحــظ انطبــاق احلمــض‬\n      ‫النــووي مــن العينــة املرفوعــة مــن احلــدث املجنــي عليــه علــى املدعــى عليــه‬\n      ‫وأنــه مصــدر تلــك التلوثــات املنويــة ‪ ،‬حكمــت احملكمــة بق ــتل املدعــى‬\n      ‫عليــه تعزيــرا جــزاء لــه ‪ ،‬وبعرضــه عليهمــا قــرر املدعــي العــام وقــرر‬\n\n‫‪127‬‬\n\f‫املدعــى عليــه عــدم القناعــة فجــرى إفهامهمــا بتعليمــات االســتئناف‬\n‫‪ ،‬عــادت املعاملــة مــن محكمــة االســتئناف بعــدد مــن امللحوظــات مــن‬\n‫أبرزهــا طلــب التصريــح بشــأن طلــب املدعــي العــام إقامــة حــد احلرابــة‬\n‫والتحقــق مــن حالــة املدعــى عليــه النفســية وإجــراء الــازم حيــال طلــب‬\n‫املدعــي العــام مصــادرة الســيارة ‪ ،‬أجابــت الدائــرة بالتصريــح بــرد‬\n‫دعــوى املدعــي العــام طلبــه إقامــة حــد احلرابــة علــى املدعــى عليــه وطلبــه‬\n‫مصــادرة الســيارة اكتفــاء بعقوبــة القتــل عمــا بأصــل تداخــل العقوبــات‬\n‫و لئــا تســري العقوبــة علــى ورثتــه حــال تنفيــذ العقوبــة عليــه وأمــا عــن‬\n‫حالــة املدعــى عليــه النفســية فقــد ظهــر للدائــرة مــن خــال االســتجواب‬\n‫بأنــه عاقــل ومــدرك ويحســن اجلــواب والدفــاع وال يســوغ فتــح هــذا البــاب‬\n‫لئــا يكــون ذريعــة لتخلــص املجرمــن عــن جرائمهــم مبثــل هــذا الدفــع ‪،‬‬\n‫صــدق احلكــم مــن محكمــة االســتئناف ‪ ،‬صــدق احلكــم من احملكمة‬\n                                                                             ‫العليــا‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلدينــا نحــن القضــاة يف احملكمــة العامــة بحائــل‬\n‫كال مــن ‪...........‬و‪...........‬واملكلــف بشــرح فضيلــة الرئيــس املســاعد‬\n‫و‪ ...........‬القائــم بعمــل فضيلــة الشــيخ ‪...........‬الــذي يتمتــع بإجــازة عاديــة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بحائــل املســاعد برقــم ‪ 3483544‬وتاريــخ ‪ 1434/02/19‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34396101‬وتاريــخ ‪1434/2/17‬ه ـ ففــي يــوم الســبت‬\n‫املوافــق‪ 1434/02/23‬ه ـ افتتحــت اجللســة األولى الســاعة ‪12 : 00‬وفيها‬\n‫حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليــه ‪...........‬ســعودي‬\n\n                                                                                          ‫‪128‬‬\n\f      ‫مبوجــب الســجل املدنــي رقــم ‪...........‬وادعى املدعي العــام بدعوى محرره‬\n      ‫اآلتــي نصهــا « احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده‬\n      ‫بصفتــي مدعيـ ًا عامـ ًا بدائــرة االدعــاء العــام لفــرع الهيئــة مبنطقــة حائــل‬\n      ‫أدعــي علــى املذكــور أعــاه بتاريــخ‪1433/12/ 26‬ه ـ تقــدم املواطــن‪/‬‬\n      ‫‪...........‬ببــاغ للجهــات األمنيــة يفيــد فيــه بأنــه كان جالسـ ًا يف املســجد‬\n      ‫بعــد صــاة العصــر وورده اتصــال مــن أهلــه يفيدونــه بــأن ابنــه البالــغ مــن‬\n      ‫العمــر (‪ )15‬عامــا تعــرض حملاولــة خطــف فاجتــه للمنــزل وســأل ابنــه‬\n      ‫عمــا حــدث فأفــاد بأنــه كان ذاهب ـ ًا للتموينــات علــى قدميــه فوقــف‬\n      ‫عنــده صاحــب ســيارة مــن نــوع (‪ )........‬رقــم اللوحــة (‪ )...........‬وســأله عــن‬\n      ‫شــقق مفروشــة فقــام بوصــف الشــقق لــه فتحــرك ثــم عــاد إليــه ووقــف‬\n      ‫عنــده ونــزل وأمســك بيــده وقــام بســحبه يريــد إركابــه فدفعــه عنــه ثــم‬\n      ‫ذهــب ‪ -‬ثــم ركــب املبلــغ مــع ابنــه علــى الســيارة وقامــا بالبحــث عــن‬\n      ‫الســيارة ولــم يجداهــا ‪ -‬ثــم ذهــب االبــن لوحــده علــى الســيارة يبحــث‬\n      ‫عنهــا فأخبــر والــده بأنــه وجدهــا يف حــي ‪ ...........‬فذهــب املبلــغ ليــرى‬\n      ‫الســيارة وإذا هــي نفــس األوصــاف فوقفــا عنهــا بعيــدا ثــم نــزل علــى‬\n      ‫أقدامــه وإذا بهــا يف حالــة تشــغيل وبهــا شــخص معــه طفــل عــاري املالبــس‬\n      ‫يفعــل الفاحشــة بــه فطــرق عليــه زجــاج الســيارة فهــرب ومعــه الطفــل‬\n      ‫وأفــاد املبلــغ بــأن اإلضــاءة األماميــة لســيارة املدعــى عليــه مــن اجلهــة‬\n      ‫اليمنــى تالفــة‪ .‬وبســماع أقــوال املجنــي عليــه (‪ )...........‬أفــاد بأنــه كان‬\n      ‫ذاهبـ ًا للتموينــات بعــد صــاة العصــر مباشــرة وأثنــاء رجوعــه يف الطريــق‬\n      ‫أعتــرض لــه صاحــب ســيارة مــن نــوع (‪ )........‬رقــم اللوحــة(‪ )...........‬ووقــف‬\n      ‫عنــده وســأله عــن شــقق مفروشــة فوصــف لــه شــقق ‪...........‬فتحــرك ثــم‬\n      ‫وقــف عنــده مــرة أخــرى ونــزل وقــال لــه اركــب لتدلنــي علــى الشــقق‬\n\n\n‫‪129‬‬\n\f‫فرفــض املجنــي عليــه فأمســك بــه بالقــوة وســحبه فقــام املجنــي عليــه‬\n‫بدفعــه وهــرب إلــى منزلهــم وأبلــغ أهلــه ثــم ركــب مــع والــده للبحــث‬\n‫عــن الســيارة ولــم يعثــرا عليهــا ثــم رجعــا إلــى املنــزل ثــم أخــذ الســيارة‬\n‫وقــام بالبحــث لوحــده فوجدهــا بحــي ‪...........‬واقفــة بــأرض فضــاء فرجــع‬\n‫للمنــزل وأخبــر والــده بذلــك ثــم ذهبــا ســويا ونــزل والــده إلــى تلك الســيارة‬\n‫ثــم تفاجــأ بســرعة رجــوع الســيارة وهروبــه‪ .‬وباالطــاع علــى محضــر‬\n‫تنفيــذ املهمــة املتضمــن بأنــه أثنــاء حضــور الدوريــة األمنيــة للمبلــغ حضــر‬\n‫شــخص آخــر يفيــد باختفــاء ابــن أخيــه عنــد ذهابــه للتموينــات ويتوقــع‬\n‫بأنــه نفــس احلــدث الــذي شــاهده املبلــغ األول مــع صاحــب الســيارة ‪-‬‬\n‫وأثنــاء ذلــك حضــر شــخص يفيــد بأنــه حضــر لــه شــخص علــى ســيارة‬\n‫مــن نــوع (‪ ).......‬ويســأله عــن منــزل شــخص يدعــى (‪ )...........‬وأنــه مــر‬\n‫عليــه أكثــر مــن مــرة ‪ .‬وبســماع بــاغ عــم املجنــي عليــه املختطــف والبالــغ‬\n‫مــن العمــر(‪ )11‬عام ـ ًا بالتفصيــل أفــاد بأنــه اتصلــت عليــه زوجــة أخيــه‬\n‫تفيــد بــأن ابنهــا (‪ )...........‬خــرج إلــى التموينــات بحــي ‪...........‬ولــم يعــد‬\n‫مــن بعــد صــاة العصــر ‪ -‬فواجــه أكثــر مــن دوريــه وأبلغهــم مبــا حصــل ‪.‬‬\n‫وباالطــاع علــى محضــر تنفيــذ املهمــة املتضمــن بأنــه ورد تعميــم مبدئــي‬\n‫علــى ســيارة مــن نــوع (……‪ )..‬رقــم اللوحــة (‪ )...........‬وأنــه مت اختطــاف‬\n‫حــدث ومتــت مشــاهدة الســيارة أمــام أســواق ‪...........‬ومبتابعــة الســيارة الذ‬\n‫بالهــرب وقــام باالصطــدام بالدوريــة عــدة مــرات ثــم هــرب علــى أقدامــه‬\n‫ومتــت مالحقتــه فقــام املدعــى عليــه بالدخــول إلــى فيال حتت اإلنشــاء ومت‬\n‫إطــاق طلقــة ناريــة حتذيريــة ثــم قــام بالقفــز علــى عــدة منــازل حتــى مت‬\n‫القبــض عليــه بالشــارع املجــاور للمنــازل ومت العثــور علــى احلــدث (‪...........‬‬\n‫( وبســماع أقــوال املجنــي عليــه (‪ )...........‬أفــاد بأنــه ذهــب إلــى التموينــات‬\n\n\n                                                                                          ‫‪130‬‬\n\f      ‫بعــد صــاة العصــر ووقــف عنــده صاحــب ســيارة مــن نــوع (‪ )........‬مظللــة‬\n      ‫بشــكل خفيــف ونــزل وقــال لــه اركــب فهــرب عنــه وحلــق بــه وبعــد‬\n      ‫ســقوط املجنــي عليــه علــى األرض أخــذه واركبــه بالســيارة وحتــرك بــه‬\n      ‫إلــى داخــل احلــي ووقــف يف مــكان فضــاء وقــام بضربــه ويقــول لــه (نــزل‬\n      ‫مالبســك) فأنزلهــا وفعــل بــه الفاحشــة حيــث ادخــل ذكــره وفجــأة طــرق‬\n      ‫الزجــاج شــخص فتحــرك املدعــى عليــه وهــرب بســرعة واجتــه إلــى حــي‬\n      ‫‪...........‬ووقــف يف مــكان صحــراوي ثــم فعــل بــه الفاحشــة داخــل الســيارة‬\n      ‫قبــل املغــرب إلــى قــرب صــاة العشــاء وجــرد احلــدث مــن مالبســه وقــام‬\n      ‫بكيــه بســيجارة ثــم طلــب منــه أن يدخــن معــه ‪ .‬ومبعاينــة ســيارة املدعــى‬\n      ‫عليــه مــن نــوع (……‪ ).‬رقــم اللوحــة ‪ ...........‬اتضــح أنهــا مضللــة اجلوانــب‬\n      ‫وبهــا كســر يف األنــوار األماميــة اليمنــى واليســرى‪ -‬ومبعاينــة الســيارة‬\n      ‫مــن الداخــل عثــر علــى ثــوب وشــماغ ومت رفــع اآلثــار التــي ميكــن أن‬\n                                                                  ‫يســتفاد منهــا لفحصهــا‪.‬‬\n      ‫وبســماع شــهادة املواطــن ‪.........../‬أفــاد بأنــه بعــد صــاة العصــر حضــر‬\n      ‫لــه صاحــب ســيارة مــن نــوع (‪ )......‬لــم يأخــذ رقــم اللوحــة حيــث وقــف‬\n      ‫أمــام منزلهــم وســأله عــن منــزل شــخص يدعــى (‪ )...........‬فلــم يــرد عليــه‬\n      ‫ثــم كــرر عليــه الســؤال ثــم حتــرك ‪ -‬ثــم رجــع لــه مــرة أخــرى وكان‬\n      ‫يســير علــى مهلــة ثــم ثالثــة ثــم الرابعــة أتــى مســرع ًا ‪ -‬وأفــاد املواطــن بأنــه‬\n      ‫يســتطيع التعــرف علــى الســيارة فقــط أمــا قائدهــا فــا يســتطيع التعــرف‬\n             ‫عليــه ‪ .‬جــرى بعــث املجنــي عليــه للطــب الشــرعي للكشــف عليــه‪.‬‬\n      ‫مت ســحب عينــة مــن املدعــى عليــه لتحليلهــا عــن املــواد املســكر واملخدرة‬\n      ‫‪ .‬جــرى بعــث مالبــس املجنــي لألدلــة اجلنائيــة لفحصهــا ‪ .‬مت رفــع آثــار مــن‬\n                                              ‫مرتبــة الســيارة مــن قبــل األدلــة اجلنائيــة‪.‬‬\n\n\n‫‪131‬‬\n\f‫وباستشــمام املدعــى عليــه لــم يتضــح انبعــاث رائحــة املســكر مــن‬\n‫أنفاســه‪ .‬وبعــرض ســيارة املدعــى عليــه علــى الشــاهد ‪ ...........‬اســتطاع‬\n‫التعــرف عليهــا متامـ ًا مؤكــد ًا وجازمـ ًا بأنهــا نفــس الســيارة وبهــا كســر‬\n‫يف اإلضــاءة األماميــة ‪ .‬وبعــرض املدعــى عليــه وســيارته علــى املبلــغ‬\n‫وابنــه (املجنــي عليــه) اســتطاعا التعــرف عليــه وعلــى ســيارته مؤكديــن‬\n‫وجازمــن بأنــه قائــد الســيارة ‪ ....‬رقــم اللوحــة‪ ............‬وهــو مــن كان‬\n‫داخلهــا ‪ .‬مت إيقافــه اســتناد ًا للقــرار الــوزاري (‪ )1900‬وباســتجوابه أقــر‬\n‫بــأن الســيارة مــن نــوع ‪ .......‬رقــم اللوحــة ‪ ...........‬عائــده لــه ‪ .‬ومبواجهتــه‬\n‫مبحضــر التعــرف أفــاد بأنــه وقــف عنــد أحدهمــا عنــد التموينــات‬\n‫القريبــة مــن إدارة املــرور وســأله عــن منــزل شــخص يدعــى (‪)...........‬‬\n‫فهــرب احلــدث أمــا األخــر فلــم يشــاهدهم إطالقــا يف حياتــه‪ .‬كمــا أفــاد‬\n‫بأنــه هــرب مــن الدوريــات األمنيــة خوفـ ًا منهــم حيــث أن بينــه وبــن أحــد‬\n‫أفــراد الدوريــة خــاف ‪،‬وأنكــر خــاف ذلــك‪ .‬وبإعــادة اســتجوابه أفــاد‬\n‫بــأن الدوريــة األمنيــة هــي التــي صدمتــه مــن األمــام حينمــا كان واقفــا‬\n‫عنــد الصرافــة ‪ -‬كمــا أفــاد بأنــه يف تاريــخ ‪1433/12/26‬ه ـ كان يف‬\n‫منزلــه مــن الســاعة الثالثــة عصــر ًا وخــرج بعــد املغــرب للصرافــة التــي‬\n‫تقــع بجــوار فنــدق(‪ )......................‬وأصــر علــى بقيــة أقوالــه الســابقة ‪.‬‬\n‫وقــد أثبــت التقريــر الطبــي الشــرعي رقم‪...........‬لســنة ‪1433‬ه ـ الصــادر‬\n‫مــن إدارة الطــب الشــرعي …‪ ..‬بأنــه بفحــص ظاهــر جســم املجنــي عليــه‬\n‫(‪ )...........‬اتضح وجود عالمات عنف بعامة جســمه تشــير إلى اســتخدام‬\n‫القــوة يف إجبــار املجنــي عليــه علــى فعــل الفاحشــة بــه ‪ .‬وبفحــص منطقــة‬\n‫الشــرج شــوهد احمــرار شــديد حــول فتحــة الشــرج ووجــود ســائل مصفــر‬\n‫اللــون شــبه متجلــط بــن االليتــن وحــول وداخــل الشــرج ورفعــت مســحات‬\n\n\n                                                                                           ‫‪132‬‬\n\f      ‫منــه لفحصهــا ‪ -‬كمــا تبــن وجــود شــق شــرجي ســطحي حديــث بفتحــة‬\n      ‫الشــرج‪ -‬كمــا تبــن وجــود جــرح تهتكــي يقــع عمــودي علــى محيــط‬\n      ‫فتحــة الشــرج وهــو جــرح دامــي ومتعــرج ومحــاط بتكــدم‪ .‬كمــا لــم‬\n      ‫يتبــن ثمــة قطــوع أو متزقــات أو ثقــوب مبالبــس املجني عليــه‪ .‬كما وردت‬\n      ‫نتيجــة فحــص املســحات املأخــوذة مــن داخــل الشــرج وخارجــه بالتقريــر‬\n      ‫رقــم ‪...........‬بإيجابيــة فحــص املســحات عــن التلوثــات املنويــة كمــا ثبــت‬\n      ‫بــأن البصمــة الوراثيــة لهــذه التلوثــات املنويــة قــد تطابقــت مــع البصمــة‬\n                                                           ‫الوراثيــة للمدعــى عليــه ‪.‬‬\n      ‫كمــا بلغــت قيمــة تلفيــات الدوريــة األمنيــة تســعة آالف وتســعمائة‬\n      ‫وســتون ريــاال ‪ .‬وقــد أســفر التحقيــق معــه عــن اتهامــه بخطــف حــدث‬\n      ‫وفعــل فاحشــة اللــواط بــه بالقــوة ومحاولــة خطــف حــدث أخــر والهــرب‬\n      ‫مــن رجــال األمــن وصــدم دوريــة أمنيــة واملجــرم شــرعاً‪ .‬وذلــك لألدلــة‬\n                                                                   ‫والقرائــن التاليــة‪:‬‬\n      ‫‪ -1‬مــا جــاء يف أقوالــه املنــوه عنهــا واملدونــة على الصفحــة(‪)1-2-3-4-5‬‬\n      ‫مــن دفتــر التحقيــق املرفــق لفــة رقــم(‪ - 2 )24‬مــا جــاء يف شــهادة‬\n      ‫الشــهود املنــوه عنهــا واملدونــة علــى الصفحــة (‪ )10‬مــن دفتــر تقريــر‬\n      ‫األحــوال األمنيــة املرفــق لفــة رقــم(‪ )1‬والصفحــة (‪ )1-2‬مــن دفتــر ملــف‬\n      ‫اســتكمال إجــراءات االســتدالل املرفــق لفــة رقــم (‪ -3 )3‬مــا جــاء يف‬\n      ‫محضــر تنفيــذ املهمــة املرفــق لفــة رقــم (‪ -4 )4-5-12‬مــا جــاء يف تقريــر‬\n      ‫الطــب الشــرعي وتقريــر الفحــوص الوراثيــة املرفــق لفــة رقــم (‪ -5 )38‬مــا‬\n      ‫جــاء يف محاضــر التعــرف املنــوه عنهــا واملدونــة علــى الصفحــة (‪ )16‬مــن‬\n      ‫دفتــر تقريــر األحــوال األمنيــة املرفــق لفــة رقــم (‪ )1‬والصفحــة (‪)2-3‬‬\n      ‫مــن دفتــر ملــف اســتكمال إجــراءات االســتدالل املرفــق لفــة رقــم(‪3‬‬\n\n\n‫‪133‬‬\n\f‫) ‪ - 6‬مــا جــاء يف محضــر املعاينــة املنــوه عنــه واملــدون علــى الصفحــة‬\n‫(‪ )2-3‬مــن دفتــر تقريــر األحــوال األمنيــة املرفــق لفــة رقــم(‪. (1‬وحيــث‬\n‫إن مــا أقــدم عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا وهــو محصــن‬\n‫يعــد ضرب ـ ًا مــن ضــروب احلرابــة واإلفســاد يف األرض وهــو فعــل محــرم‬\n‫ومعاقــب عليــه شــرع ًا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n‫بحــد احلرابــة الــوارد يف اآليــة رقــم (‪ )33‬مــن ســورة املائــدة علــى ضــوء‬\n‫قــرار هيئــة كبــار العلمــاء رقــم (‪ )85‬بتاريــخ ‪1401/11/11‬ه ــومصادرة‬\n‫ســيارته املســتخدمة باجلرميــة (علم ـ ًا بــأن احلــق اخلــاص مــازال قائم ـاً)‬\n                                     ‫وبــاهلل التوفيــق ‪ .‬املدعــي العــام ‪...........‬‬\n‫وبعــرض ذلــك علــى املدعــى عليــه ‪ :‬أجــاب وهــو يفهم اخلطاب جيــدا بقوله‬\n‫مــا ذكــره املدعــي العــام بدعــواه كلــه غيــر صحيــح جملــة وتفصيــا‬\n‫هــذه إجابتــي ثــم جــرى ســؤاله عــن الســوابق التــي ذكرهــا املدعــي العــام‬\n‫فقــال كل الســوابق التــي ذكرهــا املدعــي العــام غيــر صحيحــة عــدا‬\n‫املخــدرات فهــي صحيحــة ثــم جــرى ســؤاله عــن نــوع الســيارة التــي معــه‬\n‫فأجــاب بقولــه ســيارتي هــي مــن نــوع ‪ ......‬ولونهــا ‪ ........‬فجــرى ســؤاله هــل‬\n‫هــو متــزوج وهــل لديــه أوالد وهــل هــو يدخــن أم ال فقــال أنــا متــزوج منــذ‬\n‫خمــس ســنوات وليــس لــدي أوالد وأشــرب الدخــان ثــم جــرى ســؤاله هــل‬\n‫هــو موظــف فقــال أنــا علــى وظيفــة ســائق ومراســل لــدى أمانــة منطقــة‬\n‫‪ ......‬علــى املرتبــة الثالثــة والثالثــن ولــي يف اخلدمــة ثمــان ســنوات ومت‬\n‫توجيــه هــذه األســئلة للمدعــى عليــه وقــد أجــاب عليهــا بهــذه اإلجابــات‬\n‫الواضحــة املفهومــة وقــد كان يفهــم كل ســؤال يوجــه إليــه وقــد مت‬\n‫الرجــوع إلــى املعاملــة فوجدنــا إجاباتــه بخصــوص الســيارة والوظيفــة‬\n‫واحلالــة االجتماعيــة مطابقــة ملــا جــاء يف إجاباتــه وللرجــوع للمعاملــة‬\n\n\n                                                                                         ‫‪134‬‬\n\f      ‫ورصــد مــا فيهــا مــن بيانــات رفعــت اجللســة األولــى وتأجلــت إلــى يــوم‬\n      ‫الســبت املوافــق ‪1434/2/30‬ه ـ الســاعة العاشــرة ومت إغالقهــا الســاعة‬\n      ‫‪ 12: 45‬وعليــه جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                  ‫نبينــا محمــد وآلــه وصحبــه أجمعــن حــرر يف ‪1434/2/23‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلدينــا نحــن القضــاة يف احملكمــة العامــة بحائــل‬\n      ‫كال مــن ‪...........‬و‪................‬و‪ ...........‬القائــم بعمــل فضيلــة الشــيخ‬\n      ‫‪......................‬الــذي يتمتــع بإجــازة عاديــة واملكلفــن مبوجــب شــرح‬\n      ‫فضيلــة الرئيــس املســاعد رقــم ‪ 34369794‬وتاريــخ ‪1434/02/13‬ه ـ‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بحائــل املســاعد برقــم ‪ 3483544‬وتاريــخ ‪1434/02/19‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 34396101‬وتاريــخ ‪1434/2/17‬ه ـ ففــي يــوم الســبت‬\n      ‫املوافق‪1434/02/30‬ه ـ افتتحــت اجللســة الثالثــة الســاعة ‪ 11 : 45‬وفيهــا‬\n      ‫حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليــه وبالرجــوع إلــى‬\n      ‫املعاملــة لرصــد بينــات املدعــي العــام وجــد علــى اللفــة رقــم (‪ )24‬دفتــر‬\n      ‫حتقيــق حيــث وجــد علــى الصفحــات ( ‪ ) 5 - 1‬اســتجواب للمدعــى عليــه‬\n      ‫ونــص احلاجــة منــه « س‪ /‬قــدم نفســك جلهــة التحقيــق ج‪ /‬االســم‬\n      ‫‪ ......................‬ســعودي عمــري (‪ )35‬ســنة ومتــزوج وأعمــل موظــف خاص‬\n      ‫وأســكن يف حائل بحي ‪...........‬متعلم ابتدائي س‪ /‬أنت متهم باختطاف‬\n      ‫حــدث وفعــل فاحشــة اللــواط فيــه بالقــوة وكذلــك محاولــة خطــف حدث‬\n      ‫آخــر فمــا قولــك وصــدم دوريــة أمنيــة والهــروب عنهــا فمــا قولــك ؟ ج‪/‬‬\n      ‫غيــر صحيــح بــل كنــت واقــف عنــد الصرافــة وصدمتنــي الدوريــة مــن‬\n      ‫األمام س‪ /‬ملاذا قاموا بصدمك ؟ ج‪ /‬ال أعلم س‪ /‬أفاد املواطن ‪...........‬‬\n      ‫بأنــه شــاهدك متوقــف بســيارتك بأحــد األحيــاء وأنــت تفعــل الفاحشــة‬\n\n\n‫‪135‬‬\n\f‫بحــدث ثــم هربــت فمــا قولــك ؟ ج‪ /‬غيــر صحيــح س‪ /‬إذا كان غيــر‬\n‫صحيــح فلمــاذا يفتــري عليــك ؟ ج‪ /‬ال أدري س‪ /‬أفــاد احلــدث ‪...........‬‬\n‫بأنــك اختطفتــه وفعلــت بــه الفاحشــة بالســيارة وقمــت بكيــه بســيجارة‬\n‫وطلبــت منــه أيضـ ًا أن يدخــن فمــا قولــك ؟ ج‪ /‬غيــر صحيــح س‪ /‬ملــن تعــود‬\n‫الســيارة مــن نــوع ‪ ......‬رقــم اللوحــة (‪ )...............‬؟ ج‪ /‬تعـ ــود لــي س‪ /‬لقــد‬\n‫اســتطاعا املجنــي عليهمــا وذويهــم التعــرف عليــك وعلــى ســيارتك فمــا‬\n‫قولــك ؟ ج‪ /‬أمــا األحــداث فقــد وقفــت عنــد أحدهمــا عنــد البقالــة‬\n‫القريبــة مــن املــرور وســألت عــن منــزل ‪...........‬ثــم هــرب أما اآلخــر وذويهم‬\n‫فلــم أشــاهدهم إطالقــا يف حياتــي س‪ /‬مــن هــو ‪...........‬الــذي تبحــث عنــه‬\n‫؟ ج‪ /‬هــو صديقــي وأردت زيارتــه س‪ /‬ملــاذا لــم تتصــل عليــه ؟ ج‪ /‬جوالــه‬\n‫مقـف ــل س‪ /‬ملــاذا قمــت بالهــرب مــن الدوريــات ؟ ج‪ /‬خفــت منهــم س‪ /‬هــل‬\n‫قمــت بعمــل شــيء حتــى تخــاف منــه ؟ ج‪ /‬كال ولكــن بينــي وبــن أحــد‬\n‫أفــراد الدوريــة خــاف فهربــت خوفــا منــه س‪ /‬هــذا كالم غيــر منطقــي‬\n‫وأنصحــك بقــول احلقيقــة ؟ ج‪ /‬مــا قلتــه هــو احلقيقــة س‪ /‬هــل تتعاطــى‬\n‫شــيء مــن املــواد املســكرة واملخــدرة ؟ ج‪ /‬كال س‪ /‬لقــد أفــاد عــم‬\n‫احلــدث ‪ ...........‬بأنــه خــرج إلــى البقالــة بحــي ‪...........‬ولــم يع ــد مــن بعــد‬\n‫صــاة العصــر وأنــه أبلــغ العمليــات بذلــك فوجــدت الدوريــات احلــدث‬\n‫‪...........‬بســيارتك فعلــى مــا يــدل ذلــك ؟ج‪ /‬غيــر صحيــح س‪ /‬احلــي الــذي‬\n‫خطــف منــه احلــدث ‪...........‬هــو نفــس احلــي الــذي كنــت تبحــث عــن منزل‬\n‫صديقــك ‪...........‬فيــه فيــدل علــى أنــك أنــت مــن قمــت بخطــف احلــدث‬\n‫فمــا قولــك ؟ ج‪ /‬نعــم صحيــح ولكــن لــم أخطــف أحــدا س‪ /‬هــل لديــك‬\n‫أقــوال أخــرى ؟ ج‪ /‬كال س‪ /‬هــل لديــك ســوابق ؟ ج‪ /‬نعــم صحيــح‬\n‫مخــدرات س‪ /‬هــل تصــادق علــى أقوالــك ؟ج‪ /‬نع ــم وقــد أقفــل احملضــر‬\n\n\n                                                                                            ‫‪136‬‬\n\f      ‫يف وقتــه وحينــه وذيــل بتوقيــع املدعــى عليــه وكاتــب الضبــط واحملقــق‬\n      ‫كمــا وجــد علــى الصفحــة رقــم ( ‪ 4‬و ‪ ) 5‬محضــر إعــادة اســتجواب‬\n      ‫للمدعى عليه ونص احلاجة منه س‪ /‬أين كنت بتاريخ ‪1433/12/26‬هـ‬\n      ‫مــن الســاعة الثالثــة عصــرا حتــى الســاعة الثامنــة مســاءا ؟ ج‪ /‬كنــت يف‬\n      ‫املنــزل وخرجــت بعــد املغــرب للصرافــة التــي عنــد فنــدق ‪...........‬س‪ /‬مــن‬\n      ‫كان معــك يف املنــزل أثنــاء تواجــدك ؟ ج‪ /‬زوجتــي فقــط س‪ /‬لقــد‬\n      ‫اســتطاع احلدثــن التعــرف عليــك فمــاذا تبــرر ذلــك ؟ ج‪ /‬غيــر صحيــح‬\n      ‫لقــد مت عرضــي عليهــم ولــم يســتطيع التعــرف علــي « أ‪ .‬ه ـ نــص احلاجــة‬\n      ‫منــه كمــا وجــد علــى اللفــة رقــم (‪ )1‬دفتــر تقريــر األحــوال األمنيــة‬\n      ‫املوح ــد حيــث وجــد علــى الصفحــة رقــم (‪ « )10‬شــهادة ‪...........‬أفيدكــم‬\n      ‫أننــي بقيــت باملســجد بعــد صــاة العصــر فوردنــي اتصــال مــن أهلــي‬\n      ‫مفــاده أن ‪...........‬حــاول شــخص خطفــه واجتهــت إلــى املنــزل بعــد نصــف‬\n      ‫ســاعة مــن صــاة العصــر ووجــدت ‪ .......‬وســألته عمــا حــدث فأفــاد بأنــه‬\n      ‫ذاهــب للتموينــات علــى أقدامــه ووقــف عنــده صاحــب ســيارة ‪ .......‬رقــم‬\n      ‫اللوحــة ( ‪ )...........‬وهــو يف طريقــه إلــى املنــزل وســأله عــن شــقق مفروشــة‬\n      ‫ووصــف لــه ثــم حتــرك ثــم عــاد لــه ووقــف عنــده ونــزل وأمســك بيــده‬\n      ‫وســحبه يريــد إركابــه فدفعــه عنــه وحتــرك ثــم أنــا بــدوري حتركــت‬\n      ‫أنــا وابنــي علــى ســيارتي للبحــث عــن الســيارة يف احلــي ولــم أجدهــا ثــم‬\n      ‫ذهــب ابنــي علــى الســيارة لوحــده يبحــث عنهــا فأفادنــي أنــه وجدهــا‬\n      ‫واقفــة بحــي ‪...........‬بشــارع وعــدت معــه علــى الســيارة ودلنــي عليهــا وهــي‬\n      ‫نفــس املواصفــات ومض ــللة ووقفنــا عنهــا بعيــدا ثــم نزلــت علــى أقدامــي‬\n      ‫للســيارة وإذا بحالــة تشــغيل وقربــت مــن الزجــاج فــإذا بهــا شــخص يحتمل‬\n      ‫أننــي أعرفــه عنــد مشــاهدته عمــره (‪ )27‬عــام تقريبــا ومنــزل مالبســه‬\n\n\n‫‪137‬‬\n\f‫ومعــه طفــل عــاري مــن املالبــس يفعــل بــه الفاحشــة وطرقــت الزجــاج‬\n‫بيــدي وانتبــه ورجــع بهــا للخلــف بســرعة ثــم حتــرك لألمــام وهــرب ومعــه‬\n‫الطفــل س‪ /‬هــل تعــرف الطفــل وكــم عمــره ؟ ج‪ /‬لــم أمتكــن مــن وجهــه‬\n‫وعمــره أكبــر مــن عشــر ســنوات تقريبــا أمــا مواصفــات الشــخص‬\n‫اخلاطــف علــى ذقنــه شــعر خفيــف وشــيب ولــم أمتكــن مــن رؤيتــه متامــا‬\n‫س‪ /‬هــل تســتطيع التعــرف علــى الســيارة ؟ نعــم ويوجــد بهــا االســطب‬\n‫األمامــي األميــن تالــف « أ‪.‬ه ـ كمــا وجــد علــى اللفــة رقــم (‪ )3‬ملــف‬\n‫اســتكمال محاضــر إجــراءات االســتدالل حيــث وجــد علــى الصفحــة‬\n‫رقــم ( ‪ ) 2 - 1‬شــهادة‪...........‬اآلتي نصهــا ‪ :‬س‪ /‬أعطــي معلومــات‬\n‫شــخصية عــن نفســك ج‪ /‬االســم ‪ .............../‬العمــر ‪ )18( /‬عــام املهنــة ‪/‬‬\n‫طالــب احلالــة االجتماعيــة ‪ /‬أعــزب احلالــة التعليميــة ‪ /‬متعلــم الســكن ‪/‬‬\n‫حــي ‪...........‬رقــم الســجل املدنــي (‪)..........‬مصدرهــا ‪ /‬حائــل تاريخهــا‬\n‫‪1432/04/18‬ه ـ جــوال (‪ )...........‬س‪ /‬أفدنــي عمــا لديــك مــن معلومــات‬\n‫ج‪ /‬أفيدكــم أنــه بعــد صــاة العصــر حضــر لــي صاحــب ســيارة ‪ ......‬لــم‬\n‫آخــذ رقــم لوحتهــا حيــث وقــف أمــام منزلنــا عندما كنت واقــف ونظرني‬\n‫ويقــول أيــن بيت‪...........‬ولــم أرد عليــه وكــرر الســؤال ثــم حتــرك ثــم رجــع‬\n‫لــي مــرة ثانيــة مــع الشــارع حيــث ميشــي علــى مهلــه ثــم ثالثــة ورابعــة أتــى‬\n‫مســرعا س‪ /‬هــل تكلــم معــك بشــيء ج‪ /‬كال فقــط ســؤال عــن بيــت‬\n‫‪...........‬س‪ /‬هــل تعــرض لــك بــأذى ج‪ /‬كال س‪ /‬هــل ترغــب مواصلــة‬\n‫دعــواك ضــده ؟ ج‪ /‬كال س‪ /‬هــل تســتطيع التعــرف عليــه وعلى الســيارة‬\n‫؟ ج‪ /‬ال أســتطيع التعــرف علــى الســيارة أمــا الشــخص فلــم أمتكــن مــن‬\n‫وجهــه حيــث كنــت غيــر منتبــه لــه وال أرغــب مقابلتــه نهائيــا س‪ /‬هــل‬\n‫تصــادق علــى أقوالــك ج‪ /‬نعــم وقــد ذيــل بتوقيــع احملقــق واملســتجوب «‬\n\n\n                                                                                         ‫‪138‬‬\n\f      ‫أ‪.‬ه ـ كمــا وجــد علــى اللفــة رقــم (‪ 4‬و ‪ )5‬محضــر تنفيــذ مهمــة وتســليمها‬\n      ‫جلهــة االختصــاص برقــم ‪...........‬يف يــوم األحــد ‪1433/12/26‬ه ـ يتضمــن‬\n      ‫بــاغ مــن ‪...........‬و‪...........‬والشــاهد ‪ ...........‬واحلــدث ‪ ...........‬واحلــدث‬\n      ‫‪...........‬نــوع الســيارة التــي لهــا عالقــة باحلالــة ‪ )...........( ....‬وملخــص احلالة‬\n      ‫نحيــل إليكــم املدعــن املوضــح أســمها أعــاه حيث يدعــي املدعي األول‬\n      ‫علــى صاحــب ‪ ....‬املوضــح بياناتــه حيــث حــاول خطــف ابنــه ومتكــن ابنــه‬\n      ‫مــن الفــرار وبعــد ذلــك قــام بالبحــث عــن الســيارة ووجدهــا داخــل احلــي‬\n      ‫متوقفــة وبعــد ترجلــه شــاهد القائــد معــه حــدث داخــل ســيارة ‪ .....‬بــدون‬\n      ‫مالبــس ويفعــل الفاحشــة باحلــدث داخــل الســيارة علمــا بــأن الســيارة‬\n      ‫كانــت بوضــع التشــغيل ومقف ــلة األبــواب وحــاول املدعــي كســر الزجاج‬\n      ‫بعصــى خشــبية وبعــده ارتكــب الفــرار الشــخص دون كســر زجــاج‬\n      ‫الســيارة وأثنــاء مقابلــة الدوريــة للمدعــي األول حضــر املدعــي الثانــي‬\n      ‫حيــث يفيــد عــن اختفــاء ابــن أخيــه عنــد ذهابــه للبقالــة واحتمــال كبيــر‬\n      ‫أنــه يكــون نفــس احلــادث الــذي شــاهده املدعــي األول مــع صاحــب‬\n      ‫الســيارة وأثنــاء وجــود الدوريــة مــع املدعــن حضــر شــخص يفيــد بأنــه‬\n      ‫حضــر لــه شــخص علــى ســيارة مــن نــوع ‪ .....‬املوضــح بياناته أعاله ويســأل‬\n      ‫عــن منــزل شــخص يدعــى ‪...........‬وأفــاد أنــه دار أكثــر مــن مــرة كمــا‬\n      ‫وجــد علــى اللفــة رقــم (‪ )12‬محضــر تنفيــذ مهمــة برقــم ‪...........‬يف‬\n      ‫‪1433/12/26‬ه ـ يتضمــن القبــض علــى ســيارة ‪ )........... ( .......‬وملخــص‬\n      ‫احلالــة نحيــل لكــم الســيارة والشــخص املوضــح حيــث ورد بــاغ تعميــم‬\n      ‫مبدئــي مــن قبلكــم علــى الســيارة املوضحــة اختطــاف حــدث ومت‬\n      ‫مشــاهدة الســيارة أمــام ‪...........‬وقــام بالهــروب وقــام بصــدم الدوريــة عــدة‬\n      ‫مــرات وقــام بالهــروب علــى األقــدام ومتابعتــه ودخوله فيال حتت اإلنشــاء‬\n\n\n‫‪139‬‬\n\f‫ومت إطــاق طلقــة حتذيريــة وقــام بالقفــز لعــدة منــازل حتــى مت القبــض‬\n‫عليــه بالشــارع املجــاور للمنــازل وتعــرض إلصابــة بســيطة جــراء القفــز‬\n‫الــذي قــام بــه املجنــي وأثنــاء القبــض مت العثــور علــى احلــدث املوضــح وهــو‬\n‫‪...........‬وهــو بصحــة جيــدة علمــا بأنــه مت نقــل اجلانــي للطــوارئ لتلقــي‬\n‫العــاج ومت طلــب دوريــة املــرور باملوقــع لتخطيــط احلــادث ومت إحالــة‬\n‫احلــدث برفقــة أخيــه املوضــح اســمه ونفيدكــم بــأن اجلانــي يتلقــى العــاج‬\n‫حاليــا نأمــل اســتالم املوضــوع التخــاذ الــازم كمــا وجــد علــى اللفــة رقــم‬\n‫(‪ )37‬تقريــر الطــب الشــرعي وتقريــر الفحــوص الوراثيــة مرفقــة بظــرف‬\n‫حيــث وجــد التقريــر الطبــي الشــرعي رقــم ‪...........‬لســنة ‪1433‬ه ـ نــص‬\n‫احلاجــة منــه « املناقشــة والــرأي ممــا ســبق وتقــدم وإجابة ألســئلة التحقيق‬\n‫نقــرر اآلتــي ‪ )1( :‬احلــدث ‪ ............. /‬ســعودي اجلنســية ويبلــغ مــن العمــر‬\n‫‪ 11‬عــام ـ ـ رقــم الســجل املدنــي ‪ )2(...........‬كان املذكــور حــال توقيــع‬\n‫الكشــف الطبــي عليــه واعيــا ومــدركا للزمــان واملــكان واألشــخاص‬\n‫(‪ )3‬ادعــى املذكــور بخطفــه أثنــاء عودتــه ملنزلــه مــن البقالــة بعــد صــاة‬\n‫عصــر يــوم األحــد املوافق‪1433/12/26‬ه ـ وفعــل فاحشــة اللــواط بــه‬\n‫بالقــوة مــن قبــل شــخص مجهــول وأن الشــخص قــد أدخل ذكره بالشــرج‬\n‫مرتــن (‪ )4‬بفحــص مالبــس املذكــور التــي كان يرتديهــا وقــت احلــادث‬\n‫تبــن لنــا اآلتــي ‪ :‬أ‪ -‬لــم نتبــن بهــا ثمــة قطــوع أو متزقــات مشــتبهة وهــذا‬\n‫يشــير النعــدام املقاومــة والتشــابك بــن املجنــي عليــه واجلانــي نظــرا لعــدم‬\n‫التكافــؤ يف قــوة كل منهمــا بـ ـ تبينــا بالبنطلــون مواضــع تلوثــات يشــتبه‬\n‫بكونهــا تلوثــات منويــة ج‪ -‬أفــاد فحــص املالبــس مــن قبــل األدلــة اجلنائيــة‬\n‫بســلبية الفحــص عــن التلوثــات املنويــة ‪ )5( -‬تبــن لنــا وجــود عالمــات‬\n‫عنــف عامــة بجســم املذكــور وتشــير الســتخدام القــوة يف إجبــار املجنــي‬\n\n\n                                                                                       ‫‪140‬‬\n\f      ‫عليــه علــى فعــل الفاحشــة بــه وهــذه العالمــات هــي أ‪ -‬الســحج‬\n      ‫االحتكاكــي املشــاهدة بأســفل ميــن مقــدم الصــدر واملوصــوف بصلــب‬\n      ‫التقريــر هــي إصابــات رضيــة احتكاكيــة وتنتــج عــن االحتــكاك‬\n      ‫بطــرف ناتــئ جلســم صلــب أيــا كان نوعــه أثنــاء كبــه علــى وجهــه لفعــل‬\n      ‫الفاحشــة بــه وقــد مــر علــى هــذا الســحج مــدة تقــدر بعــدة ســاعات فقــط‬\n      ‫حيــث كان ســطحها محمــرا وبــه ارتشــاح مصلــي وهــذا يتفــق مــع مــا‬\n      ‫أفادنــا بــه املجنــي عليــه بخصــوص وقــت االعتــداء عليــه ب ‪ -‬التكدمات‬\n      ‫احلديثــة املشــاهدة بيســار الوجــه ويســار األنــف هــي إصابــات رضيــة‬\n      ‫حديثــة وتنتــج عــن املصادمــة بجســم أو أجســام صلبــة راضــة وهــي‬\n      ‫ممكنــة احلــدوث نتيجــة الصفــع بيــد اجلانــي للمجنــي عليــه كمــا أفــاد‬\n      ‫املجنــي عليــه ‪ - 7 -‬تبــن لنــا مــن خــال الفحــص املوضعي ملنطقة الشــرج‬\n      ‫‪ -‬كمــا هــو مشــار إليــه بصلــب التقريرـ ـ عــدم وجــود عالمــات ومظاهــر‬\n      ‫تشــير لتكــرار اســتعمال املذكــور مــن اخللــف لواطــا ‪ - 8 -‬جــاءت‬\n      ‫نتيجــة فحــص املســحات املرفوعــة مــن داخــل الشــرج وخارجــه إيجابيــة‬\n      ‫بالنســبة للتلوثــات املنويــة وقــد تطابقــت البصمــة الوراثيــة لهــذه التلوثــات‬\n      ‫مــع البصمــة الوراثيــة ألحــد األشــخاص املســجلني لــدى األدلــة اجلنائيــة‬\n      ‫وهــو نفــس الشــخص الــذي اعتــدى علــى املذكــور وهــذا يثبــت تعــرض‬\n      ‫املذكــور لإلمنــاء عليــه مــن قبــل الشــخص املتهــم ‪ - 9 -‬تبينــا مبنطقــة‬\n      ‫الشــرج وجــود إصابــات حديثــة علــى هيئــة شــق شــرجي ســطحي مقابــل‬\n      ‫موضــع الســاعة الثانيــة عشــرة علــى قــرص الســاعة وكذلــك شــق‬\n      ‫شــرجي نــازف علــى هيئــة جــرح تهتكــي وهــي إصابــات رضيــة حديثــة‬\n      ‫وميكــن أن حتــدث نتيجــة إيــاج جســم صلــب راض مثــل قضيــب ذكــر‬\n      ‫بالــغ منتصــب أو مــا يف حكمــه ويعاصــر تاريــخ حــدوث هــذه اإلصابــات‬\n\n\n‫‪141‬‬\n\f‫تاريــخ الواقعــة املدعــاة ‪ - 10 -‬إن واقعــة االعتــداء علــى املذكــور قــد‬\n‫تأكــدت مبــا يلــي أ‪ -‬مــا أثبتتــه الفحــوص الوراثيــة مــن إيجابيــة فحــص‬\n‫املســحات الشــرجية للتلوثــات املنويــة وأن بصمتهــا الوراثيــة تتطابــق مــع‬\n‫الشــخص املعتــدي علــى احلــدث املذكــور ب ‪ -‬كمــا يؤكــد االعتــداء‬\n‫اجلنســي أيضــا وجــود املظاهــر اإلصابيــة املوضعيــة احلديثــة املشــاهدة‬\n‫مبنطقــة الشــرج واملشــار إليهــا بعاليــه (احمــرار شــديد باجللــد ووجــود‬\n‫شــقني شــرجيني ) والتــي ميكــن حدوثهــا نتيجــة إيــاج عنيــف لقضيــب‬\n‫ذكــر منتصــب بالشــرج وجــود عالمــات عنــف عامــة بجســم املذكــور‬\n          ‫وتشير الستخدام القوة إلرهابه وإجباره على االستسالم للجاني‬\n‫د ‪ -‬مــا أفــاده التحقيــق مــن القبــض علــى اجلاني وبرفقته املجني عليه بعد‬\n‫االعتــداء عليــه أثنــاء إعادتــه ملنزلــه ‪ - 11 -‬قمنــا بإحالــة املجني عليه بعد‬\n‫الكشــف عليــه لقســم اجلراحــة مبستشــفى ‪ .....‬العــام للكشــف الطبــي‬\n‫علــى اإلصابــات املشــاهدة مبنطقــة الشــرج وتقــدمي العــاج املناســب‬\n‫واهلل املوفــق أخصائــي أول الطــب الشــرعي ‪ .....‬الدكتــور ‪........... /‬‬\n‫توقيعــه وختــم الطــب الشــرعي « كمــا وجــد تقريــر الفحــوص الوراثيــة‬\n‫ـاء علــى‬‫رقــم ‪ 1433/...........13‬نــص احلاجــة منــه « النتيجــة النهائيــة بنـ ً‬\n‫حتليــل احلمــض النــووي الوراثــي (‪ )DNA‬ملورثــات ال ـ (‪ )STR‬املوضحة‬\n‫يف اجلــدول الســابق تبــن مــا يلــي‪ :‬تطابــق ‪ :‬األمنــاط الوراثيــة للعينــة رقــم‬\n‫(‪ )...........‬الــوارد تفصيلهــا باجلــدول اخلــاص بالعينــات الــواردة للفحــص‬\n‫مــع األمنــاط الوراثيــة لعينــة الــدم ا لقياســية رقــم (‪ )...........‬والعائــدة ل ـ‬\n‫‪......................‬والصــادر بحقهــا تقريرنــا رقم‪...........‬ممــا يثبــت أن ‪...........‬‬\n‫(ســعودي اجلنســية) هــو مصــدر التلوثــات املنويــة يف هــذه العينــة ‪ -‬األمنــاط‬\n‫الوراثيــة للعينــة القياســية رقــم (‪ )...........‬والعائــدة ل‪...........‬تقــع ضمــن‬\n\n\n                                                                                              ‫‪142‬‬\n\f      ‫األمنــاط الوراثيــة للعينــة املختلطــة رقــم (‪ )...........‬الــوارد تفصيلها باجلدول‬\n      ‫اخلــاص بالعينــات الــواردة للفحــص ممــا يــدل أنهــا أحــد مصــادر هــذا‬\n      ‫االختــاط ‪ -‬مت حتديــد األمنــاط الوراثيــة للعينــة رقــم (‪ )...........‬الــوارد‬\n      ‫تفصيلهــا يف اجلــدول اخلــاص بالعينــات الــواردة للفحــص وقــد مت بحــث‬\n      ‫هــذه األمنــاط يف قاعــدة املعلومــات الوراثيــة لدينــا ولــم نتبــن حتــى وقــت‬\n      ‫إعــداد هــذا التقريــر وجــود تطابــق جنائــي مــع أي قضايــا ســابقة ‪ -‬ســلبية‬\n      ‫العينــة رقــم (‪ )...........‬الــوارد تفصيلهــا باجلــدول اخلــاص بالعينــات الــواردة‬\n      ‫للفحــص للحمــض النــووي الوراثــي الفاحــص مــازم أول كيميائــي ‪/‬‬\n      ‫‪...........‬توقيعــه الفاحــص ‪/‬مديــر شــعبة املختبرات اجلنائيــة ‪...........‬توقيعه‬\n      ‫يعتمــد مديــر إدارة األدلــة اجلنائيــة مقــدم كيميائــي ‪...........‬توقيعــه اخلتــم‬\n      ‫الرســمي « كمــا وجــد علــى اللفــة رقــم (‪ )1‬دفتــر حتقيــق األحــوال‬\n      ‫األمنيــة حيــث وجــد علــى الصفحــة رقــم (‪ )16‬حيــث اســتطاع ‪...........‬‬\n      ‫وابنه‪...........‬التعــرف علــى ســيارة املدعــى عليــه وكذلــك اللفــة رقــم (‪)3‬‬\n      ‫علــى الصفحــة رقــم ( ‪ 2‬و ‪ ) 3‬محاضــر تعــرف حيــث اســتطاع ‪...........‬‬\n      ‫التعرف على سيارة املدعى عليه ‪ .....‬كما استطاع ‪...........‬وابنه ‪...........‬‬\n      ‫التعــرف علــى املدعــى عليــه وأنــه هــو قائــد الســيارة ‪ ....‬كمــا وجــد علــى‬\n      ‫الصفحــة رقــم (‪ 2‬و ‪ )3‬مــن الدفتــر املرفــق لفــة رقــم (‪ )1‬محضــر معاينــة‬\n      ‫اآلتــي نصــه « جــرى معاينــة الســيارة العائــدة للمتهــم ‪...........‬نــوع ‪ ......‬رقــم‬\n      ‫اللوحــة (‪ )...........‬وذلــك مــن األدلــة اجلنائيــة واتضــح أنهــا مظللــة اجلوانــب‬\n      ‫وبهــا صدم ــة بــل كســر يف االســطب األمامــي األميــن واأليســر كمــا‬\n      ‫جــرى معاينــة الســيارة مــن الداخــل وعثــر بداخلهــا علــى ثــوب ‪ +‬شــماغ ‪+‬‬\n      ‫فايــن يف أحــد األدراج ومت رفــع ذلــك مــن قبــل األدلــة اجلنائيــة وقامــوا ذلــك‬\n      ‫بقــص تلبيســة املقعــد األميــن للمرافــق لفحصهــا ولــم يعثــر علــى شــيء‬\n\n\n‫‪143‬‬\n\f‫ســوى مــا ذكــر ومت إعــداد هــذا احملضــر وذيــل بتوقيــع معديــه « أ‪ .‬ه ـ‬\n‫كمــا وجــد علــى الصفحــة رقــم (‪ 14‬ـ ـ ‪ )15‬مــن نفــس الدفتــر اســتجواب‬\n‫للحــدث ……… املتضمــن االســم ‪........... /‬العمــر ‪ 11 /‬املهن ــة ‪ /‬طالــب‬\n‫احلالــة التعليميــة ‪ /‬متعلــم الســكن ‪ /‬حــي ‪...........‬س‪ /‬أفدنــي كيــف مت‬\n‫خطفــك ؟ ج‪ /‬أفيدكــم أننــي ذهبــت إلــى التموينــات علــى أقدامــي ويف‬\n‫طريقــي بعــد صــاة العصــر وقــف عنــدي صاحــب ســيارة ‪ .......‬مظللــة‬\n‫خفيــف ونــزل وقــال لــي اركــب وهربــت عنــه وحلــق بــي بعــد ســقوطي‬\n‫علــى األرض وأخذنــي وأركبنــي داخــل الســيارة وحتــرك بــي إلــى داخــل‬\n‫احلــي ووقــف يف مــكان فاضــي وأخــذ يضربنــي ويقــول نــزل مالبســك‬\n‫ونزلــت مالبســي وافتعــل بــي حيــث أدخــل ذكــره داخــل وهــو منــزل‬\n‫بنطلونــه وفانيلتــه وفجــأة طــرق الزجــاج شــخص وحتــرك هاربـ ًا بســرعة‬\n‫واجتــه إلــى حــي ‪...........‬بالقــرب مــن حديقــة ‪...........‬التابعــة للمجمــع‬\n‫وهــي حديقــة النســاء حيــث وقــف يف مــكان صحــراوي مقابلهــا وافتعــل‬\n‫بــي داخــل الســيارة قبــل املغــرب إلــى قــرب صــاة العشــاء حيــث جردنــي‬\n‫مــن مالبســي وكينــي بســيجارة س‪ ............... /‬س‪ /‬هــل أدخــل ذكــره‬\n‫؟ ج‪ /‬نعــم باســتمرار س‪ /‬هــل تعرفــه مــن قبــل ؟ ج‪ /‬كال س‪ /‬إلــى أيــن‬\n‫اجتــه بعــد ذلــك ؟ ج‪ /‬حتــرك بعــد أن أنزلنــي وأنــا طلبــت منــه إركابــي‬\n‫وإيصالــي وقــال ال تعلــم أحــد واجتــه إلــى الصرافــة وحلقــت بــه الشــرطة‬\n‫وهــرب واســتوقفوه بالقــوة وهــرب علــى أقدامــه وأخذونــي الشــرطة س‪/‬‬\n‫مــاذا فعــل غيــر فعــل الفاحشــة ؟ ج‪ /‬أعطانــي ســيجارة وطلــب منــي أن‬\n‫أعمــر دخــان وعمــرت دخــان س‪ /‬هــل لديــك أقــوال ؟ ج‪ /‬كال س‪ /‬هــل‬\n‫تصــادق علــى أقوالــك؟ ج‪ /‬نع ــم « أ‪ .‬ه ـ وبعــرض ذلــك علــى املدعــى عليــه‬\n‫أجــاب بقولــه جميــع مــا جــاء يف بينــات املدعــي العــام غيــر صحيــح جملــة‬\n\n\n                                                                                    ‫‪144‬‬\n\f      ‫وتفصيــا وأنــا ال أعــرف الشــهود الذيــن جــاء ذكرهــم يف البينــات ولــم‬\n      ‫أشــاهد أحــدا منهــم إال يف شــرطة ‪...........‬أحضروهــم لــي هــذه إجابتــي‬\n      ‫ثــم ســألت املدعــي العــام هــل لديــه زيــادة بينــة قــال نعــم وســوف أحضرهــا‬\n      ‫يف اجللســة القادمــة إن شــاء اهلل هكــذا قــرر وقــد أجيــب لطلبــه ورفعــت‬\n      ‫اجللســة الثالثــة وتأجلــت إلــى يــوم االثنــن ‪1434/3/2‬ه ـ الســاعة التاســعة‬\n      ‫وقــد مت إغــاق اجللســة يف متــام الســاعة ‪ 12 : 30‬وعليــه جــرى التوقيــع‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                  ‫أجمعــن حــرر يف ‪1434/02/30‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد والصــاة والســام علــى مــن ال نبــي بعــده‬\n      ‫وبعــد ‪ :‬فلدينــا نحــن القضــاة يف احملكمــة العامــة بحائــل كال مــن‬\n      ‫‪......................‬و‪...........‬و‪...........‬ويف يــوم الثالثــاء املوافــق ‪1434/3/3‬ه ـ‬\n      ‫افتتحــت اجللســة يف الســاعة ‪12 : 00‬وفيهــا حضــر املدعــي العــام وحضــر‬\n      ‫حلضــوره املدعــى عليــه ‪...........‬وقــد مت ســؤال املدعــي العــام هــل أحضــر‬\n      ‫مــا وعــد بإحضــاره مــن زيــادة بينــه قــال نعــم وأطلــب ســماع مــا لديهــم هذا‬\n      ‫وقــد حضــر يف هــذه اجللســة أفــراد الدوريــات األمنيــة كال مــن ‪...........‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...........‬و ‪...........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقم ‪...........‬وبســؤالهما عمــا لديهما من‬\n      ‫شــهادة شــهد كل واحــد منهمــا مبفــرده بقولــه لقــد جاءنــا بــاغ عــن قيــام‬\n      ‫شــخص باختطــاف حــدث صغيــره عمــره ال يتجــاوز إحــدى عشــر ســنة‬\n      ‫ومت وصــف ســيارته لنــا وأنهــا ‪ ......‬فبحثــت عنــه وشــاهدته بعــد ســاعتني‬\n      ‫تقريب ـ ًا عنــد صرافــة بنــك ‪...........‬القريبــة مــن ‪...........‬التــي مقابلــه ‪....‬‬\n      ‫منطقــة حائــل فوقفــت أمامــه بســيارة الدوريــات فقام بصدمــي من األمام‬\n      ‫ثــم رجــع إلــى اخللــف وقفــز الرصيــف وهــرب فلحقــت بــه ثــم متــت متابعتــه‬\n\n\n‫‪145‬‬\n\f‫داخــل احلــي الــذي خلــف ‪...........‬حتــى وصــل إلــى طريــق مغلــق فاضطــر‬\n‫إلــى الوقــوف ثــم رجــع إلــى اخللــف حتــى تعلقــت ســيارته بصــدام ســيارة‬\n‫الدوريــة ثــم نــزل علــى قدميــه مــن الســيارة ثــم وجدنــا احلــدث يف الســيارة‬\n‫التــي كانــت بقيــادة املدعــى عليــه هــذا احلاضــر فأخذنــاه ووضعنــاه يف‬\n‫الدوريــة ثــم حاولنــا اإلمســاك باملذكــور إال انــه اســتطاع أن يفلــت منــي‬\n‫فأطلقــت عليــه طلقــة تخويفيــة يف الهــواء إال انــه هــرب ودخــل عمــارة‬\n‫حتــت اإلنشــاء ثــم بحثــت عنــه واســتطاع أن ينتقــل إلــى عمــاره أخــرى‬\n‫ا ثــم انتقــل إلــى عمــارة ثالثــه ونزل يف حوشــها‬ ‫مســكونه وبقــي فيهــا قليـ ً‬\n‫وفتــح البــاب وخــرج ثــم حــاول دخــول عمــارة أخــرى وبينمــا هــو يتســلق‬\n‫البــاب للدخــول قبضــت عليــه فلمــا قبضــت عليــه اتضــح انــه الشــخص‬\n‫الــذي مت اإلبــاغ عنــه وهــو ‪ ...........‬وهــو املدعــى عليــه هــذا احلاضــر هــذا‬\n‫مــا لــدي مــن شــهاده وبــه اشــهد هكــذا شــهد كل واحــد منهمــا منفــرد ًا‬\n‫كمــا حضــر يف هــذه اجللســة ‪ ..............‬ســعودي اجلنســية مبوجــب ســجل‬\n‫مدنــي رقــم ‪...........‬وبســؤاله عمــا لــدي مــن شــهاده قــال اشــهد هلل انــه يف‬\n‫يــوم األحــد ‪ 1433/12/26‬عصــرا كنــت يف املســجد وكان ابنــي يف‬\n‫البيــت فأرســلته والدتــه إلــى البقالــة فلمــا رجــع مــن البقالــة تعــرض لــه‬\n‫شــخص وقــال لــه اركــب فتركــه ابنــي وذهــب فنــزل صاحــب الســيارة‬\n‫وحلــق بــه وامســك بــه فقــام ابنــي بدفعــه وأفلــت منــه ثــم رجــع الشــخص‬\n‫وركــب يف ســيارته ومشــى وكان كأنــه مرتبــك ويتلفــت كثيــر ًا ثــم‬\n‫جاءنــي اتصــال مــن أهلــي ورجعــت إلــى البيــت وســألت ابنــي عمــا حــدث‬\n‫فاخبرنــي مبــا ذكرتــه ووصــف لــي الســيارة وأنهــا مــن نــوع ‪ ....‬فخرجــت‬\n‫أنــا وابنــي يف الســيارة نبحــث عــن الشــخص الــذي حــاول اإلمســاك‬\n‫بــه بنــاء علــى وصــف الســيارة فأخذنــا دورة يف احلــي وهــو حــي ‪...........‬‬\n\n\n                                                                                        ‫‪146‬‬\n\f      ‫إال أننــا لــم جنــده ثــم رجعنــا إلــى البيــت ثــم ا خــذ الســيارة أبنــي وذهــب‬\n      ‫يبحــث عنــه لوحــده ورجــع إلــي فأخبرنــي أنــه وجــد الســيارة التــي كان‬\n      ‫عليهــا الشــخص الــذي حــاول خطفــه ثــم ذهبــت أنــا وأيــاه إلــى الســيارة‬\n      ‫فوجدناهــا يف أرض فضــاء وعندهــا كــوم مــن الرمــل وكنــت أظــن أنــه‬\n      ‫ال يوجــد أحــد يف الســيارة فأوقفــت ســيارتي ونزلــت علــى قدمــي وذهبــت‬\n      ‫إلــى الســيارة فلمــا اقتربــت منهــا وجدتهــا علــى وضــع التشــغيل وكانــت‬\n      ‫مظللــة بالكامــل مــن اجلوانــب ومــن اخللــف فلمــا نظــرت داخــل الســيارة‬\n      ‫شــاهدت شــخص عــاري مــن الســرة إلــى األســفل وكان علــى بطنــه يف‬\n      ‫املرتبــة األماميــة التــي بجــوار الســائق وشــعرت أن حتتــه شــخص آخــر‬\n      ‫فلمــا شــعر بــي انتقــل مــن مرتبــة الراكــب إلــى مرتبــة الســائق مباشــرة‬\n      ‫ولــم يلبــس أي شــيء وكان يشــير إلــي بيــده ثــم حــرك الســيارة وهــرب‬\n      ‫فوجــدت خشــبة يف األرض وأخذتهــا محــاو ًال أن أضــرب الســيارة‬\n      ‫ورميتهــا علــى الســيارة إال أن الســيارة ابتعــدت عنــي وضربتهــا ضربــة‬\n      ‫خفيفــة ثــم أخــذت رقــم الســيارة وبلغــت الدوريــات األمنيــة فواعدونــي‬\n      ‫عــن ‪...........‬فلمــا ذهبــت إلــى هنــاك وجــدت شــخص آخــر ذكــر لــي أن‬\n      ‫ابنــه أو أبــن أخيــه قــد خــرج مــن العصــر ولــم يعــد إلــى اآلن وكان ذلــك‬\n      ‫قبــل املغــرب بنصــف ســاعة تقريب ـ ًا ثــم أخبرونــي الدوريــات بعــد ذلــك‬\n      ‫ـاء مــن نفــس اليــوم فلمــا ذهبــت‬‫أنهــم قبضــوا عليــه الســاعة الثامنــة مسـ ً‬\n      ‫إلــى مركــز الضبــط اإلداري وشــاهدت الشــخص عرفــت أنــه هــو الــذي‬\n      ‫شــاهدته يف الســيارة وهــو هــذا احلاضــر املدعــى عليــه هــذا مــا لــدي مــن‬\n      ‫شــهادة وبــه أشــهد وبعــرض الشــهود ومــا جــاء يف شــهادتهم علــى املدعــى‬\n      ‫عليــه قــال مــا جــاء يف شــهادتهم غيــر صحيــح وأنــا ال اعرفهــم وال أقــول‬\n      ‫فيهــم أي شــيء هــذه إجابتــي وبطلــب مزكيــن احضــر املدعــي العــام‬\n\n\n‫‪147‬‬\n\f‫ال مــن ‪...........‬ســعودي بالســجل املدنــي‬  ‫بتزكيــة أفــراد الدوريــات ك ً‬\n‫رقــم ‪...........‬و ‪......................‬ســعودي بالســجل املدنــي رقــم ‪...........‬‬\n‫واحضــر لتزكيــة الشــاهد ‪...........‬كال مــن ‪...........‬ســعودي بالســجل‬\n‫رقــم ‪...........‬و ‪...........‬ســعودي بالســجل املدنــي رقــم ‪...........‬وقــد شــهد‬\n‫كل مزكــي مبفــرده بعدالــة وثقــة الشــهود املذكوريــن بعاليــه وقــد مت‬\n‫ســؤال املدعــي العــام هــل لديــه زيــادة بينــة قــال اكتفــي مبــن أحضــرت‬\n‫ومبــا يف املعاملــة هكــذا قــرر وللتأمــل وإصــدار احلكــم رفعــت اجللســة‬\n‫وتأجلــت إلــى بعــد صــاة الظهــر بنفــس هــذا اليــوم الثالثــاء املوافــق‬\n‫‪1434/3/3‬ه ـ الســاعة ‪ 1 : 00‬ومت إغالقهــا الســاعة ‪ 12 : 40‬وعليــه‬\n‫جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه‬\n                                   ‫وصحبــه أجمعــن حــرر يف ‪1434/3/3‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n‫فلدينــا نحــن القضــاة يف احملكمــة العامــة بحائــل كال مــن ‪...........‬و‪.‬‬\n‫‪.....................‬و‪...........‬وبنــاء علــى املعاملــة احلالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة املســاعد برقــم ‪ 3483544‬يف ‪1434/2/19‬ه ـ واملقيــدة‬\n‫باحملكمــة برقــم ‪ 34396101‬يف ‪1434/2/19‬ه ـ عليــه فيهــذا اليــوم‬\n‫الثالثاء املوافق ‪1434/3/3‬هـ افتتحت اجللســة يف الســاعة ‪ 1 : 15‬كما‬\n‫وردنــا تقريــر كيميائــي شــرعي صــادر مــن مركــز املســموم والكيمياء‬\n‫الطبيــة الشــرعية مبنطقــة القصيــم برقــم ‪...........‬يف ‪1434/1/28‬ه ـ‬\n‫واملقيــد باحملكمــة برقــم ‪ 34478337‬يف ‪1434/2/25‬ه ـ املتضمــن ثبت‬\n‫إيجابيــة العينــات لالمفيتامــن هــو مــن املــواد الكيميائيــة املنبهــة للجهاز‬\n‫العصبــي املركــز واملدرجــة بجــدول املؤثــرات العقليــة رقــم (‪ )2‬وفئة (ب)‬\n‫التــي عناهــا تعميــم وزارة الصحــة رقــم ‪ 30440/136‬واملبنــي علــى تعميــم‬\n\n\n                                                                                               ‫‪148‬‬\n\f      ‫الهيئــة العامــة للغــذاء والــدواء رقــم ‪ 4933‬يف ‪1431/2‬ه ـ انتهــى التقريــر‬\n      ‫وبعرضــه علــى املدعــى عليــه قــال ما جاء فيه غيــر صحيح هذا وقد جرى‬\n      ‫االطــاع علــى كامــل أوراق املعاملــة فبنــاء علــى مــا تقــدم وحيــث أنكــر‬\n      ‫املدعــى عليــه دعــوى املدعــي العــام وألن بينــات املدعــي العــام كافي ــة يف‬\n      ‫إدانــة املدعــى عليــه مبــا نســب إليــه ومــن ذلــك شــهادة الشــاهد ‪...........‬‬\n      ‫الــذي تضمنــت شــهادته محاولــة املدعــى عليــه خطفــه ووصفــه ســيارته‬\n      ‫وانطباقهــا عليــه واملرصــودة يف ضبطــه وكذلــك شــهادة ‪...........‬الــذي‬\n      ‫حضــر والتــي تضمنــت شــهادته رؤيتــه لســيارة املدعــى عليــه واقف ــة بعــد‬\n      ‫أن أبلغــه ابنــه الشــاهد األول بأنهــا الســيارة التــي حــاول قائدهــا خطفــه‬\n      ‫وشــاهدها مــن الداخــل ووجــد املدعــى عليــه يف ســيارته وخاصمــه وأنــه‬\n      ‫أحــس بوجــود شــخص حتتــه ثــم الذ بالفــرار وقــام املدعــى عليــه بجــرأة‬\n      ‫بإعــادة فعــل الفاحشــة بالغــام مــن قبــل املغــرب إلــى قريــب مــن العشــاء‬\n      ‫وانطبقــت أوصــاف الســيارة التــي وصفهــا الشــاهد الثانــي علــى الســيارة‬\n      ‫التــي وصفهــا املدعــى عليــه لدينــا وصــادق علــى أنهــا ســيارته وأنهــا‬\n      ‫بقيادتــه وهــو مــا دلــت عليــه اســتمارة الســيارة املرفقــة باملعاملــة وكذلــك‬\n      ‫انطبقــت إفــادة الغــام املجنــي عليــه مــع شــهادة الشــاهد الثانــي ‪...........‬‬\n      ‫حيــث ذكــر أن شــخصا طــرق أو أطــل عليهــم مــن زجــاج ســيارة املدعــى‬\n      ‫عليــه حينمــا كان يفعــل بــه الفاحشــة وكل ذلــك مــع انطبــاق احلمــض‬\n      ‫النــووي مــن العينــة املرفوع ــة مــن احلــدث املجنــي عليــه علــى املدعــى عليــه‬\n      ‫وأنــه هــو مصــدر تلــك التلوثــات املنويــة مــع كونــه مــن أربــاب الســوابق‬\n      ‫وكذلــك شــهادة الشــاهدين رجلــي األمــن املرصــودة بعاليــه والتــي‬\n      ‫تضمــن القبــض علــى املدعــى عليــه وبرفقتــه احلــدث املجنــي عليــه وهروبه‬\n      ‫منهــم ودخولــه مســاكن بــدون أذن اصحابهــا فــكل ذلــك يديــن املدعــى‬\n\n\n‫‪149‬‬\n\f‫عليــه مبــا نســب إليــه وحيــث أن مــا أقــدم عليــه املدعــى عليــه يعــد جرمــا‬\n‫عظيمــا وفســاد ًا كبيــر ًا وزعزعــة لألمــن وجــرأة علــى األعــراض وعلــى‬\n‫احلــرام يف بــاد احلرمــن وهــي بــاد األمــن واألمــان ويــدل علــى تأصــل‬\n‫الشــر والفســاد والشــذوذ يف نفس ــه وهــو محصــن متــزوج وهــو مــن أربــاب‬\n‫الســوابق يف شــتى أنــواع الفســاد واملعاصــي ومــن ســوابقه مــا هــو مــن‬\n‫جنــس جرميتــه احلاليــة فســابقته األولــى فعــل فاحشــة اللــواط وســابقته‬\n‫الثانيــة محاولــة إركاب فتــاة أو فتــى لغــرض ســيء وســابقته الثالثــة‬\n‫جتــول يف الليــل وســابقته الرابع ــة ســرقة ســيارات وســابقته اخلامســة‬\n‫حيــازة واســتعمال املخــدرات والتــي لــم تردعــه أحكامهــا الســابقة عــن‬\n‫العــودة ملثــل تلــك األفعــال وألن مــا يدعــي بــه عليــه املدعــي العــام لدينــا‬\n‫إمنــا هــو مجموعــة جرائــم متنوع ــة مــن محاولــة خطــف‪ ،‬وخط ــف وفعــل‬\n‫فاحشــة‪ ،‬وصــدم دوريــة أمنيــة وهــروب مــن الســلطة ودخــول مســاكن‬\n‫بطريقــة تــروع اآلمنــن أقــدم عليهــا املدعــى عليــه مــن غيــر مبــاالة وال هــم‬\n‫لــه ســوى إشــباع رغباتــه ونزعاتــه الشــيطانية ولقولــه تعالــى « إمنــا جــزاء‬\n‫الذيــن يحاربــون اهلل ورســوله ويســعون يف األرض فســادا أن يقتلــوا أو‬\n‫يصلبــوا أو تقطــع أيديهــم وأرجلهــم مــن خــاف أو ينفــوا مــن األرض ‪..‬‬\n‫« اآليــة ولقولــه صلــى اهلل عليــه وعلــى آلــه وســلم « مــن وجدمتــوه يعمــل‬\n‫عمــل قــوم لــوط فاقتلــوا الفاعــل واملفعــول بــه « رواه الترمــذي (‪ 57/4‬ـ ـ‬\n‫‪ )58‬وســن أبــي داوود (‪ 607/4‬ـ ـ ‪ )608‬وابــن ماج ــه (‪ )856/2‬والســن‬\n‫الكبــرى للبيهقــي (‪ )232/8‬ومسن ــد اإلمــام أحم ــد (‪ )300/1‬وســن‬\n‫الــدار قطنــي (‪ )124/3‬واحلاكــم يف مســتدركه (‪ )355/4‬والكامــل‬\n‫البــن عــدي (‪ )1768/5‬واألوســط البــن املنــذر (‪ )623/2‬واحمللــى البــن‬\n‫حــزم (‪ )383/11‬وحلديــث « ملعــون مــن عمــل عمــل قــوم لــوط « رواه‬\n\n\n                                                                                        ‫‪150‬‬\n\f      ‫الترمــذي وقــد أجمــع الصحابــة رضــوان اهلل عليهــم علــى قتــل اللوطــي‬\n      ‫وأن معصيتــه مــن أعظــم املعاصــي والتــي يــرجت لهــا عــرش الرحمــن وأن‬\n      ‫اهلل تعالــى جمــع علــى أهلهــا مــن أنــواع العقوبــات مــا لــم ينــكل بــه أم ــة‬\n      ‫ســواهم وذلــك لعظــم مفســدة هــذه اجلرميــة أنظــر فتــاوى ابــن تيميــة‬\n      ‫(‪ 334/28‬ـ ـ ‪ )345‬والسياســة الشــرعية البــن تيميــة ص(‪ )52‬وزاد املعــاد‬\n      ‫البــن القي ــم (‪ )40/5‬وملــا هــو مقــرر لــدى احملققــن مــن أهــل العلــم أن مــن‬\n      ‫لــم يندفــع فســاده إال بالق ــتل فإنــه يق ــتل وهــذه قاعــدة عظيمــة إلصــاح‬\n      ‫البــاد والعب ــاد والعقوبــات التعزيريــة فيهــا كبح جلمــاح املجرمني وقطعا‬\n      ‫لفســادهم وإصــاح للمجتمــع ولكــون املدعــى عليــه مكلــف شــرعا‬\n      ‫وهــو بالــغ عاقــل وجلميــع مــا ســبق فإننــا أمرنــا بق ــتل املدعــى عليــه ‪...........‬‬\n      ‫ســجل مدنــي رقــم (‪ )...........‬تعزيــرا جــزاء لــه وردعا ألم ــثاله وبه حكمنا‬\n      ‫وبعرضــه علــى الطرفــن قــرر املدعــي العــام وقــرر املدعــى عليــه عــدم‬\n      ‫القناعــة فجــرى إفهامهمــا بتعليمــات االســتئناف وانــه ســيتم تســليمهما‬\n      ‫صــورة مــن صــك احلكــم يف يــوم األربعــاء املوافــق ‪1434/3/4‬ه ـ الســاعة‬\n      ‫التاســعة لالعتــراض عليــه خــال ثالثــن يوم ـ ًا مــن تاريــخ اســتالمه وإذا‬\n      ‫لــم يقدمــا اعتراضهمــا ســيتم رفــع احلكــم إلــى محكمــة االســتئناف‬\n      ‫بــدون الئحــة اعتراضيــة ففهمــا ذلــك ومت إغــاق اجللســة يف الســاعة ‪33‬‬\n      ‫‪01 :‬وعليــه حصــل التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                               ‫محمــد والــه وصحبــه أجمعــن حــرر يف ‪1434/3/3‬ه ـ‬\n      ‫ال مــن ‪......................‬و‪...........‬‬\n                                              ‫احلمــد هلل وحــده وبعــد فلدينــا ك ً‬\n      ‫القاضيــن يف احملكمــة العامــة بحائــل وبنــاء علــى املعاملــة احملالــة لنــا‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة بحائــل املســاعد برقــم ‪3483544‬‬\n      ‫وتاريــخ ‪ 1434/02/19‬ه ـ املقيــدة باحملكمــة برقــم ‪34396101‬‬\n\n\n‫‪151‬‬\n\f‫وتاريــخ ‪1434/2/17‬ه ـ ففــي يــوم الســبت املوافــق‪1434/04/27‬‬\n‫ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 45‬وكنــا قــد تلقينــا املعاملــة مــن‬\n‫محكمــة االســتئناف بحائــل مبوجــب خطــاب فضيلــة رئيســها رقــم‬\n‫‪ 34396101‬يف ‪1434/04/14‬ه ـ مرفق ـ ًا بهــا القــرار رقــم ‪34186869‬‬\n‫يف ‪1434/04/14‬ه ـ املتضمــن (وبدراســة الصــك وصــورة ضبطه وأوراق‬\n‫املعاملــة واللوائــح االعتراضيــة لوحــظ مــا يلــي أو ًال طلــب املدعــي العــام‬\n‫يف دعــواه احلكــم علــى املدعــى عليــه بحــد احلرابــة ولــم جنــد أصحــاب‬\n‫الفضيلــة تطرقــوا لذلــك يف حكمهــم بإثبــات ذلــك مــن عدمــه والبــد‬\n‫ـاء علــى املــادة (‪ )174‬مــن نظــام اإلجــراءات اجلزائيــة ‪ -‬ثانيـاً‪:‬‬  ‫مــن ذلــك بنـ ً‬\n‫طلــب املدعــي العــام يف دعــواه مصــادرة الســيارة املســتخدمة باجلرميــة‬\n‫ولــم جنــد أصحــاب الفضيلــة تطرقــوا لذلــك يف حكمهــم ‪ -‬ثالث ـاً‪:‬‬\n‫لــم يحضــر أصحــاب الفضيلــة احلدثــن املجنــي عليهمــا ……… و‬\n‫……… لســماع مــا لديهمــا للتثبــت ممــا نســب إليهمــا أســوة ببقيــة‬\n‫الشــهود حيــث أشــار أصحــاب الفضيلــة ملــا ورد مــن شــهادة ‪ ......‬مبحضــر‬\n‫التحقيــق فقــط دون حضــوره وهــذا ال يكفــي ‪ -‬رابعـاً‪ :‬ورد يف الالئحــة‬\n‫االعتراضيــة املقدمــة مــن املدعــى عليــه أنــه مريــض نفســي مزمــن منــذ‬\n‫الصغــر ولــه مراجعــة مبستشــفى الصحــة النفســية بحائــل وأول مراجعــة‬\n‫لــه يف ‪1417/05/26‬ه ـ حســب اإلفــادة املرفــق صورتــه يف الالئحــة وأن‬\n‫لديــه اكتئــاب جســيم حســب التقريــر الطبــي املرفــق صورتــه بالالئحــة‬\n‫وأنــه ســبق أن ســكب البنزيــن علــى نفســه وأحرقهــا حســب مراجعتــه‬\n‫للمستشــفى واثبــات ذلــك لــدى الشــرطة والبــد مــن التحقــق مــن ذلــك‬\n‫والكتابــة للجهــات املختصــة للتحقــق ممــا ذكــره وهــل املدعــى عليــه‬\n‫مســؤول جنائي ـ ًا عــن أفعالــه وقــت اجلرميــة أم ال احتياطــا للدمــاء وبــراء ًة‬\n\n\n                                                                                           ‫‪152‬‬\n\f      ‫للذمــة ‪ -‬خامس ـاً‪ :‬تكــرار الصفحــة اخلامســة مــن الصــك وصــورة‬\n      ‫الضبــط فــا بــد مــن معاجلــة ذلــك ‪ -‬سادسـاً‪ :‬عــدم توقيــع املدعــي العــام‬\n      ‫يف الضبــط علــى الصفحــات(‪ )4-3-2-1‬والبــد مــن ذلــك ‪ -‬ســابعاً‪ :‬عــدم‬\n      ‫ختــم وتوقيــع الصفحــة األخيــرة مــن صــورة الضبــط مبطابقتهــا ألصلهــا‬\n      ‫‪ -‬ثامن ـاً‪ :‬مت اختتــام الصفحــة األولــى مــن الضبــط والصــك واجللســة لــم‬\n      ‫تنتــه بعــد فــا بــد مــن تصحيــح ذلــك ‪ -‬تاســعاً‪ :‬وجــود عــدد مــن األخطــاء‬\n      ‫املطبعيــة يف الصفحــات (‪ )12-10-9-8-6-4‬وضــع حتتهــا خــط بقلــم‬\n      ‫رصــاص وال بــد مــن تعديلهــا الطــاع أصحــاب الفضيلــة وإعــادة النظــر‬\n      ‫وإكمــال الــازم وتقريــر مــا يظهــر أخير ًا واهلل املوفــق)أ‪ .‬هـ وعليه جنيب‬\n      ‫أصحــاب الفضيلــة أمــا بخصــوص أو ًال فــإن حــد احلرابــة لــم يثبــت لدينــا‬\n      ‫ونقــرر باألكثريــة رد دعــوى املدعــى العــام طلــب إقامــة حــد احلرابــة علــى‬\n      ‫املدعــى عليــه لعــدم موجبــه ‪ -‬أمــا مــا جــاء يف ثاني ـ ًا فقــد حكمنــا علــى‬\n      ‫املدعــى عليــه بالقتــل وال نــرى اجلمــع عليــه وال علــى ورثتــه بــن القتــل‬\n      ‫ومصــادرة أو إتــاف مالــه لــذا لــم نحكــم مبصــادرة الســيارة ‪ -‬ألن‬\n      ‫املقــرر فقه ـ ًا تداخــل العقوبــات يف العقوبــة األشــد ولذلــك فإننــا نقــرر‬\n      ‫باألكثريــة رد دعــوى املدعــي العــام مبصــادرة الســيارة أمــا مــا جــاء يف‬\n      ‫املالحظــة الثالثــة فــإن إحضــار احلدثــن لــم يجــر عليــه العمــل وهــو منــاف‬\n      ‫ملقاصــد الشــريعة مــن الســتر علــى مــن جنــي عليــه مبثــل هذه اجلنايــة وفيه‬\n      ‫تأثيــر علــى احلدثــن وذويهمــا واعتبــار احلدثــن شــاهدين واحلــق اخلــاص‬\n      ‫مــازال قائم ـ ًا ال ميكــن االعتمــاد عليــه فيــه مــن اخلصومــة وجــر منفعــة‬\n      ‫لهمــا ‪ -‬أمــا مــا جــاء يف رابع ـ ًا فــإن كثيــر ممــن تقــع منهــم هــذه اجلرائــم‬\n      ‫الكبيــرة يدفــع بهــذا الدفــع تخلص ـ ًا مــن إيقــاع العقوبــة عليــه ولــو فتــح‬\n      ‫هــذا البــاب ملثــل هــؤالء ملــا أقيمــت كثيــر مــن احلــدود ولــم يعــزر كثيــر‬\n\n\n‫‪153‬‬\n\f‫مــن اجلنــاة وقــد كان املدعــى عليــه ‪...........‬يف املجلــس الشــرعي يفهــم‬\n‫اخلطــاب ويــرد اجلــواب ويــدرك كل مــا حولــه ومــا يقــال لــه ومــا يطلــب‬\n‫منــه كمــا هــو ظاهــر مــن خــال إجاباتــه علــى األســئلة التــي وجهــت لــه‬\n‫يف اجللســة وكان مــا ذكــره أصحــاب الفضيلــة مقصــود ًا مــن املناقشــة‬\n‫لــه حتــى أنــه يف اجللســة األولــى رفــض التوقيــع علــى الضبــط مــدركا ملــا‬\n‫أدعــى بــه املدعــي العــام وقــد كان يناقــش ويحــاور ويــرد علــى األســئلة‬\n‫أعقــل مــن بعــض العقــاء ‪ -‬أمــا مــا جــاء يف املالحظــة اخلامســة فقــدمت‬\n‫مــن قبــل كاتبــه ونظــر ًا ألن فضيلــة الشــيخ ‪ ...........‬منــدوب فــا ميكــن‬\n‫إلغــاء هــذه الصفحــة ألنــه يحتــاج إلــى إعــادة طباعــة وقــد مت التقويــس‬\n‫علــى املكــرر وهــذا مــا جنيــب بــه علــى املالحظــة التاســعة ‪ -‬أمــا مــا جــاء‬\n‫يف املالحظــة السادســة فقــد مت تصويــر الضبــط مــن قبــل املشــرف قبــل‬\n‫توقيــع املدعــي العــام وقــد مت إعــادة تصويــره وتداركــه وهلل احلمــد أمــا‬\n‫مــا جــاء يف املالحظــة الثامنــة فهــو قــد وقــع ســهو ًا وهــو غيــر مؤثــر واملطلع‬\n‫عليــه يعــرف أن اجللســة لــم تنتــه ويســري عليــه مــا ذكــر يف اإلجابــة علــى‬\n‫املالحظــة اخلامســة هــذا مــا لــزم اإلجابــة بــه علــى مالحظــات أصحــاب‬\n‫الفضيلــة وســيتم إحلــاق ذلــك يف الصــك وســجله وإعادتــه إلــى محكمــة‬\n‫االســتئناف بحائــل علم ـ ًا أن فضيلــة القاضــي املشــارك الشــيخ ‪...........‬‬\n‫قــد نــدب ملــدة شــهرين إلــى املجلــس األعلــى للقضــاء مبوجــب قــرار‬\n‫رئيــس املجلــس األعلــى للقضــاء رقــم ‪ 1772‬يف ‪1434/03/08‬ه ــوالقائم‬\n‫بعملــه القاضــي ‪...........‬وقــد مت إغــاق اجللســة يف الســاعة ‪12 : 11‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n‫يف ‪1434/04/27‬ه ـ احلمــد هلل وحــده و بعــد فقــد اطلعنــا نحــن قضــاة‬\n‫الدائــرة املختصــة بتدقيــق القضايــا اخلماســية مبحكمــة االســتئناف‬\n\n\n                                                                                          ‫‪154‬‬\n\f      ‫مبنطقــة حائــل علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامة‬\n      ‫بحائــل املســاعد برقــم ‪ 34396101‬يف ‪1434/4/29‬ه ـ و املقيــدة لدينــا‬\n      ‫برقــم ‪ 341065453‬يف ‪1434/4/30‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫صاحــب الفضيلــة الشــيخ ‪...........‬و مشــاركيه ‪ ..........‬والشــيخ ‪...........‬‬\n      ‫القائــم بعمــل فضيلــة الشــيخ ‪...........‬القضــاة باحملكمــة العامــة برقــم‬\n      ‫‪ 3455295‬يف ‪1434/3/3‬ه ـ اخلاصــة بدعــوى املدعــي العــام ضــد‬\n      ‫‪ .............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...........‬التهامــه‬\n      ‫بقضيــة خطــف غــام وفعــل فاحشــة اللــواط بــه و قــد تضمــن الصــك‬\n      ‫حكــم أصحــاب الفضيلــة و فقهــم اهلل بقتــل املدعــى عليــه تعزيــرا علــى‬\n      ‫النحــو املفصــل يف الصــك و صــورة ضبطــه و قــد ســبق منــا دراســة الصــك‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة و أوراق املعاملــة و باالطــاع علــى‬\n      ‫ـاء علــى‬‫مــا أجــاب بــه أصحــاب الفضيلــة ومــا أحلقــوه بالصــك وضبطــه بنـ ً‬\n      ‫قرارنــا ‪ 34186869‬رقــم وتاريــخ ‪1434/4/14‬ه ــ‪ :‬جــرت املصادقــة علــى‬\n      ‫ماحكــم بــه أصحــاب الفضيلــة وفقهــم اهلل علــى املدعــى عليــه بالقتــل‬\n      ‫تعزيــر ًا بعــد اإليضــاح واإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى‬\n                                                                          ‫نبينــا محمــد ‪.‬‬\n\n\n\n\n‫‪155‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":126,"source_page_end":155,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fac120463686f4669756da4d1cf68d86d5ce5b7b1e83482f2a4d8941a31a445e","normalized_text_hash":"8afa04c52a5257d144a3ebd1d20d550b95caa9447b4500f3670473f362dc88fb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p126-3455295"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"08d7328d-a609-5ebf-8f44-0eafdc1b0cac","document_type":"judgment","category":"judicial","subcategory":"general","title":"انتهاك حرمة منزل بغرض السرقة -تستر -إقرار -ظروف مخففة للعقوبة -تعزير بالسجن واجللد -تعهد ض ب ع د إ ص ل ح ها)) -1قوله تعالى (( :و ل ت ف س دوا ف","document_number":"34186538","case_number":"34157003","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية على املعاملة املقيدة لدى المحكمة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/14","year":"1434","subject":"انتهاك حرمة منزل بغرض السرقة -تستر -إقرار -ظروف مخففة للعقوبة -تعزير بالسجن واجللد -تعهد ض ب ع د إ ص ل ح ها)) -1قوله تعالى (( :و ل ت ف س دوا ف","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"                  ‫رقم الصك ‪ 34186538 :‬تاريخه‪:‬‬\n           ‫‪1434/04/14‬هـ رقم الدعوى‪34157003 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34204176‬تاريخه‪1434/5/4 :‬هـ‬\n\n\n     ‫انتهــاك حرمــة منــزل بغــرض الســرقة ‪ -‬تســتر ‪ -‬إقــرار ‪ -‬ظــروف مخففة‬\n                                 ‫للعقوبــة ‪ -‬تعزيــر بالســجن واجللــد ‪ -‬تعهد‬\n\n\n\n                               ‫ض َب ْع َد ِإ ْص َل ِح َها))‬               ‫‪ -1‬قوله تعالى ‪َ (( :‬و َل ُت ْف ِس ُدوا ِف ْ َ‬\n                                                                     ‫ال ْر ِ‬\n                                  ‫ين))‬‫الل ال ُي ِح ُّب ْالُ ْع َتدِ َ‬      ‫‪ -2‬قوله تعالى ‪َ (( :‬وال َت ْع َت ُدوا ِإ َّن َّ َ‬\n     ‫دمـ ُه‬‫(كل املســلم علــى املســلم حــرا ٌم ُ‬                     ‫ُّ‬        ‫‪ -3‬قولــه صلــى اهلل عليــه وســلم ‪:‬‬\n                                                                                                              ‫وعرضــه)‬\n                                                                                                                    ‫ُ‬             ‫وما ُلـ ُه‬\n     ‫اض ُكـ ْـم‬\n              ‫كـ ْـم َوأ َْم َوا َل ُكـ ْـم َوأَعْ َر َ‬‫‪ -4‬قولــه صلــى اهلل عليــه وســلم ‪( :‬فَ ـ ِإ َّن د َِم َاء ُ‬\n     ‫كـ ْـم‬  ‫ك ْم َهـ َـذا ‪ِ ،‬ف َب َلدِ ُ‬        ‫ك ُح ْر َم ـ ِة َي ْومِ ُكـ ْـم َهـ َـذا ‪ِ ،‬ف َشــهْ ِر ُ‬   ‫َحـ َـرا ٌم َع َل ْي ُكـ ْـم َ‬\n                                                                                                                                     ‫َهـ َـذا)‬\n     ‫ـس‬  ‫‪ -5‬قولــه صلــى اهلل عليــه وســلم ‪( :‬أَال ِإ َّن ْالُ ْس ـل َِم أ َُخــو ْالُ ْس ـل ِِم ‪ ،‬فَ َل ْيـ َ‬\n                                 ‫َي ِحـ ُّـل لِ ُ ْس ـل ٍِم مِ ـ ْـن أ َِخي ـ ِه َشـ ْـي ٌء ِإال َمــا َحـ َّـل َل ـ ُه مِ ـ ْـن َن ْف ِس ـهِ)‬\n\n\n\n\n     ‫توجيــه االتهــام للمدعــى عليــه بقيامــه بالقفز من على ســور منزل ودخوله‬\n     ‫عبــر فتحــة مكيــف أحــد الغــرف بعــد دفعــه إلــى داخــل الغرفــة بغــرض‬\n     ‫الســرقة وتســتره علــى الهاربــن‪ ،‬وذلــك بعــد القبــض علــى املدعــى عليــه‬\n     ‫إثــر ورود بــاغ للجهــات املختصــة مــن أحــد املواطنــن مفــاده تعــرض‬\n\n‫‪83‬‬\n\f‫الفيــا التــي يقطــن فيهــا للقفــز مــن علــى الســور اخلارجــي مــن قبــل ثالثــة‬\n‫أشــخاص بغــرض الســرقة وعنــد مشــاهدتهم لــه الذوا بالفــرار‪ -‬بالبحــث‬\n‫عــن ســوابقه لــم يعثــر لــه علــى ســوابق جنائيــة مســجلة‪ -‬طلــب املدعــي‬\n‫العــام احلكــم عليــه بعقوبــة تعزيريــة‪ -‬بعــرض دعــوى املدعــي العــام علــى‬\n‫ـواء مــن الشــيطان‬‫املدعــى عليــه صــادق عليهــا وقــرر أن ذلــك كان إغـ ٌ‬\n‫وأنــه تائــب ونــادم علــى مــا بــدر منــه‪ -‬ثبتــت إدانــة املدعــى عليــه مبــا أســند‬\n‫أن مــا صــدر مــن املدعــى عليــه مــن احملـ َّـرم شــرعاً؛ ولتوجــه‬    ‫إليــه ومبــا َّ‬\n‫ـوابق لــه‬\n     ‫تخفيــف العقوبــة عليــه لظهــور آثــار النــدم عليــه وعــدم وجــود سـ ٍ‬\n‫ولصغــر ســنه والنتهــاء احلــق اخلــاص بالتنــازل كمــا يتوجــه أن تكــون‬\n‫عقوبتــه باجللــد أشـ َّـد مــن الســجن للظــروف الســابقة لــذا مت احلكــم‬\n‫بتعزيــره بســجنه ســبعة أشــهر وبجلــده مائتــي جلــدة مفرقــة علــى أربــع‬\n‫دفعــات وأخــذ التعهــد عليــه بعــدم العــودة ملثــل مــا صــدر منــه‪ -‬بعــرض‬\n‫احلكــم علــى الطرفــن قــرر املدعــي القناعــة وطلــب املدعــي العــام رفــع‬\n‫كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم دون الئحـ ٍة‬\n‫اعتراضيــة مكتفي ـ ًا مبــا ورد يف الئحــة الدعــوى‪ -‬وبعــد رفــع احلكــم‬\n                                   ‫حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد‬\n‫ـاء علــى‬\n       ‫ـدي أنــا ‪ .....‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n                                                                   ‫فلـ َّ‬\n‫املعاملــة الــواردة إلينــا مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة‬\n‫األحســاء برقــم ‪.....‬وتاريخ‪1434/04/03‬ه ـ واملقيــدة بهــذه احملكمــة‬\n‫برقم‪34836374‬وتاريخ‪1434/04/06‬ه ـ واحملالــة إلينــا مــن فضيلــة‬\n\n                                                                                            ‫‪84‬‬\n\f     ‫الرئيــس برقــم ‪ 34157003‬وتاريــخ ‪1434/04/06‬ه ـ فتحــت اجللســة‬\n     ‫األولــى يــوم االربعــاء ‪1434/04/10‬ه ـ الســاعة العاشــرة والنصــف‬\n     ‫صباحـ ًا وفيهــا حضــر املدعــي العــام ‪ .....‬امل َُع ّمــد بالترافــع أمــام احملكمــة‬\n     ‫طرفنــا مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واالدعــاء العــام‬\n     ‫مبحافظــة األحســاء ذي الرقــم ‪.....‬والتاريــخ ‪1433/12/1‬ه ـ وقـ ّـرر دعــواه‬\n     ‫عامــا بدائــرة االدعــاء العــام مبحافظة األحســاء‬     ‫ا ‪ :‬فبصفتــي مدعيـ ًا ً‬     ‫قائـ ً‬\n     ‫أدعــي علــى ‪ 20 ،.....:‬عامـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫رقــم (‪ ).....‬طالــب ‪ ،‬أوقــف بتاريــخ ‪1434/3/9‬ه ـ وأحيــل لشــعبة ســجن‬\n     ‫ا لديهــم برقــم (‪ ).....‬اســتناد ًا للفقــرة رقم‬   ‫محافظــة األحســاء وســجل نزيـ ً‬\n     ‫(‪ )13‬مــن القــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ ‪.‬حيــث‬\n     ‫أنــه بتاريــخ ‪1433/3/9‬ه ـ ورد لرجــال الدوريــات األمنيــة بــاغ مــن‬\n     ‫املدعــو ‪.....‬مفــاده تعــرض الفيــا التــي يقطــن فيهــا للقفــز مــن علــى الســور‬\n     ‫اخلارجــي مــن قبــل ثالثــة أشــخاص بغــرض الســرقة وعنــد مشــاهدتهم لــه‬\n     ‫الذوا بالفــرار وقبــض علــى املدعــى عليــه ‪.‬وباالنتقــال واملعاينــة للمنــزل‬\n     ‫اتضــح أن اجلنــاة وضعــوا دافــور لونــه أزرق حتــت موقــع مكيــف املقلــط‬\n     ‫واســتخدموه يف االرتفــاع ملســتوى املكيــف ليتــم دفعــه وقــد شــوهد‬\n     ‫املكيــف ســاقط داخــل املقلــط واملجلــس مبعثــر وكذلــك غرفــة نــوم‬\n     ‫األطفــال والصالة‪.‬وبضبــط أقــوال املبلــغ ‪.....‬أفــاد بأنــه ورد إليــه اتصــال‬\n     ‫مــن زوجتــه أخبرتــه عــن ســماع دخــول أشــخاص بواســطة القفــز مــن علــى‬\n     ‫الســور ومــن ثــم عبــر فتحــة املكيــف مــن أحــد الغــرف وعنــد وصولــه‬\n     ‫متكــن مــن القبــض علــى املدعــى عليــه ‪.‬وبضبــط أقــوال زوجــة املبلــغ ‪.....‬‬\n     ‫أفــادت أنهــا ســمعت صوتـ ًا بالــدور األرضــي وعنــد محاولــة خروجهــا مــن‬\n     ‫غرفتهــا شــاهدت شــخصني فعــادت مســرعة لغرفتهــا وأقفلــت البــاب‬\n\n\n‫‪85‬‬\n\f‫عليهــا وعلــى الفــور اتصلــت بزوجهــا وبجارتهــا وقــد حــاول اجلنــاة فتــح‬\n‫غرفتهــا ممــا دعاهــا إلــى الصــراخ بصــوت مرتفــع ممــا نتــج عنــه هروبهمــا‬\n‫‪.‬وبضبــط أقــوال الشــهود ‪.....‬و‪.....‬و‪.....‬أفــادوا بأنهــم شــاهدوا املبلــغ ‪.....‬‬\n‫يخــرج مــن منزلــه مســرع ًا واللحــاق بشــخص قــام بالقفــز مــن علــى ســور‬\n‫منزلــه ‪ .‬وباســتجواب املدعــى عليــه أقــر بالقفــز علــى منــزل املبلــغ ودخــول‬\n‫منزلــه عبــر فتحــة مكيــف أحــد الغــرف بعــد أن قــام بإخراجــه عنــوه‬\n‫ممــا أدى إلــى ســقوط املكيــف علــى األرض وعنــد محاولــة فتــح بــاب‬\n‫أحــد الغــرف الداخليــة ســمع صــوت صــراخ امــرأة حينهــا الذ بالفــرار ومت‬\n‫القبــض عليــه مــن قبــل املبلــغ ‪ .‬وقــد أســفر التحقيــق عــن توجيــه االتهــام‬\n‫لــه بقيامــه بالقفــز مــن علــى ســور منــزل املبلــغ ودخــول منزلــه عبــر فتحــة‬\n‫مكيــف أحــد الغــرف بعــد دفعــه إلــى داخــل الغرفــة بغــرض الســرقة‬\n                   ‫وتســتره علــى الهاربــن؛ وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n     ‫‪ .1‬إقراره املدونة على الصفحات رقم (‪ )11/10‬املرفق لفه رقم (‪.)1‬‬\n‫‪ .2‬محضــر االنتقــال واملعاينــة املــدون علــى الصفحــات رقــم (‪)3_2‬‬\n                                                            ‫املرفــق لفــه رقــم (‪.)2‬‬\n‫‪ .3‬أقــوال املبلــغ املدونــة علــى الصفحــات رقــم (‪ )9_10‬املرفــق لفــه رقــم‬\n                                                                                ‫(‪.)2‬‬\n‫‪ .4‬أقــوال زوجــة املبلــغ املدونــة علــى الصفحــات رقــم (‪ )5_4‬املرفــق لفــه‬\n                                                                           ‫رقــم (‪)1‬‬\n‫‪ .5‬أقــوال الشــهود املدونــة علــى الصفحــات رقــم (‪ )4‬املرفــق لفــه رقــم (‪)2‬‬\n                                     ‫والصفحــات رقــم (‪ )6‬املرفــق لفــه رقم (‪.)1‬‬\n                                       ‫‪ .6‬محضر القبض املرفق لفه رقم (‪)12‬‬\n‫وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق جنائيــة‬\n\n\n                                                                                        ‫‪86‬‬\n\f     ‫مســجلة كمــا هــو مــدون بقــرار االتهــام وحيــث إن مــا أقــدم عليــه‬\n     ‫املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب‬\n     ‫عليــه شــرعاً؛ لــذا أطلــب إثبــات مــا أســند إليــه ‪ ،‬واحلكــم عليــه بعقوبــة‬\n     ‫تعزيريــة تزجــره وتــردع غيــره ‪(.‬علم ـ ًا أن احلــق اخلــاص ال يــزال قائم ـاً)‬\n     ‫هكــذا ا َّدعــى ؛ عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد مــن‬\n     ‫ا ‪ :‬مــا‬   ‫هويتــه جــرى عــرض دعــوى املدعــي العــام عليــه فأجــاب قائ ـ ً‬\n     ‫ذكــره املدعــي العــام مــن اتهامــي بالقيــام بالقفــز علــى مــن علــى ســور‬\n     ‫املنــزل أحــد املواطنــن ودخــول منزلــه عبــر فتحــة مكيــف أحــد الغــرف‬\n     ‫بعــد دفعــه إلــى داخــل الغرفــة بغــرض الســرقة وتســتري علــى الهاربــن‬\n     ‫ـواء مــن الشــيطان وأنــا تائــب‬           ‫كل ذلــك صحيــح وقــد كان ذلــك إغـ ٌ‬\n     ‫ونــادم علــى مــا بــدر منــي هكــذا أجــاب ثــم جــرى االطــاع علــى جميــع‬\n     ‫أوراق املعاملــة ومنهــا كــرت ســوابق املدعــى عليــه املتضمــن عــدم وجــود‬\n     ‫ســوابق عليــه كمــا جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه‬\n     ‫ـاء علــى مــا تقــدم مــن‬        ‫املتضمنــة أنــه أوقــف بتاريــخ ‪1434/03/09‬ه ـ فبنـ ً‬\n     ‫الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه والتأكــد مــن‬\n     ‫أن املدعــى عليــه أقـ َّـر‬     ‫أهليتــه وبعــد دراســة أوراق املعاملــة وتأملهــا ومبــا َّ‬\n     ‫بدعــوى املدعــي العــام باتهامــه بالقيــام بالقفــز علــى مــن علــى ســور املنــزل‬\n     ‫أحــد املواطنــن ودخــول منزلــه عبــر فتحــة مكيــف أحــد الغــرف بعــد‬\n     ‫دفعــه إلــى داخــل الغرفــة بغــرض الســرقة وتســتره علــى الهاربــن ومبــا‬\n     ‫((و َل‬‫أن مــا صــدر مــن املدعــى عليــه مــن احملـ َّـرم شــرع ًا قــال تعالــى ‪َ :‬‬                  ‫َّ‬\n     ‫((وال َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n     ‫الل‬                           ‫ض َب ْعـ َـد ِإ ْص َلحِ َهــا)) وقــال تعالــى ‪َ :‬‬    ‫ُت ْف ِسـ ُـدوا ِف ْ َ‬\n                                                                                    ‫ال ْر ِ‬\n     ‫ال ُي ِحـ ُّـب ْال ُْع َتدِ يـ َـن)) وقــال صلــى اهلل عليــه وســلم ‪( :‬كلُّ املســلم علــى‬\n     ‫(فـ ِإ َّن‬\n             ‫وعرضــه) وقــال عليــه الصــاة والســام‪َ :‬‬         ‫ُ‬        ‫دمـ ُه وما ُلـ ُه‬\n                                                                                        ‫ـرام ُ‬\n                                                                                            ‫املســلم حـ ٌ‬\n\n‫‪87‬‬\n\f‫كـ ْـم‬  ‫ك ُح ْر َم ـ ِة َي ْومِ ُ‬‫كـ ْـم َ‬    ‫كـ ْـم َحـ َـر ٌام َع َل ْي ُ‬   ‫َكـ ْـم َو َأ ْع َر َ‬\n                                                                          ‫اض ُ‬                        ‫كـ ْـم َو َأ ْم َوال ُ‬\n                                                                                                                           ‫د َِم َاء ُ‬\n‫كـ ْـم َهـ َـذا) وقــال عليــه الصــاة‬                           ‫ك ْم َهـ َـذا ‪ِ ،‬ف َبلَدِ ُ‬         ‫َهـ َـذا ‪ِ ،‬ف َشـ ْـه ِر ُ‬\n‫ـس َي ِحــلُّ لِ ُْس ـل ٍِم مِ ــنْ َأخِ ي ـ ِه‬‫والســام ‪َ ( :‬أال ِإ َّن ْال ُْسـ ِـل َم َأ ُخــو ْال ُْس ـل ِِم ‪َ ،‬ف َل ْيـ َ‬\n‫َشـ ْـي ٌء ِإال َمــا َحــلَّ َل ـ ُه مِ ــنْ ن َْف ِس ـهِ) ممــا يســتوجب تعزيــر املدعــى عليــه‬\n‫ويتوجــه تخفيــف العقوبــة عليــه لظهــور آثــار النــدم عليــه وعــدم وجــود‬\n‫ـوابق لــه ولصغــر ســنه والنتهــاء احلــق اخلــاص بالتنــازل كمــا يتوجــه أن‬                                              ‫سـ ٍ‬\n‫تكــون عقوبتــه باجللــد أشـ َّـد مــن الســجن للظــروف الســابقة لــذا كلــه‬\n‫وألجــل احلــق العــام حكمـ ُـت علــى املدعــى عليــه مبــا يلــي ‪ :‬أوالً‪ /‬ثبــت‬\n‫ـدي إدانــة املدعــى عليــه بالقيــام بالقفــز علــى مــن علــى ســور املنــزل‬                                                ‫لـ َّ‬\n‫ألحــد املواطنــن ودخــول منزلــه عبــر فتحــة مكيــف أحــد الغــرف بعــد‬\n‫دفعــه إلــى داخــل الغرفــة بغــرض الســرقة وتســتره علــى الهاربــن وعزرتــه‬\n‫لقــاء ذلــك بســجنه ســبعة أشــهر مــن تاريــخ إيقافــه علــى ذمــة القضيــة‬\n‫وبجلــده مائتــا جلــدة مفرقــة علــى أربــع دفعــات كل دفعــة خمســون جلــدة‬\n‫وبــن كل دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيــام ‪ .‬ثاني ـ ًا ‪ /‬يؤخــذ‬\n‫عليــه التعهــد بعــدم العــودة ملثــل مــا صــدر منــه ‪ .‬وبتــاوة احلكــم علــى‬\n‫الطرفــن وإفهــام املدعــى عليــه بحقــه يف متييــز احلكــم قــرر القناعــة بــه‬\n‫وطلــب املدعــي العــام رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف‬\n‫لتدقيــق احلكــم دون الئح ـ ٍة اعتراضيــة مكتفي ـ ًا مبــا ورد يف الئحــة‬\n‫الدعــوى وأقفلــت اجللســة الســاعة احلاديــة عشــرة وصلــى اهلل وسـلَّم علــى‬\n  ‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪ُ .‬حـ ِـر َر يف ‪1434/04/10‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/341021209‬ج‪ 2‬وتاريــخ ‪1434/4/27‬ه ـ‬\n\n\n                                                                                                                                         ‫‪88‬‬\n\f     ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n     ‫املكلــف برقــم ‪ 34845938‬وتاريــخ ‪1434/4/22‬ه ـ املرفــق بهــا القــرار‬\n     ‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ...../‬املســجل برقــم‬\n     ‫‪ 34186538‬وتاريــخ ‪1434/4/14‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام‬\n     ‫ضــد‪...../‬يف قضيــة دخــول منــزل وســرقته وقــد تضمــن القــرار حكــم‬\n     ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n     ‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل‬\n              ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/5/1‬ه ـ‬\n\n\n\n\n‫‪89‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":83,"source_page_end":89,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"54b6b86f2aa80ec1184ba4ed1f8245bfde5d37acfa23d527d78e3fe1238dd150","normalized_text_hash":"c4a1e53b7d7748e1a39cb16a5e958a74a42223698b8e09f5595463f659d17730","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p83-34186538"},{"id":"add4ddcc-00a5-55f0-974c-28de2f7bc4c1","document_type":"judgment","category":"judicial","subcategory":"general","title":"-انتهاك حرمة منزل -رجوع املقر عن إقراره يف غير احلدود ال يقبل -تكرر السوابق من نفس نوع اجلرم املتهم به -إثبات إدانة - التعزير بالسجن واجللد علنا.","document_number":"34234470","case_number":"34168877","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/7","year":"1434","subject":"-انتهاك حرمة منزل -رجوع املقر عن إقراره يف غير احلدود ال يقبل -تكرر السوابق من نفس نوع اجلرم املتهم به -إثبات إدانة - التعزير بالسجن واجللد علنا.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34234470 :‬تاريخه‪1434/6/7 :‬هـ‬\n                   ‫رقم الدعوى‪34168877 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34297413‬تاريخه‪1434/8/15:‬هـ‬\n\n\n‫دخــول منــزل دون إذن صاحبــه مــع توجــه شــبهة الغــرض الســيء‬\n‫‪ -‬انتهــاك حرمــة منــزل ‪ -‬رجــوع املقــر عــن إقــراره يف غيــر احلــدود ال‬\n‫يقبــل ‪ -‬تكــرر الســوابق مــن نفــس نــوع اجلــرم املتهــم بــه ‪ -‬إثبــات إدانــة ‪-‬‬\n                                              ‫التعزيــر بالســجن واجللــد علنــا‪.‬‬\n\n\n\n‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم ‪ « :‬مــن اطلــع يف بيــت قــوم بغيــر‬\n                     ‫إذنهــم ‪ ،‬فقــد حــل لهــم أن يفقــؤوا عينــه » رواه مســلم‪.‬‬\n‫‪ -2‬مــا قــرره أهــل العلــم أن رجــوع املقــر عــن إقــراره ال يقبــل يف غيــر‬\n‫احلــدود‪ ،‬جــاء يف كشــاف القنــاع ‪ « :‬وال يقبــل رجــوع املقــر عــن إقــراره‬\n‫لتعلــق حــق املقــر لــه باملقــر بــه إال فيمــا كان حــد ًا هلل تعالــى فيقبــل‬\n‫رجوعــه عنــه كمــا تقــدم يف مواضعــه ألن احلــد يــدرأ بالشــبهة ‪.»6/475‬‬\n\n\n\n\n‫توجيــه االتهــام للمدعــى عليــه بدخــول منــزلٍ لغــرض ســيء لالطــاع علــى‬\n‫أهلــه مــن خــال نوافــذ املنــزل‪ ،‬وذلــك بعــد تقــدم أحد املقيمني بشــكوى‬\n‫للجهــات املختصــة مفادهــا قيــام املدعــى عليــه بالدخــول لفنــاء منزلــه‬\n‫وقيامــه بالنظــر إلــى أســرته مــن خــال فتحــات النوافــذ‪ -‬طلــب املدعــي‬\n‫العــام احلكــم عليــه بعقوبــة تعزيريــة‪ ،‬والتشــديد عليــه يف العقوبــة‬\n\n\n                                                                                       ‫‪90‬‬\n\f     ‫لكثــرة ســوابقه وتكــرار اجلــرم املتهــم بــه‪ -‬بالبحــث عــن ســوابقه تبــن‬\n     ‫وجــود ســت ســوابق مســجلة عليــه أربــع ســوابق منهــا دخــول منــزل لغــرض‬\n     ‫ســيء وســابقة ســرقة وســابقة تلفــظ بألفــاظ غيــر الئقــة‪ -‬بعــرض دعــوى‬\n     ‫املدعــي العــام علــى املدعــى عليــه أنكرهــا ودفــع أنــه وقــف علــى البيــت‬\n     ‫خطــأ حينمــا كان يبحــث عــن بيـ ٍـت آخــر‪ -‬مت ســماع شــهادة الشــاهد‬\n     ‫وبعــرض الشــاهد وشــهادته علــى املدعــى عليــه كــذب الشــهادة ولــم‬\n     ‫يطعــن يف الشــاهد‪ ،‬ثــم جــرى تعديــل الشــهود‪ -‬جــرى االطــاع علــى‬\n     ‫إقــرار املدعــى عليــه حتقيق ـ ًا وبعرضــه عليــه أنكــره‪ -‬نظــر ًا إلنــكار‬\n     ‫املدعــى عليــه مــا نســبه إليــه املدعــي العــام‪ ،‬وإلقــراره املدعــى عليــه‬\n     ‫بدخــول حــوش املنــزل وألن رجــوع املقــر عــن إقــراره يف غيــر احلــدود‬\n     ‫ال يقبــل مــا جــاء يف شــهادة الشــاهد املدونــة ‪ ،‬ولســوابق املدعــى عليــه‬\n     ‫ومنهــا أربــع ســوابق بنفــس التهمــة ولضعــف مــا دفــع بــه املدعــى عليــه‬\n     ‫مــن أن ذهابــه كان للبحــث عــن منــزل صاحبــه‪ ،‬وألن مــا أقــدم عليــه‬\n     ‫املدعــى عليــه فعــل منكــر وتعــدٍ علــى احلرمــات التــي جــاءت الشــريعة‬\n     ‫اإلســامية بحفظهــا لــذا ثبتــت إدانــة املدعــى عليــه بدخــول منــزل بغيــر‬\n     ‫إذن أهلــه‪ ،‬وتوجــه التهمــة القويــة بــأن دخولــه كان لغــرض ســيء ومت‬\n     ‫احلكــم بتعزيــره بســجنه مــدة عشــرة أشــهر وجلــده مائتــي جلــدة علن ـ ًا‬\n     ‫مفرقــة علــى دفعــات ‪ ،‬علــى أن تكــون دفعتــن منهــا يف مــكان عــام يف‬\n     ‫نفــس احلــي الــذي وقعــت فيــه حادثــة املدعــى عليــه‪ -‬بعــرض احلكــم علــى‬\n     ‫املدعــي العــام قــرر اعتراضــه وطلــب رفعــه حملكمــة االســتئناف بــدون‬\n     ‫الئحــة اعتراضيــة وبعرضــه علــى املدعــى عليــه قــرر اعتراضــه وطلــب‬\n     ‫تســليمه نســخة مــن احلكــم لكتابــة اعتراضــه عليــه ‪ ،‬فأجيــب لطلبــه‪،‬‬\n                  ‫وبعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n‫‪91‬‬\n\f‫احلمــد هلل وحــده وبعــد‪ :‬فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n‫بينبــع ‪ ،‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بينبع‪/‬املســاعد برقــم ‪ 34168877‬وتاريــخ ‪1434/04/13‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 34852448‬وتاريــخ ‪1434/04/08‬ه ـ ففــي‬\n‫يــوم األربعــاء املوافق‪1434/05/01‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي العــام ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪).....‬‬\n‫واملكلــف مــن رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة ينبــع‬\n‫باخلطــاب رقــم ‪.....‬وتاريــخ ‪1432/4/11‬ه ـ وادعــى قائــا‪ :‬بصفتــي مدعيا‬\n‫عامــا بدائــرة التحقيــق واالدعــاء العــام أدعي على ‪ )40(.....‬عاما ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬عاطــل عــن العمــل ويســكن‬\n‫يف ‪.....‬قبــض عليــه بتاريــخ ‪1434/3/9‬ه ـ وأودع بســجن محافظــة ينبــع‬\n‫‪ ،‬وبالبحــث عــن ســوابقه تبــن وجــود ســت ســوابق مســجلة عليــه وهــي‬\n‫أربــع ســوابق دخــول منــزل لغــرض ســيء وســابقة ســرقة وســابقة التلفــظ‬\n‫بألفــاظ غيــر الئقــة ‪ ،‬حيــث أنــه بتاريــخ ‪1434/3/8‬ه ـ تقــدم الوافــد‪.....‬‬\n‫مصــري اجلنســية بشــكوى للجهــات األمنيــة تتضمــن قيــام املتهــم أعــاه‬\n‫بالدخــول لفنــاء منزلــه وقيامــه بالنظــر علــى أســرته مــن خــال فتحــات‬\n‫النوافــذ ‪ ،‬وباالنتقــال واملعاينــة ملنــزل املدعــي مت مشــاهدة ســيارة املتهــم‬\n‫متوقفــة مبســافة كيلــو ونصــف عــن منــزل املدعــي وهــي نــوع فــورد لونهــا‬\n‫أبيــض ‪ .‬وباســتجواب املتهــم ‪ :‬اعتــرف بأنــه دخــل ملنــزل املدعــي حيــث‬\n‫اشــتبه عليــه منــزل املدعــي أحــد أصدقائــه كان يــود زيارتــه وبســماع‬\n‫شــهادة ‪(..... :‬جــار املدعــي ) أفــاد بأنــه شــاهد املتهــم كثيــر ًا مــا يكــرر‬\n\n                                                                                       ‫‪92‬‬\n\f     ‫حضــوره لنفــس احلــي الــذي يســكن بــه ‪ ،‬وقــد ســبق أن ســأل املتهــم عــن‬\n     ‫تواجــده يف احلــي الــذي يســكن بــه فأفــاد بأنــه حضــر لزيــارة قريــب لــه ‪،‬‬\n     ‫ويف املرة األخيرة شــاهد املتهم أوقف ســيارته بعيد ًا عن ســكن املدعي‬\n     ‫وهــي نــوع ‪ ......‬تقريب ـ ًا وعندهــا صعــد الشــاهد لســطح منزلــه فشــاهد‬\n     ‫املتهــم يقــوم بالنظــر مــن خــال نوافــذ منــزل املدعــي وفتحــات مكيــف‬\n     ‫التبريــد فنــزل وقــام بالقبــض عليــه مبســاعدة جــاره املدعــي وقامــوا‬\n     ‫بتســليمه للدوريــات األمنيــة ‪ .‬وقــد انتهــى التحقيــق إلــى توجيــه االتهــام‬\n     ‫لــه بدخــول منــزل املدعــي لغــرض ســيء باالطــاع علــى أســرته مــن خــال‬\n     ‫نوافــذ املنــزل وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء يف شــهادة‬\n     ‫الشــاهد واملدونــة بصفحــة (‪ )5-4‬مبلــف التحقيــق املرفــق بالقضيــة ‪-2 .‬‬\n     ‫مــا جــاء يف أقــوال املتهــم واملدونــة بصفحــة (‪ )3-1‬مبلــف التحقيــق املرفــق‬\n     ‫بالقضيــة ‪ -3 .‬مــا جــاء يف محضــر االنتقــال واملعاينــة واملدونــة بصفحــة‬\n     ‫(‪ )3‬مبلــف االســتدالل املرفــق بالقضيــة ‪ .‬وحيــث إن مــا أقــدم عليــه املتهــم‬\n     ‫فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب مــا أســند إليــه واحلكــم عليــه‬\n     ‫بعقوبــة تعزيريــة رادعــه لــه ولغيــره‪ .‬والتشــديد عليــه يف العقوبــة لكثــرة‬\n     ‫ســوابقه وتكــرار اجلــرم املتهــم بــه (علم ـ ًا بــأن احلــق اخلــاص قــد انتهــى‬\n     ‫بالتنــازل ) هكــذا ادعــى‪ .‬وجــرى عــرض دعــوى املدعــي العــام علــى‬\n     ‫ا ‪ :‬مــا ذكــره املدعــي العــام يف دعــواه كلــه‬    ‫املدعــى عليــه فأجــاب قائـ ً‬\n     ‫غيــر صحيــح ‪ ،‬فقــد كنــت يف اليــوم املذكــور يف الدعــوى مدعــوا عنــد‬\n     ‫زميلــي ‪ .....‬وقــد ذهبــت للحــي الــذي يســكن فيــه للمــرة الثانيــة إال إنــي‬\n     ‫لــم أســتطيع الوصــول إلــى بيتــه ‪ ،‬وقــد ســبق أن ذهبــت معــه يف املــرة‬\n     ‫األولــى ‪ ،‬وقــد أوقفــت ســيارتي يف مــكان بعيــدٍ عــن البيــت وذهبــت‬\n     ‫للبحــث عــن البيــت علــى قدمـ ّـي إال إنــي وقفــت علــى بيـ ٍـت خطــأ وفــور أن‬\n\n\n‫‪93‬‬\n\f‫تبــن لــي ذلــك قمــت باالنصــراف فلحــق بــي صاحــب املنــزل وأمســكني‬\n‫يف الشــارع قريبـ ًا مــن بيتــه هكــذا أجــاب‪ .‬ثــم جــرى ســؤاله عــن ســوابقه‬\n‫؟ فقــال ‪ :‬إنهــا صحيحــة وقــد تبــت منهــا وأخــذت جزاءهــا هكــذا أجــاب‪.‬‬\n‫ولطلــب البينــة مــن املدعــي العــام رفعــت اجللســة‪ .‬ويف جلســة أخــرى حضــر‬\n‫املدعــي العــام واملدعــى عليــه وبســؤال املدعــي العــام عــن البينــة؟ قــال ‪:‬‬\n‫لــم حتضــر وأطلــب مهلــة ثانيــة إلحضارهــا فأجيــب إلــى طلبــه ورفعــت‬\n‫اجللســة لذلــك‪ .‬ويف جلســة أخــرى حضــر املدعــي العــام واملدعــى عليــه‬\n‫وبســؤال املدعــي العــام عــن البينــة؟ قــال‪ :‬لــم حتضــر وأطلــب مهلــة أخــرى‬\n‫إلحضارهــا فأجيــب إلــى طلبــه وعليــه جــرى رفــع اجللســة ‪ .‬ويف جلســة‬\n‫أخــرى حضــر املدعــي العــام واملدعــى عليــه وبســؤال املدعــي العــام عــن‬\n‫البينــة؟ أحضــر للشــهادة ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم (‪ ).....‬والــذي يعمــل عســكري يف الدفــاع املدنــي يف الهيئــة امللكيــة‬\n‫وبســؤاله عمــا لديــه مــن شــهادة؟ قــال‪ :‬أشــهد هلل تعالــى بــأن هــذا احلاضــر‬\n‫‪.....‬كان يكثــر مــن تكــرار احلضــور للحــي الــذي يســكن فيــه والــدي‬\n‫وقــد شــاهدته أكثــر مــن ثــاث مــرات ‪ ،‬وقــد مســكته قبــل هــذه‬\n‫املــرة يف نفــس احلــي أنــا وزمالئــي تقريب ـ ًا بعــد الســاعة الثانيــة عشــرة‬\n‫ا وكانــت يــداه عليهــا مــادة بيضــاء تشــبه مــادة البويــة التــي علــى‬    ‫لي ـ ً‬\n‫جــدران املنــازل وقلــت لــه‪ :‬أيــش عنــدك يف حارتنــا؟ فقــال إنــي يف زيــارة‬\n‫لشــخص ‪ ،‬وعندمــا ســألته عــن اســمه لــم يخبرنــي ‪ ،‬وبعــد فتــرة اتصــل‬\n‫بــي أصدقائــي وأخبرونــي أنهــم شــاهدوه يف احلــي وكان يوقــف ســيارته‬\n‫بعيــدا ‪ ،‬ثــم ذهــب ويف املــرة األخيــرة شــاهدت ســيارته مــن نــوع فورد أظن‬\n‫أن موديلهــا ‪1995‬م وصعــدت إلــى أعلــى منزلــي للبحــث عنــه فشــاهدته‬\n‫داخــل حــوش املدعــو‪ .....‬وهــو يســترق النظــر مــن الشــباك فنزلــت مــن‬\n\n\n                                                                                        ‫‪94‬‬\n\f     ‫أعلــى وكان قــد خــرج مــن احلــوش وأخــذ يجــري وكان صاحــب املنــزل‬\n     ‫قــد خــرج مــن النــادي فناديــت عليــه ثــم قبضنــا علــى املدعــو ‪.....‬واتصلنــا‬\n     ‫علــى الدوريــات ثــم هــرب منــا فركضنــا وراءه ومســكناه يف احلــارة‬\n     ‫وعنــد مســكي لــه أخــذ يتوســلني بــأن أســتر عليــه وأتركــه ثــم جــاءت‬\n     ‫الدوريــات وقبضــت عليــه ‪ ،‬هــذا مــا أشــهد به وبعرض الشــاهد وشــهادته‬\n     ‫علــى املدعــى عليــه قــال ‪ :‬أمــا الشــاهد فــا أعرفــه ‪ ،‬وأمــا شــهادته فغيــر‬\n     ‫صحيحــة ‪ ،‬فلــم أكــرر احلضــور للحــي ولــم أوقــف ســيارتي بعيـ ًـد ًا ‪ ،‬ولــم‬\n     ‫أدخــل حــوش املدعــو ‪.....‬أو أســترق النظــر إلــى داخل منزلــه هكذا قال‪،‬‬\n     ‫وعليــه ولطلــب معدلــن لشــاهد املدعــي العــام رفعــت اجللســة ‪ .‬ويف جلســة‬\n     ‫أخــرى حضــر املدعــي العــام واملدعــى عليــه وبســؤال املدعــي العــام عــن‬\n     ‫تعديــل الشــاهد ‪.....‬أحضــر معــه ‪ .....‬ســعودي اجلنســية مبوجــب الســجل‬\n     ‫املدنــي رقــم ‪.....‬و‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n     ‫وبســؤالهما عمــا لديهمــا حيــال الشــاهد املذكــور؟ أجــاب كل واحــد‬\n     ‫ا ‪ :‬أشــهد هلل تعالــى أن ‪.....‬ثقــة عــدل مرضــي الشــهادة وأقبــل‬   ‫منهمــا قائـ ً‬\n     ‫شــهادته لــي أو علــي ‪ ،‬وقــد عرفتــه بالصــدق واحملافظــة علــى الصــاة‪.‬‬\n     ‫هكــذا شــهدا ‪ .‬ثــم جــرى رفــع اجللســة لدراســة القضيــة ‪ .‬ويف جلســة‬\n     ‫أخــرى حضــر املدعــي العــام واملدعــى عليــه وجــرى الرجــوع للمعاملــة‬\n     ‫وفيهــا إقــرار املدعــى عليــه املــدون علــى ص (‪ )1‬لفــة (‪ )9‬وقــد تضمــن‬\n     ‫‪ « :‬أفيدكــم بأنــي كنــت ذاهــب إلــى منــزل زميلي‪.....‬وكنــت متواجــد‬\n     ‫معــه علــى زيارتــه وقمــت بالدخــول إلــى أحــد املنــازل حيــث اشــتبه لــي أنــه‬\n     ‫منــزل ‪.....‬حيــث فتــح بــاب احلــوش ودخلــت إلــى حــوش املنــزل ظنـ ًا منــي أنه‬\n     ‫منــزل ‪ « .......‬أ ‪ .‬ه ـ وبعــرض مــا جــاء يف اإلقــرار أعــاه علــى املدعــى عليــه‬\n     ‫قــال ‪ :‬ال أدري عــن ذلــك فقــد ذكــرت لهــم أنــي لــم أدخــل حــوش املنــزل‬\n\n\n‫‪95‬‬\n\f‫هكــذا قــال ‪ .‬وعليــه فبعــد االطــاع علــى دعــوى املدعــي العــام وإجابــة‬\n‫املدعــى عليــه ‪ ،‬ونظــر ًا إلنــكار املدعــى عليــه ملــا نســبه إليــه املدعــي‬\n‫العــام ‪ ،‬وإلقــرار املدعــى عليــه بدخــول حــوش املنــزل باإلقــرار املرصــود‬\n‫أعــاه وألن رجــوع املقــر عــن إقــراره يف غيــر احلــدود ال يقبــل كمــا قــرره‬\n‫أهــل العلــم ‪ ،‬جــاء يف كشــاف القنــاع ‪ « :‬وال يقبــل رجــوع املقــر عــن‬\n‫إقــراره لتعلــق حــق املقــر لــه باملقــر بــه إال فيمــا كان حــد ًا هلل تعالــى‬\n‫فيقبــل رجوعــه عنــه كمــا تقــدم يف مواضعــه ألن احلــد يــدرأ بالشــبهة‬\n‫‪ »6/475‬لذلــك فقــد ثبــت لــدي إدانــة املدعــى عليــه بدخــول منــزل بغيــر‬\n‫إذن أهلــه‪ ،‬وتوجــه التهمــة القويــة بــأن دخولــه كان لغــرض ســيء ملــا جــاء‬\n‫يف شــهادة الشــاهد املدونــة ‪ ،‬ولســوابق املدعــى عليــه ومنهــا أربــع ســوابق‬\n‫بنفــس التهمــة ولضعــف مــا دفــع بــه املدعــى عليــه مــن أن ذهابــه كان‬\n‫للبحــث عــن منــزل صاحبــه ‪ ،‬وألن مــا أقــدم عليــه املدعــى عليــه فعــل‬\n‫منكــر وتعــدٍ علــى احلرمــات التــي جــاءت الشــريعة اإلســامية بحفظهــا‬\n‫ولقــول النبــي صلــى اهلل عليــه وســلم ‪ « :‬مــن اطلــع يف بيــت قــوم بغيــر‬\n‫إذنهــم ‪ ،‬فقــد حــل لهــم أن يفقــؤوا عينــه « رواه مســلم ‪ ،‬لذلــك فقــد‬\n‫قــررت تعزيــر املدعــى عليــه للحــق العــام مبــا يلــي ‪ /1 :‬ســجنه ملــدة عشــرة‬\n‫أشــهر مــن تاريــخ إيداعــه الســجن بســبب هــذه القضيــة ‪ /2‬جلــده مئتــي‬\n‫جلــدة علنـ ًا مفرقــة علــى دفعــات ‪ ،‬كل دفعــة خمســون جلــدة وبــن كل‬\n‫دفعــة وأخــرى مــا ال يقــل عــن أســبوع علــى أن تكــون دفعتــن منهــا يف‬\n‫مــكان عــام يف نفــس احلــي الــذي وقعــت فيــه حادثــة املدعــى عليــه هــذا‬\n‫مــا ظهــر لــي وبــه حكمــت ‪ ،‬وبعــرض احلكــم علــى املدعــي العــام قــرر‬\n‫اعتراضــه وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة اعتراضيــة‬\n‫وبعرضــه علــى املدعــى عليــه قــرر اعتراضــه وطلــب تســليمه نســخة مــن‬\n\n\n                                                                                      ‫‪96‬‬\n\f     ‫احلكــم لكتابــة اعتراضــه عليــه ‪ ،‬فأجيــب لطلبــه وأفهــم أنــه ســيجري‬\n     ‫اســتدعاءه الســتالم نســخة مــن احلكــم وإفهامــه بتعليمــات االســتئناف‬\n     ‫وعليــه جــرى التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‪1434/6/6‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافق‪1434/08/06‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 10 : 15‬وفيهــا جــرى اإلطــاع على املعاملة بعد‬\n     ‫ورودهــا مــن محكمــة االســتئناف مبكــة املكرمــة برقــم ‪34852448‬‬\n     ‫يف ‪1434/7/18‬ه ـ مرفقــا بهــا قــرار الدائــرة اجلزائيــة السادســة برقــم‬\n     ‫‪ 34234470‬يف ‪1434/6/7‬هـ املتضمن بعد املقدمة ما نصه « وبدراسة‬\n     ‫القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا فضيلــة‬\n     ‫حاكمهــا ملالحظــة أن مــا حكــم بــه علــى املدعــى عليــه مــن ســجن وجلد‬\n     ‫كثيــر ال يتناســب مــع جرميتــه فعلــى فضيلتــه إعــادة النظــر يف حكمــه‬\n     ‫واهلل املوفــق « قاضــي اســتئناف ‪.....‬ختمــه وتوقيعــه وقاضــي اســتئناف‬\n     ‫‪.....‬ختمــه وتوقيعــه رئيــس الدائــرة ‪.....‬ختمــه وتوقيعــه ‪،‬عليــه أجيــب علــى‬\n     ‫مــا جــاء يف قــرار أصحــاب الفضيلــة وفقهــم اهلل بأنــه لــم يظهــر لــي بــأن‬\n     ‫احلكــم علــى املدعــى عليــه لقــاء مــا أقــدم عليــه كثيــر وال يتناســب مــع‬\n     ‫جرميتــه ذلــك أنــه ال يخفــى علــى شــريف علــم أصحــاب الفضيلــة أن مــا‬\n     ‫أقــدم عليــه املدعــى عليــه فيــه تعــدٍ علــى األعــراض التــي جــاءت الشــريعة‬\n     ‫اإلســامية بحفظهــا ‪ ،‬وهتــك للســتر الــذي جــاءت الشــريعة بصيانتــه‬\n     ‫وال بــد مــن احلــزم يف مثــل هــذا لكــي يأمــن النــاس علــى محارمهــم‬\n     ‫وأعراضهــم يف بيوتهــم ‪ ،‬وال ســيما أن للمدعــى عليــه خمــس ســوابق‬\n     ‫منهــا أربــع يف نفــس موضــوع الدعــوى ‪ ،‬مــا يوحــي بعــدم ارتــداع املدعــى‬\n     ‫عليــه وتأصــل اإلجــرام فيــه ‪ ،‬واحلاجــة ألخــذه باحلــزم والشــدة لذلــك فإنــه‬\n\n\n‫‪97‬‬\n\f‫لــم يظهــر لــي ســوى مــا أجريــت ‪ ،‬وال زلــت باقي ـ ًا علــى مــا حكمــت بــه‬\n‫‪ ،‬وقــررت إعــادة املعاملــة مــع القــرار بعــد هــذا اإلجــراء إلــى محكمــة‬\n‫االســتئناف لتقريــر مــا يلــزم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‪1434/8/6‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ -:‬نحــن‬\n‫قضاة الدائرة اجلزائية السادسة مبحكمة االستئناف مبكة املكرمة‬\n‫جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه احملكمــة بكتــاب‬\n‫فضيلــة رئيــس احملكمــة العامــة بينبــع املســاعد رقــم (‪)34852448‬‬\n‫وتاريــخ (‪1434/8/7‬هــ) املرفــق بهــا القــرار رقــم(‪ )34234470‬وتاريــخ‬\n‫(‪1434/6/7‬هــ) الصــادر مــن فضيلــة الشــيخ‪ ...../‬القاضــي باحملكمــة‬\n‫العامــة بينبــع‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪ ...../‬ســعودي‬\n‫اجلنســية ‪ ،‬املتهــم بدخــول منــزل شــخص لغــرض ســيء‪ ،‬احملكــوم‬\n‫فيــه مبــا دون باطنــه ‪ ،‬واملالحــظ عليــه بقــرار محكمــة االســتئناف‬\n‫رقم‪34267985‬وتاريخ‪1434/7/15‬ه ـ ‪ ،‬وبدراســة القــرار وصــورة‬\n‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم بعــد اجلــواب‬\n‫األخيــر‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آله وصحبه‬\n                                                                         ‫وســلم‬\n\n\n\n\n                                                                                   ‫‪98‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":90,"source_page_end":98,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bcf9daeef038826d8ffd2706e82a6d8ca13ba125e4b53cb0f6f52d67c6ddd3ba","normalized_text_hash":"1644e5ea7f652a3999f4738822324a288f1b8d09b71bd36cd1812f36d8db7622","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p90-34234470"},{"id":"190714d2-1227-5a7c-b4e3-646faa8e004a","document_type":"judgment","category":"judicial","subcategory":"general","title":"دخول منزل دون إذن صاحبه -خلوة غير شرعية -إسام املدعى عليه بعد ارتكاب اجلرمية -اعتناق اإلسام يسقط التعازير يف احلقوق العامة دون احلقوق اخلاصة -اإلسام يجب ما قبله.","document_number":"34246286","case_number":"34204648","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية مبوجب اخلطاب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/20","year":"1434","subject":"دخول منزل دون إذن صاحبه -خلوة غير شرعية -إسام املدعى عليه بعد ارتكاب اجلرمية -اعتناق اإلسام يسقط التعازير يف احلقوق العامة دون احلقوق اخلاصة -اإلسام يجب ما قبله.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34246286 :‬تاريخه‪1434/6/20 :‬هـ‬\n                        ‫رقم الدعوى‪34204648 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34303138‬تاريخه‪1434/8/23 :‬هـ‬\n\n\n     ‫دخــول منــزل دون إذن صاحبــه ‪ -‬خلــوة غيــر شــرعية ‪ -‬إســام املدعــى‬\n     ‫عليــه بعــد ارتــكاب اجلرميــة ‪ -‬اعتنــاق اإلســام يســقط التعازيــر يف‬\n      ‫احلقــوق العامــة دون احلقــوق اخلاصــة ‪ -‬اإلســام يجــب مــا قبلــه‪.‬‬\n\n\n\n\n     ‫ـاص قــال ‪:‬‬ ‫أن عمــرو بـ َـن العـ ِ‬    ‫‪ -1‬أن اإلســام يجــب مــا قبلــه ملــا ُروي مــن َّ‬\n     ‫هلل ع ـ َّز وجـ َّـل يف قلبــي اإلســا َم قــال أتيـ ُـت النبــي ص َّلــى ا ُ‬\n     ‫هلل‬                                                                            ‫( ملــا ألقــى ا ُ‬\n       ‫ُبايعــك يــا رســولَ ا ِ‬\n     ‫هلل‬                      ‫بايعنــي فبســط يـ َـده إلـ َّـي فقلـ ُـت ال أ ُ‬  ‫عليـ ِه وسـ َّل َم ل ُِي َ‬\n      ‫هلل ص َّلــى ا ُ‬\n     ‫هلل‬             ‫حتــى تغفـ َـر لــي مــا تقـ َّـدم مــن ذنبــي قــال فقــال لــي رســولُ ا ِ‬\n     ‫الذنوب‬\n        ‫ِ‬         ‫تـ ُّـب مــا قب َلها مــن‬              ‫عليـ ِه وسـ َّل َم يــا عمــرو أمــا علمـ َـت َّ‬\n                                          ‫أن الهجــر َة َ ُ‬\n          ‫ـوب )‪.‬‬\n             ‫أن اإلســا َم َي ُجـ ُّـب مــا كان قب َلــه مــن الذنـ ِ‬    ‫يــا عمــرو أمــا علمـ َـت َّ‬\n                               ‫‪ -2‬املادة رقم ( ‪ ) 195‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n\n     ‫اتهــام املدعــى عليــه بالدخــول إلــى منــزلٍ بغيــر إذن صاحبــه لغــرض ســيء‬\n     ‫وإقامــة عالقــة محرمــة مــع خادمتــه واخللــوة بهــا‪ ،‬وذلــك بعــد القبــض على‬\n     ‫املدعــى عليــه داخــل املنــزل‪ -‬طلــب املدعــي العــام احلكــم علــى املدعــى‬\n     ‫عليــه بعقوبــة تعزيريــة‪ -‬بعــرض دعــوى املدعــي العــام علــى املدعــى عليــه‬\n     ‫بواســطة املترجــم أقــر بعالقتــه غيــر الشــرعية مــع اخلادمــة وأنــه دخــل‬\n\n‫‪99‬‬\n\f‫معهــا يف غرفتهــا يف منــزل كفيلهــا‪ ،‬وقــرر أنــه محصــن وأنــه دخــل يف‬\n‫اإلســام بعــد هــذه القضيــة ‪ -‬ألن اإلســام يجــب مــا قبلــه‪ ،‬وألن اخللــوة‬\n‫غيــر الشــرعية باخلادمــة حـ ٌـق محــض هلل تعالــى بينمــا انتهــاك حرمــة‬\n‫املنــزل املذكــور يتعلــق بــه حـ ٌـق آلدمــي لذلــك كلــه فقــد ثبتــت إدانــة‬\n‫املدعــى عليــه بانتهــاك حرمــة املنــزل املذكــور يف الدعــوى بالدخــول‬\n‫فيــه ومت احلكــم بتعزيــره لقــاء ذلــك للحــق العــام بســجنه مــدة خمســة‬\n‫أشــهر وجلــده تســعني جلــدة مفرقــة علــى دفعتــن متســاويتني‪ .‬بعــرض‬\n‫احلكــم علــى الطرفــن قــرر املدعــى عليــه القناعــة وقــرر املدعــي العــام‬\n‫االعتــراض وطلــب رفــع احلكــم حملكمــة االســتئناف بالئحـ ٍة اعتراضية‬\n‫مقدمـ ًة منــه ف ُأجيــب لطلبــه ‪ -‬انتهــت مــدة االعتــراض ولــم يســتلم املدعــي‬\n‫العــام صــورة احلكــم ولــم يقــدم الئحتــه االعتراضيــة وعليــه فقــد ســقط‬\n‫حقــه يف تقدميهــا ومت رفــع احلكــم حملكمــة االســتئناف ومتــت املصادقــة‬\n                                                                  ‫علــى احلكــم‪.‬‬\n\n\n\n\n‫اجلزائيــة‬\n   ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة‬\n‫بالدمــام ويف يــوم االثنــن املوافــق‪ 1434/06/19‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 11 : 15‬وفيهــا قــدم املدعــي العــام ‪ ................‬دعــواه ضــد‬\n‫ا فيهــا ‪ :‬إنــه بتاريــخ ‪1434/4/17‬ه ـ تقــدم املواطــن‬   ‫املدعــى عليــه ‪.....‬قائـ ً‬\n‫‪..... /‬بشــكوى مفادهــا قيــام املدعــى عليــه بانتهــاك حرمــة منزلــه‬\n‫ودخولــه مــن غيــر إذنــه وقــد مت القبــض علــى املدعــى عليــه داخــل منــزل‬\n‫املدعــي يف نفــس يــوم البــاغ وبســماع أقــوال املدعــى عليــه أقــر بأنهــا‬\n‫املــرة األولــى التــي يقــوم فيهــا بالدخــول ملنــزل املدعــي وباســتجوابه أقــر‬\n\n                                                                                        ‫‪100‬‬\n\f      ‫بدخولــه منــزلَ املدعــي بغيــر إذن منــه وأفــاد أنــه قــام بالدخــول حملادثــة‬\n      ‫اخلادمــة املنزليــة وأنــه اختلــى بهــا وانتهــى التحقيــق إلــى اتهــام ‪.....‬بانتهــاك‬\n      ‫منــزل املدعــي بالدخــول فيــه بغيــر إذنــه لغــرض ســيء وإقامــة عالقــة‬\n      ‫محرمــة مــع خادمتــه املنزليــة واخللــوة بهــا وذلــك لألدلــة والقرائــن التاليــة‬\n      ‫‪ -1 :‬مــا جــاء يف محضــر اســتجوابه املرفــق لفــه ( ‪ -2. ) 6,5‬مــا جــاء يف‬\n      ‫محضــر ســماع أقوالــه املــدون علــى الصفحتــن رقــم ( ‪ ) 11,10‬مــن دفتــر‬\n      ‫االســتدالل املرفــق لفــه ( ‪ -3. ) 1‬مــا جــاء يف محضــر القبــض املرفــق لفــه‬\n      ‫( ‪ ) 2‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه‬\n      ‫شــرع ًا واطالــب بإثبــات مــا ُأســند إليــه شــرع ًا واحلكــم عليــه بعقوبــة‬\n      ‫تعزيريــة تزجــره وتــردع غيــره ( علم ـ ًا بــأن احلــق اخلــاص ال زال قائم ـ ًا )‬\n      ‫وبــاهلل التوفيــق ويف هــذه اجللســة حضــر املدعــى عليــه ‪.....‬فلبينــي اجلنســية‬\n      ‫مبوجــب رخصــة إقامــة صــادرة مــن اخلبــر املــدون بهــا الرقــم ‪.....‬وبعــرض‬\n      ‫ا‪:‬‬ ‫دعــوى املدعــي العــام عليــه بواســطة مترجــم احملكمــة ‪.....‬أجــاب قائـ ً‬\n      ‫الصحيح أن هذه اخلادمة ال متت لي بصل ٍة شرعية وقد تعرفت عليها عن‬\n      ‫طريــق ُأختهــا يف الفلبــن وحصــل بينــي وبني اخلادمة املذكــورة اتصاالت‬\n      ‫هاتفيــة وقــد طلبــت منــي احلضــور ملنــزل كفيلهــا لكــي آخــذ منهــا مبلــغ‬\n      ‫مالــي وأقــوم بتحويلــه إلــى أهلهــا يف الفلبــن وبالفعــل حضــرت للمنــزل‬\n      ‫املذكــور وفتحــت لــي اخلادمــة البــاب ودخلــت يف غرفــة اخلادمــة بالــدور‬\n      ‫األرضــي ولــم يحصــل بينــي وبينهــا شــيء ســوى أنني حتدثــت معها وكان‬\n      ‫ا وكان بعــض أهــل البيــت موجوديــن ولكــن‬              ‫بــاب الغرفــة مفتــوح قلي ـ ً‬\n      ‫لــم يرونــي وأثنــاء ذلــك رأتنــي صاحبــة املنــزل وقــام ابنهــا مبســكي ومت‬\n      ‫إبــاغ الشــرطة علمـ ًا أننــي محصــن متــزوج وقــد دخلــت يف اإلســام بعــد‬\n      ‫هــذه القضيــة وتســميت باســم ‪.....‬هــذه إجابتــي ‪ .‬وبســؤال املدعــي العــام‬\n\n\n‫‪101‬‬\n\f‫هــل لديــه مزيــد بينــة علــى الدعــوى قــال ليس لدي ســوى مــا ورد يف الئحة‬\n‫الدعــوى وأوراق املعاملــة فنظــر ًا ملــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬\n‫أقــر املدعــى عليــه بجــود عالقـ ٍة هاتفيــه مــع اخلادمــة املذكــورة ودخولــه‬\n‫ـاك حلرمــة هــذا‬  ‫لغرفــة اخلادمــة باملنــزل املذكــور وحيــث أن يف ذلــك انتهـ ٌ‬\n‫املنــزل وبعــد االطــاع علــى طيــات املعاملــة وحيــث قــرر املدعــى عليــه‬\n‫أن‬\n ‫دخولــه يف اإلســام وحيــث أن اإلســام يجــب مــا قبلــه وملــا ُروي مــن َّ‬\n‫ـام قــال‬                                    ‫ُ‬\n         ‫ـاص قــال ‪ ( :‬ملــا ألقــى اهلل عـ َّـز وجــلَّ يف قلبــي اإلسـ َ‬  ‫عمــرو بـ َـن العـ ِ‬\n                                                                     ‫أتيـ ُـت النبــي ص َّلــى ُ‬\n                                         ‫اهلل علي ـ ِه وس ـل ََّم ل ُِي َ‬\n‫بايعنــي فبســط يـ َـده إلـ َّـي فقلـ ُـت ال‬\n‫هلل حتــى تغفـ َـر لــي مــا تقـ َّـدم مــن ذنبــي قــال فقــال لــي‬                       ‫ُأ ُ‬\n                                                                      ‫بايعــك يــا رســولَ ا ِ‬\n‫تـ ُّـب‬\n      ‫أن الهجــر َة َ ُ‬                                                ‫هلل ص َّلــى ُ‬\n                      ‫اهلل عليـ ِه وسـل ََّم يــا عمــرو أمــا علمـ َـت َّ‬        ‫رســولُ ا ِ‬\n‫ـام َي ُجـ ُّـب مــا كان‬\n                     ‫أن اإلسـ َ‬   ‫ـوب يــا عمــرو أمــا علمـ َـت َّ‬\n                                                                ‫مــا قب َلهــا مــن الذنـ ِ‬\n‫ـوب ) وحيــث أن اخللــوة غيــر الشــرعية باخلادمــة املذكــورة‬      ‫قب َلــه مــن الذنـ ِ‬\n‫حـ ٌـق محــض هلل تعالــى بينمــا انتهــاك حرمــة املنــزل املذكــور يتعلــق بــه‬\n‫حـ ٌـق آلدمــي لذلــك كلــه فقــد قــررت مــا يلــي أوالً‪ -‬ثبــت لــدي إدانــة‬\n‫املدعــى عليــه بانتهــاك حرمــة املنــزل املذكــور يف الدعــوى بالدخــول فيــه‬\n‫ـداء‬\n‫وقــررت تعزيــره لقــاء ذلــك للحــق العــام بســجنه ملــدة خمســة أشــهر ابتـ ً‬\n‫مــن تاريــخ إيقافــه وجلــده تســعني جلــدة مفرقــة علــى دفعتــن متســاويتني‬\n‫بــن كل دفعــة وأخــرى مــا ال يقــل عــن خمســة عشــر يومــا ‪ .‬ثانيـاً‪ -‬ثبــت‬\n‫لــدي إدانــة املدعــى عليــه باالختــاء احملــرم مــع امــرأ ٍة ال متــت لــه بصلــة‬\n‫شــرعية وال أرى معاقبتــه علــى ذلــك ملــا ذكــره مــن دخولــه يف اإلســام‬\n‫ـات أعــاه وبذلــك أجمــع حكمــت وبعــرض‬                ‫ومــا مت ذكــره مــن حيثيـ ٍ‬\n‫احلكــم علــى الطرفــن قــرر املدعــى عليــه بواســطة املترجــم آنــف‬\n‫الذكــر القناعــة وقــرر املدعــي العــام االعتــراض وطلــب رفــع احلكــم‬\n\n\n                                                                                                   ‫‪102‬‬\n\f      ‫حملكمــة االســتئناف بالئح ـ ٍة اعتراضيــة مقدم ـ ًة منــه ف ُأجيــب لطلبــه‬\n      ‫وجــرى إفهامــه أن عليــه احلضــور يــوم الثالثــاء ‪1434/6/20‬ه ـ الســتالم‬\n      ‫صــورة مــن احلكــم وأنــه يف التاريــخ املذكــور ســوف يتــم إيــداع القــرار‬\n      ‫ملــف الدعــوى وســوف يكــون ذلــك اإليــداع مجريـ ًا مليعــاد الثالثــن يومـ ًا‬\n      ‫يقــدم خاللهــا الئحتــه االعتراضيــة وأنــه مبضيهــا دون تقــدمي الالئحــة‬\n      ‫ويرفــع احلكــم حملكمــة االســتئناف‬          ‫ســوف يســقط حقــه يف تقدميهــا ُ‬\n      ‫بدونهــا فامتثــل واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n      ‫وســلم احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء املوافق‪1434/07/25‬ه ـ‬\n      ‫أفتتحــت اجللســة وقــد انتهــت مــدة االعتــراض املنصــوص عليهــا يف املــادة‬\n      ‫رقــم ( ‪ ) 194‬مــن نظــام اإلجــراءات اجلزائيــة ولــم يســتلم املدعــي العــام‬\n      ‫صــورة احلكــم ولــم يقــدم الئحتــه االعتراضيــة وعليــه فقــد ســقط حقــه‬\n      ‫ـاء علــى املــادة‬\n                      ‫يف تقدميهــا وســوف ُيرفــع احلكــم حملكمــة االســتئناف بنـ ً‬\n      ‫رقــم ( ‪ ) 195‬مــن نظــام اإلجــراءات اجلزائيــة واهلل املوفــق وصلــى اهلل‬\n                                            ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم األربعــاء املوافق‪1434/10/14‬ه ـ فتحــت‬\n      ‫اجللســة وقــد وردت املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n      ‫مبوجــب اخلطــاب رقــم ‪ 342010273‬يف ‪1434/09/15‬ه ـ وبرفقهــا‬\n      ‫قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة الثانيــة مبحكمــة‬\n      ‫االســتئناف باملنطقــة الشــرقية رقــم ‪ 34303138‬يف ‪1434/08/23‬ه ـ‬\n      ‫املتضمــن املصادقــة علــى احلكــم لــذا جــرى إحلاقــه واهلل املوفــق وصلــى‬\n                                                     ‫اهلل علــى نبينــا محمــد وآلــه وســلم‬\n\n\n\n\n‫‪103‬‬\n\f104\n\f105\n\f106\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":99,"source_page_end":106,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d8f37f0bb0040d713f0f53bc2af456059673a2f480dcfbf1a8f76e0b3042d7f6","normalized_text_hash":"931947143ee7b2665a2944fc2f01cf1e9bd710a6c55509f4b8452e2b49d8fc2f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p99-34246286"},{"id":"2636714e-f068-5983-bd0e-bd6f9dd7a8a6","document_type":"judgment","category":"judicial","subcategory":"general","title":"حرابة -لواط -ارتكاب فاحشة اللوط بحدث -اعتداء بالضرب -إنكار املدعى عليه -حتليل حمض نووي -عدم ثبوت -رد طلب إثبات احلرابة -عدم وجود سوابق قضائية -توجه الشبهة املوجبة للتعزير بالسجن واجللد.","document_number":"34261554","case_number":"341961","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بجازان كال من","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/8","year":"1434","subject":"حرابة -لواط -ارتكاب فاحشة اللوط بحدث -اعتداء بالضرب -إنكار املدعى عليه -حتليل حمض نووي -عدم ثبوت -رد طلب إثبات احلرابة -عدم وجود سوابق قضائية -توجه الشبهة املوجبة للتعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34261554 :‬تاريخه‪1434/7/8 :‬هـ‬\n                          ‫رقم الدعوى‪341961 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34370126‬تاريخه‪1434/11/25 :‬هـ‬\n\n\n      ‫حرابــة ‪ -‬لــواط ‪ -‬ارتــكاب فاحشــة اللــوط بحــدث ‪ -‬اعتــداء بالضــرب‬\n      ‫‪ -‬إنــكار املدعــى عليــه ‪ -‬حتليــل حمــض نــووي ‪ -‬عــدم ثبــوت ‪ -‬رد طلــب‬\n      ‫إثبــات احلرابــة ‪ -‬عــدم وجــود ســوابق قضائيــة ‪ -‬توجــه الشــبهة املوجبــة‬\n                                                    ‫للتعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n      ‫‪ -1‬اتفــاق العلمــاء علــى مشــروعية التعزيــر لإلمــام « مجمــوع الفتــاوي‬\n                                                                               ‫‪.»402/35‬‬\n      ‫‪ -2‬التعزيــر «واجــب يف كل معصيــة ال حــد فيهــا وال كفــارة» كشــاف‬\n                                                                      ‫القناع (‪.)3027/5‬‬\n      ‫‪« -3‬املعصيــة تفتقــر إلــى مــا مينــع مــن فعلهــا فــإذا لــم يجــب فيهــا حــد‬\n      ‫وال كفــارة وجــب أن يشــرع فيهــا التعزيــر ليتحقــق املانــع مــن فعلهــا»‬\n                                                        ‫كشــاف القنــاع (‪.)3027/5‬‬\n      ‫‪« -4‬التعزيــر يكــون بالضــرب واحلبــس والصفــع والتوبيــخ والعــزل عــن‬\n                                             ‫الواليــة» كشــاف القنــاع (‪.)3029/5‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه باعتدائــه علــى‬\n      ‫حــدث وفعــل الفاحشــة بــه بالقــوة وطلــب إثبــات مــا أســند إليــه واحلكــم‬\n\n‫‪107‬‬\n\f‫عليــه بحــد احلرابــة حيــث تقــدم أحــد املواطنــن ببــاغ للشــرطة بــأن ابنــه‬\n‫احلــدث (‪ )16‬عامــا تعــرض للضــرب وفعــل فاحشــة قــوم لــوط بــه مــن قبــل‬\n‫املدعــى عليــه فجــرى البحــث عنــه وتبــن بأنــه هــارب وقــد قــام بتســليم‬\n‫نفســه للشــرطة الحقــا ‪ ،‬شــوهدت آثــار الضــرب علــى جســم املجنــي‬\n‫عليــه وأفــاد بــأن املدعــى عليــه صــوره وهــو عــاري بجوالــه ثــم أصبــح‬\n‫يبتــزه بالصــور وأنــه علــى عالقــة قدميــة معــه وفعــل بــه الفاحشــة عــدة‬\n‫مــرات ‪ ،‬أنكــر املدعــى عليــه فعــل الفاحشــة بــه وتصويــره وهروبــه وقــرر‬\n‫بــأن الصحيــح بأنــه تضــارب معــه خلــاف مالــي واصطلــح معــه يف يومهــا‬\n‫‪ ،‬بعــرض مــا تضمنــه تقريــر األدلــة اجلنائيــة املتضمــن فحــص التلوثــات‬\n‫املنويــة املرفوعــة مــن ســراويل املجنــي عليــه عبــر تقنيــة احلمــض النــووي‬\n‫(‪ )DNA‬وثبــوت بــأن هــذه التلوثــات عائــدة لــه أجــاب بأنــه احتلــم ليلتهــا‬\n‫وبقــي آثــار االحتــام يف ســراويله وقــام بلبســها بعــد الســباحة ‪ ،‬جــرى‬\n‫ســؤال املدعــي العــام عــن البينــة فقــرر بأن بينتــه األوراق املرفقــة باملعاملة‬\n‫‪ ،‬عليــه وإلنــكار املدعــى عليــه ولعــدم قيــام البينــة املوصلــة وملــا احتــف‬\n‫الدعــوى مــن قرائــن كاختفائــه عــن األنظــار بعــد االعتــداء عليــه ومــا‬\n‫تضمنــه تقريــر األدلــة اجلنائيــة وفحــص احلمــض النــووي وآثــار االعتــداء‬\n‫اجلســمي علــى املجنــي عليــه وإقــراره بوجــود عالقــة حــب قدميــة والتواجــد‬\n‫يف املســبح ‪ ،‬عليــه وألن مــا اتهــم بــه عمــل محــرم وضــرب مــن ضــروب‬\n‫اإلفســاد يف األرض ‪ ،‬والتفــاق العلمــاء علــى مشــروعية التعزيــر ‪ ،‬ونظــرا‬\n‫لعــدم وجــود ســوابق عليــه وملجمــوع مــا تقــدم فقــد قــررت احملكمــة عــدم‬\n‫ثبــوت إدانــة املدعــى عليــه مبــا يوجــب إقامــة حــد احلرابــة علــى املدعــى‬\n‫عليــه مــع توجــه التهمــة املوجبــة للعقوبــة التعزيريــة بحقــه وحكمــت‬\n‫بصــرف النظــر عــن دعــوى املدعــي العــام وطلبــه إقامــة حــد احلرابــة علــى‬\n\n\n                                                                                       ‫‪108‬‬\n\f      ‫املدعــى عليــه‪ ،‬وتعزيــر املدعــى عليــه بالســجن ثــاث ســنوات ابتــداء مــن‬\n      ‫تاريــخ إيقافــه يف هــذه القضيــة وتعزيــر املدعــى عليــه بجلــده ثالثمئــة‬\n      ‫جلــدة مفرقــة علــى دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة‬\n      ‫والتــي تليهــا أســبوع وقــرر املدعــي العــام واملدعــى عليــه االعتــراض علــى‬\n                  ‫احلكــم بالئحــة‪ ،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلدينــا نحــن القضــاة باحملكمــة العامــة‬\n      ‫بجــازان كال مــن‪...........‬و‪ ...........‬و‪ ...........‬وبنــاء علــى املعاملــة احملالــة‬\n      ‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بجــازان برقــم ‪341961‬‬\n      ‫وتاريــخ ‪1434/01/03‬ه ـ واملقيــدة باحملكمــة برقــم ‪ 341213‬وتاريــخ‬\n      ‫‪1434/01/03‬ه ـ ففــي يــوم األحــد املوافــق ‪1434/02/ 08‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪09 : 30‬وفيهــا حضــر املدعــي العــام املكلــف باالدعــاء‬\n      ‫مــن فضيلــة رئيــس فــرع هيئــة التحقيــق واالدعــاء العــام بجــازان مبوجــب‬\n      ‫التعميــد رقــم ‪...........‬وتاريــخ ‪1433/2/2‬ه ـ ولــم يحضــر املدعــى‬\n      ‫عليــه‪ ...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)...........‬‬\n      ‫‪ ،‬فقــررت ســماع وتدويــن دعــوى املدعــي العــام اســتنادا للمــادة (‪)141‬‬\n      ‫مــن نظــام اإلجــراءات اجلزائيــة ‪ .‬وبســؤال املدعــي العــام عــن دعــواه ادعــى‬\n      ‫ا ‪( :‬بصفتــي مدعيـ ًا عامـ ًا بدائــرة االدعــاء العام لفــرع الهيئة مبنطقة‬       ‫قائـ ً‬\n      ‫جــازان أدعــي علــى املذكــور أعــاه بتاريــخ ‪1431/12/17‬ه ـ تقــدم‬\n      ‫املواطــن‪........... /‬ببــاغ لشــرطة محافظــة ‪ ..........‬يفيــد فيــه بتعــرض ابنــه‬\n      ‫احلــدث (‪ )...........‬البالــغ مــن العمــر (‪ 16‬ســنة) للضــرب وفعــل فاحشــة‬\n      ‫اللــواط بــه مــن قبــل املدعــي عليــه عندهــا جــرى البحــث عنــه وتبــن أنــه‬\n\n‫‪109‬‬\n\f‫غيــر موجــود وأنــه هــارب ولــم يتم القبض عليه إال بتاريخ ‪1433/4/11‬هـ‬\n‫حيــث ســلم نفســه للشــرطة‪ .‬مبعاينــة جســم املجنــي عليــه (‪ )...........‬مــن‬\n‫قبــل الشــرطة بتاريــخ ‪1431/12/17‬ه ـ شــوهدت آثــار ضــرب خلــف‬\n‫ظهــره ويف كلتــا يديــه واعــد محضــر ًا بذلــك ‪ .‬أوقــف املدعــي عليــه‬\n‫اســتناد ًا للقــرار الــوزاري رقــم (‪ )1900‬كــون قضيتــه موجبــة للتوقيــف‬\n‫بســماع أقــوال احلــدث (‪ )...........‬ذكــر أنــه ذهــب مــع املدعــي عليــه يف‬\n‫ســيارته نــوع (‪ ) ...........‬وذلــك حلــوش يف قريــة (‪ )...........‬وذلــك قبــل شــهر‬\n‫مــن البــاغ ‪ ،‬واعتــدى عليــه املدعــي عليــه بالضــرب وخلــع مالبســه‬\n‫وصــوره وهــو عــاري بجــوال نــوع (‪ )........‬وقــد حــاول الصيــاح ولكــن دون‬\n‫جــدوى لعــدم وجــود أي شــخص‪ ،‬ثــم بعدهــا صــار يبتــزه بتلــك الصــور‬\n‫وقــد تقابــا يــوم األحــد املوافــق ‪1431/10/15‬ه ـ وتخاصمــا بخصــوص‬\n‫ذلــك‪ ،‬كمــا ذكــر أنــه يف متــام الســاعة العاشــرة مــن يــوم االثنــن املوافــق‬\n‫‪1431/12/16‬ه ـ وعنــد خروجــه مــن منــزل جدتــه قابــل املدعــي عليــه‬\n‫وحــاول أن يرضيــه فطلــع معــه يف الســيارة وذهبــا ملطعــم ‪...........‬ثــم بعدها‬\n‫جلســا يتجــوالن يف شــوارع محافظــة (‪ )...........‬ثــم توقــف بــه املدعــي عليــه‬\n‫خلــف مســبح وضربــه بسلســلة علــى أنحــاء جســمه وأقفــل أبــواب الســيارة‬\n‫ثــم خلــع مالبســه وفعــل بــه الفاحشــة بإيــاج وبعــد االنتهــاء هــدده بنشــر‬\n‫صــوره إن أخبــر أحــد ًا بذلــك ‪ ،‬كمــا أفــاد أن العالقــة بينــه وبــن املدعــي‬\n‫عليــه قدميـ ًا كانــت عالقــة حــب يف البدايــة وقــد عمــل بــه املدعــي عليــه‬\n‫الفاحشــة عــدة مــرات وصــادق علــى أقوالــه ‪ .‬وباســتجواب املدعــي عليــه‬\n‫(‪ )......‬اعتــرف بضربــه للمجنــي عليــه وأنكــر فعــل الفاحشــة بــه أو‬\n‫تصويــره ‪ ،‬وذكــر أن جوالــه نــوع (‪ ).....‬ويوجــد لديــه جــوال آخــر نــوع‬\n‫(‪ ).....‬وقــد باعــه ‪ ،‬ومبواجهتــه مبــا ورد يف تقريــر (‪ )DNA‬مــن عائديــه‬\n\n\n                                                                                         ‫‪110‬‬\n\f      ‫بعــض التلوثــات املنويــة لــه ذكــر أنــه كان يف ذلــك اليــوم نائــم وقــد‬\n      ‫احتلــم يف املنــزل ثــم ذهــب للمســبح دون أن يغتســل وســبح هــو واملجنــي‬\n      ‫عليــه يف املســبح ثــم قــام املجنــي عليــه بلبــس ســرواله القصيــر باخلطــأ‪،‬‬\n      ‫ومبواجهتــه حــول تهربــه ألكثــر مــن ســنة وثالثــة أشــهر ذكــر أنــه جلــس‬\n      ‫فتــرة ثالثــة أشــهر يف جــدة يبحــث عــن وظيفــة كمــا أن والــده جــرى عليه‬\n      ‫حــادث وبقــي بجــواره حلــن تعافيــه وال يعلــم عــن كونــه مطلــوب للشــرطة‬\n                                                                    ‫وصــادق علــى أقوالــه ‪.‬‬\n      ‫بالكشــف علــى احلــدث املجنــي عليــه (‪ )...........‬ورد التقريــر الطبــي‬\n      ‫الصادر من مستشفى …‪ .‬العام برقم (‪ )...........‬وتاريخ ‪1431/12/17‬هـ‬\n      ‫املتضمــن (وجــود آثــار لعــض أســنان علــى الفخــذ األميــن واأليســر وعلــى‬\n      ‫الظهــر والذراعــن ‪ ،‬وآثــار للكمــة باجلانــب األيســر مــن الوجــه ‪،‬‬\n      ‫وســحجة ســطحية بالشــرج ‪ ،‬وال يوجــد دم أو آثــار إلفــرازات أخــرى)‬\n      ‫‪.‬وببعــث املالبــس وعينــات املســحات لألدلــة اجلنائيــة ‪ .....‬باخلطــاب رقــم‬\n      ‫‪ ...........‬وتاريــخ ‪1431/12/17‬ه ـ لفحصهــا فــورد التقريــر رقــم (‪...........‬‬\n      ‫) املتضمــن ((تطابــق األمنــاط الوارثيــة للعينــات (تلوثــات منويــة و خاليــا‬\n      ‫طالئيــة) بالعينــات الــواردة للفحــص ممــا يثبــت أنهــا مــن مصــدر واحــد))‬\n      ‫وعلــى ضــوء ذلــك مت طلــب عينــات دم قياســية مــن املجنــي عليــه و املدعــي‬\n      ‫عليــه ملقارنتهــا بهــذه النتيجــة فجــرى بعــث تلــك العينــات ‪(( -‬يتبــع)) وورد‬\n      ‫التقريــر رقــم (‪ )...........‬املتضمــن (تطابــق األمنــاط الوراثيــة لعينــة الــدم‬\n      ‫القياســية للفحــص مــع عينــات التلوثــات املنويــة والتــي صــدر بحقهــا‬\n      ‫التقريــر الفنــي رقــم (‪ )...........‬ممــا يثبــت أن املدعــي عليــه (‪ )...........‬هــو‬\n      ‫مصــدر تلــك التلوثــات املنويــة ‪.‬وقــد أســفر التحقيــق مــع املدعــي عليــه عــن‬\n      ‫توجيــه االتهــام للمدعــى عليــه باعتدائــه بالضــرب وفعــل الفاحشــة بالقــوة‬\n\n\n‫‪111‬‬\n\f‫باحلــدث (‪...........‬وحيــث إن مــا أقــدم عليــه املدعــي عليــه وهــو بكامــل‬\n‫ويعـ ّـد ضرب ـ ًا‬\n               ‫أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ُ‬\n‫مــن ضــروب احلرابــة واإلفســاد يف األرض وانتهــاك ًا ألعــراض املســلمني‬\n‫علــى ســبيل الغلبــة والقهــر لــذا أطلب‪/‬إثبات ما أســند إليــه واحلكم عليه‬\n‫بحــد احلرابــة الــوارد يف اآليــة الكرميــة رقــم (‪ )33‬مــن ســورة املائــدة يف‬\n‫ضــوء قــرار هيئــة كبــار العلمــاء رقــم (‪ )85‬يف ‪1401/11/11‬هــ‪( ،‬علمـ ًا‬\n‫بــأن احلــق اخلــاص ال زال قائمــا)‪ .‬هكــذا ادعــى ‪ .‬فقــررت رفــع اجللســة‬\n‫لطلــب املدعــى عليــه وعــرض دعــوى املدعــي العــام عليــه وســماع اإلجابــة‬\n‫‪ .‬ويف يــوم االثنــن املوافــق ‪143/04/01‬ه ـ افتتحــت اجللســة الســاعة ‪00‬‬\n‫‪ 10 :‬وفيهــا حضــر املدعــي العــام وحضــر املدعــى عليــه وبعــرض دعــوى‬\n‫ا ‪ ( :‬ما ذكــره املدعي العام‬     ‫املدعــي العــام علــى املدعــى عليــه أجــاب قائـ ً‬\n‫يف دعــواه غيــر صحيــح جملــة وتفصيــا والصحيــح أننــي قمــت مبضاربــة‬\n‫املجنــي عليــه أثــر خــاف مــادي وقــد قمــت بالصلــح معــه يف يومهــا ومــا‬\n‫ذكــره مــن وجــود حيوانــات منويــة فذلــك كونــي احتلمــت ومازالــت آثــار‬\n‫االحتــام يف ســروالي وقــد قــام بلبــس ســروالي بعــد الســباحة ولــم أقــم‬\n‫بالهــرب وال التخفــي وإمنــا كنــت مــع والــدي ملرافقتــه أثنــاء مرضــه )‪.‬‬\n‫هكــذا أجــاب ‪ .‬وبســؤال املدعــي العــام عــن بينتــه ‪ .‬قــال بينتــي مــا يف‬\n‫أوراق املعاملــة ‪ .‬فجــرى االطــاع علــى ‪ -1 :‬التقريــر الطبــي ‪ -2 .‬التقريــر‬\n‫الفنــي‪ -3 .‬أقــوال املدعــى عليــه‪ -4 .‬محاضــر املعاينــة ‪ .‬وبعــرض ذلــك‬\n‫علــى املدعــى عليــه قــال ‪ :‬أمــا التقريــر الطبــي فمــا ورد فيــه هــو نتيجــة‬\n‫املضاربــة وال أذكــر أنــي قــد قمــت بعــض املجنــي عليــه‪ .‬وأمــا التقريــر‬\n‫الفنــي فذلــك نتيجــة لبــس املجنــي عليــه ملالبســي التــي بهــا آثــار احتــام‬\n‫‪ .‬وأمــا أقوالــي فصحيــح أنــي ذهبــت للمســبح مــع املجنــي عليــه لغــرض‬\n\n\n                                                                                        ‫‪112‬‬\n\f      ‫الســباحة لكونــه صاحــب لــي منــذ زمــن وقــد اختلفــت معــه لكونــه أخذ‬\n      ‫مــن فلوســي ودفــع لصاحــب املســبح ‪ .‬ثــم حصلــت املضاربــة بعــد ذلــك‬\n      ‫‪ .‬هكــذا أجــاب ‪ .‬فجــرى ســؤال املدعــي العــام هــل لديــه مزيــد بينــة ‪.‬‬\n      ‫فقــال ليــس لــدي ســوى مــا ذكــرت يف أوراق املعاملــة ‪ .‬فقــرر رفــع اجللســة‬\n      ‫لدراســة القضيــة والتأمــل ‪ .‬ويف يــوم االثنــن املوافــق‪ 1434/04/29‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة (‪ )10:15‬لدينــا نحــن القضــاة يف احملكمــة‬\n      ‫العامــة بجــازان ‪..........‬و‪ ...........‬ونظــر ًا النتقــال فضيلــة الشــيخ ‪...........‬‬\n      ‫لقضــاء احملكمــة اجلزائيــة بالدمــام وعــدم مباشــرة خلــف لــه فقــد قررنــا‬\n      ‫التوقــف عــن إكمــال نظــر هــذه القضيــة مؤقت ـ ًا حلــن إعــادة تشــكيل‬\n      ‫أعضــاء الدوائــر اجلنائيــة املشــتركة ولألهميــة جــرى تدويــن ذلــك ‪ .‬ويف‬\n      ‫يــوم األربعــاء املوافــق ‪1434/07/05‬ه ـ افتتحــت اجللســة عنــد الســاعة‬\n      ‫(‪ )11:00‬وفيهــا حضــر املدعــي العــام واملدعــى عليــه وقــد جــرى اطــاع‬\n      ‫فضيلــة الشــيخ املشــارك ‪...........‬علــى مــا مت ضبــط ســابقا ‪ ،‬وبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة ‪ ،‬وجلميــع مــا قــرره الطرفــان ونظــرا‬\n      ‫ألن املدعــى عليــه أنكــر مــا جــاء يف هــذه الدعــوى وأنــه غيــر صحيــح‬\n      ‫ا ولعــدم قيــام البينــة املثبتــة لصحــة الدعــوى وملــا احتــف‬      ‫جملــة وتفصي ـ ً‬\n      ‫بوقائــع هــذه الدعــوى مــن قرائــن متضافــرة منهــا اختفــاؤه عــن األنظــار‬\n      ‫بعــد االعتــداء ‪ ،‬و مــا ورد يف التقريــر الطبــي وتطابــق األمنــاط الوراثيــة ‪،‬‬\n      ‫وآثــار االعتــداء علــى املجنــي عليــه ‪ ،‬وإقــراره بوجــود عالقــة حــب حتقيقــا‬\n      ‫‪ ،‬والتواجــد معــه يف املســبح ‪ .‬ونظــر ًا ألن هــذا العمــل يعــد يف أصلــه‬\n      ‫ا محرمــا وهــو نــوع مــن اإلفســاد يف األرض ‪ .‬والتفــاق العلمــاء علــى‬         ‫عمـ ً‬\n      ‫مشــروعية التعزيــر لإلمــام ( مجمــوع الفتــاوى ‪ )402/35‬وألنــه واجــب‬\n      ‫يف كل معصيــة ال حــد فيهــا وال كفــارة ألن املعصيــة تفتقــر إلــى مــا‬\n\n\n‫‪113‬‬\n\f‫مينــع مــن فعلهــا فــإذا لــم يجــب فيهــا حــد وال كفــارة وجــب أن يشــرع‬\n‫فيهــا التعزيــر ليتحقــق املانــع مــن فعلهــا (كشــاف القنــاع ‪ )121/6‬وألن‬\n‫التعزيــر يكــون بالضــرب واحلبــس والصفــع والتوبيــخ والعــزل عــن الوالية‬\n‫(كشــاف القنــاع ‪ )134/6‬ونظــر ًا لعــدم وجــود ســوابق بحــق املدعــى‬\n                         ‫عليــه‪ .‬ولــكل مــا تقــدم فقــد تقــرر لدينــا مــا يلــي ‪:‬‬\n‫لــم يثبــت لدينــا إدانــة املدعــى عليــه مبــا يوجــب حــد احلرابــة مــع توجــه‬\n‫(التهمــة) املوجبــة للعقوبــة بحقــه ‪ .‬وحكمنــا يف هــذه القضية (باإلجماع)‬\n                                                                             ‫مبــا يلــي ‪:‬‬\n‫أوال‪ :‬صرفنــا النظــر عــن طلــب املدعــي العــام إقامــة حــد احلرابــة بحــق‬\n                                                                       ‫املدعــى عليــه‬\n‫ثانيــا‪ :‬حكمنــا بتعزيــر املدعــى عليــه بالســجن ملــدة(‪ )3‬ثــاث ســنوات‬\n                           ‫تبــدأ مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة‪.‬‬\n‫ثالثــا ‪ :‬حكمنــا بتعزيــر املدعــى عليــه بجلــده عــدد (‪ )300‬ثالثمائــة جلــده‬\n‫مفرقــة علــى دفعــات مقــدار كل دفعــة خمســون جلــده بــن كل دفعــة‬\n                                                         ‫والتــي تليهــا مــدة أســبوع ‪.‬‬\n‫وبجميــع ذلــك حكمنــا واهلل أحكــم احلاكمــن ‪ .‬وبعرضه على أطراف‬\n‫الدعــوى قــرر املدعــى عليــه االعتــراض علــى احلكــم وقــرر املدعــي العــام‬\n‫اعتراضــه علــى احلكــم ورغــب كل منهــم يف رفــع احلكــم وأوراق‬\n‫املعاملــة إلــى محكمــة االســتئناف بالئحــة اعتراضيــة فأجبنــاه لطلبــه‬\n‫وســلم اجلميــع نســخة مــن صــك احلكــم حــاال وأفهــم بــأن لــه مهلــة ‪30‬‬\n‫يومــا لتقــدمي الئحتــه االعتراضيــة علــى احلكــم فــإن انقضــت املــدة ولــم‬\n‫يتقــدم بهــا ســقط حقــه يف االعتــراض ويرفــع بعــد ذلــك صــك احلكــم‬\n‫برفقــة كافــة أوراق املعاملــة حملكمــة االســتئناف مبنطقــة عســير‬\n\n\n                                                                                             ‫‪114‬‬\n\f      ‫لتدقيــق احلكــم حســب املتبــع ‪ ،‬وكان ختــام هــذه اجللســة بعــد النطــق‬\n      ‫باحلكــم عنــد الســاعة ‪ 11 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل وســلم علــى‬\n               ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/5‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/12/29‬ه ـ ويف‬\n      ‫متــام الســاعة (‪ )8:00‬افتتحــت اجللســة وقــد عــادت املعاملــة رفــق خطــاب‬\n      ‫رئيــس محكمــة االســتئناف مبنطقــة عســير رقــم ‪ 342585493‬يف‬\n      ‫تاريــخ ‪1434/12/19‬ه ـ مرفقــا بهــا قــرار الدائــرة اخلماســية الثانيــة رقــم‬\n      ‫‪ 34370126‬يف ‪1434/11/25‬ه ـ واملتضمــن نــص احلاجــة منــه وبدراســة‬\n      ‫احلكــم وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم مذيــا عليــه‬\n      ‫بتوقيــع قضــاة االســتئناف‪ ...... :‬و ‪......‬و ‪......‬و ‪ ......‬و‪ ......‬وحتــى ال يخفــى‬\n      ‫جــرى احلاقــة وأمرنــا بالتهميــش وكان ختــام هــذه اجللســة الســاعة‬\n      ‫(‪ )8:15‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد ‪ .‬حــرر يف‬\n                                                                       ‫‪1434/12/29‬ه ـ ‪.‬‬\n\n\n\n\n‫‪115‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":107,"source_page_end":115,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"814fb31a262e312a11ce91e08234c1a528e8903f9cc7d374e9c91341f602531c","normalized_text_hash":"69da99dd8b189d30bd3cad4e841cc3568b99c5e8875e405bf8759b21b100c3f6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p107-34261554"},{"id":"1de22b7a-60c0-570b-a619-d421f4b98ae1","document_type":"judgment","category":"judicial","subcategory":"general","title":"حرابة -لواط -ارتكاب فاحشة اللواط بحدث -خطف حدث - درء حد احلرابة -رجوع عن إقرار -التعزير لقاء التهمة بالسجن واجللد واإلبعاد.","document_number":"34301602","case_number":"3470780","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/21","year":"1434","subject":"حرابة -لواط -ارتكاب فاحشة اللواط بحدث -خطف حدث - درء حد احلرابة -رجوع عن إقرار -التعزير لقاء التهمة بالسجن واجللد واإلبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34301602 :‬تاريخه ‪1434/8/21:‬هـ‬\n                    ‫رقم الدعوى‪3470780 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34354098‬تاريخه‪1434/11/9 :‬هـ‬\n\n\n‫حرابــة ‪ -‬لــواط ‪ -‬ارتــكاب فاحشــة اللــواط بحــدث ‪ -‬خطــف حــدث ‪-‬‬\n‫درء حــد احلرابــة ‪ -‬رجــوع عــن إقــرار ‪ -‬التعزيــر لقــاء التهمــة بالســجن‬\n                                                          ‫واجللــد واإلبعــاد‪.‬‬\n\n\n\n\n                  ‫قوله صلى اهلل عليه وسلم‪( :‬ادرؤوا احلدود بالشبهات)‪.‬‬\n\n\n\n\n‫توجيــه االتهــام للمدعــى عليــه املقيــم بخطــف طفــل عمــره خمــس ســنوات‬\n‫وفعــل فاحشــة اللــواط بــه ‪ ،‬تقدمــت والــدة الطفــل ببالغ ملركز الشــرطة‬\n‫عــن قيــام املدعــى عليــه بأخــذ الطفــل البالــغ مــن العمــر خمــس ســنوات‬\n‫مــن املجلــس والتوجــه بــه إلــى غرفتــه وفعــل الفاحشــة بــه بإيــاج ‪ ،‬طلــب‬\n‫املدعــي العــام إثبــات مــا أســند للمدعــى عليــه واحلكــم عليه بحــد احلرابة‬\n‫‪ ،‬أقــر املدعــى عليــه مبــا نســب إليــه بواســطة مترجــم احملكمــة ‪ ،‬يف‬\n‫جلســة أخــرى رجــع املدعــى عليــه عــن إقــراره وأنكــر مــا جــاء يف دعــوى‬\n‫املدعــي العــام ‪ ،‬قــرر املدعــي العــام أن بينتــه إقــرار املدعــى عليــه حتقيقـ ًا‬\n‫‪ ،‬جــرى الرجــوع إلــى هــذا اإلقــرار ورصــد مضمونــه وهــو مطابــق ملــا جــاء‬\n‫يف دعــوى املدعــي العــام ‪ ،‬جــرى عــرض اإلقــرار علــى املدعــى عليــه فقــرر‬\n‫أن هــذا اإلقــرار صــدر منــه بســبب مــا تعــرض لــه مــن ضــرب شــديد مــن‬\n\n                                                                                         ‫‪116‬‬\n\f      ‫قبــل احملقــق ومــا جــاء فيــه غيــر صحيــح ‪ ،‬طلبــت احملكمــة مــن املدعــى‬\n      ‫عليــه البينــة علــى دعــوى الضــرب فقــرر أن ال بينــه لديــه ‪ ،‬جــرى الرجــوع‬\n      ‫إلــى محضــر اســتنطاق الطفــل وهــو مطابــق ملــا جــاء يف دعــوى املدعــي‬\n      ‫العــام ‪ ،‬جــرى عرضــه علــى املدعــي عليــه فقــرر أنــه والــدة الطفــل هي من‬\n      ‫أمرتــه بقــول هــذا الــكالم ‪ ،‬جــرى الرجــوع إلــى تقريــر الطــب الشــرعي‬\n      ‫ورصــد مضمونــه ‪ ،‬بالرجــوع إلــى صحيفــة ســوابق املدعــى عليــه وتبــن‬\n      ‫عــدم وجــود ســوابق مســجله عليــه ‪ ،‬صــدر احلكــم بــرد دعــوى املدعــي‬\n      ‫العــام يف طلبــه إثبــات إدانــة املدعــى عليــه بخطــف الطفــل ورد دعــواه‬\n      ‫بطلــب إقامــة حــد احلرابــة عليــه لعــدم ثبــوت موجبهــا وتعزيــر املدعــى‬\n      ‫عليــه لقــاء التهمــة املوجهــة لــه وذلــك بســجنه ســنتني وجلــده ثالثمائــة‬\n      ‫جلــدة مفرقــة علــى ســت دفعــات والتوصيــة بإبعــاده عــن البــاد ‪ ،‬صــدق‬\n                                               ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلدينــا نحــن ‪..............‬و‪..............‬و‪............‬‬\n      ‫القضــاة يف احملكمــة العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة‬\n      ‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالرياض‪/‬املســاعد برقــم‬\n      ‫‪..............‬وتاريــخ ‪1434/02/12‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ‬\n      ‫‪1434/02/09‬ه ـ ففــي يــوم األحــد املوافق‪1434/02/17‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪08 : 45‬وفيهــا حضــر املدعــي العــام وقــد الئحــة الدعــوى‬\n      ‫العامــة التالــي نصهــا (بصفتــي مدعيـ ًا عامـ ًا بدائــرة االدعاء العــام مبدينة‬\n      ‫الريــاض أدعــي علــى‪ ............. :‬عام ـ ًا ‪ ،‬باكســتاني اجلنســية مبوجــب‬\n      ‫رخصــة اإلقامــة رقــم(‪ )................‬غيــر محصــن‪ ،‬مســلم الديانــة‪،‬‬\n\n‫‪117‬‬\n\f‫موقــوف بتاريــخ‪ 1433/9/20‬مبوجــب أمــر التوقيــف رقــم وتاريــخ‪/21‬‬\n‫‪1433/9‬ه ـ وأمــر التمديــد واإلحالــة رقــم وتاريــخ ‪1433/9/24‬هـ ـ ‪.‬‬\n‫بتاريــخ ‪1433/9/20‬ه ـ قبــض علــى املدعــى عليــه مــن قبــل مركــز‬\n‫شــرطة ‪.....‬إثــر بــاغ تقدمــت بــه املرأة‪......../‬إرتيريــة اجلنســية ‪ ،‬عــن قيــام‬\n‫املتهــم املذكــور بفعــل الفاحشــة بابنهــا البالــغ مــن العمــر ‪5‬ســنوات وذلــك‬\n‫بقيامــه بأخــذه مــن املجلــس والتوجــه بــه إلــى غرفتــه وفعــل الفاحشــة بــه‬\n‫بإيــاج ‪ .‬وباســتنطاق الطفــل ‪ /‬أفــاد بــأن املذكــور قــام بحملــه والتوجــه‬\n‫بــه إلــى غرفتــه وأنــه قــام بخلــع مالبســه وفعــل بــه الفاحشــة وبإحضــار‬\n‫املتهــم املذكــور أمامــه أشــار إليــه بأنــه مــن قــام بذلــك ‪ .‬وبســماع أقــوال‬\n‫املتهــم واســتجوابه‪ /‬أقــر بأنــه شــاهد الطفــل ‪ ،‬يلعــب يف فنــاء املنــزل وأنــه‬\n‫قــام بحملــه بيديــه والتوجــه بــه إلــى غرفتــه خــارج القصــر وأنــه قــام بخلــع‬\n‫مالبســه وفعــل الفاحشــة بــه بإيــاج ‪ .‬صــدر بحــق املجنــي عليــه تقريــر‬\n‫الطــب الشــرعي رقــم(‪ ).....‬لعام‪1433‬ه ـ واملتضمــن أنــه بفحصه موضعيا‬\n‫مــن دبــر تبــن وجــود احمــرار وتــورم حــول فتحــة الشــرج وتشــققات مدماه‬\n‫عديــدة عنــد الســاعة‪ 11‬والســاعة ‪ 7‬مــن مينــاء عقــارب الســاعة وهــي‬\n‫إصابيــة املنشــأ معاصــره للواقعــة مضــى عليهــا أقــل مــن ‪24‬ســاعة مــن‬\n‫تاريــخ الكشــف الطبــي الشــرعي قــد تشــير إلــى محاولــة إيــاج مــن دبــر‬\n‫بجســم صلــب أيــا كان نوعــه ويجــوز حدوثهــا مــن مثــل عضــو ذكــري‬\n‫منتصــب لرجــل بالــغ أو مــا شــبهه كمــا تضمــن تعــذر أخــذ مســحات‬\n‫مــن جســمه ومســحات شــرجية لقيــام والــدة الطفــل بغســل جســم الطفــل‬\n‫باملــاء والصابــون ومــاده مطهــره عــن االثــار واملــواد املنويــة العالقة باجلســم‪.‬‬\n‫صــدر تقريــر االدلــة اجلنائيــة رقــم (‪ )....-...‬لعام‪1433‬ه ـ بشــأن فحــص‬\n‫مالبــس املجنــي عليــه واملتضمــن ســلبيات العينــات الــواردة يف الفحــص‬\n\n\n                                                                                          ‫‪118‬‬\n\f      ‫للحمــض النــووي الوراثــي ممــا يتعــذر معــه إجــراء أي مقارنــة ‪ .‬صــدر‬\n      ‫تقريــر األدلــة اجلنائيــة رقــم (‪ )....-....‬لعام‪1433‬ه ـ بشــأن فحــص عينــة‬\n      ‫دم قياســية للمتهــم املذكــور واملتضمــن حتديــد األمنــاط الوراثيــة لعينــة‬\n      ‫الــدم القياســية رقــم (‪ )...‬ومت بحــث هــذه األمنــاط يف قاعــدة املعلومــات‬\n      ‫الوراثيــة ولــم يتبــن حتــى وقــت إعــداد التقريــر وجــود تطابــق جنائــي مــع‬\n      ‫أي قضايــا ســابقة ‪ .‬وقــد أســفر التحقيــق عــن اتهــام املذكــور بخطــف‬\n               ‫طفــل وفعــل فاحشــة اللــواط بــه وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n      ‫‪ .1‬مــا جــاء يف إقــرار املتهــم واملــدون علــى الصفحــة (‪ )6‬مــن محضــر‬\n      ‫االســتجواب املرفــق لفــة رقــم (‪ )9‬وتطابــق أقوالــه مــع أقــوال والــدة‬\n                                                                 ‫الطفــل املجنــي عليــه‪.‬‬\n      ‫‪ .2‬مــا جــاء يف محضــر االســتنطاق وتعــرف املجنــي عليــه علــى املتهــم‬\n      ‫واملــدون علــى الصفحــة رقــم (‪ )3‬مــن ملــف االســتجواب املرفــق لفــه رقــم‬\n                                                                                      ‫(‪.)9‬‬\n                     ‫‪ .3‬ما جاء يف تقرير الطب الشرعي املرفق لفه رقم(‪.)17/16‬‬\n          ‫وباالطالع على سوابقه لم يعثر له على سوابق مسجلة حتى تاريخه ‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املتهــم فعــل محرم ومعاقب عليه شــرعا وضربا‬\n      ‫مــن ضــروب اإلفســاد يف األرض علــى ســبيل الغلبــة والقهــر أطلــب إثبــات‬\n      ‫مــا أســند إليــه واحلكــم عليــه بحــد احلرابــة الــوارد يف اآليــة الكرميــة رقــم‬\n      ‫(‪ )33‬مــن ســورة املائــدة يف ضــوء قــرار هيئــة كبــار العلمــاء رقــم (‪)85‬‬\n      ‫وتاريــخ ‪1401/11/11‬هـ(علمــا بــأن احلــق اخلــاص مــازال قائمــا)‪ .‬فرفعــت‬\n      ‫اجللســة إلحضــار املدعــى عليــه ويف يــوم الســبت املوافق‪1434/06/17‬هـ‬\n      ‫حضــر املدعــي العــام واملدعــى عليــه باكســتاني اجلنســية مبوجــب‬\n      ‫اإلقامــة رقــم ‪ ........‬متــت تــاوة الدعــوى عليــه بواســطة املترجــم ‪........‬‬\n\n\n‫‪119‬‬\n\f‫باكســتاني اجلنســية حامــل اإلقامــة رقــم ‪ ......‬فأجــاب قائــا بواســطة‬\n‫املترجــم املذكــور مــا ذكــره املدعــي العــام يف دعــواه كلــه صحيــح‬\n‫فقــد خطفــت الطفــل البالــغ مــن العمــر خمــس ســنوات وتوجهــت بــه‬\n‫إلــى غرفتــي وفعلــت الفاحشــة بــه بإيــاج حيــث أوجلــت ذكــري يف دبــره‬\n‫هكــذا أجــاب فرفعــت اجللســة إلحضــار مترجــم آخــر ‪ .‬ويف يــوم الســبت‬\n‫املوافــق ‪1434/07/15‬ه ـ افتتحــت اجللســة الســاعة العاشــرة مبشــاركة‬\n‫فضيلــة الشــيخ ‪ .......‬القاضــي بهــذه احملكمــة خلفـ ًا لفضيلــة ‪ ....‬النتقالــه‬\n‫مــن هــذه احملكمــة ‪ ،‬وفيهــا حضــر املدعــي العــام ولــم يحضــر املدعــى‬\n‫عليــه مــن قبــل إدارة الســجون ‪ ،‬ثــم جــرى االطــاع علــى مــا ســبق ضبطــه‬\n‫وبعرضه على املدعي العام صادق عليه ‪ ،‬ثم جرى رفع اجللســة إلحضار‬\n‫املدعــى عليــه ‪ .‬ويف يــوم الســبت املوافــق ‪1434/07/29‬ه ـ افتتحــت‬\n‫اجللســة الســاعة العاشــرة وفيهــا حضــر املدعــي العــام واملدعــى عليــه ‪،‬‬\n‫وحضــر املترجــم املتعــاون مــع احملكمــة باكســتاني اجلنســية مبوجــب‬\n‫رخصــة اإلقامــة الصــادرة مــن جــوازات اخلــرج برقــم‪ ، ......‬ثــم جــرى‬\n‫عــرض مــا ســبق ضبطــه علــى املدعــى عليــه بواســطة املترجــم احلاضــر‬\n‫ا ‪ :‬مــا ذكرتــه يف جوابــي علــى الدعــوى باجللســة الســابقة‬       ‫فقــرر قائ ـ ً‬\n‫مختلــف عمــا مت تدوينــه ولعــل املترجــم لــم يفهــم كالمــي ‪ ،‬والصحيــح‬\n‫أن مــا جــاء يف دعــوى املدعــي العــام كلــه غيــر صحيــح فلــم أقــم بخطــف‬\n‫الطفــل وال فعــل الفاحشــة بــه بإيــاج وال بــدون إيــاج ولــم أتعــرض لــه ‪،‬‬\n‫وأنــا أعمــل يف قصــر األميــرة ‪ .....‬ووالــدة الطفــل املذكــور تعمــل خادمــة‬\n‫هنــاك وحتضــر معهــا ابنهــا وال أعلــم ســبب تقدمهــا بالشــكوى ضــدي‬\n‫ا‪:‬‬ ‫هكــذا قــرر ‪ ،‬وبســؤال املدعــي العــام هــل لديــك بينــة أجــاب قائ ـ ً‬\n‫لــدي إقــرار املدعــى عليــه ومــا يف أوراق املعاملــة أطلــب الرجــوع إليهــا‬\n\n\n                                                                                      ‫‪120‬‬\n\f      ‫هكــذا أجــاب ‪ ،‬فجــرى االطــاع علــى أوراق املعاملــة فوجدنــا بــن‬\n      ‫طياتهــا وعلــى الصحيفــة رقــم ‪ 6‬مــن ملــف االســتجواب املرفــق باملعاملــة‬\n      ‫لغــة رقــم ‪ 9‬إقــرارا للمدعــى عليــه تضمــن مــا نصــه ( أننــي شــاهدت‬\n      ‫الطفــل يلعــب يف ســور القصــر وقمــت بحملــه علــى يــدي وتوجهــت بــه إلــى‬\n      ‫الغرفــة وقمــت بفعــل الفاحشــة بــه مــرة واحــدة بإيــاج وقمــت بإرجاعــه‬\n      ‫مــرة أخــرى إلــى املجلــس اخلــاص بالنســاء ) انتهــى نصــه ‪ ،‬وبعرضــه علــى‬\n      ‫ا ‪ :‬صحيــح أننــي‬  ‫املدعــي عليــه بواســطة املترجــم وســؤاله عنــه أجــاب قائـ ً‬\n      ‫أقــررت بهــذا اإلقــرار ‪ ،‬ولكــن كان بســبب مــا تعرضــت لــه مــن ضــرب‬\n      ‫شــديد مــن قبــل العســكري ‪ ،‬ومــا جــاء يف هــذا اإلقــرار كلــه غيــر‬\n      ‫صحيــح هكــذا أجــاب ‪ ،‬فســألناه هــل لديــك بينــة علــى الضــرب فأجــاب‬\n      ‫ا ‪ :‬ليــس لــدي بينــة وال أعــرف مــن ضربنــي هكــذا أجــاب ‪ ،‬كمــا‬         ‫قائـ ً‬\n      ‫جــرى االطــاع علــى محضــر االســتنطاق املــدون علــى الصحيفــة رقــم ‪3‬‬\n      ‫مــن امللــف املرفــق رقــم ‪ 9‬فوجدنــاه تضمــن أنــه مت اســتنطاق الطفــل عمــا‬\n      ‫تعــرض لــه وأفــاد بــأن الباكســتاني ( املدعــى عليــه ) قــام بحملــه إلــى‬\n      ‫الغرفــة وخلــع مالبســه وأدخــل ذكــره فيــه مــن اخللــف مرتــن ‪ ،‬علم ـ ًا‬\n      ‫بأنــه جــرى إحضــار الباكســتاني لــه وأشــار بأنــه مــن قــام بهــذه الفعلــة‬\n      ‫انتهــى مضمونــه ‪ ،‬وبعرضــه علــى املدعــى عليــه بواســطة املترجــم أجــاب‬\n      ‫ا ‪ :‬أن والــدة الطفــل هــي مــن أمرتــه بقــول هــذا الــكالم هكــذا‬      ‫قائ ـ ً‬\n      ‫أجــاب ‪ ،‬فســألنا املدعــى عليــه هــل أنــت متــزوج أو ســبق لــك الــزواج‬\n      ‫ا ‪ :‬لــم يســبق لــي الــزواج هكــذا أجــاب ‪ ،‬كمــا جــرى‬        ‫فأجــاب قائ ـ ً‬\n      ‫االطــاع علــى تقريــر الفحــوص الوراثيــة رقــم (‪ )...-...‬فحــوص وراثيــة‬\n      ‫الصــادر مــن شــعبة املختبــرات اجلنائيــة واملرفــق باملعاملــة لفــة رقــم ‪22‬‬\n      ‫فوجدنــاه تضمــن أن مالبــس احلــدث جــرى فحصهــا باســتخدام تقنيــة‬\n\n\n‫‪121‬‬\n\f‫احلمــض النــووي وتبــن ســلبيتها للحمــض النــووي ممــا يتعــذر معــه إجــراء‬\n‫املقارنــة انتهــى مضمونهــا ‪ ،‬كمــا جــرى االطــاع علــى التقريــر الطبــي‬\n‫الشــرعي رقــم ‪ ....‬لعــام ‪1433‬ه ـ املرفــق باملعاملــة لفــة رقــم ‪20 -18‬‬\n‫فوجدنــاه تضمــن يف ( الــرأي ) مــا نصــه ( ممــا ســبق وتقــدم فإننــا نــرى‬\n‫اآلتــي ‪1 :‬ـ لــم يتبــن لنــا مــن الكشــف الطبــي الشــرعي علــى الطفــل ‪/‬‬\n‫‪ 4 ........‬أعــوام ‪ ......‬اجلنســية وجــود عالمــات العتــداء جســدي مثــل جــروح‬\n‫أو كدمــات أو ســحجات ظفريــة أو شــريطية أو عالمــات تربيــط علــى‬\n‫اليديــن أو الســاقني أو عالمــات ذات طبيعــة جنســية مثــل عالمــات مــص‬\n‫أو عــض عــدا وجــود تلــون بلــون أحمــر يف أعلــى الكتفــن قــد يشــير إلــى‬\n‫إمســاك ومحاولــة إعتــداء جنســي ‪2 .‬ـ تعــذر فحــص املالبــس باســتخدام‬\n‫تقنيــة الكشــافات والنظــارات اجلنائيــة للتحــري عــن التلوثــات أو البقــع‬\n‫املشــتبهة لقيــام والــدة الطفــل بتســليمها للشــرطة ‪ ،‬كمــا تعــذر أخــذ‬\n‫املســحات الالزمــة مــن أنحــاء اجلســم ومــن املنطقــة الشــرجية ـ للتحــري‬\n‫عــن املــواد واحليوانــات املنويــة إن وجــدت ليتــم فحصهــا يف مختــرات‬\n‫إدارة األدلــة اجلنائيــة ويف حــال إيجابيــة املســحات ميكــن مقارنتهــا‬\n‫باحلمــض النــووي للمتهــم ـ لقيــام والــدة الطفــل بغســل جســم الطفــل باملــاء‬\n‫والصابــون ومــادة مطهــرة عــن اآلثــار واملــواد املنويــة العالقــة باجلســم ‪.‬‬\n‫‪3‬ـ وبفحصــه موضعي ـ ًا مــن دبــر تبــن وجــود احمــرار وتــورم حــول فتحــة‬\n‫الشــرج وتشــققات مدمــاه عديــدة عنــد الســاعة ‪ 11‬والســاعة ‪ 7‬مــن‬\n‫مينــاء عقــارب الســاعة وهــي إصابيــة املنشــأ معاصــرة للواقعــة مضــى‬\n‫عليهــا أقــل مــن أربــع وعشــرين ســاعة مــن تاريــخ الكشــف الطبــي‬\n‫الشــرعي قــد تشــير إلــى محاولــة إيــاج مــن دبــر بجســم صلــب أيــا كان‬\n‫نوعــه ويجــوز حدوثهــا مــن مثــل عضــو ذكــري منتصــب لرجــل بالــغ أو‬\n\n\n                                                                                     ‫‪122‬‬\n\f      ‫مــا شــابهه ‪4 .‬ـ وجتــدر اإلشــارة إلــى أن املواقعــة اجلنســية بإيــاج كامــل‬\n      ‫مــن دبــر بجســم صلــب مثــل عضــو ذكــري منتصــب لرجــل بالــغ أو مــا‬\n      ‫شــابهه عنــد األطفــال غالبـ ًا مــا ينتــج عنــه جــرح رضــي يف فتحــة الشــرح‬\n      ‫يتفــاوت يف شــدته مــن جــرح رضــي ســطحي إلــى جــرح رضــي عميــق‬\n      ‫نــازف يســتدعي تدخــل طبــي جراحــي لعالجــه نظــر ًا لعــدم التناســب مــا‬\n      ‫بــن حجــم الشــرج الطفولــي والعضــو الذكــري املنتصــب لرجــل بالــغ ‪،‬‬\n      ‫كمــا أن اســتخدام مــواد مزجلــة أثنــاء محاولــة اإليــاج يقلــل مــن شــدة‬\n      ‫اإلصابــة وقــد ال يتــرك أثــر ًا إصابي ـ ًا ينــم عنــه ويف مثــل تلــك احلــاالت‬\n      ‫ميكــن الرجــوع إلــى نتائــج الفحوصــات املخبريــة للمالبــس ‪5 .‬ـ لــم يتبــن‬\n      ‫وجــود عالمــات لفعــل الفاحشــة املتكــرر بإتيانــه لواط ـ ًا بإيــاج مــن‬\n      ‫ُدبــر) انتهــى نصــه ‪ ،‬وباالطــاع علــى صحيفــة الســوابق املرفقــة باملعاملــة‬\n      ‫لفــة رقــم ‪ 46‬وجدناهــا تضمنــت عــدم تســجيل الســوابق بحقــه ‪ ،‬ثــم‬\n      ‫قررنــا رفــع اجللســة للتأمــل والنطــق باحلكــم إلــى يــوم الســبت املوافــق‬\n      ‫‪1434/8/13‬ه ـ ‪ .‬ويف املوعــد احملــدد افتتحــت اجللســة الســاعة احلاديــة‬\n      ‫عشــرة والربــع للتأخــر يف إحضــار الســجني مــن قبــل إدارة الســجون ‪،‬‬\n      ‫ويف هــذه اجللســة حضــر املدعــي العــام واملدعــى عليــه واملترجــم املتعــاون‬\n      ‫مــع احملكمــة ‪ ، .......‬املــدون هويتــه بضبطــه ‪ ،‬وبســؤال املدعــي العــام‬\n      ‫واملدعــى عليــه إن كان لديهمــا مــا يــودان إضافتــه علــى مــا ســبق قــرر‬\n      ‫كل منهمــا قائــا ليــس لــدي ســوى مــا ســبق هكــذا قــررا ‪ ،‬فقفلنــا‬\n      ‫بــاب املرافعــة ‪ ،‬وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ‪ ،‬ومبــا أن‬\n      ‫املدعــى عليــه أقــر يف املجلــس الشــرعي مبــا نســبه إليــه املدعــي العــام يف‬\n      ‫دعــواه ‪ ،‬ثــم رجــع وأنكــر صحــة إقــراره وادعــى وهــم املترجــم يف فهمــه‬\n      ‫ملــا أجــاب بــه ‪ ،‬وبنــاء علــى مــا جــاء يف إقــراره املــدون مضمونــه أعــاه‬\n\n\n‫‪123‬‬\n\f‫املتضمــن إقــراره بصحــة مــا نســب إليــه مــن فعــل فاحشــة اللــواط بإيــاج‬\n‫بالطفــل املذكــور ‪ ،‬وادعــى اإلكــراه وال بينــة لــه علــى ذلــك‪ ،‬ونظــرا‬\n‫لعــدم إمكانيــة اســتبيان حقيقــة مــا جــرى للطفــل ومــدى عالقــة املدعــى‬\n‫عليــه بــه ـ نفيــا أو إيجابــا ـ عــن طريــق التحاليــل والفحــوص الوراثيــة‬\n‫جلســد الطفــل ومالبســه نظــرا لســلبيتها للحمــض النــووي نتيجــة لغســلها‬\n‫مــن قبــل والــدة الطفــل ‪ ،‬وبنــاء علــى مــا جــاء يف التقريــر الطبــي الشــرعي‬\n‫املتضمــن يف نتيجتــه أن الطفــل يعانــي مــن آثــار يف دبــره قــد تشــير إلــى‬\n‫محاولــة إيــاج جلســم صلــب ‪ ،‬مــن املمكــن حدوثهــا مــن عضــو ذكــر‬\n‫بالــغ ‪ ،‬ولــم يذكــر بالطفــل عالمــات تــدل علــى اعتــداء جســدي مــن‬\n‫جــروح أو خــدوش ونحوهــا ‪ ،‬وألن مــا ســبق عرضــه مــن أدلــة املدعــي‬\n‫العــام قرائــن ال تثبــت اإلدانــة بهــا ‪ ،‬وإمنــا تتوجــه بهــا التهمــة للمدعــى‬\n‫عليــه ‪ ،‬ونظــرا إلــى إنــكار املدعــى عليــه أخيــرا ملــا أقــر بــه ســابقا يعتبــر‬\n‫شــبهة تقــدح يف صحــة إقــراره ‪ ،‬وبنــاء علــى أن احلــدود تــدرأ بالشــبهات‬\n‫لقولــه عليــه الصــاة والســام (ادرؤوا احلــدود بالشــبهات) ‪ ،‬ولــكل مــا‬\n‫تقــدم فقــد توجهــت التهمــة القويــة للمدعــى عليــه بفعــل فاحشــة اللــواط‬\n‫بطفــل ‪ ،‬وقررنــا مــا يلــي‪ :‬أوال‪ /‬رد دعــوى املدعــي العــام يف طلبــه إثبــات‬\n‫إدانــة املدعــى عليــه بخطــف الطفــل ورد دعــواه بطلــب إقامــة حــد احلرابــة‬\n‫عليــه لعــدم ثبــوت موجبهــا ‪ .‬ثانيــا ‪ /‬تعزيــر املدعــى عليــه لقــاء التهمــة‬\n‫املوجــه لــه وذلــك بســجنه ســنتان اعتبــارا مــن تاريــخ إيقافــه بســبب هــذه‬\n‫القضيــة وجلــده ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات بــن كل دفعــة‬\n‫وأخــرى عشــرة أيــام ‪ ،‬وقــدر كل دفعــة خمســون جلــدة ‪ ،‬ثالثــا‪ /‬نوصــي‬\n‫بإبعــاد املدعــى عليــه عــن اململكــة بعــد انتهــاء محكوميتــه اتقــاء لشــره‬\n‫‪ ،‬وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليــه قــرر املدعــى عليــه‬\n\n\n                                                                                          ‫‪124‬‬\n\f      ‫قناعتــه بــه ‪ ،‬وأمــا املدعــي العــام فقــرر رغبتــه يف اســتئناف احلكــم‬\n      ‫مســتعدا بتقــدمي الئحــة اعتراضيــة فأفهــم بأنــه ســيتم تســليمه نســخة‬\n      ‫مــن القــرار لتقــدمي الئحتــه االعتراضيــة عليــه خــال ثالثــن يومــا مــن‬\n      ‫تاريــخ هــذا اليــوم ‪ ،‬وأنــه إذا لــم يتقــدم باعتراضــه عليــه خــال املــدة‬\n      ‫فســيتم رفــع املعاملــة حملكمــة االســتئناف بــدون الئحتــه االعتراضيــة‬\n      ‫ففهــم ذلــك ‪ ،‬وختمــت اجللســة الســاعة احلاديــة عشــرة والنصــف ‪ ،‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                        ‫حــرر يف ‪ 1434/08/13‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/12/19‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة الواحــدة والنصــف وقــد وردتنــا املعاملــة مــن‬\n      ‫محكمــة االســتئناف بالريــاض وقــد همــش علــى ظهــر الصــك مبــا نصــه‬\n      ‫( تظهيــرات الدائــرة اجلزائيــة اخلماســية مبحكمــة االســتئناف بالريــاض‬\n      ‫‪ ،‬احلمــد هلل وحــده وبعــد ‪ :‬فقــد اطلعنــا علــى هــذا القــرار رقــم وتاريــخ‬\n      ‫‪1434/08/21‬ه ـ الصــادر مــن أصحــاب الفضيلــة قضــاة احملكمــة‬\n      ‫العامة بالرياض الشــيخ ‪ ....‬والشــيخ ‪ ....‬والشــيخ ‪ ....‬وأصدرنا القرار رقم‬\n      ‫وتاريــخ ‪1434/11/09‬ه ـ املتضمــن املصادقــة باألكثريــة علــى احلكــم‬\n      ‫‪ ،‬واهلل املوفــق ‪ .‬قاضــي اســتئناف ختمــه وتوقيعــه قاضــي اســتئناف‬\n      ‫ختمــه وتوقيعــه قاضــي اســتئناف ختمــه وتوقيعــه لــه وجهــة نظــر قاضــي‬\n      ‫اســتئناف ختمــه وتوقيعــه رئيــس الدائــرة ختمــه وتوقيعــه ) وكان ختــام‬\n      ‫هــذه اجللســة الســاعة الثانيــة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                   ‫محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/12/19‬ه ـ ‪.‬‬\n\n\n\n\n‫‪125‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":116,"source_page_end":125,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"735c3d30538eb0efdbc3815a34e829489d384c76319b1763312b5fedac47dd65","normalized_text_hash":"90217091df4bdf3452eed124b18856150d4ad4dca04da759cd97bae15b8cbf95","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p116-34301602"},{"id":"daef242e-dae0-57be-8cbc-b91ea9955cbd","document_type":"judgment","category":"judicial","subcategory":"general","title":"حرابة -لواط -خطف حدث -فعل فاحشة بالقوة مع حدث -شهادة شهود -تقرير طبيب شرعي -حمض نووي -سوابق - قتل تعزير ا -مالحظة تقرير عدم حاجة عرض املدعى عليه على مصحة نفسية لفهمه اخلطاب -رد حد احلرابة ومصادر السيارة .","document_number":"3455295","case_number":"3483544","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل كال من","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/3","year":"1434","subject":"حرابة -لواط -خطف حدث -فعل فاحشة بالقوة مع حدث -شهادة شهود -تقرير طبيب شرعي -حمض نووي -سوابق - قتل تعزير ا -مالحظة تقرير عدم حاجة عرض املدعى عليه على مصحة نفسية لفهمه اخلطاب -رد حد احلرابة ومصادر السيارة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3455295 :‬تاريخه‪1434/3/3 :‬هـ‬\n                   ‫رقم الدعوى‪3483544 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 341167635‬تاريخه‪1434/7/1:‬هـ‬\n\n\n‫حرابــة ‪ -‬لــواط ‪ -‬خطــف حــدث ‪ -‬فعــل فاحشــة بالقــوة مــع حــدث‬\n‫‪ -‬شــهادة شــهود ‪ -‬تقريــر طبيــب شــرعي ‪ -‬حمــض نــووي ‪ -‬ســوابق ‪-‬‬\n‫قتــل تعزيــر ًا ‪ -‬مالحظــة تقريــر عــدم حاجــة عــرض املدعــى عليــه علــى‬\n‫مصحــة نفســية لفهمــه اخلطــاب ‪ -‬رد حــد احلرابــة ومصــادر الســيارة ‪.‬‬\n\n\n\n\n‫‪ -1‬قــول اهلل تعالــى‪ « :‬إمنــا جــزاء الذيــن يحاربــون اهلل ورســوله ويســعون‬\n‫يف األرض فســادا أن يقتلــوا أو يصلبــوا أو تقطــع أيديهــم وأرجلهــم مــن‬\n                                     ‫خــاف أو ينفــوا مــن األرض‪« ..‬اآليــة‪.‬‬\n‫‪ -2‬قــول النبــي صلــى اهلل عليــه وعلــى آلــه وســلم « مــن وجدمتــوه يعمــل‬\n‫عمــل قــوم لــوط فاقتلــوا الفاعــل واملفعــول بــه « رواه الترمــذي (‪57/4‬‬\n‫ـ ـ ‪ )58‬وســن أبــي داوود (‪ 607/4‬ـ ـ ‪ )608‬وابــن ماج ــه (‪ )856/2‬والســن‬\n‫الكبــرى للبيهقــي (‪ )232/8‬ومسن ــد اإلمــام أحم ــد (‪ )300/1‬وســن الــدار‬\n‫قطنــي (‪ )124/3‬واحلاكــم يف مســتدركه (‪ )355/4‬والكامــل البــن‬\n‫عــدي (‪ )1768/5‬واألوســط البــن املنــذر (‪ )623/2‬واحمللــى البــن حــزم‬\n                                                                  ‫(‪.)383/11‬‬\n‫‪ -3‬قــول النبــي صلــى اهلل عليــه وســلم‪ »:‬ملعــون مــن عمــل عمــل قــوم‬\n                                                     ‫لــوط « رواه الترمــذي‪.‬‬\n‫‪ -4‬إجمــاع الصحابــة رضــوان اهلل عليهــم علــى قتــل اللوطــي وأن‬\n\n\n                                                                                  ‫‪126‬‬\n\f      ‫معصيتــه مــن أعظــم املعاصــي التــي يــرجت لهــا عــرش الرحمــن وأن اهلل‬\n      ‫تعالــى جمــع علــى أهلهــا مــن أنــواع العقوبــات مــا لــم ينــكل بــه أم ــة‬\n      ‫ســواهم وذلــك لعظــم مفســدة هــذه اجلرميــة أنظــر فتــاوى ابــن تيميــة‬\n      ‫(‪ 334/28‬ـ ـ ‪ )345‬والسياســة الشــرعية البــن تيميــة ص(‪ )52‬وزاد املعــاد‬\n                                                                 ‫البــن القي ــم (‪.)40/5‬‬\n      ‫‪ -5‬مــا هــو مقــرر لــدى احملققــن مــن أهــل العلــم أن مــن لــم يندفــع‬\n                                                    ‫فســاده إال بالق ــتل فإنــه يق ــتل‪.‬‬\n\n\n\n      ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بخطــف حــدث‬\n      ‫وفعــل فاحشــة قــوم لــوط بــه بالقــوة ومحاولــة خطــف حــدث آخــر والهــرب‬\n      ‫مــن رجــال األمــن وصــدم دوريــة أمنيــة وطلــب إثبــات مــا أســند إليــه‬\n      ‫واحلكــم عليــه بحــد احلرابــة حيــث تقــدم أحــد املواطنــن ببــاغ عــن‬\n      ‫محاولــة أحــد األشــخاص خطــف ابنــه ولكنــه فــر منــه ‪ ،‬ومبحاولــة‬\n      ‫العثــور علــى الســيارة مت العثــور عليهــا وبداخلهــا شــخص ميــارس اللــواط‬\n      ‫مــع حــدث ‪ ،‬حــاول األب اســتيقافه ولكنــه هــرب ‪ ،‬مت القبــض علــى‬\n      ‫املدعــى عليــه وتبــن وجــود عــدة ســوابق قضائيــة لــه ‪ ،‬أنكــر املدعــى‬\n      ‫عليــه الدعــوى ‪ ،‬أحضــر املدعــى العــام بينــة وهــم رجــال األمــن وأحــد‬\n      ‫املواطنــن والــد املجنــي عليــه األول ومت ســماع شــهادتهم ‪ ،‬مت االطــاع‬\n      ‫علــى التقريــر الطبــي وفحــص احلمــض النــووي ولوحــظ انطبــاق احلمــض‬\n      ‫النــووي مــن العينــة املرفوعــة مــن احلــدث املجنــي عليــه علــى املدعــى عليــه‬\n      ‫وأنــه مصــدر تلــك التلوثــات املنويــة ‪ ،‬حكمــت احملكمــة بق ــتل املدعــى‬\n      ‫عليــه تعزيــرا جــزاء لــه ‪ ،‬وبعرضــه عليهمــا قــرر املدعــي العــام وقــرر‬\n\n‫‪127‬‬\n\f‫املدعــى عليــه عــدم القناعــة فجــرى إفهامهمــا بتعليمــات االســتئناف‬\n‫‪ ،‬عــادت املعاملــة مــن محكمــة االســتئناف بعــدد مــن امللحوظــات مــن‬\n‫أبرزهــا طلــب التصريــح بشــأن طلــب املدعــي العــام إقامــة حــد احلرابــة‬\n‫والتحقــق مــن حالــة املدعــى عليــه النفســية وإجــراء الــازم حيــال طلــب‬\n‫املدعــي العــام مصــادرة الســيارة ‪ ،‬أجابــت الدائــرة بالتصريــح بــرد‬\n‫دعــوى املدعــي العــام طلبــه إقامــة حــد احلرابــة علــى املدعــى عليــه وطلبــه‬\n‫مصــادرة الســيارة اكتفــاء بعقوبــة القتــل عمــا بأصــل تداخــل العقوبــات‬\n‫و لئــا تســري العقوبــة علــى ورثتــه حــال تنفيــذ العقوبــة عليــه وأمــا عــن‬\n‫حالــة املدعــى عليــه النفســية فقــد ظهــر للدائــرة مــن خــال االســتجواب‬\n‫بأنــه عاقــل ومــدرك ويحســن اجلــواب والدفــاع وال يســوغ فتــح هــذا البــاب‬\n‫لئــا يكــون ذريعــة لتخلــص املجرمــن عــن جرائمهــم مبثــل هــذا الدفــع ‪،‬‬\n‫صــدق احلكــم مــن محكمــة االســتئناف ‪ ،‬صــدق احلكــم من احملكمة‬\n                                                                             ‫العليــا‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلدينــا نحــن القضــاة يف احملكمــة العامــة بحائــل‬\n‫كال مــن ‪...........‬و‪...........‬واملكلــف بشــرح فضيلــة الرئيــس املســاعد‬\n‫و‪ ...........‬القائــم بعمــل فضيلــة الشــيخ ‪...........‬الــذي يتمتــع بإجــازة عاديــة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بحائــل املســاعد برقــم ‪ 3483544‬وتاريــخ ‪ 1434/02/19‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34396101‬وتاريــخ ‪1434/2/17‬ه ـ ففــي يــوم الســبت‬\n‫املوافــق‪ 1434/02/23‬ه ـ افتتحــت اجللســة األولى الســاعة ‪12 : 00‬وفيها‬\n‫حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليــه ‪...........‬ســعودي‬\n\n                                                                                          ‫‪128‬‬\n\f      ‫مبوجــب الســجل املدنــي رقــم ‪...........‬وادعى املدعي العــام بدعوى محرره‬\n      ‫اآلتــي نصهــا « احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده‬\n      ‫بصفتــي مدعيـ ًا عامـ ًا بدائــرة االدعــاء العــام لفــرع الهيئــة مبنطقــة حائــل‬\n      ‫أدعــي علــى املذكــور أعــاه بتاريــخ‪1433/12/ 26‬ه ـ تقــدم املواطــن‪/‬‬\n      ‫‪...........‬ببــاغ للجهــات األمنيــة يفيــد فيــه بأنــه كان جالسـ ًا يف املســجد‬\n      ‫بعــد صــاة العصــر وورده اتصــال مــن أهلــه يفيدونــه بــأن ابنــه البالــغ مــن‬\n      ‫العمــر (‪ )15‬عامــا تعــرض حملاولــة خطــف فاجتــه للمنــزل وســأل ابنــه‬\n      ‫عمــا حــدث فأفــاد بأنــه كان ذاهب ـ ًا للتموينــات علــى قدميــه فوقــف‬\n      ‫عنــده صاحــب ســيارة مــن نــوع (‪ )........‬رقــم اللوحــة (‪ )...........‬وســأله عــن‬\n      ‫شــقق مفروشــة فقــام بوصــف الشــقق لــه فتحــرك ثــم عــاد إليــه ووقــف‬\n      ‫عنــده ونــزل وأمســك بيــده وقــام بســحبه يريــد إركابــه فدفعــه عنــه ثــم‬\n      ‫ذهــب ‪ -‬ثــم ركــب املبلــغ مــع ابنــه علــى الســيارة وقامــا بالبحــث عــن‬\n      ‫الســيارة ولــم يجداهــا ‪ -‬ثــم ذهــب االبــن لوحــده علــى الســيارة يبحــث‬\n      ‫عنهــا فأخبــر والــده بأنــه وجدهــا يف حــي ‪ ...........‬فذهــب املبلــغ ليــرى‬\n      ‫الســيارة وإذا هــي نفــس األوصــاف فوقفــا عنهــا بعيــدا ثــم نــزل علــى‬\n      ‫أقدامــه وإذا بهــا يف حالــة تشــغيل وبهــا شــخص معــه طفــل عــاري املالبــس‬\n      ‫يفعــل الفاحشــة بــه فطــرق عليــه زجــاج الســيارة فهــرب ومعــه الطفــل‬\n      ‫وأفــاد املبلــغ بــأن اإلضــاءة األماميــة لســيارة املدعــى عليــه مــن اجلهــة‬\n      ‫اليمنــى تالفــة‪ .‬وبســماع أقــوال املجنــي عليــه (‪ )...........‬أفــاد بأنــه كان‬\n      ‫ذاهبـ ًا للتموينــات بعــد صــاة العصــر مباشــرة وأثنــاء رجوعــه يف الطريــق‬\n      ‫أعتــرض لــه صاحــب ســيارة مــن نــوع (‪ )........‬رقــم اللوحــة(‪ )...........‬ووقــف‬\n      ‫عنــده وســأله عــن شــقق مفروشــة فوصــف لــه شــقق ‪...........‬فتحــرك ثــم‬\n      ‫وقــف عنــده مــرة أخــرى ونــزل وقــال لــه اركــب لتدلنــي علــى الشــقق‬\n\n\n‫‪129‬‬\n\f‫فرفــض املجنــي عليــه فأمســك بــه بالقــوة وســحبه فقــام املجنــي عليــه‬\n‫بدفعــه وهــرب إلــى منزلهــم وأبلــغ أهلــه ثــم ركــب مــع والــده للبحــث‬\n‫عــن الســيارة ولــم يعثــرا عليهــا ثــم رجعــا إلــى املنــزل ثــم أخــذ الســيارة‬\n‫وقــام بالبحــث لوحــده فوجدهــا بحــي ‪...........‬واقفــة بــأرض فضــاء فرجــع‬\n‫للمنــزل وأخبــر والــده بذلــك ثــم ذهبــا ســويا ونــزل والــده إلــى تلك الســيارة‬\n‫ثــم تفاجــأ بســرعة رجــوع الســيارة وهروبــه‪ .‬وباالطــاع علــى محضــر‬\n‫تنفيــذ املهمــة املتضمــن بأنــه أثنــاء حضــور الدوريــة األمنيــة للمبلــغ حضــر‬\n‫شــخص آخــر يفيــد باختفــاء ابــن أخيــه عنــد ذهابــه للتموينــات ويتوقــع‬\n‫بأنــه نفــس احلــدث الــذي شــاهده املبلــغ األول مــع صاحــب الســيارة ‪-‬‬\n‫وأثنــاء ذلــك حضــر شــخص يفيــد بأنــه حضــر لــه شــخص علــى ســيارة‬\n‫مــن نــوع (‪ ).......‬ويســأله عــن منــزل شــخص يدعــى (‪ )...........‬وأنــه مــر‬\n‫عليــه أكثــر مــن مــرة ‪ .‬وبســماع بــاغ عــم املجنــي عليــه املختطــف والبالــغ‬\n‫مــن العمــر(‪ )11‬عام ـ ًا بالتفصيــل أفــاد بأنــه اتصلــت عليــه زوجــة أخيــه‬\n‫تفيــد بــأن ابنهــا (‪ )...........‬خــرج إلــى التموينــات بحــي ‪...........‬ولــم يعــد‬\n‫مــن بعــد صــاة العصــر ‪ -‬فواجــه أكثــر مــن دوريــه وأبلغهــم مبــا حصــل ‪.‬‬\n‫وباالطــاع علــى محضــر تنفيــذ املهمــة املتضمــن بأنــه ورد تعميــم مبدئــي‬\n‫علــى ســيارة مــن نــوع (……‪ )..‬رقــم اللوحــة (‪ )...........‬وأنــه مت اختطــاف‬\n‫حــدث ومتــت مشــاهدة الســيارة أمــام أســواق ‪...........‬ومبتابعــة الســيارة الذ‬\n‫بالهــرب وقــام باالصطــدام بالدوريــة عــدة مــرات ثــم هــرب علــى أقدامــه‬\n‫ومتــت مالحقتــه فقــام املدعــى عليــه بالدخــول إلــى فيال حتت اإلنشــاء ومت‬\n‫إطــاق طلقــة ناريــة حتذيريــة ثــم قــام بالقفــز علــى عــدة منــازل حتــى مت‬\n‫القبــض عليــه بالشــارع املجــاور للمنــازل ومت العثــور علــى احلــدث (‪...........‬‬\n‫( وبســماع أقــوال املجنــي عليــه (‪ )...........‬أفــاد بأنــه ذهــب إلــى التموينــات‬\n\n\n                                                                                          ‫‪130‬‬\n\f      ‫بعــد صــاة العصــر ووقــف عنــده صاحــب ســيارة مــن نــوع (‪ )........‬مظللــة‬\n      ‫بشــكل خفيــف ونــزل وقــال لــه اركــب فهــرب عنــه وحلــق بــه وبعــد‬\n      ‫ســقوط املجنــي عليــه علــى األرض أخــذه واركبــه بالســيارة وحتــرك بــه‬\n      ‫إلــى داخــل احلــي ووقــف يف مــكان فضــاء وقــام بضربــه ويقــول لــه (نــزل‬\n      ‫مالبســك) فأنزلهــا وفعــل بــه الفاحشــة حيــث ادخــل ذكــره وفجــأة طــرق‬\n      ‫الزجــاج شــخص فتحــرك املدعــى عليــه وهــرب بســرعة واجتــه إلــى حــي‬\n      ‫‪...........‬ووقــف يف مــكان صحــراوي ثــم فعــل بــه الفاحشــة داخــل الســيارة‬\n      ‫قبــل املغــرب إلــى قــرب صــاة العشــاء وجــرد احلــدث مــن مالبســه وقــام‬\n      ‫بكيــه بســيجارة ثــم طلــب منــه أن يدخــن معــه ‪ .‬ومبعاينــة ســيارة املدعــى‬\n      ‫عليــه مــن نــوع (……‪ ).‬رقــم اللوحــة ‪ ...........‬اتضــح أنهــا مضللــة اجلوانــب‬\n      ‫وبهــا كســر يف األنــوار األماميــة اليمنــى واليســرى‪ -‬ومبعاينــة الســيارة‬\n      ‫مــن الداخــل عثــر علــى ثــوب وشــماغ ومت رفــع اآلثــار التــي ميكــن أن‬\n                                                                  ‫يســتفاد منهــا لفحصهــا‪.‬‬\n      ‫وبســماع شــهادة املواطــن ‪.........../‬أفــاد بأنــه بعــد صــاة العصــر حضــر‬\n      ‫لــه صاحــب ســيارة مــن نــوع (‪ )......‬لــم يأخــذ رقــم اللوحــة حيــث وقــف‬\n      ‫أمــام منزلهــم وســأله عــن منــزل شــخص يدعــى (‪ )...........‬فلــم يــرد عليــه‬\n      ‫ثــم كــرر عليــه الســؤال ثــم حتــرك ‪ -‬ثــم رجــع لــه مــرة أخــرى وكان‬\n      ‫يســير علــى مهلــة ثــم ثالثــة ثــم الرابعــة أتــى مســرع ًا ‪ -‬وأفــاد املواطــن بأنــه‬\n      ‫يســتطيع التعــرف علــى الســيارة فقــط أمــا قائدهــا فــا يســتطيع التعــرف‬\n             ‫عليــه ‪ .‬جــرى بعــث املجنــي عليــه للطــب الشــرعي للكشــف عليــه‪.‬‬\n      ‫مت ســحب عينــة مــن املدعــى عليــه لتحليلهــا عــن املــواد املســكر واملخدرة‬\n      ‫‪ .‬جــرى بعــث مالبــس املجنــي لألدلــة اجلنائيــة لفحصهــا ‪ .‬مت رفــع آثــار مــن‬\n                                              ‫مرتبــة الســيارة مــن قبــل األدلــة اجلنائيــة‪.‬‬\n\n\n‫‪131‬‬\n\f‫وباستشــمام املدعــى عليــه لــم يتضــح انبعــاث رائحــة املســكر مــن‬\n‫أنفاســه‪ .‬وبعــرض ســيارة املدعــى عليــه علــى الشــاهد ‪ ...........‬اســتطاع‬\n‫التعــرف عليهــا متامـ ًا مؤكــد ًا وجازمـ ًا بأنهــا نفــس الســيارة وبهــا كســر‬\n‫يف اإلضــاءة األماميــة ‪ .‬وبعــرض املدعــى عليــه وســيارته علــى املبلــغ‬\n‫وابنــه (املجنــي عليــه) اســتطاعا التعــرف عليــه وعلــى ســيارته مؤكديــن‬\n‫وجازمــن بأنــه قائــد الســيارة ‪ ....‬رقــم اللوحــة‪ ............‬وهــو مــن كان‬\n‫داخلهــا ‪ .‬مت إيقافــه اســتناد ًا للقــرار الــوزاري (‪ )1900‬وباســتجوابه أقــر‬\n‫بــأن الســيارة مــن نــوع ‪ .......‬رقــم اللوحــة ‪ ...........‬عائــده لــه ‪ .‬ومبواجهتــه‬\n‫مبحضــر التعــرف أفــاد بأنــه وقــف عنــد أحدهمــا عنــد التموينــات‬\n‫القريبــة مــن إدارة املــرور وســأله عــن منــزل شــخص يدعــى (‪)...........‬‬\n‫فهــرب احلــدث أمــا األخــر فلــم يشــاهدهم إطالقــا يف حياتــه‪ .‬كمــا أفــاد‬\n‫بأنــه هــرب مــن الدوريــات األمنيــة خوفـ ًا منهــم حيــث أن بينــه وبــن أحــد‬\n‫أفــراد الدوريــة خــاف ‪،‬وأنكــر خــاف ذلــك‪ .‬وبإعــادة اســتجوابه أفــاد‬\n‫بــأن الدوريــة األمنيــة هــي التــي صدمتــه مــن األمــام حينمــا كان واقفــا‬\n‫عنــد الصرافــة ‪ -‬كمــا أفــاد بأنــه يف تاريــخ ‪1433/12/26‬ه ـ كان يف‬\n‫منزلــه مــن الســاعة الثالثــة عصــر ًا وخــرج بعــد املغــرب للصرافــة التــي‬\n‫تقــع بجــوار فنــدق(‪ )......................‬وأصــر علــى بقيــة أقوالــه الســابقة ‪.‬‬\n‫وقــد أثبــت التقريــر الطبــي الشــرعي رقم‪...........‬لســنة ‪1433‬ه ـ الصــادر‬\n‫مــن إدارة الطــب الشــرعي …‪ ..‬بأنــه بفحــص ظاهــر جســم املجنــي عليــه‬\n‫(‪ )...........‬اتضح وجود عالمات عنف بعامة جســمه تشــير إلى اســتخدام‬\n‫القــوة يف إجبــار املجنــي عليــه علــى فعــل الفاحشــة بــه ‪ .‬وبفحــص منطقــة‬\n‫الشــرج شــوهد احمــرار شــديد حــول فتحــة الشــرج ووجــود ســائل مصفــر‬\n‫اللــون شــبه متجلــط بــن االليتــن وحــول وداخــل الشــرج ورفعــت مســحات‬\n\n\n                                                                                           ‫‪132‬‬\n\f      ‫منــه لفحصهــا ‪ -‬كمــا تبــن وجــود شــق شــرجي ســطحي حديــث بفتحــة‬\n      ‫الشــرج‪ -‬كمــا تبــن وجــود جــرح تهتكــي يقــع عمــودي علــى محيــط‬\n      ‫فتحــة الشــرج وهــو جــرح دامــي ومتعــرج ومحــاط بتكــدم‪ .‬كمــا لــم‬\n      ‫يتبــن ثمــة قطــوع أو متزقــات أو ثقــوب مبالبــس املجني عليــه‪ .‬كما وردت‬\n      ‫نتيجــة فحــص املســحات املأخــوذة مــن داخــل الشــرج وخارجــه بالتقريــر‬\n      ‫رقــم ‪...........‬بإيجابيــة فحــص املســحات عــن التلوثــات املنويــة كمــا ثبــت‬\n      ‫بــأن البصمــة الوراثيــة لهــذه التلوثــات املنويــة قــد تطابقــت مــع البصمــة‬\n                                                           ‫الوراثيــة للمدعــى عليــه ‪.‬‬\n      ‫كمــا بلغــت قيمــة تلفيــات الدوريــة األمنيــة تســعة آالف وتســعمائة‬\n      ‫وســتون ريــاال ‪ .‬وقــد أســفر التحقيــق معــه عــن اتهامــه بخطــف حــدث‬\n      ‫وفعــل فاحشــة اللــواط بــه بالقــوة ومحاولــة خطــف حــدث أخــر والهــرب‬\n      ‫مــن رجــال األمــن وصــدم دوريــة أمنيــة واملجــرم شــرعاً‪ .‬وذلــك لألدلــة‬\n                                                                   ‫والقرائــن التاليــة‪:‬‬\n      ‫‪ -1‬مــا جــاء يف أقوالــه املنــوه عنهــا واملدونــة على الصفحــة(‪)1-2-3-4-5‬‬\n      ‫مــن دفتــر التحقيــق املرفــق لفــة رقــم(‪ - 2 )24‬مــا جــاء يف شــهادة‬\n      ‫الشــهود املنــوه عنهــا واملدونــة علــى الصفحــة (‪ )10‬مــن دفتــر تقريــر‬\n      ‫األحــوال األمنيــة املرفــق لفــة رقــم(‪ )1‬والصفحــة (‪ )1-2‬مــن دفتــر ملــف‬\n      ‫اســتكمال إجــراءات االســتدالل املرفــق لفــة رقــم (‪ -3 )3‬مــا جــاء يف‬\n      ‫محضــر تنفيــذ املهمــة املرفــق لفــة رقــم (‪ -4 )4-5-12‬مــا جــاء يف تقريــر‬\n      ‫الطــب الشــرعي وتقريــر الفحــوص الوراثيــة املرفــق لفــة رقــم (‪ -5 )38‬مــا‬\n      ‫جــاء يف محاضــر التعــرف املنــوه عنهــا واملدونــة علــى الصفحــة (‪ )16‬مــن‬\n      ‫دفتــر تقريــر األحــوال األمنيــة املرفــق لفــة رقــم (‪ )1‬والصفحــة (‪)2-3‬‬\n      ‫مــن دفتــر ملــف اســتكمال إجــراءات االســتدالل املرفــق لفــة رقــم(‪3‬‬\n\n\n‫‪133‬‬\n\f‫) ‪ - 6‬مــا جــاء يف محضــر املعاينــة املنــوه عنــه واملــدون علــى الصفحــة‬\n‫(‪ )2-3‬مــن دفتــر تقريــر األحــوال األمنيــة املرفــق لفــة رقــم(‪. (1‬وحيــث‬\n‫إن مــا أقــدم عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا وهــو محصــن‬\n‫يعــد ضرب ـ ًا مــن ضــروب احلرابــة واإلفســاد يف األرض وهــو فعــل محــرم‬\n‫ومعاقــب عليــه شــرع ًا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n‫بحــد احلرابــة الــوارد يف اآليــة رقــم (‪ )33‬مــن ســورة املائــدة علــى ضــوء‬\n‫قــرار هيئــة كبــار العلمــاء رقــم (‪ )85‬بتاريــخ ‪1401/11/11‬ه ــومصادرة‬\n‫ســيارته املســتخدمة باجلرميــة (علم ـ ًا بــأن احلــق اخلــاص مــازال قائم ـاً)‬\n                                     ‫وبــاهلل التوفيــق ‪ .‬املدعــي العــام ‪...........‬‬\n‫وبعــرض ذلــك علــى املدعــى عليــه ‪ :‬أجــاب وهــو يفهم اخلطاب جيــدا بقوله‬\n‫مــا ذكــره املدعــي العــام بدعــواه كلــه غيــر صحيــح جملــة وتفصيــا‬\n‫هــذه إجابتــي ثــم جــرى ســؤاله عــن الســوابق التــي ذكرهــا املدعــي العــام‬\n‫فقــال كل الســوابق التــي ذكرهــا املدعــي العــام غيــر صحيحــة عــدا‬\n‫املخــدرات فهــي صحيحــة ثــم جــرى ســؤاله عــن نــوع الســيارة التــي معــه‬\n‫فأجــاب بقولــه ســيارتي هــي مــن نــوع ‪ ......‬ولونهــا ‪ ........‬فجــرى ســؤاله هــل‬\n‫هــو متــزوج وهــل لديــه أوالد وهــل هــو يدخــن أم ال فقــال أنــا متــزوج منــذ‬\n‫خمــس ســنوات وليــس لــدي أوالد وأشــرب الدخــان ثــم جــرى ســؤاله هــل‬\n‫هــو موظــف فقــال أنــا علــى وظيفــة ســائق ومراســل لــدى أمانــة منطقــة‬\n‫‪ ......‬علــى املرتبــة الثالثــة والثالثــن ولــي يف اخلدمــة ثمــان ســنوات ومت‬\n‫توجيــه هــذه األســئلة للمدعــى عليــه وقــد أجــاب عليهــا بهــذه اإلجابــات‬\n‫الواضحــة املفهومــة وقــد كان يفهــم كل ســؤال يوجــه إليــه وقــد مت‬\n‫الرجــوع إلــى املعاملــة فوجدنــا إجاباتــه بخصــوص الســيارة والوظيفــة‬\n‫واحلالــة االجتماعيــة مطابقــة ملــا جــاء يف إجاباتــه وللرجــوع للمعاملــة‬\n\n\n                                                                                         ‫‪134‬‬\n\f      ‫ورصــد مــا فيهــا مــن بيانــات رفعــت اجللســة األولــى وتأجلــت إلــى يــوم‬\n      ‫الســبت املوافــق ‪1434/2/30‬ه ـ الســاعة العاشــرة ومت إغالقهــا الســاعة‬\n      ‫‪ 12: 45‬وعليــه جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                  ‫نبينــا محمــد وآلــه وصحبــه أجمعــن حــرر يف ‪1434/2/23‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلدينــا نحــن القضــاة يف احملكمــة العامــة بحائــل‬\n      ‫كال مــن ‪...........‬و‪................‬و‪ ...........‬القائــم بعمــل فضيلــة الشــيخ‬\n      ‫‪......................‬الــذي يتمتــع بإجــازة عاديــة واملكلفــن مبوجــب شــرح‬\n      ‫فضيلــة الرئيــس املســاعد رقــم ‪ 34369794‬وتاريــخ ‪1434/02/13‬ه ـ‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بحائــل املســاعد برقــم ‪ 3483544‬وتاريــخ ‪1434/02/19‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 34396101‬وتاريــخ ‪1434/2/17‬ه ـ ففــي يــوم الســبت‬\n      ‫املوافق‪1434/02/30‬ه ـ افتتحــت اجللســة الثالثــة الســاعة ‪ 11 : 45‬وفيهــا‬\n      ‫حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليــه وبالرجــوع إلــى‬\n      ‫املعاملــة لرصــد بينــات املدعــي العــام وجــد علــى اللفــة رقــم (‪ )24‬دفتــر‬\n      ‫حتقيــق حيــث وجــد علــى الصفحــات ( ‪ ) 5 - 1‬اســتجواب للمدعــى عليــه‬\n      ‫ونــص احلاجــة منــه « س‪ /‬قــدم نفســك جلهــة التحقيــق ج‪ /‬االســم‬\n      ‫‪ ......................‬ســعودي عمــري (‪ )35‬ســنة ومتــزوج وأعمــل موظــف خاص‬\n      ‫وأســكن يف حائل بحي ‪...........‬متعلم ابتدائي س‪ /‬أنت متهم باختطاف‬\n      ‫حــدث وفعــل فاحشــة اللــواط فيــه بالقــوة وكذلــك محاولــة خطــف حدث‬\n      ‫آخــر فمــا قولــك وصــدم دوريــة أمنيــة والهــروب عنهــا فمــا قولــك ؟ ج‪/‬‬\n      ‫غيــر صحيــح بــل كنــت واقــف عنــد الصرافــة وصدمتنــي الدوريــة مــن‬\n      ‫األمام س‪ /‬ملاذا قاموا بصدمك ؟ ج‪ /‬ال أعلم س‪ /‬أفاد املواطن ‪...........‬‬\n      ‫بأنــه شــاهدك متوقــف بســيارتك بأحــد األحيــاء وأنــت تفعــل الفاحشــة‬\n\n\n‫‪135‬‬\n\f‫بحــدث ثــم هربــت فمــا قولــك ؟ ج‪ /‬غيــر صحيــح س‪ /‬إذا كان غيــر‬\n‫صحيــح فلمــاذا يفتــري عليــك ؟ ج‪ /‬ال أدري س‪ /‬أفــاد احلــدث ‪...........‬‬\n‫بأنــك اختطفتــه وفعلــت بــه الفاحشــة بالســيارة وقمــت بكيــه بســيجارة‬\n‫وطلبــت منــه أيضـ ًا أن يدخــن فمــا قولــك ؟ ج‪ /‬غيــر صحيــح س‪ /‬ملــن تعــود‬\n‫الســيارة مــن نــوع ‪ ......‬رقــم اللوحــة (‪ )...............‬؟ ج‪ /‬تعـ ــود لــي س‪ /‬لقــد‬\n‫اســتطاعا املجنــي عليهمــا وذويهــم التعــرف عليــك وعلــى ســيارتك فمــا‬\n‫قولــك ؟ ج‪ /‬أمــا األحــداث فقــد وقفــت عنــد أحدهمــا عنــد البقالــة‬\n‫القريبــة مــن املــرور وســألت عــن منــزل ‪...........‬ثــم هــرب أما اآلخــر وذويهم‬\n‫فلــم أشــاهدهم إطالقــا يف حياتــي س‪ /‬مــن هــو ‪...........‬الــذي تبحــث عنــه‬\n‫؟ ج‪ /‬هــو صديقــي وأردت زيارتــه س‪ /‬ملــاذا لــم تتصــل عليــه ؟ ج‪ /‬جوالــه‬\n‫مقـف ــل س‪ /‬ملــاذا قمــت بالهــرب مــن الدوريــات ؟ ج‪ /‬خفــت منهــم س‪ /‬هــل‬\n‫قمــت بعمــل شــيء حتــى تخــاف منــه ؟ ج‪ /‬كال ولكــن بينــي وبــن أحــد‬\n‫أفــراد الدوريــة خــاف فهربــت خوفــا منــه س‪ /‬هــذا كالم غيــر منطقــي‬\n‫وأنصحــك بقــول احلقيقــة ؟ ج‪ /‬مــا قلتــه هــو احلقيقــة س‪ /‬هــل تتعاطــى‬\n‫شــيء مــن املــواد املســكرة واملخــدرة ؟ ج‪ /‬كال س‪ /‬لقــد أفــاد عــم‬\n‫احلــدث ‪ ...........‬بأنــه خــرج إلــى البقالــة بحــي ‪...........‬ولــم يع ــد مــن بعــد‬\n‫صــاة العصــر وأنــه أبلــغ العمليــات بذلــك فوجــدت الدوريــات احلــدث‬\n‫‪...........‬بســيارتك فعلــى مــا يــدل ذلــك ؟ج‪ /‬غيــر صحيــح س‪ /‬احلــي الــذي‬\n‫خطــف منــه احلــدث ‪...........‬هــو نفــس احلــي الــذي كنــت تبحــث عــن منزل‬\n‫صديقــك ‪...........‬فيــه فيــدل علــى أنــك أنــت مــن قمــت بخطــف احلــدث‬\n‫فمــا قولــك ؟ ج‪ /‬نعــم صحيــح ولكــن لــم أخطــف أحــدا س‪ /‬هــل لديــك‬\n‫أقــوال أخــرى ؟ ج‪ /‬كال س‪ /‬هــل لديــك ســوابق ؟ ج‪ /‬نعــم صحيــح‬\n‫مخــدرات س‪ /‬هــل تصــادق علــى أقوالــك ؟ج‪ /‬نع ــم وقــد أقفــل احملضــر‬\n\n\n                                                                                            ‫‪136‬‬\n\f      ‫يف وقتــه وحينــه وذيــل بتوقيــع املدعــى عليــه وكاتــب الضبــط واحملقــق‬\n      ‫كمــا وجــد علــى الصفحــة رقــم ( ‪ 4‬و ‪ ) 5‬محضــر إعــادة اســتجواب‬\n      ‫للمدعى عليه ونص احلاجة منه س‪ /‬أين كنت بتاريخ ‪1433/12/26‬هـ‬\n      ‫مــن الســاعة الثالثــة عصــرا حتــى الســاعة الثامنــة مســاءا ؟ ج‪ /‬كنــت يف‬\n      ‫املنــزل وخرجــت بعــد املغــرب للصرافــة التــي عنــد فنــدق ‪...........‬س‪ /‬مــن‬\n      ‫كان معــك يف املنــزل أثنــاء تواجــدك ؟ ج‪ /‬زوجتــي فقــط س‪ /‬لقــد‬\n      ‫اســتطاع احلدثــن التعــرف عليــك فمــاذا تبــرر ذلــك ؟ ج‪ /‬غيــر صحيــح‬\n      ‫لقــد مت عرضــي عليهــم ولــم يســتطيع التعــرف علــي « أ‪ .‬ه ـ نــص احلاجــة‬\n      ‫منــه كمــا وجــد علــى اللفــة رقــم (‪ )1‬دفتــر تقريــر األحــوال األمنيــة‬\n      ‫املوح ــد حيــث وجــد علــى الصفحــة رقــم (‪ « )10‬شــهادة ‪...........‬أفيدكــم‬\n      ‫أننــي بقيــت باملســجد بعــد صــاة العصــر فوردنــي اتصــال مــن أهلــي‬\n      ‫مفــاده أن ‪...........‬حــاول شــخص خطفــه واجتهــت إلــى املنــزل بعــد نصــف‬\n      ‫ســاعة مــن صــاة العصــر ووجــدت ‪ .......‬وســألته عمــا حــدث فأفــاد بأنــه‬\n      ‫ذاهــب للتموينــات علــى أقدامــه ووقــف عنــده صاحــب ســيارة ‪ .......‬رقــم‬\n      ‫اللوحــة ( ‪ )...........‬وهــو يف طريقــه إلــى املنــزل وســأله عــن شــقق مفروشــة‬\n      ‫ووصــف لــه ثــم حتــرك ثــم عــاد لــه ووقــف عنــده ونــزل وأمســك بيــده‬\n      ‫وســحبه يريــد إركابــه فدفعــه عنــه وحتــرك ثــم أنــا بــدوري حتركــت‬\n      ‫أنــا وابنــي علــى ســيارتي للبحــث عــن الســيارة يف احلــي ولــم أجدهــا ثــم‬\n      ‫ذهــب ابنــي علــى الســيارة لوحــده يبحــث عنهــا فأفادنــي أنــه وجدهــا‬\n      ‫واقفــة بحــي ‪...........‬بشــارع وعــدت معــه علــى الســيارة ودلنــي عليهــا وهــي‬\n      ‫نفــس املواصفــات ومض ــللة ووقفنــا عنهــا بعيــدا ثــم نزلــت علــى أقدامــي‬\n      ‫للســيارة وإذا بحالــة تشــغيل وقربــت مــن الزجــاج فــإذا بهــا شــخص يحتمل‬\n      ‫أننــي أعرفــه عنــد مشــاهدته عمــره (‪ )27‬عــام تقريبــا ومنــزل مالبســه‬\n\n\n‫‪137‬‬\n\f‫ومعــه طفــل عــاري مــن املالبــس يفعــل بــه الفاحشــة وطرقــت الزجــاج‬\n‫بيــدي وانتبــه ورجــع بهــا للخلــف بســرعة ثــم حتــرك لألمــام وهــرب ومعــه‬\n‫الطفــل س‪ /‬هــل تعــرف الطفــل وكــم عمــره ؟ ج‪ /‬لــم أمتكــن مــن وجهــه‬\n‫وعمــره أكبــر مــن عشــر ســنوات تقريبــا أمــا مواصفــات الشــخص‬\n‫اخلاطــف علــى ذقنــه شــعر خفيــف وشــيب ولــم أمتكــن مــن رؤيتــه متامــا‬\n‫س‪ /‬هــل تســتطيع التعــرف علــى الســيارة ؟ نعــم ويوجــد بهــا االســطب‬\n‫األمامــي األميــن تالــف « أ‪.‬ه ـ كمــا وجــد علــى اللفــة رقــم (‪ )3‬ملــف‬\n‫اســتكمال محاضــر إجــراءات االســتدالل حيــث وجــد علــى الصفحــة‬\n‫رقــم ( ‪ ) 2 - 1‬شــهادة‪...........‬اآلتي نصهــا ‪ :‬س‪ /‬أعطــي معلومــات‬\n‫شــخصية عــن نفســك ج‪ /‬االســم ‪ .............../‬العمــر ‪ )18( /‬عــام املهنــة ‪/‬‬\n‫طالــب احلالــة االجتماعيــة ‪ /‬أعــزب احلالــة التعليميــة ‪ /‬متعلــم الســكن ‪/‬‬\n‫حــي ‪...........‬رقــم الســجل املدنــي (‪)..........‬مصدرهــا ‪ /‬حائــل تاريخهــا‬\n‫‪1432/04/18‬ه ـ جــوال (‪ )...........‬س‪ /‬أفدنــي عمــا لديــك مــن معلومــات‬\n‫ج‪ /‬أفيدكــم أنــه بعــد صــاة العصــر حضــر لــي صاحــب ســيارة ‪ ......‬لــم‬\n‫آخــذ رقــم لوحتهــا حيــث وقــف أمــام منزلنــا عندما كنت واقــف ونظرني‬\n‫ويقــول أيــن بيت‪...........‬ولــم أرد عليــه وكــرر الســؤال ثــم حتــرك ثــم رجــع‬\n‫لــي مــرة ثانيــة مــع الشــارع حيــث ميشــي علــى مهلــه ثــم ثالثــة ورابعــة أتــى‬\n‫مســرعا س‪ /‬هــل تكلــم معــك بشــيء ج‪ /‬كال فقــط ســؤال عــن بيــت‬\n‫‪...........‬س‪ /‬هــل تعــرض لــك بــأذى ج‪ /‬كال س‪ /‬هــل ترغــب مواصلــة‬\n‫دعــواك ضــده ؟ ج‪ /‬كال س‪ /‬هــل تســتطيع التعــرف عليــه وعلى الســيارة‬\n‫؟ ج‪ /‬ال أســتطيع التعــرف علــى الســيارة أمــا الشــخص فلــم أمتكــن مــن‬\n‫وجهــه حيــث كنــت غيــر منتبــه لــه وال أرغــب مقابلتــه نهائيــا س‪ /‬هــل‬\n‫تصــادق علــى أقوالــك ج‪ /‬نعــم وقــد ذيــل بتوقيــع احملقــق واملســتجوب «‬\n\n\n                                                                                         ‫‪138‬‬\n\f      ‫أ‪.‬ه ـ كمــا وجــد علــى اللفــة رقــم (‪ 4‬و ‪ )5‬محضــر تنفيــذ مهمــة وتســليمها‬\n      ‫جلهــة االختصــاص برقــم ‪...........‬يف يــوم األحــد ‪1433/12/26‬ه ـ يتضمــن‬\n      ‫بــاغ مــن ‪...........‬و‪...........‬والشــاهد ‪ ...........‬واحلــدث ‪ ...........‬واحلــدث‬\n      ‫‪...........‬نــوع الســيارة التــي لهــا عالقــة باحلالــة ‪ )...........( ....‬وملخــص احلالة‬\n      ‫نحيــل إليكــم املدعــن املوضــح أســمها أعــاه حيث يدعــي املدعي األول‬\n      ‫علــى صاحــب ‪ ....‬املوضــح بياناتــه حيــث حــاول خطــف ابنــه ومتكــن ابنــه‬\n      ‫مــن الفــرار وبعــد ذلــك قــام بالبحــث عــن الســيارة ووجدهــا داخــل احلــي‬\n      ‫متوقفــة وبعــد ترجلــه شــاهد القائــد معــه حــدث داخــل ســيارة ‪ .....‬بــدون‬\n      ‫مالبــس ويفعــل الفاحشــة باحلــدث داخــل الســيارة علمــا بــأن الســيارة‬\n      ‫كانــت بوضــع التشــغيل ومقف ــلة األبــواب وحــاول املدعــي كســر الزجاج‬\n      ‫بعصــى خشــبية وبعــده ارتكــب الفــرار الشــخص دون كســر زجــاج‬\n      ‫الســيارة وأثنــاء مقابلــة الدوريــة للمدعــي األول حضــر املدعــي الثانــي‬\n      ‫حيــث يفيــد عــن اختفــاء ابــن أخيــه عنــد ذهابــه للبقالــة واحتمــال كبيــر‬\n      ‫أنــه يكــون نفــس احلــادث الــذي شــاهده املدعــي األول مــع صاحــب‬\n      ‫الســيارة وأثنــاء وجــود الدوريــة مــع املدعــن حضــر شــخص يفيــد بأنــه‬\n      ‫حضــر لــه شــخص علــى ســيارة مــن نــوع ‪ .....‬املوضــح بياناته أعاله ويســأل‬\n      ‫عــن منــزل شــخص يدعــى ‪...........‬وأفــاد أنــه دار أكثــر مــن مــرة كمــا‬\n      ‫وجــد علــى اللفــة رقــم (‪ )12‬محضــر تنفيــذ مهمــة برقــم ‪...........‬يف‬\n      ‫‪1433/12/26‬ه ـ يتضمــن القبــض علــى ســيارة ‪ )........... ( .......‬وملخــص‬\n      ‫احلالــة نحيــل لكــم الســيارة والشــخص املوضــح حيــث ورد بــاغ تعميــم‬\n      ‫مبدئــي مــن قبلكــم علــى الســيارة املوضحــة اختطــاف حــدث ومت‬\n      ‫مشــاهدة الســيارة أمــام ‪...........‬وقــام بالهــروب وقــام بصــدم الدوريــة عــدة‬\n      ‫مــرات وقــام بالهــروب علــى األقــدام ومتابعتــه ودخوله فيال حتت اإلنشــاء‬\n\n\n‫‪139‬‬\n\f‫ومت إطــاق طلقــة حتذيريــة وقــام بالقفــز لعــدة منــازل حتــى مت القبــض‬\n‫عليــه بالشــارع املجــاور للمنــازل وتعــرض إلصابــة بســيطة جــراء القفــز‬\n‫الــذي قــام بــه املجنــي وأثنــاء القبــض مت العثــور علــى احلــدث املوضــح وهــو‬\n‫‪...........‬وهــو بصحــة جيــدة علمــا بأنــه مت نقــل اجلانــي للطــوارئ لتلقــي‬\n‫العــاج ومت طلــب دوريــة املــرور باملوقــع لتخطيــط احلــادث ومت إحالــة‬\n‫احلــدث برفقــة أخيــه املوضــح اســمه ونفيدكــم بــأن اجلانــي يتلقــى العــاج‬\n‫حاليــا نأمــل اســتالم املوضــوع التخــاذ الــازم كمــا وجــد علــى اللفــة رقــم‬\n‫(‪ )37‬تقريــر الطــب الشــرعي وتقريــر الفحــوص الوراثيــة مرفقــة بظــرف‬\n‫حيــث وجــد التقريــر الطبــي الشــرعي رقــم ‪...........‬لســنة ‪1433‬ه ـ نــص‬\n‫احلاجــة منــه « املناقشــة والــرأي ممــا ســبق وتقــدم وإجابة ألســئلة التحقيق‬\n‫نقــرر اآلتــي ‪ )1( :‬احلــدث ‪ ............. /‬ســعودي اجلنســية ويبلــغ مــن العمــر‬\n‫‪ 11‬عــام ـ ـ رقــم الســجل املدنــي ‪ )2(...........‬كان املذكــور حــال توقيــع‬\n‫الكشــف الطبــي عليــه واعيــا ومــدركا للزمــان واملــكان واألشــخاص‬\n‫(‪ )3‬ادعــى املذكــور بخطفــه أثنــاء عودتــه ملنزلــه مــن البقالــة بعــد صــاة‬\n‫عصــر يــوم األحــد املوافق‪1433/12/26‬ه ـ وفعــل فاحشــة اللــواط بــه‬\n‫بالقــوة مــن قبــل شــخص مجهــول وأن الشــخص قــد أدخل ذكره بالشــرج‬\n‫مرتــن (‪ )4‬بفحــص مالبــس املذكــور التــي كان يرتديهــا وقــت احلــادث‬\n‫تبــن لنــا اآلتــي ‪ :‬أ‪ -‬لــم نتبــن بهــا ثمــة قطــوع أو متزقــات مشــتبهة وهــذا‬\n‫يشــير النعــدام املقاومــة والتشــابك بــن املجنــي عليــه واجلانــي نظــرا لعــدم‬\n‫التكافــؤ يف قــوة كل منهمــا بـ ـ تبينــا بالبنطلــون مواضــع تلوثــات يشــتبه‬\n‫بكونهــا تلوثــات منويــة ج‪ -‬أفــاد فحــص املالبــس مــن قبــل األدلــة اجلنائيــة‬\n‫بســلبية الفحــص عــن التلوثــات املنويــة ‪ )5( -‬تبــن لنــا وجــود عالمــات‬\n‫عنــف عامــة بجســم املذكــور وتشــير الســتخدام القــوة يف إجبــار املجنــي‬\n\n\n                                                                                       ‫‪140‬‬\n\f      ‫عليــه علــى فعــل الفاحشــة بــه وهــذه العالمــات هــي أ‪ -‬الســحج‬\n      ‫االحتكاكــي املشــاهدة بأســفل ميــن مقــدم الصــدر واملوصــوف بصلــب‬\n      ‫التقريــر هــي إصابــات رضيــة احتكاكيــة وتنتــج عــن االحتــكاك‬\n      ‫بطــرف ناتــئ جلســم صلــب أيــا كان نوعــه أثنــاء كبــه علــى وجهــه لفعــل‬\n      ‫الفاحشــة بــه وقــد مــر علــى هــذا الســحج مــدة تقــدر بعــدة ســاعات فقــط‬\n      ‫حيــث كان ســطحها محمــرا وبــه ارتشــاح مصلــي وهــذا يتفــق مــع مــا‬\n      ‫أفادنــا بــه املجنــي عليــه بخصــوص وقــت االعتــداء عليــه ب ‪ -‬التكدمات‬\n      ‫احلديثــة املشــاهدة بيســار الوجــه ويســار األنــف هــي إصابــات رضيــة‬\n      ‫حديثــة وتنتــج عــن املصادمــة بجســم أو أجســام صلبــة راضــة وهــي‬\n      ‫ممكنــة احلــدوث نتيجــة الصفــع بيــد اجلانــي للمجنــي عليــه كمــا أفــاد‬\n      ‫املجنــي عليــه ‪ - 7 -‬تبــن لنــا مــن خــال الفحــص املوضعي ملنطقة الشــرج‬\n      ‫‪ -‬كمــا هــو مشــار إليــه بصلــب التقريرـ ـ عــدم وجــود عالمــات ومظاهــر‬\n      ‫تشــير لتكــرار اســتعمال املذكــور مــن اخللــف لواطــا ‪ - 8 -‬جــاءت‬\n      ‫نتيجــة فحــص املســحات املرفوعــة مــن داخــل الشــرج وخارجــه إيجابيــة‬\n      ‫بالنســبة للتلوثــات املنويــة وقــد تطابقــت البصمــة الوراثيــة لهــذه التلوثــات‬\n      ‫مــع البصمــة الوراثيــة ألحــد األشــخاص املســجلني لــدى األدلــة اجلنائيــة‬\n      ‫وهــو نفــس الشــخص الــذي اعتــدى علــى املذكــور وهــذا يثبــت تعــرض‬\n      ‫املذكــور لإلمنــاء عليــه مــن قبــل الشــخص املتهــم ‪ - 9 -‬تبينــا مبنطقــة‬\n      ‫الشــرج وجــود إصابــات حديثــة علــى هيئــة شــق شــرجي ســطحي مقابــل‬\n      ‫موضــع الســاعة الثانيــة عشــرة علــى قــرص الســاعة وكذلــك شــق‬\n      ‫شــرجي نــازف علــى هيئــة جــرح تهتكــي وهــي إصابــات رضيــة حديثــة‬\n      ‫وميكــن أن حتــدث نتيجــة إيــاج جســم صلــب راض مثــل قضيــب ذكــر‬\n      ‫بالــغ منتصــب أو مــا يف حكمــه ويعاصــر تاريــخ حــدوث هــذه اإلصابــات‬\n\n\n‫‪141‬‬\n\f‫تاريــخ الواقعــة املدعــاة ‪ - 10 -‬إن واقعــة االعتــداء علــى املذكــور قــد‬\n‫تأكــدت مبــا يلــي أ‪ -‬مــا أثبتتــه الفحــوص الوراثيــة مــن إيجابيــة فحــص‬\n‫املســحات الشــرجية للتلوثــات املنويــة وأن بصمتهــا الوراثيــة تتطابــق مــع‬\n‫الشــخص املعتــدي علــى احلــدث املذكــور ب ‪ -‬كمــا يؤكــد االعتــداء‬\n‫اجلنســي أيضــا وجــود املظاهــر اإلصابيــة املوضعيــة احلديثــة املشــاهدة‬\n‫مبنطقــة الشــرج واملشــار إليهــا بعاليــه (احمــرار شــديد باجللــد ووجــود‬\n‫شــقني شــرجيني ) والتــي ميكــن حدوثهــا نتيجــة إيــاج عنيــف لقضيــب‬\n‫ذكــر منتصــب بالشــرج وجــود عالمــات عنــف عامــة بجســم املذكــور‬\n          ‫وتشير الستخدام القوة إلرهابه وإجباره على االستسالم للجاني‬\n‫د ‪ -‬مــا أفــاده التحقيــق مــن القبــض علــى اجلاني وبرفقته املجني عليه بعد‬\n‫االعتــداء عليــه أثنــاء إعادتــه ملنزلــه ‪ - 11 -‬قمنــا بإحالــة املجني عليه بعد‬\n‫الكشــف عليــه لقســم اجلراحــة مبستشــفى ‪ .....‬العــام للكشــف الطبــي‬\n‫علــى اإلصابــات املشــاهدة مبنطقــة الشــرج وتقــدمي العــاج املناســب‬\n‫واهلل املوفــق أخصائــي أول الطــب الشــرعي ‪ .....‬الدكتــور ‪........... /‬‬\n‫توقيعــه وختــم الطــب الشــرعي « كمــا وجــد تقريــر الفحــوص الوراثيــة‬\n‫ـاء علــى‬‫رقــم ‪ 1433/...........13‬نــص احلاجــة منــه « النتيجــة النهائيــة بنـ ً‬\n‫حتليــل احلمــض النــووي الوراثــي (‪ )DNA‬ملورثــات ال ـ (‪ )STR‬املوضحة‬\n‫يف اجلــدول الســابق تبــن مــا يلــي‪ :‬تطابــق ‪ :‬األمنــاط الوراثيــة للعينــة رقــم‬\n‫(‪ )...........‬الــوارد تفصيلهــا باجلــدول اخلــاص بالعينــات الــواردة للفحــص‬\n‫مــع األمنــاط الوراثيــة لعينــة الــدم ا لقياســية رقــم (‪ )...........‬والعائــدة ل ـ‬\n‫‪......................‬والصــادر بحقهــا تقريرنــا رقم‪...........‬ممــا يثبــت أن ‪...........‬‬\n‫(ســعودي اجلنســية) هــو مصــدر التلوثــات املنويــة يف هــذه العينــة ‪ -‬األمنــاط‬\n‫الوراثيــة للعينــة القياســية رقــم (‪ )...........‬والعائــدة ل‪...........‬تقــع ضمــن‬\n\n\n                                                                                              ‫‪142‬‬\n\f      ‫األمنــاط الوراثيــة للعينــة املختلطــة رقــم (‪ )...........‬الــوارد تفصيلها باجلدول‬\n      ‫اخلــاص بالعينــات الــواردة للفحــص ممــا يــدل أنهــا أحــد مصــادر هــذا‬\n      ‫االختــاط ‪ -‬مت حتديــد األمنــاط الوراثيــة للعينــة رقــم (‪ )...........‬الــوارد‬\n      ‫تفصيلهــا يف اجلــدول اخلــاص بالعينــات الــواردة للفحــص وقــد مت بحــث‬\n      ‫هــذه األمنــاط يف قاعــدة املعلومــات الوراثيــة لدينــا ولــم نتبــن حتــى وقــت‬\n      ‫إعــداد هــذا التقريــر وجــود تطابــق جنائــي مــع أي قضايــا ســابقة ‪ -‬ســلبية‬\n      ‫العينــة رقــم (‪ )...........‬الــوارد تفصيلهــا باجلــدول اخلــاص بالعينــات الــواردة‬\n      ‫للفحــص للحمــض النــووي الوراثــي الفاحــص مــازم أول كيميائــي ‪/‬‬\n      ‫‪...........‬توقيعــه الفاحــص ‪/‬مديــر شــعبة املختبرات اجلنائيــة ‪...........‬توقيعه‬\n      ‫يعتمــد مديــر إدارة األدلــة اجلنائيــة مقــدم كيميائــي ‪...........‬توقيعــه اخلتــم‬\n      ‫الرســمي « كمــا وجــد علــى اللفــة رقــم (‪ )1‬دفتــر حتقيــق األحــوال‬\n      ‫األمنيــة حيــث وجــد علــى الصفحــة رقــم (‪ )16‬حيــث اســتطاع ‪...........‬‬\n      ‫وابنه‪...........‬التعــرف علــى ســيارة املدعــى عليــه وكذلــك اللفــة رقــم (‪)3‬‬\n      ‫علــى الصفحــة رقــم ( ‪ 2‬و ‪ ) 3‬محاضــر تعــرف حيــث اســتطاع ‪...........‬‬\n      ‫التعرف على سيارة املدعى عليه ‪ .....‬كما استطاع ‪...........‬وابنه ‪...........‬‬\n      ‫التعــرف علــى املدعــى عليــه وأنــه هــو قائــد الســيارة ‪ ....‬كمــا وجــد علــى‬\n      ‫الصفحــة رقــم (‪ 2‬و ‪ )3‬مــن الدفتــر املرفــق لفــة رقــم (‪ )1‬محضــر معاينــة‬\n      ‫اآلتــي نصــه « جــرى معاينــة الســيارة العائــدة للمتهــم ‪...........‬نــوع ‪ ......‬رقــم‬\n      ‫اللوحــة (‪ )...........‬وذلــك مــن األدلــة اجلنائيــة واتضــح أنهــا مظللــة اجلوانــب‬\n      ‫وبهــا صدم ــة بــل كســر يف االســطب األمامــي األميــن واأليســر كمــا‬\n      ‫جــرى معاينــة الســيارة مــن الداخــل وعثــر بداخلهــا علــى ثــوب ‪ +‬شــماغ ‪+‬‬\n      ‫فايــن يف أحــد األدراج ومت رفــع ذلــك مــن قبــل األدلــة اجلنائيــة وقامــوا ذلــك‬\n      ‫بقــص تلبيســة املقعــد األميــن للمرافــق لفحصهــا ولــم يعثــر علــى شــيء‬\n\n\n‫‪143‬‬\n\f‫ســوى مــا ذكــر ومت إعــداد هــذا احملضــر وذيــل بتوقيــع معديــه « أ‪ .‬ه ـ‬\n‫كمــا وجــد علــى الصفحــة رقــم (‪ 14‬ـ ـ ‪ )15‬مــن نفــس الدفتــر اســتجواب‬\n‫للحــدث ……… املتضمــن االســم ‪........... /‬العمــر ‪ 11 /‬املهن ــة ‪ /‬طالــب‬\n‫احلالــة التعليميــة ‪ /‬متعلــم الســكن ‪ /‬حــي ‪...........‬س‪ /‬أفدنــي كيــف مت‬\n‫خطفــك ؟ ج‪ /‬أفيدكــم أننــي ذهبــت إلــى التموينــات علــى أقدامــي ويف‬\n‫طريقــي بعــد صــاة العصــر وقــف عنــدي صاحــب ســيارة ‪ .......‬مظللــة‬\n‫خفيــف ونــزل وقــال لــي اركــب وهربــت عنــه وحلــق بــي بعــد ســقوطي‬\n‫علــى األرض وأخذنــي وأركبنــي داخــل الســيارة وحتــرك بــي إلــى داخــل‬\n‫احلــي ووقــف يف مــكان فاضــي وأخــذ يضربنــي ويقــول نــزل مالبســك‬\n‫ونزلــت مالبســي وافتعــل بــي حيــث أدخــل ذكــره داخــل وهــو منــزل‬\n‫بنطلونــه وفانيلتــه وفجــأة طــرق الزجــاج شــخص وحتــرك هاربـ ًا بســرعة‬\n‫واجتــه إلــى حــي ‪...........‬بالقــرب مــن حديقــة ‪...........‬التابعــة للمجمــع‬\n‫وهــي حديقــة النســاء حيــث وقــف يف مــكان صحــراوي مقابلهــا وافتعــل‬\n‫بــي داخــل الســيارة قبــل املغــرب إلــى قــرب صــاة العشــاء حيــث جردنــي‬\n‫مــن مالبســي وكينــي بســيجارة س‪ ............... /‬س‪ /‬هــل أدخــل ذكــره‬\n‫؟ ج‪ /‬نعــم باســتمرار س‪ /‬هــل تعرفــه مــن قبــل ؟ ج‪ /‬كال س‪ /‬إلــى أيــن‬\n‫اجتــه بعــد ذلــك ؟ ج‪ /‬حتــرك بعــد أن أنزلنــي وأنــا طلبــت منــه إركابــي‬\n‫وإيصالــي وقــال ال تعلــم أحــد واجتــه إلــى الصرافــة وحلقــت بــه الشــرطة‬\n‫وهــرب واســتوقفوه بالقــوة وهــرب علــى أقدامــه وأخذونــي الشــرطة س‪/‬‬\n‫مــاذا فعــل غيــر فعــل الفاحشــة ؟ ج‪ /‬أعطانــي ســيجارة وطلــب منــي أن‬\n‫أعمــر دخــان وعمــرت دخــان س‪ /‬هــل لديــك أقــوال ؟ ج‪ /‬كال س‪ /‬هــل‬\n‫تصــادق علــى أقوالــك؟ ج‪ /‬نع ــم « أ‪ .‬ه ـ وبعــرض ذلــك علــى املدعــى عليــه‬\n‫أجــاب بقولــه جميــع مــا جــاء يف بينــات املدعــي العــام غيــر صحيــح جملــة‬\n\n\n                                                                                    ‫‪144‬‬\n\f      ‫وتفصيــا وأنــا ال أعــرف الشــهود الذيــن جــاء ذكرهــم يف البينــات ولــم‬\n      ‫أشــاهد أحــدا منهــم إال يف شــرطة ‪...........‬أحضروهــم لــي هــذه إجابتــي‬\n      ‫ثــم ســألت املدعــي العــام هــل لديــه زيــادة بينــة قــال نعــم وســوف أحضرهــا‬\n      ‫يف اجللســة القادمــة إن شــاء اهلل هكــذا قــرر وقــد أجيــب لطلبــه ورفعــت‬\n      ‫اجللســة الثالثــة وتأجلــت إلــى يــوم االثنــن ‪1434/3/2‬ه ـ الســاعة التاســعة‬\n      ‫وقــد مت إغــاق اجللســة يف متــام الســاعة ‪ 12 : 30‬وعليــه جــرى التوقيــع‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                  ‫أجمعــن حــرر يف ‪1434/02/30‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد والصــاة والســام علــى مــن ال نبــي بعــده‬\n      ‫وبعــد ‪ :‬فلدينــا نحــن القضــاة يف احملكمــة العامــة بحائــل كال مــن‬\n      ‫‪......................‬و‪...........‬و‪...........‬ويف يــوم الثالثــاء املوافــق ‪1434/3/3‬ه ـ‬\n      ‫افتتحــت اجللســة يف الســاعة ‪12 : 00‬وفيهــا حضــر املدعــي العــام وحضــر‬\n      ‫حلضــوره املدعــى عليــه ‪...........‬وقــد مت ســؤال املدعــي العــام هــل أحضــر‬\n      ‫مــا وعــد بإحضــاره مــن زيــادة بينــه قــال نعــم وأطلــب ســماع مــا لديهــم هذا‬\n      ‫وقــد حضــر يف هــذه اجللســة أفــراد الدوريــات األمنيــة كال مــن ‪...........‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...........‬و ‪...........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقم ‪...........‬وبســؤالهما عمــا لديهما من‬\n      ‫شــهادة شــهد كل واحــد منهمــا مبفــرده بقولــه لقــد جاءنــا بــاغ عــن قيــام‬\n      ‫شــخص باختطــاف حــدث صغيــره عمــره ال يتجــاوز إحــدى عشــر ســنة‬\n      ‫ومت وصــف ســيارته لنــا وأنهــا ‪ ......‬فبحثــت عنــه وشــاهدته بعــد ســاعتني‬\n      ‫تقريب ـ ًا عنــد صرافــة بنــك ‪...........‬القريبــة مــن ‪...........‬التــي مقابلــه ‪....‬‬\n      ‫منطقــة حائــل فوقفــت أمامــه بســيارة الدوريــات فقام بصدمــي من األمام‬\n      ‫ثــم رجــع إلــى اخللــف وقفــز الرصيــف وهــرب فلحقــت بــه ثــم متــت متابعتــه‬\n\n\n‫‪145‬‬\n\f‫داخــل احلــي الــذي خلــف ‪...........‬حتــى وصــل إلــى طريــق مغلــق فاضطــر‬\n‫إلــى الوقــوف ثــم رجــع إلــى اخللــف حتــى تعلقــت ســيارته بصــدام ســيارة‬\n‫الدوريــة ثــم نــزل علــى قدميــه مــن الســيارة ثــم وجدنــا احلــدث يف الســيارة‬\n‫التــي كانــت بقيــادة املدعــى عليــه هــذا احلاضــر فأخذنــاه ووضعنــاه يف‬\n‫الدوريــة ثــم حاولنــا اإلمســاك باملذكــور إال انــه اســتطاع أن يفلــت منــي‬\n‫فأطلقــت عليــه طلقــة تخويفيــة يف الهــواء إال انــه هــرب ودخــل عمــارة‬\n‫حتــت اإلنشــاء ثــم بحثــت عنــه واســتطاع أن ينتقــل إلــى عمــاره أخــرى‬\n‫ا ثــم انتقــل إلــى عمــارة ثالثــه ونزل يف حوشــها‬ ‫مســكونه وبقــي فيهــا قليـ ً‬\n‫وفتــح البــاب وخــرج ثــم حــاول دخــول عمــارة أخــرى وبينمــا هــو يتســلق‬\n‫البــاب للدخــول قبضــت عليــه فلمــا قبضــت عليــه اتضــح انــه الشــخص‬\n‫الــذي مت اإلبــاغ عنــه وهــو ‪ ...........‬وهــو املدعــى عليــه هــذا احلاضــر هــذا‬\n‫مــا لــدي مــن شــهاده وبــه اشــهد هكــذا شــهد كل واحــد منهمــا منفــرد ًا‬\n‫كمــا حضــر يف هــذه اجللســة ‪ ..............‬ســعودي اجلنســية مبوجــب ســجل‬\n‫مدنــي رقــم ‪...........‬وبســؤاله عمــا لــدي مــن شــهاده قــال اشــهد هلل انــه يف‬\n‫يــوم األحــد ‪ 1433/12/26‬عصــرا كنــت يف املســجد وكان ابنــي يف‬\n‫البيــت فأرســلته والدتــه إلــى البقالــة فلمــا رجــع مــن البقالــة تعــرض لــه‬\n‫شــخص وقــال لــه اركــب فتركــه ابنــي وذهــب فنــزل صاحــب الســيارة‬\n‫وحلــق بــه وامســك بــه فقــام ابنــي بدفعــه وأفلــت منــه ثــم رجــع الشــخص‬\n‫وركــب يف ســيارته ومشــى وكان كأنــه مرتبــك ويتلفــت كثيــر ًا ثــم‬\n‫جاءنــي اتصــال مــن أهلــي ورجعــت إلــى البيــت وســألت ابنــي عمــا حــدث‬\n‫فاخبرنــي مبــا ذكرتــه ووصــف لــي الســيارة وأنهــا مــن نــوع ‪ ....‬فخرجــت‬\n‫أنــا وابنــي يف الســيارة نبحــث عــن الشــخص الــذي حــاول اإلمســاك‬\n‫بــه بنــاء علــى وصــف الســيارة فأخذنــا دورة يف احلــي وهــو حــي ‪...........‬‬\n\n\n                                                                                        ‫‪146‬‬\n\f      ‫إال أننــا لــم جنــده ثــم رجعنــا إلــى البيــت ثــم ا خــذ الســيارة أبنــي وذهــب‬\n      ‫يبحــث عنــه لوحــده ورجــع إلــي فأخبرنــي أنــه وجــد الســيارة التــي كان‬\n      ‫عليهــا الشــخص الــذي حــاول خطفــه ثــم ذهبــت أنــا وأيــاه إلــى الســيارة‬\n      ‫فوجدناهــا يف أرض فضــاء وعندهــا كــوم مــن الرمــل وكنــت أظــن أنــه‬\n      ‫ال يوجــد أحــد يف الســيارة فأوقفــت ســيارتي ونزلــت علــى قدمــي وذهبــت‬\n      ‫إلــى الســيارة فلمــا اقتربــت منهــا وجدتهــا علــى وضــع التشــغيل وكانــت‬\n      ‫مظللــة بالكامــل مــن اجلوانــب ومــن اخللــف فلمــا نظــرت داخــل الســيارة‬\n      ‫شــاهدت شــخص عــاري مــن الســرة إلــى األســفل وكان علــى بطنــه يف‬\n      ‫املرتبــة األماميــة التــي بجــوار الســائق وشــعرت أن حتتــه شــخص آخــر‬\n      ‫فلمــا شــعر بــي انتقــل مــن مرتبــة الراكــب إلــى مرتبــة الســائق مباشــرة‬\n      ‫ولــم يلبــس أي شــيء وكان يشــير إلــي بيــده ثــم حــرك الســيارة وهــرب‬\n      ‫فوجــدت خشــبة يف األرض وأخذتهــا محــاو ًال أن أضــرب الســيارة‬\n      ‫ورميتهــا علــى الســيارة إال أن الســيارة ابتعــدت عنــي وضربتهــا ضربــة‬\n      ‫خفيفــة ثــم أخــذت رقــم الســيارة وبلغــت الدوريــات األمنيــة فواعدونــي‬\n      ‫عــن ‪...........‬فلمــا ذهبــت إلــى هنــاك وجــدت شــخص آخــر ذكــر لــي أن‬\n      ‫ابنــه أو أبــن أخيــه قــد خــرج مــن العصــر ولــم يعــد إلــى اآلن وكان ذلــك‬\n      ‫قبــل املغــرب بنصــف ســاعة تقريب ـ ًا ثــم أخبرونــي الدوريــات بعــد ذلــك‬\n      ‫ـاء مــن نفــس اليــوم فلمــا ذهبــت‬‫أنهــم قبضــوا عليــه الســاعة الثامنــة مسـ ً‬\n      ‫إلــى مركــز الضبــط اإلداري وشــاهدت الشــخص عرفــت أنــه هــو الــذي‬\n      ‫شــاهدته يف الســيارة وهــو هــذا احلاضــر املدعــى عليــه هــذا مــا لــدي مــن‬\n      ‫شــهادة وبــه أشــهد وبعــرض الشــهود ومــا جــاء يف شــهادتهم علــى املدعــى‬\n      ‫عليــه قــال مــا جــاء يف شــهادتهم غيــر صحيــح وأنــا ال اعرفهــم وال أقــول‬\n      ‫فيهــم أي شــيء هــذه إجابتــي وبطلــب مزكيــن احضــر املدعــي العــام‬\n\n\n‫‪147‬‬\n\f‫ال مــن ‪...........‬ســعودي بالســجل املدنــي‬  ‫بتزكيــة أفــراد الدوريــات ك ً‬\n‫رقــم ‪...........‬و ‪......................‬ســعودي بالســجل املدنــي رقــم ‪...........‬‬\n‫واحضــر لتزكيــة الشــاهد ‪...........‬كال مــن ‪...........‬ســعودي بالســجل‬\n‫رقــم ‪...........‬و ‪...........‬ســعودي بالســجل املدنــي رقــم ‪...........‬وقــد شــهد‬\n‫كل مزكــي مبفــرده بعدالــة وثقــة الشــهود املذكوريــن بعاليــه وقــد مت‬\n‫ســؤال املدعــي العــام هــل لديــه زيــادة بينــة قــال اكتفــي مبــن أحضــرت‬\n‫ومبــا يف املعاملــة هكــذا قــرر وللتأمــل وإصــدار احلكــم رفعــت اجللســة‬\n‫وتأجلــت إلــى بعــد صــاة الظهــر بنفــس هــذا اليــوم الثالثــاء املوافــق‬\n‫‪1434/3/3‬ه ـ الســاعة ‪ 1 : 00‬ومت إغالقهــا الســاعة ‪ 12 : 40‬وعليــه‬\n‫جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه‬\n                                   ‫وصحبــه أجمعــن حــرر يف ‪1434/3/3‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n‫فلدينــا نحــن القضــاة يف احملكمــة العامــة بحائــل كال مــن ‪...........‬و‪.‬‬\n‫‪.....................‬و‪...........‬وبنــاء علــى املعاملــة احلالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة املســاعد برقــم ‪ 3483544‬يف ‪1434/2/19‬ه ـ واملقيــدة‬\n‫باحملكمــة برقــم ‪ 34396101‬يف ‪1434/2/19‬ه ـ عليــه فيهــذا اليــوم‬\n‫الثالثاء املوافق ‪1434/3/3‬هـ افتتحت اجللســة يف الســاعة ‪ 1 : 15‬كما‬\n‫وردنــا تقريــر كيميائــي شــرعي صــادر مــن مركــز املســموم والكيمياء‬\n‫الطبيــة الشــرعية مبنطقــة القصيــم برقــم ‪...........‬يف ‪1434/1/28‬ه ـ‬\n‫واملقيــد باحملكمــة برقــم ‪ 34478337‬يف ‪1434/2/25‬ه ـ املتضمــن ثبت‬\n‫إيجابيــة العينــات لالمفيتامــن هــو مــن املــواد الكيميائيــة املنبهــة للجهاز‬\n‫العصبــي املركــز واملدرجــة بجــدول املؤثــرات العقليــة رقــم (‪ )2‬وفئة (ب)‬\n‫التــي عناهــا تعميــم وزارة الصحــة رقــم ‪ 30440/136‬واملبنــي علــى تعميــم‬\n\n\n                                                                                               ‫‪148‬‬\n\f      ‫الهيئــة العامــة للغــذاء والــدواء رقــم ‪ 4933‬يف ‪1431/2‬ه ـ انتهــى التقريــر‬\n      ‫وبعرضــه علــى املدعــى عليــه قــال ما جاء فيه غيــر صحيح هذا وقد جرى‬\n      ‫االطــاع علــى كامــل أوراق املعاملــة فبنــاء علــى مــا تقــدم وحيــث أنكــر‬\n      ‫املدعــى عليــه دعــوى املدعــي العــام وألن بينــات املدعــي العــام كافي ــة يف‬\n      ‫إدانــة املدعــى عليــه مبــا نســب إليــه ومــن ذلــك شــهادة الشــاهد ‪...........‬‬\n      ‫الــذي تضمنــت شــهادته محاولــة املدعــى عليــه خطفــه ووصفــه ســيارته‬\n      ‫وانطباقهــا عليــه واملرصــودة يف ضبطــه وكذلــك شــهادة ‪...........‬الــذي‬\n      ‫حضــر والتــي تضمنــت شــهادته رؤيتــه لســيارة املدعــى عليــه واقف ــة بعــد‬\n      ‫أن أبلغــه ابنــه الشــاهد األول بأنهــا الســيارة التــي حــاول قائدهــا خطفــه‬\n      ‫وشــاهدها مــن الداخــل ووجــد املدعــى عليــه يف ســيارته وخاصمــه وأنــه‬\n      ‫أحــس بوجــود شــخص حتتــه ثــم الذ بالفــرار وقــام املدعــى عليــه بجــرأة‬\n      ‫بإعــادة فعــل الفاحشــة بالغــام مــن قبــل املغــرب إلــى قريــب مــن العشــاء‬\n      ‫وانطبقــت أوصــاف الســيارة التــي وصفهــا الشــاهد الثانــي علــى الســيارة‬\n      ‫التــي وصفهــا املدعــى عليــه لدينــا وصــادق علــى أنهــا ســيارته وأنهــا‬\n      ‫بقيادتــه وهــو مــا دلــت عليــه اســتمارة الســيارة املرفقــة باملعاملــة وكذلــك‬\n      ‫انطبقــت إفــادة الغــام املجنــي عليــه مــع شــهادة الشــاهد الثانــي ‪...........‬‬\n      ‫حيــث ذكــر أن شــخصا طــرق أو أطــل عليهــم مــن زجــاج ســيارة املدعــى‬\n      ‫عليــه حينمــا كان يفعــل بــه الفاحشــة وكل ذلــك مــع انطبــاق احلمــض‬\n      ‫النــووي مــن العينــة املرفوع ــة مــن احلــدث املجنــي عليــه علــى املدعــى عليــه‬\n      ‫وأنــه هــو مصــدر تلــك التلوثــات املنويــة مــع كونــه مــن أربــاب الســوابق‬\n      ‫وكذلــك شــهادة الشــاهدين رجلــي األمــن املرصــودة بعاليــه والتــي‬\n      ‫تضمــن القبــض علــى املدعــى عليــه وبرفقتــه احلــدث املجنــي عليــه وهروبه‬\n      ‫منهــم ودخولــه مســاكن بــدون أذن اصحابهــا فــكل ذلــك يديــن املدعــى‬\n\n\n‫‪149‬‬\n\f‫عليــه مبــا نســب إليــه وحيــث أن مــا أقــدم عليــه املدعــى عليــه يعــد جرمــا‬\n‫عظيمــا وفســاد ًا كبيــر ًا وزعزعــة لألمــن وجــرأة علــى األعــراض وعلــى‬\n‫احلــرام يف بــاد احلرمــن وهــي بــاد األمــن واألمــان ويــدل علــى تأصــل‬\n‫الشــر والفســاد والشــذوذ يف نفس ــه وهــو محصــن متــزوج وهــو مــن أربــاب‬\n‫الســوابق يف شــتى أنــواع الفســاد واملعاصــي ومــن ســوابقه مــا هــو مــن‬\n‫جنــس جرميتــه احلاليــة فســابقته األولــى فعــل فاحشــة اللــواط وســابقته‬\n‫الثانيــة محاولــة إركاب فتــاة أو فتــى لغــرض ســيء وســابقته الثالثــة‬\n‫جتــول يف الليــل وســابقته الرابع ــة ســرقة ســيارات وســابقته اخلامســة‬\n‫حيــازة واســتعمال املخــدرات والتــي لــم تردعــه أحكامهــا الســابقة عــن‬\n‫العــودة ملثــل تلــك األفعــال وألن مــا يدعــي بــه عليــه املدعــي العــام لدينــا‬\n‫إمنــا هــو مجموعــة جرائــم متنوع ــة مــن محاولــة خطــف‪ ،‬وخط ــف وفعــل‬\n‫فاحشــة‪ ،‬وصــدم دوريــة أمنيــة وهــروب مــن الســلطة ودخــول مســاكن‬\n‫بطريقــة تــروع اآلمنــن أقــدم عليهــا املدعــى عليــه مــن غيــر مبــاالة وال هــم‬\n‫لــه ســوى إشــباع رغباتــه ونزعاتــه الشــيطانية ولقولــه تعالــى « إمنــا جــزاء‬\n‫الذيــن يحاربــون اهلل ورســوله ويســعون يف األرض فســادا أن يقتلــوا أو‬\n‫يصلبــوا أو تقطــع أيديهــم وأرجلهــم مــن خــاف أو ينفــوا مــن األرض ‪..‬‬\n‫« اآليــة ولقولــه صلــى اهلل عليــه وعلــى آلــه وســلم « مــن وجدمتــوه يعمــل‬\n‫عمــل قــوم لــوط فاقتلــوا الفاعــل واملفعــول بــه « رواه الترمــذي (‪ 57/4‬ـ ـ‬\n‫‪ )58‬وســن أبــي داوود (‪ 607/4‬ـ ـ ‪ )608‬وابــن ماج ــه (‪ )856/2‬والســن‬\n‫الكبــرى للبيهقــي (‪ )232/8‬ومسن ــد اإلمــام أحم ــد (‪ )300/1‬وســن‬\n‫الــدار قطنــي (‪ )124/3‬واحلاكــم يف مســتدركه (‪ )355/4‬والكامــل‬\n‫البــن عــدي (‪ )1768/5‬واألوســط البــن املنــذر (‪ )623/2‬واحمللــى البــن‬\n‫حــزم (‪ )383/11‬وحلديــث « ملعــون مــن عمــل عمــل قــوم لــوط « رواه‬\n\n\n                                                                                        ‫‪150‬‬\n\f      ‫الترمــذي وقــد أجمــع الصحابــة رضــوان اهلل عليهــم علــى قتــل اللوطــي‬\n      ‫وأن معصيتــه مــن أعظــم املعاصــي والتــي يــرجت لهــا عــرش الرحمــن وأن‬\n      ‫اهلل تعالــى جمــع علــى أهلهــا مــن أنــواع العقوبــات مــا لــم ينــكل بــه أم ــة‬\n      ‫ســواهم وذلــك لعظــم مفســدة هــذه اجلرميــة أنظــر فتــاوى ابــن تيميــة‬\n      ‫(‪ 334/28‬ـ ـ ‪ )345‬والسياســة الشــرعية البــن تيميــة ص(‪ )52‬وزاد املعــاد‬\n      ‫البــن القي ــم (‪ )40/5‬وملــا هــو مقــرر لــدى احملققــن مــن أهــل العلــم أن مــن‬\n      ‫لــم يندفــع فســاده إال بالق ــتل فإنــه يق ــتل وهــذه قاعــدة عظيمــة إلصــاح‬\n      ‫البــاد والعب ــاد والعقوبــات التعزيريــة فيهــا كبح جلمــاح املجرمني وقطعا‬\n      ‫لفســادهم وإصــاح للمجتمــع ولكــون املدعــى عليــه مكلــف شــرعا‬\n      ‫وهــو بالــغ عاقــل وجلميــع مــا ســبق فإننــا أمرنــا بق ــتل املدعــى عليــه ‪...........‬‬\n      ‫ســجل مدنــي رقــم (‪ )...........‬تعزيــرا جــزاء لــه وردعا ألم ــثاله وبه حكمنا‬\n      ‫وبعرضــه علــى الطرفــن قــرر املدعــي العــام وقــرر املدعــى عليــه عــدم‬\n      ‫القناعــة فجــرى إفهامهمــا بتعليمــات االســتئناف وانــه ســيتم تســليمهما‬\n      ‫صــورة مــن صــك احلكــم يف يــوم األربعــاء املوافــق ‪1434/3/4‬ه ـ الســاعة‬\n      ‫التاســعة لالعتــراض عليــه خــال ثالثــن يوم ـ ًا مــن تاريــخ اســتالمه وإذا‬\n      ‫لــم يقدمــا اعتراضهمــا ســيتم رفــع احلكــم إلــى محكمــة االســتئناف‬\n      ‫بــدون الئحــة اعتراضيــة ففهمــا ذلــك ومت إغــاق اجللســة يف الســاعة ‪33‬‬\n      ‫‪01 :‬وعليــه حصــل التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                               ‫محمــد والــه وصحبــه أجمعــن حــرر يف ‪1434/3/3‬ه ـ‬\n      ‫ال مــن ‪......................‬و‪...........‬‬\n                                              ‫احلمــد هلل وحــده وبعــد فلدينــا ك ً‬\n      ‫القاضيــن يف احملكمــة العامــة بحائــل وبنــاء علــى املعاملــة احملالــة لنــا‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة بحائــل املســاعد برقــم ‪3483544‬‬\n      ‫وتاريــخ ‪ 1434/02/19‬ه ـ املقيــدة باحملكمــة برقــم ‪34396101‬‬\n\n\n‫‪151‬‬\n\f‫وتاريــخ ‪1434/2/17‬ه ـ ففــي يــوم الســبت املوافــق‪1434/04/27‬‬\n‫ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 45‬وكنــا قــد تلقينــا املعاملــة مــن‬\n‫محكمــة االســتئناف بحائــل مبوجــب خطــاب فضيلــة رئيســها رقــم‬\n‫‪ 34396101‬يف ‪1434/04/14‬ه ـ مرفق ـ ًا بهــا القــرار رقــم ‪34186869‬‬\n‫يف ‪1434/04/14‬ه ـ املتضمــن (وبدراســة الصــك وصــورة ضبطه وأوراق‬\n‫املعاملــة واللوائــح االعتراضيــة لوحــظ مــا يلــي أو ًال طلــب املدعــي العــام‬\n‫يف دعــواه احلكــم علــى املدعــى عليــه بحــد احلرابــة ولــم جنــد أصحــاب‬\n‫الفضيلــة تطرقــوا لذلــك يف حكمهــم بإثبــات ذلــك مــن عدمــه والبــد‬\n‫ـاء علــى املــادة (‪ )174‬مــن نظــام اإلجــراءات اجلزائيــة ‪ -‬ثانيـاً‪:‬‬  ‫مــن ذلــك بنـ ً‬\n‫طلــب املدعــي العــام يف دعــواه مصــادرة الســيارة املســتخدمة باجلرميــة‬\n‫ولــم جنــد أصحــاب الفضيلــة تطرقــوا لذلــك يف حكمهــم ‪ -‬ثالث ـاً‪:‬‬\n‫لــم يحضــر أصحــاب الفضيلــة احلدثــن املجنــي عليهمــا ……… و‬\n‫……… لســماع مــا لديهمــا للتثبــت ممــا نســب إليهمــا أســوة ببقيــة‬\n‫الشــهود حيــث أشــار أصحــاب الفضيلــة ملــا ورد مــن شــهادة ‪ ......‬مبحضــر‬\n‫التحقيــق فقــط دون حضــوره وهــذا ال يكفــي ‪ -‬رابعـاً‪ :‬ورد يف الالئحــة‬\n‫االعتراضيــة املقدمــة مــن املدعــى عليــه أنــه مريــض نفســي مزمــن منــذ‬\n‫الصغــر ولــه مراجعــة مبستشــفى الصحــة النفســية بحائــل وأول مراجعــة‬\n‫لــه يف ‪1417/05/26‬ه ـ حســب اإلفــادة املرفــق صورتــه يف الالئحــة وأن‬\n‫لديــه اكتئــاب جســيم حســب التقريــر الطبــي املرفــق صورتــه بالالئحــة‬\n‫وأنــه ســبق أن ســكب البنزيــن علــى نفســه وأحرقهــا حســب مراجعتــه‬\n‫للمستشــفى واثبــات ذلــك لــدى الشــرطة والبــد مــن التحقــق مــن ذلــك‬\n‫والكتابــة للجهــات املختصــة للتحقــق ممــا ذكــره وهــل املدعــى عليــه‬\n‫مســؤول جنائي ـ ًا عــن أفعالــه وقــت اجلرميــة أم ال احتياطــا للدمــاء وبــراء ًة‬\n\n\n                                                                                           ‫‪152‬‬\n\f      ‫للذمــة ‪ -‬خامس ـاً‪ :‬تكــرار الصفحــة اخلامســة مــن الصــك وصــورة‬\n      ‫الضبــط فــا بــد مــن معاجلــة ذلــك ‪ -‬سادسـاً‪ :‬عــدم توقيــع املدعــي العــام‬\n      ‫يف الضبــط علــى الصفحــات(‪ )4-3-2-1‬والبــد مــن ذلــك ‪ -‬ســابعاً‪ :‬عــدم‬\n      ‫ختــم وتوقيــع الصفحــة األخيــرة مــن صــورة الضبــط مبطابقتهــا ألصلهــا‬\n      ‫‪ -‬ثامن ـاً‪ :‬مت اختتــام الصفحــة األولــى مــن الضبــط والصــك واجللســة لــم‬\n      ‫تنتــه بعــد فــا بــد مــن تصحيــح ذلــك ‪ -‬تاســعاً‪ :‬وجــود عــدد مــن األخطــاء‬\n      ‫املطبعيــة يف الصفحــات (‪ )12-10-9-8-6-4‬وضــع حتتهــا خــط بقلــم‬\n      ‫رصــاص وال بــد مــن تعديلهــا الطــاع أصحــاب الفضيلــة وإعــادة النظــر‬\n      ‫وإكمــال الــازم وتقريــر مــا يظهــر أخير ًا واهلل املوفــق)أ‪ .‬هـ وعليه جنيب‬\n      ‫أصحــاب الفضيلــة أمــا بخصــوص أو ًال فــإن حــد احلرابــة لــم يثبــت لدينــا‬\n      ‫ونقــرر باألكثريــة رد دعــوى املدعــى العــام طلــب إقامــة حــد احلرابــة علــى‬\n      ‫املدعــى عليــه لعــدم موجبــه ‪ -‬أمــا مــا جــاء يف ثاني ـ ًا فقــد حكمنــا علــى‬\n      ‫املدعــى عليــه بالقتــل وال نــرى اجلمــع عليــه وال علــى ورثتــه بــن القتــل‬\n      ‫ومصــادرة أو إتــاف مالــه لــذا لــم نحكــم مبصــادرة الســيارة ‪ -‬ألن‬\n      ‫املقــرر فقه ـ ًا تداخــل العقوبــات يف العقوبــة األشــد ولذلــك فإننــا نقــرر‬\n      ‫باألكثريــة رد دعــوى املدعــي العــام مبصــادرة الســيارة أمــا مــا جــاء يف‬\n      ‫املالحظــة الثالثــة فــإن إحضــار احلدثــن لــم يجــر عليــه العمــل وهــو منــاف‬\n      ‫ملقاصــد الشــريعة مــن الســتر علــى مــن جنــي عليــه مبثــل هذه اجلنايــة وفيه‬\n      ‫تأثيــر علــى احلدثــن وذويهمــا واعتبــار احلدثــن شــاهدين واحلــق اخلــاص‬\n      ‫مــازال قائم ـ ًا ال ميكــن االعتمــاد عليــه فيــه مــن اخلصومــة وجــر منفعــة‬\n      ‫لهمــا ‪ -‬أمــا مــا جــاء يف رابع ـ ًا فــإن كثيــر ممــن تقــع منهــم هــذه اجلرائــم‬\n      ‫الكبيــرة يدفــع بهــذا الدفــع تخلص ـ ًا مــن إيقــاع العقوبــة عليــه ولــو فتــح‬\n      ‫هــذا البــاب ملثــل هــؤالء ملــا أقيمــت كثيــر مــن احلــدود ولــم يعــزر كثيــر‬\n\n\n‫‪153‬‬\n\f‫مــن اجلنــاة وقــد كان املدعــى عليــه ‪...........‬يف املجلــس الشــرعي يفهــم‬\n‫اخلطــاب ويــرد اجلــواب ويــدرك كل مــا حولــه ومــا يقــال لــه ومــا يطلــب‬\n‫منــه كمــا هــو ظاهــر مــن خــال إجاباتــه علــى األســئلة التــي وجهــت لــه‬\n‫يف اجللســة وكان مــا ذكــره أصحــاب الفضيلــة مقصــود ًا مــن املناقشــة‬\n‫لــه حتــى أنــه يف اجللســة األولــى رفــض التوقيــع علــى الضبــط مــدركا ملــا‬\n‫أدعــى بــه املدعــي العــام وقــد كان يناقــش ويحــاور ويــرد علــى األســئلة‬\n‫أعقــل مــن بعــض العقــاء ‪ -‬أمــا مــا جــاء يف املالحظــة اخلامســة فقــدمت‬\n‫مــن قبــل كاتبــه ونظــر ًا ألن فضيلــة الشــيخ ‪ ...........‬منــدوب فــا ميكــن‬\n‫إلغــاء هــذه الصفحــة ألنــه يحتــاج إلــى إعــادة طباعــة وقــد مت التقويــس‬\n‫علــى املكــرر وهــذا مــا جنيــب بــه علــى املالحظــة التاســعة ‪ -‬أمــا مــا جــاء‬\n‫يف املالحظــة السادســة فقــد مت تصويــر الضبــط مــن قبــل املشــرف قبــل‬\n‫توقيــع املدعــي العــام وقــد مت إعــادة تصويــره وتداركــه وهلل احلمــد أمــا‬\n‫مــا جــاء يف املالحظــة الثامنــة فهــو قــد وقــع ســهو ًا وهــو غيــر مؤثــر واملطلع‬\n‫عليــه يعــرف أن اجللســة لــم تنتــه ويســري عليــه مــا ذكــر يف اإلجابــة علــى‬\n‫املالحظــة اخلامســة هــذا مــا لــزم اإلجابــة بــه علــى مالحظــات أصحــاب‬\n‫الفضيلــة وســيتم إحلــاق ذلــك يف الصــك وســجله وإعادتــه إلــى محكمــة‬\n‫االســتئناف بحائــل علم ـ ًا أن فضيلــة القاضــي املشــارك الشــيخ ‪...........‬‬\n‫قــد نــدب ملــدة شــهرين إلــى املجلــس األعلــى للقضــاء مبوجــب قــرار‬\n‫رئيــس املجلــس األعلــى للقضــاء رقــم ‪ 1772‬يف ‪1434/03/08‬ه ــوالقائم‬\n‫بعملــه القاضــي ‪...........‬وقــد مت إغــاق اجللســة يف الســاعة ‪12 : 11‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n‫يف ‪1434/04/27‬ه ـ احلمــد هلل وحــده و بعــد فقــد اطلعنــا نحــن قضــاة‬\n‫الدائــرة املختصــة بتدقيــق القضايــا اخلماســية مبحكمــة االســتئناف‬\n\n\n                                                                                          ‫‪154‬‬\n\f      ‫مبنطقــة حائــل علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامة‬\n      ‫بحائــل املســاعد برقــم ‪ 34396101‬يف ‪1434/4/29‬ه ـ و املقيــدة لدينــا‬\n      ‫برقــم ‪ 341065453‬يف ‪1434/4/30‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫صاحــب الفضيلــة الشــيخ ‪...........‬و مشــاركيه ‪ ..........‬والشــيخ ‪...........‬‬\n      ‫القائــم بعمــل فضيلــة الشــيخ ‪...........‬القضــاة باحملكمــة العامــة برقــم‬\n      ‫‪ 3455295‬يف ‪1434/3/3‬ه ـ اخلاصــة بدعــوى املدعــي العــام ضــد‬\n      ‫‪ .............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...........‬التهامــه‬\n      ‫بقضيــة خطــف غــام وفعــل فاحشــة اللــواط بــه و قــد تضمــن الصــك‬\n      ‫حكــم أصحــاب الفضيلــة و فقهــم اهلل بقتــل املدعــى عليــه تعزيــرا علــى‬\n      ‫النحــو املفصــل يف الصــك و صــورة ضبطــه و قــد ســبق منــا دراســة الصــك‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة و أوراق املعاملــة و باالطــاع علــى‬\n      ‫ـاء علــى‬‫مــا أجــاب بــه أصحــاب الفضيلــة ومــا أحلقــوه بالصــك وضبطــه بنـ ً‬\n      ‫قرارنــا ‪ 34186869‬رقــم وتاريــخ ‪1434/4/14‬ه ــ‪ :‬جــرت املصادقــة علــى‬\n      ‫ماحكــم بــه أصحــاب الفضيلــة وفقهــم اهلل علــى املدعــى عليــه بالقتــل‬\n      ‫تعزيــر ًا بعــد اإليضــاح واإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى‬\n                                                                          ‫نبينــا محمــد ‪.‬‬\n\n\n\n\n‫‪155‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":126,"source_page_end":155,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fac120463686f4669756da4d1cf68d86d5ce5b7b1e83482f2a4d8941a31a445e","normalized_text_hash":"8afa04c52a5257d144a3ebd1d20d550b95caa9447b4500f3670473f362dc88fb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p126-3455295"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
